INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "金属が空気中の水分によってさびが生じ、劣化すること。", "primary_collocate": null, "pronunciation": "さびつく", "ipa": "sabit͡sɯkɯ", "syllable_count": 4, "sentences": [{"text": "湿気の多い部屋に置いたナイフが、いつの間にか錆びついていた。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "湿気[しっけ]の多[おお]い部屋[へや]に置[お]いたナイフが、いつの間[ま]にか錆[さ]びついていた。", "sentence_source": "generated"}, {"text": "空気中の水分のせいで、金属の板が錆びついてきた。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "空気中[くうきちゅう]の水分[すいぶん]のせいで、金属[きんぞく]の板[いた]が錆[さ]びついてきた。", "sentence_source": "generated"}, {"text": "梅雨が長かったので、ベランダの鉄の椅子が錆びついた。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "梅雨[つゆ]が長[なが]かったので、ベランダの鉄[てつ]の椅子[いす]が錆[さ]びついた。", "sentence_source": "generated"}, {"text": "この門は鉄でできているので、雨の日が続くと錆びつきやすい。", "target_word": "錆びつき", "complexity_tier": "T3", "furigana": "この門[もん]は鉄[てつ]でできているので、雨[あめ]の日[ひ]が続[つづ]くと錆[さ]びつきやすい。", "sentence_source": "generated"}, {"text": "水に濡れたまま放っておくと、缶は錆びついてしまう。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "水[みず]に濡[ぬ]れたまま放[ほう]っておくと、缶[かん]は錆[さ]びついてしまう。", "sentence_source": "generated"}, {"text": "錆びついた看板の文字は、ほとんど読めなくなっていた。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "錆[さ]びついた看板[かんばん]の文字[もじ]は、ほとんど読[よ]めなくなっていた。", "sentence_source": "generated"}, {"text": "港に停まっている古い船は、船体が赤く錆びついている。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "港[みなと]に停[と]まっている古[ふる]い船[ふね]は、船体[せんたい]が赤[あか]く錆[さ]びついている。", "sentence_source": "generated"}, {"text": "車の底が錆びつくことは、雪の多い地方ではよくある。", "target_word": "錆びつく", "complexity_tier": "T3", "furigana": "車[くるま]の底[そこ]が錆[さ]びつくことは、雪[ゆき]の多[おお]い地方[ちほう]ではよくある。", "sentence_source": "generated"}, {"text": "屋外のフェンスが錆びついたので、新しいものに替えた。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "屋外[おくがい]のフェンスが錆[さ]びついたので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "錆びついたナットは、力を入れても回らなかった。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "錆[さ]びついたナットは、力[ちから]を入[い]れても回[まわ]らなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錆びつかない", "label": "否定形"}, {"form": "錆びつきます", "label": "丁寧形"}, {"form": "錆びついた", "label": "過去形"}, {"form": "錆びついて", "label": "て形"}, {"form": "錆びつけば", "label": "仮定形"}, {"form": "錆びつこう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "金属が湿気でさびて劣化する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "て形。「いつの間にか錆びついていた」の形で、「いた」と続けて状態を表す。"}, {"text": "錆びつか", "is_correct": false, "explanation": "否定の語幹。「錆びつかていた」となり、活用として成立しない。"}, {"text": "錆びつき", "is_correct": false, "explanation": "連用形。「錆びつきていた」となり、て形として続かない。"}, {"text": "錆びつく", "is_correct": false, "explanation": "終止形。「錆びつくていた」となり、て形として成立しない。"}], "explanations": {"錆びついて": "て形。「いつの間にか錆びついていた」の形で、「いた」と続けて状態を表す。", "錆びつか": "否定の語幹。「錆びつかていた」となり、活用として成立しない。", "錆びつき": "連用形。「錆びつきていた」となり、て形として続かない。", "錆びつく": "終止形。「錆びつくていた」となり、て形として成立しない。"}, "sentence_index": 0, "correct_answer": "錆びついて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湿気で木の床板が錆びついて、ぎしぎし鳴るようになった。", "explanation": "ここは〈腐る〉の意味。木の床板は錆びず腐って傷むので、錆びつくは金属の酸化にしか使わない。"}, {"text": "雪の夜、寒さで道路が錆びついて、車が滑った。", "explanation": "ここは〈凍りつく〉の意味。寒さで路面が凍ることは〈凍りつく〉で表し、錆びつくは金属の酸化を指すので合わない。"}, {"text": "乾いた粘土が錆びついて、形がすっかり固まってしまった。", "explanation": "ここは〈固まる〉の意味。粘土は錆びないので、乾いて固くなる意味なら〈固まる〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "て形。「赤く錆びついている」の形で、直後の「いる」と続き状態を表す。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこういる」となり、状態を表す文に合わない。"}, {"text": "錆びついた", "is_correct": false, "explanation": "た形。「錆びついたいる」となり、「いる」に続かない。"}, {"text": "錆びついたり", "is_correct": false, "explanation": "たり形。「錆びついたりいる」となり、状態の叙述として成立しない。"}], "explanations": {"錆びついて": "て形。「赤く錆びついている」の形で、直後の「いる」と続き状態を表す。", "錆びつこう": "意志形。「錆びつこういる」となり、状態を表す文に合わない。", "錆びついた": "た形。「錆びついたいる」となり、「いる」に続かない。", "錆びついたり": "たり形。「錆びついたりいる」となり、状態の叙述として成立しない。"}, "sentence_index": 6, "correct_answer": "錆びついて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方の風で、洗濯物が錆びついて、からりと乾いた。", "explanation": "ここは〈乾く〉の意味。洗濯物は金属ではなく錆びないので、錆びつくは使わない。"}, {"text": "高温の炉の中で、鉄の塊が錆びついて液状になった。", "explanation": "ここは〈溶ける〉の意味。熱で液体になる変化は〈溶ける〉で表し、錆びつくは酸化による劣化を指すので合わない。"}, {"text": "古い油の缶が錆びついて、火に入れるとよく燃えた。", "explanation": "ここは〈燃える〉の意味。火で燃えることは〈燃える〉で表し、錆びつくは金属の酸化を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裏口の鍵は、湿気で錆びつくた。", "corrected_sentence": "裏口の鍵は、湿気で錆びついた。", "error_description": "「錆びつくた」は誤り。正しくは「錆びついた」（く→いた）。五段動詞のた形は語幹に「いた」を付けて作る。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "て形。直後の「きた」と続き、錆びてきたという変化の経過を表す。"}, {"text": "錆びつかない", "is_correct": false, "explanation": "否定形。錆びていないという意味になり、錆びてきた事実と合わない。"}, {"text": "錆びつきます", "is_correct": false, "explanation": "丁寧形。普通体の「てきた」と文体が合わない。"}, {"text": "錆びつけば", "is_correct": false, "explanation": "仮定形。仮定の意味になり、すでに起きた変化の叙述と合わない。"}], "correct_form": "錆びついて", "base_form": "錆びつく", "form_label": "て形", "sentence_index": 1, "explanations": {"錆びついて": "て形。直後の「きた」と続き、錆びてきたという変化の経過を表す。", "錆びつかない": "否定形。錆びていないという意味になり、錆びてきた事実と合わない。", "錆びつきます": "丁寧形。普通体の「てきた」と文体が合わない。", "錆びつけば": "仮定形。仮定の意味になり、すでに起きた変化の叙述と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港の古い船は、湿気を錆びついてぼろぼろになった。", "corrected_sentence": "港の古い船は、湿気で錆びついてぼろぼろになった。", "error_description": "「湿気を」は誤り。〈錆びつく〉は自動詞で、原因は「湿気で」と表す。「を」は目的語に付く助詞なので合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "錆びつく", "is_correct": true, "explanation": "辞書形。「錆びつくことは」と名詞化して主語を述べる形で、一般論の文に合う。"}, {"text": "錆びつか", "is_correct": false, "explanation": "未然形。「錆びつかことは」となり、名詞化して主語を述べる形にならない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこうことは」となり、事実を述べる文に合わない。"}, {"text": "錆びつけ", "is_correct": false, "explanation": "命令形。「錆びつけことは」となり、名詞化して述べる形として成立しない。"}], "correct_form": "錆びつく", "base_form": "錆びつく", "form_label": "辞書形", "sentence_index": 7, "explanations": {"錆びつく": "辞書形。「錆びつくことは」と名詞化して主語を述べる形で、一般論の文に合う。", "錆びつか": "未然形。「錆びつかことは」となり、名詞化して主語を述べる形にならない。", "錆びつこう": "意志形。「錆びつこうことは」となり、事実を述べる文に合わない。", "錆びつけ": "命令形。「錆びつけことは」となり、名詞化して述べる形として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを取り壊す意味。"}, {"text": "送る", "is_correct": false, "explanation": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。"}, {"text": "借りる", "is_correct": false, "explanation": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。"}, {"text": "読む", "is_correct": false, "explanation": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを取り壊す意味。", "送る": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。", "借りる": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。", "読む": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「保育園を建てる」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は名詞同士をつなぐもので、「保育園と建てる」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「保育園から建てる」では建てる対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「保育園より建てる」では比べる内容がなく成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「保育園を建てる」の目的語を示す「を」。", "と": "並列の「と」は名詞同士をつなぐもので、「保育園と建てる」では成り立たない。", "から": "「から」は起点を示すため、「保育園から建てる」では建てる対象を表せない。", "より": "「より」は比較を示すため、「保育園より建てる」では比べる内容がなく成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを壊す意味。"}, {"text": "書く", "is_correct": false, "explanation": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。"}, {"text": "歩く", "is_correct": false, "explanation": "「歩く」は移動の動作で、「建てる」と対義関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを壊す意味。", "書く": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。", "歩く": "「歩く」は移動の動作で、「建てる」と対義関係にはない。", "届ける": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "家や学校などの建物を作ることを言います。", "primary_collocate": null, "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "町に新しい学校を建てることが決まりました。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "町[まち]に新[あたら]しい学校[がっこう]を建[た]てることが決[き]まりました。", "sentence_source": "generated"}, {"text": "村の人たちはお金を出し合って、小学校を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]たちはお金[かね]を出[だ]し合[あ]って、小学校[しょうがっこう]を建[た]てた。", "sentence_source": "generated"}, {"text": "駅の前に大きなビルを建てる計画があります。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に大[おお]きなビルを建[た]てる計画[けいかく]があります。", "sentence_source": "generated"}, {"text": "公園の近くに図書館を建てて、だれでも使えるようにした。", "target_word": "建てて", "complexity_tier": "T3", "furigana": "公園[こうえん]の近[ちか]くに図書館[としょかん]を建[た]てて、だれでも使[つか]えるようにした。", "sentence_source": "generated"}, {"text": "法律で高さが決まっているので、この土地には高い建物を建てられません。", "target_word": "建てられません", "complexity_tier": "T3", "furigana": "法律[ほうりつ]で高[たか]さが決[き]まっているので、この土地[とち]には高[たか]い建物[たてもの]を建[た]てられません。", "sentence_source": "generated"}, {"text": "会社は工場を建てるために、広い土地を探している。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は工場[こうじょう]を建[た]てるために、広[ひろ]い土地[とち]を探[さが]している。", "sentence_source": "generated"}, {"text": "古い病院をこわして、新しい病院を建てました。", "target_word": "建てました", "complexity_tier": "T3", "furigana": "古[ふる]い病院[びょういん]をこわして、新[あたら]しい病院[びょういん]を建[た]てました。", "sentence_source": "generated"}, {"text": "子どもが増えたので、市は保育園を建てるそうです。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "子[こ]どもが増[ふ]えたので、市[し]は保育園[ほいくえん]を建[た]てるそうです。", "sentence_source": "generated"}, {"text": "お寺を建てた人の名前が、石に彫ってあります。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "お寺[てら]を建[た]てた人[ひと]の名前[なまえ]が、石[いし]に彫[ほ]ってあります。", "sentence_source": "generated"}, {"text": "町の中心に市役所を建てたのは、十年前のことです。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "町[まち]の中心[ちゅうしん]に市役所[しやくしょ]を建[た]てたのは、十年前[じゅうねんまえ]のことです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建てる", "label": "終止形"}, {"form": "建てた", "label": "過去形"}, {"form": "建てて", "label": "て形"}, {"form": "建てない", "label": "否定形"}, {"form": "建てれば", "label": "仮定形"}, {"form": "建てよう", "label": "意志形"}, {"form": "建てられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "学校やビルなどの建物を作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建てる", "is_correct": true, "explanation": "辞書形は「ことが」に続けて、学校を建てる予定を表すので合う。"}, {"text": "建て", "is_correct": false, "explanation": "連用形だけでは「ことが」に続かず、文が成り立たない。"}, {"text": "建てよう", "is_correct": false, "explanation": "意志形は「ことが」の前に直接つながらないので不自然。"}, {"text": "建てれば", "is_correct": false, "explanation": "仮定形は「ことが」に続かず、文として成り立たない。"}], "explanations": {"建てる": "辞書形は「ことが」に続けて、学校を建てる予定を表すので合う。", "建て": "連用形だけでは「ことが」に続かず、文が成り立たない。", "建てよう": "意志形は「ことが」の前に直接つながらないので不自然。", "建てれば": "仮定形は「ことが」に続かず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "建てる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の旅行の計画を建てた。", "explanation": "ここは〈立てる〉の意味（計画を立てる）。計画には「立てる」を使い、「建てる」は建物を作る意味なので合わない。"}, {"text": "父は毎日、朝ご飯を建てている。", "explanation": "ここは〈作る〉の意味（食事を作る）。食事には「作る」を使い、「建てる」は建築物にしか使わないので合わない。"}, {"text": "父は子ども部屋に新しい本棚を建てた。", "explanation": "ここは〈組み立てる〉の意味。本棚や家具は「組み立てる」で表し、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建てました", "is_correct": true, "explanation": "丁寧な過去形で文を言い切るので、「古い病院をこわして、新しい病院を建てました。」として成り立つ。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「新しい病院を建てて。」で終わるこの文は成り立たない。"}, {"text": "建てさせ", "is_correct": false, "explanation": "使役の語幹では文が完結せず、建てさせるという意味にもならない。"}, {"text": "建てたら", "is_correct": false, "explanation": "条件の形は後ろに結果が続く必要があり、ここでは文が終わらない。"}], "explanations": {"建てました": "丁寧な過去形で文を言い切るので、「古い病院をこわして、新しい病院を建てました。」として成り立つ。", "建てて": "て形では文を言い切れず、「新しい病院を建てて。」で終わるこの文は成り立たない。", "建てさせ": "使役の語幹では文が完結せず、建てさせるという意味にもならない。", "建てたら": "条件の形は後ろに結果が続く必要があり、ここでは文が終わらない。"}, "sentence_index": 6, "correct_answer": "建てました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人たちは、新しい劇団を建てた。", "explanation": "ここは〈立ち上げる〉の意味（団体を作る）。劇団は立ち上げるもので、「建てる」は建築物にしか使わないので合わない。"}, {"text": "市は、来年度の予算を建てた。", "explanation": "ここは〈組む〉の意味（予算を組む）。予算には「組む」を使い、「建てる」は建築物を作る意味なので合わない。"}, {"text": "選手たちは、大会で新しい目標を建てた。", "explanation": "ここは〈掲げる〉の意味（目標を掲げる）。目標には「掲げる」を使い、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は、駅前に新しい体育館に建てる計画です。", "corrected_sentence": "町は、駅前に新しい体育館を建てる計画です。", "error_description": "誤りは「体育館に」の「に」。「建てる」は建てるもの（体育館）を「を」で示すので、正しくは「体育館を建てる」。「に」は場所を表すため目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で、村の人々が小学校を建てたという完了した出来事を表し、文の内容に合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「小学校を建てて。」では文が成り立たない。"}, {"text": "建てない", "is_correct": false, "explanation": "否定形では建てないという意味になり、お金を出し合って建てた事実と合わない。"}, {"text": "建てられる", "is_correct": false, "explanation": "可能形は建てる能力を表すため、実際に建てた出来事と合わない。"}], "correct_form": "建てた", "base_form": "建てる", "form_label": "過去形", "sentence_index": 1, "explanations": {"建てた": "過去形で、村の人々が小学校を建てたという完了した出来事を表し、文の内容に合う。", "建てて": "て形では文を言い切れず、「小学校を建てて。」では文が成り立たない。", "建てない": "否定形では建てないという意味になり、お金を出し合って建てた事実と合わない。", "建てられる": "可能形は建てる能力を表すため、実際に建てた出来事と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53217, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、駅の近くに新しい塔を建つ計画です。", "corrected_sentence": "町は、駅の近くに新しい塔を建てる計画です。", "error_description": "誤りは「建つ」。「建てる」は他動詞で目的語に「を」を取るので、正しくは「塔を建てる」。「建つ」は自動詞なので「塔を建つ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "建てる", "is_correct": true, "explanation": "終止形で、「建てるそうです」の形で伝聞を表すので、保育園の建設の話として合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形は「そうです」に直接続かず、伝聞の文として成り立たない。"}, {"text": "建てろ", "is_correct": false, "explanation": "命令形は「そうです」に続かず、伝聞の文として成り立たない。"}, {"text": "建てられません", "is_correct": false, "explanation": "可能の否定形で建てられないという意味になり、建設の話と合わない。"}], "correct_form": "建てる", "base_form": "建てる", "form_label": "終止形", "sentence_index": 7, "explanations": {"建てる": "終止形で、「建てるそうです」の形で伝聞を表すので、保育園の建設の話として合う。", "建てて": "て形は「そうです」に直接続かず、伝聞の文として成り立たない。", "建てろ": "命令形は「そうです」に続かず、伝聞の文として成り立たない。", "建てられません": "可能の否定形で建てられないという意味になり、建設の話と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを取り壊す意味。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「建てる」と対義関係にはない。"}, {"text": "借りる", "is_correct": false, "explanation": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。"}, {"text": "読む", "is_correct": false, "explanation": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを取り壊す意味。", "洗う": "「洗う」は汚れを落とす動作で、「建てる」と対義関係にはない。", "借りる": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。", "読む": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「僧が建てた」で建てる主体（主語）を示す「が」。"}, {"text": "に", "is_correct": false, "explanation": "「僧に建てた」では場所や相手を示すことになり、建てる主体として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「僧へ建てた」では方向を示すが、建てる主体の表現として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「僧より建てた」では比べる内容がなく文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「僧が建てた」で建てる主体（主語）を示す「が」。", "に": "「僧に建てた」では場所や相手を示すことになり、建てる主体として成り立たない。", "へ": "「僧へ建てた」では方向を示すが、建てる主体の表現として不自然。", "より": "「より」は比較を示すため、「僧より建てた」では比べる内容がなく文が成り立たない。"}, "error_tags": {"に": "場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを壊す意味。"}, {"text": "書く", "is_correct": false, "explanation": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。"}, {"text": "歩く", "is_correct": false, "explanation": "「歩く」は移動の動作で、「建てる」と対義関係にはない。"}, {"text": "送る", "is_correct": false, "explanation": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを壊す意味。", "書く": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。", "歩く": "「歩く」は移動の動作で、「建てる」と対義関係にはない。", "送る": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "家や橋、塔などの構造物を組み立てて作る。建築する。", "primary_collocate": null, "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "町の人たちは丘の上に高い塔を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちは丘[おか]の上[うえ]に高[たか]い塔[とう]を建[た]てた。", "sentence_source": "generated"}, {"text": "王様は海を見下ろす場所に城を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "王様[おうさま]は海[うみ]を見下[みお]ろす場所[ばしょ]に城[しろ]を建[た]てた。", "sentence_source": "generated"}, {"text": "昔の人は、山のふもとに小さな家を建てて暮らした。", "target_word": "建てて", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、山[やま]のふもとに小[ちい]さな家[いえ]を建[た]てて暮[く]らした。", "sentence_source": "generated"}, {"text": "駅前に電波塔を建てる計画に、近所の人が反対している。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に電波塔[でんぱとう]を建[た]てる計画[けいかく]に、近所[きんじょ]の人[ひと]が反対[はんたい]している。", "sentence_source": "generated"}, {"text": "戦争が終わった後、人々は広場に記念碑を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "戦争[せんそう]が終[お]わった後[あと]、人々[ひとびと]は広場[ひろば]に記念碑[きねんひ]を建[た]てた。", "sentence_source": "generated"}, {"text": "橋のそばに、旅人が休むための小さな家を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "橋[はし]のそばに、旅人[たびびと]が休[やす]むための小[ちい]さな家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "台風で壊れた家を、同じ場所にもう一度建てました。", "target_word": "建てました", "complexity_tier": "T3", "furigana": "台風[たいふう]で壊[こわ]れた家[いえ]を、同[おな]じ場所[ばしょ]にもう一度[いちど]建[た]てました。", "sentence_source": "generated"}, {"text": "この塔は、五百年前に有名な僧が建てたと言われている。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "この塔[とう]は、五百年前[ごひゃくねんまえ]に有名[ゆうめい]な僧[そう]が建[た]てたと言[い]われている。", "sentence_source": "generated"}, {"text": "島の人たちは、海の神様のために小さな社を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "島[しま]の人[ひと]たちは、海[うみ]の神様[かみさま]のために小[ちい]さな社[やしろ]を建[た]てた。", "sentence_source": "generated"}, {"text": "公園の真ん中に、有名な画家の銅像を建てることになった。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "公園[こうえん]の真[ま]ん中[なか]に、有名[ゆうめい]な画家[がか]の銅像[どうぞう]を建[た]てることになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建てる", "label": "終止形"}, {"form": "建てた", "label": "過去形"}, {"form": "建てて", "label": "て形"}, {"form": "建てない", "label": "否定形"}, {"form": "建てれば", "label": "仮定形"}, {"form": "建てよう", "label": "意志形"}, {"form": "建てられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "家や塔などの構造物を建築する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で文を言い切り、町の人々が塔を建てた出来事を表すので合う。"}, {"text": "建て", "is_correct": false, "explanation": "連用形だけでは文を言い切れず、「高い塔を建て。」では成り立たない。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「高い塔を建てて。」で終わるこの文は成り立たない。"}, {"text": "建てれば", "is_correct": false, "explanation": "仮定形は後ろに結果が続く形で、ここでは文が終わらず成り立たない。"}], "explanations": {"建てた": "過去形で文を言い切り、町の人々が塔を建てた出来事を表すので合う。", "建て": "連用形だけでは文を言い切れず、「高い塔を建て。」では成り立たない。", "建てて": "て形では文を言い切れず、「高い塔を建てて。」で終わるこの文は成り立たない。", "建てれば": "仮定形は後ろに結果が続く形で、ここでは文が終わらず成り立たない。"}, "sentence_index": 0, "correct_answer": "建てた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美術の先生は、粘土で小さな人形を建てた。", "explanation": "ここは〈作る〉の意味（人形を作る）。工芸品には「作る」を使い、「建てる」は建築物にしか使わないので合わない。"}, {"text": "父は会社の方針として、来年の目標を建てた。", "explanation": "ここは〈立てる〉の意味（目標や計画を立てる）。目標には「立てる」を使い、「建てる」は建築物を完成させる意味なので合わない。"}, {"text": "研究者たちは、新しい理論を建てた。", "explanation": "ここは〈打ち立てる〉の意味（理論を打ち立てる）。理論には「打ち立てる」を使い、「建てる」は建築物にしか使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建てました", "is_correct": true, "explanation": "丁寧な過去形で文を言い切り、同じ場所にもう一度建てた出来事を表すので合う。"}, {"text": "建てさせ", "is_correct": false, "explanation": "使役の語幹では文が完結せず、「もう一度建てさせ。」は成り立たない。"}, {"text": "建てたら", "is_correct": false, "explanation": "条件の形は後ろに結果が続く必要があり、ここでは文が終わらず成り立たない。"}, {"text": "建てられ", "is_correct": false, "explanation": "可能の語幹では文が完結せず、「もう一度建てられ。」は成り立たない。"}], "explanations": {"建てました": "丁寧な過去形で文を言い切り、同じ場所にもう一度建てた出来事を表すので合う。", "建てさせ": "使役の語幹では文が完結せず、「もう一度建てさせ。」は成り立たない。", "建てたら": "条件の形は後ろに結果が続く必要があり、ここでは文が終わらず成り立たない。", "建てられ": "可能の語幹では文が完結せず、「もう一度建てられ。」は成り立たない。"}, "sentence_index": 6, "correct_answer": "建てました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人たちは、新しい劇団を建てた。", "explanation": "ここは〈立ち上げる〉の意味（団体を作る）。劇団は立ち上げるもので、「建てる」は建築物にしか使わないので合わない。"}, {"text": "市は、来年度の予算を建てた。", "explanation": "ここは〈組む〉の意味（予算を組む）。予算には「組む」を使い、「建てる」は建築物を作る意味なので合わない。"}, {"text": "選手たちは、大会で新しい目標を建てた。", "explanation": "ここは〈掲げる〉の意味（目標を掲げる）。目標には「掲げる」を使い、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、川沿いに新しい橋に建てる計画です。", "corrected_sentence": "市は、川沿いに新しい橋を建てる計画です。", "error_description": "誤りは「橋に」の「に」。「建てる」は建てるもの（橋）を「を」で示すので、正しくは「橋を建てる」。「に」は場所を表すため目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で、王様が城を建てたという完了した出来事を表し、文の内容に合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「城を建てて。」では文が成り立たない。"}, {"text": "建てない", "is_correct": false, "explanation": "否定形では城を建てなかったという意味になり、建てた事実と合わない。"}, {"text": "建てられる", "is_correct": false, "explanation": "可能形では建てる能力を表すため、実際に建てた出来事と合わない。"}], "correct_form": "建てた", "base_form": "建てる", "form_label": "過去形", "sentence_index": 1, "explanations": {"建てた": "過去形で、王様が城を建てたという完了した出来事を表し、文の内容に合う。", "建てて": "て形では文を言い切れず、「城を建てて。」では文が成り立たない。", "建てない": "否定形では城を建てなかったという意味になり、建てた事実と合わない。", "建てられる": "可能形では建てる能力を表すため、実際に建てた出来事と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53218, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、駅の近くに新しい塔を建つ計画です。", "corrected_sentence": "町は、駅の近くに新しい塔を建てる計画です。", "error_description": "誤りは「建つ」。「建てる」は他動詞で目的語に「を」を取るので、正しくは「塔を建てる」。「建つ」は自動詞なので「塔を建つ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で、僧が塔を建てたという過去の出来事を表し、「と言われている」の内容として合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文の内容を言い切れず、「建てて、と言われている」と不自然になる。"}, {"text": "建てたい", "is_correct": false, "explanation": "願望形では建てたがっているという意味になり、建てたという伝聞の内容と合わない。"}, {"text": "建てられません", "is_correct": false, "explanation": "可能の否定形で建てることができなかったという意味になり、文の内容と合わない。"}], "correct_form": "建てた", "base_form": "建てる", "form_label": "過去形", "sentence_index": 7, "explanations": {"建てた": "過去形で、僧が塔を建てたという過去の出来事を表し、「と言われている」の内容として合う。", "建てて": "て形では文の内容を言い切れず、「建てて、と言われている」と不自然になる。", "建てたい": "願望形では建てたがっているという意味になり、建てたという伝聞の内容と合わない。", "建てられません": "可能の否定形で建てることができなかったという意味になり、文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "を", "is_correct": false, "explanation": "『リブを形を説明』と目的語が重なり、説明の対象が成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『リブに形を説明』は相手や場所の意味にならず不自然。"}, {"text": "の", "is_correct": true, "explanation": "『リブの形』で、リブと形をつなぐ『の』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、『リブへ形を説明』は意味が通らないので合わない。"}], "correct_answer": "の", "explanations": {"を": "『リブを形を説明』と目的語が重なり、説明の対象が成り立たないので合わない。", "に": "『リブに形を説明』は相手や場所の意味にならず不自然。", "の": "『リブの形』で、リブと形をつなぐ『の』が正しい。", "へ": "『へ』は方向を示すが、『リブへ形を説明』は意味が通らないので合わない。"}, "error_tags": {"を": "目的語の重複", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "が", "is_correct": false, "explanation": "『恐竜のリブが化石を見ました』は主語が見る主体にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "『リブで化石を見ました』は手段の意味にならず不自然。"}, {"text": "の", "is_correct": true, "explanation": "『恐竜のリブの化石』で、リブと化石をつなぐ『の』が正しい。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、『リブから化石を見ました』は不自然。"}], "correct_answer": "の", "explanations": {"が": "『恐竜のリブが化石を見ました』は主語が見る主体にならず不自然。", "で": "『リブで化石を見ました』は手段の意味にならず不自然。", "の": "『恐竜のリブの化石』で、リブと化石をつなぐ『の』が正しい。", "から": "『から』は起点を示すが、『リブから化石を見ました』は不自然。"}, "error_tags": {"が": "主語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "胸にある骨の一本です。細長い形をしています。", "primary_collocate": null, "pronunciation": "りぶ", "ipa": "ɾibɯ", "syllable_count": 2, "sentences": [{"text": "人間の胸には、左右に十二本ずつリブがあります。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "人間[にんげん]の胸[むね]には、左右[さゆう]に十二本[じゅうにほん]ずつリブがあります。", "sentence_source": "generated"}, {"text": "先生は模型を使って、リブの形を説明しました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "先生[せんせい]は模型[もけい]を使[つか]って、リブの形[かたち]を説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "リブは細長い形をしていて、胸の中の心臓を守っています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "リブは細長[ほそなが]い形[かたち]をしていて、胸[むね]の中[なか]の心臓[しんぞう]を守[まも]っています。", "sentence_source": "generated"}, {"text": "理科の時間に、動物のリブが長く曲がっていることを学びました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "理科[りか]の時間[じかん]に、動物[どうぶつ]のリブが長[なが]く曲[ま]がっていることを学[まな]びました。", "sentence_source": "generated"}, {"text": "事故で胸を打って、リブにひびが入りました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "事故[じこ]で胸[むね]を打[う]って、リブにひびが入[はい]りました。", "sentence_source": "generated"}, {"text": "深く息を吸うと、リブが少し広がります。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "深[ふか]く息[いき]を吸[す]うと、リブが少[すこ]し広[ひろ]がります。", "sentence_source": "generated"}, {"text": "骨の標本の中から、細長いリブを一本取り出しました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "骨[ほね]の標本[ひょうほん]の中[なか]から、細長[ほそなが]いリブを一本[いっぽん]取[と]り出[だ]しました。", "sentence_source": "generated"}, {"text": "博物館で、恐竜のリブの化石を見ました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、恐竜[きょうりゅう]のリブの化石[かせき]を見[み]ました。", "sentence_source": "generated"}, {"text": "医者は胸に手を当てて、リブの位置を確かめました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "医者[いしゃ]は胸[むね]に手[て]を当[あ]てて、リブの位置[いち]を確[たし]かめました。", "sentence_source": "generated"}, {"text": "リブは胸の前で曲がっていて、かごのような形になっています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "リブは胸[むね]の前[まえ]で曲[ま]がっていて、かごのような形[かたち]になっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リブ", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "胸にある細長い骨の一本（肋骨）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腕", "is_correct": false, "explanation": "腕は左右に一本ずつある部位で、十二本ずつという数に合わないので合わない。"}, {"text": "脚", "is_correct": false, "explanation": "脚も左右に一本ずつある部位で、十二本ずつ並ぶものではないので合わない。"}, {"text": "リブ", "is_correct": true, "explanation": "胸にある細長い骨で、左右に十二本ずつある骨として入る。"}, {"text": "眉", "is_correct": false, "explanation": "眉は顔にある毛で、胸の骨の話とは合わないので合わない。"}], "explanations": {"腕": "腕は左右に一本ずつある部位で、十二本ずつという数に合わないので合わない。", "脚": "脚も左右に一本ずつある部位で、十二本ずつ並ぶものではないので合わない。", "リブ": "胸にある細長い骨で、左右に十二本ずつある骨として入る。", "眉": "眉は顔にある毛で、胸の骨の話とは合わないので合わない。"}, "sentence_index": 0, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この橋は、太いリブで全体の重さを支えています。", "explanation": "ここは建物や橋を支える太い梁の意味。胸にある骨の意味ではないので合わない。"}, {"text": "リブは、体の後ろの真ん中を一本通っています。", "explanation": "ここは〈背骨〉の意味。リブは左右に並ぶ骨で、背中の真ん中を一本通るものではないので合わない。"}, {"text": "リブは、お腹の中で長く曲がっています。", "explanation": "ここは〈腸〉の意味。リブは胸の中にある骨で、お腹の中にあるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭蓋骨", "is_correct": false, "explanation": "頭蓋骨は頭を囲む骨で、細長い形の一本として取り出すものではないので合わない。"}, {"text": "骨盤", "is_correct": false, "explanation": "骨盤は腰の骨の集まりで、細長い一本として取り出すものではないので合わない。"}, {"text": "眼球", "is_correct": false, "explanation": "眼球は目の球体で、骨の標本から取り出す対象ではないので合わない。"}, {"text": "リブ", "is_correct": true, "explanation": "細長い形の胸の骨で、標本から一本取り出す対象になる。"}], "explanations": {"頭蓋骨": "頭蓋骨は頭を囲む骨で、細長い形の一本として取り出すものではないので合わない。", "骨盤": "骨盤は腰の骨の集まりで、細長い一本として取り出すものではないので合わない。", "眼球": "眼球は目の球体で、骨の標本から取り出す対象ではないので合わない。", "リブ": "細長い形の胸の骨で、標本から一本取り出す対象になる。"}, "sentence_index": 6, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手袋の手首は、リブで編みました。", "explanation": "ここは編み物の『リブ編み』の意味。胸にある骨の意味ではないので合わない。"}, {"text": "リブは、頭を覆う硬い骨で、脳を守っています。", "explanation": "ここは〈頭蓋骨〉の意味。頭を覆う骨で、胸にある骨のリブとは合わないので誤り。"}, {"text": "リブは、お酒を分解する臓器です。", "explanation": "ここは〈肝臓〉の意味。リブは骨で、お酒を分解する臓器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人間の胸には、左右に十二本ずつリブを並んでいます。", "corrected_sentence": "人間の胸には、左右に十二本ずつリブが並んでいます。", "error_description": "『並んでいます』の主語はリブなので『が』が正しい。『を』は目的語を示すが、『並ぶ』は目的語を取らないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きく息を吸うと、リブが少し広げます。", "corrected_sentence": "大きく息を吸うと、リブが少し広がります。", "error_description": "『リブ』が自分で広がる（自動詞）ので『広がります』が正しい。『広げます』は他動詞で、誰かがリブを広げる意味になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「リブは」で主題を示し、後ろの「一本ずつ外すことができます」へつながる。"}, {"text": "に", "is_correct": false, "explanation": "「リブに一本ずつ外す」では、動作の相手や場所として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「リブで一本ずつ外す」は手段の意味になり、主題を示せない。文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「リブへ一本ずつ外す」は目的語と方向が噛み合わず、意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "正解。「リブは」で主題を示し、後ろの「一本ずつ外すことができます」へつながる。", "に": "「リブに一本ずつ外す」では、動作の相手や場所として意味が通らない。", "で": "「リブで一本ずつ外す」は手段の意味になり、主題を示せない。文の流れに合わない。", "へ": "方向を表すが、「リブへ一本ずつ外す」は目的語と方向が噛み合わず、意味が通らない。"}, "error_tags": {"に": "対象の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「リブが左右に十二本ずつ付いています」の主語で、『付く』の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "『付く』は自動詞で目的語の『を』を取らないので、「リブを左右に付いている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、「リブと左右に付いている」では主語を示せず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すので、「リブから左右に付いている」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「リブが左右に十二本ずつ付いています」の主語で、『付く』の主語を示す。", "を": "『付く』は自動詞で目的語の『を』を取らないので、「リブを左右に付いている」は成り立たない。", "と": "並列や相手を表すが、「リブと左右に付いている」では主語を示せず、意味が通らない。", "から": "起点を表すので、「リブから左右に付いている」は意味が通らない。"}, "error_tags": {"を": "自動詞の目的語の誤り", "と": "並列・相手の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "胸部を守る骨の一本です。細長い帯のような形をしているものを指します。", "primary_collocate": null, "pronunciation": "りぶ", "ipa": "ɾibɯ", "syllable_count": 2, "sentences": [{"text": "胸を守るリブは、細長い帯のような形をしています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "胸[むね]を守[まも]るリブは、細長[ほそなが]い帯[おび]のような形[かたち]をしています。", "sentence_source": "generated"}, {"text": "骨格標本のリブは、一本ずつ外すことができます。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "骨格[こっかく]標本[ひょうほん]のリブは、一本[いっぽん]ずつ外[はず]すことができます。", "sentence_source": "generated"}, {"text": "転んだとき、リブにひびが入って息をするのが痛かったです。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "転[ころ]んだとき、リブにひびが入[はい]って息[いき]をするのが痛[いた]かったです。", "sentence_source": "generated"}, {"text": "リブは左右に並んで、肺と心臓を守っています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "リブは左右[さゆう]に並[なら]んで、肺[はい]と心臓[しんぞう]を守[まも]っています。", "sentence_source": "generated"}, {"text": "医者はレントゲンを見て、リブの折れた場所を教えてくれました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "医者[いしゃ]はレントゲンを見[み]て、リブの折[お]れた場所[ばしょ]を教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "帯のように平らなリブは、胸の骨格の中でよく目立ちます。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "帯[おび]のように平[たい]らなリブは、胸[むね]の骨格[こっかく]の中[なか]でよく目立[めだ]ちます。", "sentence_source": "generated"}, {"text": "子どもの胸のリブはやわらかいので、折れにくいです。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "子[こ]どもの胸[むね]のリブはやわらかいので、折[お]れにくいです。", "sentence_source": "generated"}, {"text": "理科室の模型には、リブが左右に十二本ずつ付いています。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "理科室[りかしつ]の模型[もけい]には、リブが左右[さゆう]に十二本[じゅうにほん]ずつ付[つ]いています。", "sentence_source": "generated"}, {"text": "咳がひどくて、リブのあたりが痛くなりました。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "咳[せき]がひどくて、リブのあたりが痛[いた]くなりました。", "sentence_source": "generated"}, {"text": "レントゲン写真を見ると、リブは胸の両側に左右対称に並んでいます。", "target_word": "リブ", "complexity_tier": "T3", "furigana": "レントゲン写真[しゃしん]を見[み]ると、リブは胸[むね]の両側[りょうがわ]に左右対称[さゆうたいしょう]に並[なら]んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リブ", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "胸部を守る、細長い帯状の骨の一本（肋骨）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リブ", "is_correct": true, "explanation": "正解。胸を守る細長い帯状の骨、つまり肋骨を指し、文の主語になる。"}, {"text": "心臓", "is_correct": false, "explanation": "胸の中にある臓器で、骨ではない。細長い帯のような形もしていないので合わない。"}, {"text": "肺", "is_correct": false, "explanation": "胸の中にある臓器で、骨の形を表さない。「帯のような形」とも合わない。"}, {"text": "眉毛", "is_correct": false, "explanation": "顔の部位で、胸を守る役割はない。文の主語として意味が通らない。"}], "explanations": {"リブ": "正解。胸を守る細長い帯状の骨、つまり肋骨を指し、文の主語になる。", "心臓": "胸の中にある臓器で、骨ではない。細長い帯のような形もしていないので合わない。", "肺": "胸の中にある臓器で、骨の形を表さない。「帯のような形」とも合わない。", "眉毛": "顔の部位で、胸を守る役割はない。文の主語として意味が通らない。"}, "sentence_index": 0, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "リブは胸の中央を縦に走る平たい骨で、両側の肋骨とつながっています。", "explanation": "ここは〈胸骨〉の意味。胸の中央を縦に走る平たい骨を指すので、細長い帯状の肋骨を表すリブとは合わない。"}, {"text": "リブは背中の中心を通る一本の長い柱で、神経を守っています。", "explanation": "ここは〈背骨〉の意味。背中の中心を通る一本の長い柱を指す。リブは左右に並ぶ複数の骨なので合わない。"}, {"text": "リブは腰の下にあり、内臓を支えている大きな骨です。", "explanation": "ここは〈骨盤〉の意味。腰の下で内臓を支える大きな骨を指す。リブは胸を守る細い骨なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リブ", "is_correct": true, "explanation": "正解。子どもの胸の骨で、やわらかいので折れにくいという主語になる。"}, {"text": "腎臓", "is_correct": false, "explanation": "腰のあたりにある臓器で、骨ではない。「折れにくい」と続けるのは合わない。"}, {"text": "胃", "is_correct": false, "explanation": "腹部の臓器で、胸の中の骨を指さない。「やわらかい」「折れにくい」の主語にならない。"}, {"text": "膝", "is_correct": false, "explanation": "脚の関節で、胸の部位ではない。文の主語として意味が通らない。"}], "explanations": {"リブ": "正解。子どもの胸の骨で、やわらかいので折れにくいという主語になる。", "腎臓": "腰のあたりにある臓器で、骨ではない。「折れにくい」と続けるのは合わない。", "胃": "腹部の臓器で、胸の中の骨を指さない。「やわらかい」「折れにくい」の主語にならない。", "膝": "脚の関節で、胸の部位ではない。文の主語として意味が通らない。"}, "sentence_index": 6, "correct_answer": "リブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リブは首の付け根にあり、肩を支えています。", "explanation": "ここは〈鎖骨〉の意味。首の付け根で肩を支える骨は鎖骨で、胸を守る肋骨を指すリブとは合わない。"}, {"text": "リブは背中の上にあり、腕を動かす支点になっています。", "explanation": "ここは〈肩甲骨〉の意味。背中の上にあって腕の支点になる骨は肩甲骨で、胸を守るリブとは合わない。"}, {"text": "膝のリブが擦り減って、歩くと痛みます。", "explanation": "ここは〈軟骨〉の意味。膝で擦り減るのは関節の軟骨で、胸の骨を指すリブとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転んだあと、リブ一個にひびが入っていないか、レントゲンで確かめました。", "corrected_sentence": "転んだあと、リブ一本にひびが入っていないか、レントゲンで確かめました。", "error_description": "骨を数える助数詞は『本』で、『個』は誤り。『リブ一本』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53220, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転んだ子どもの胸のリブを、まだ折れていませんでした。", "corrected_sentence": "転んだ子どもの胸のリブは、まだ折れていませんでした。", "error_description": "『折れる』は自動詞なので、目的語の『を』は付かない。主題の『は』にすると文が成り立つ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（町の歴史）を「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」では使う対象を表せず、「歴史に活かした観光案内」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「歴史で活かした」は手段として不自然で、目的語を表さない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「歴史が活かした観光案内」は使う主体が歴史になり、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（町の歴史）を「を」で示す。", "に": "「に」では使う対象を表せず、「歴史に活かした観光案内」は不自然。", "で": "「で」は手段を示す。「歴史で活かした」は手段として不自然で、目的語を表さない。", "が": "「が」は主語を示す。「歴史が活かした観光案内」は使う主体が歴史になり、意味が通らない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（環境）を「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「川のある環境と活かして」では活かす対象が立たず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「川のある環境から活かして」では出どころの意味になり、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。比べる相手がなく、「川のある環境より活かして」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（環境）を「を」で示す。", "と": "「と」は並列を示す。「川のある環境と活かして」では活かす対象が立たず不自然。", "から": "「から」は起点を示す。「川のある環境から活かして」では出どころの意味になり、目的語にならない。", "より": "「より」は比較を示す。比べる相手がなく、「川のある環境より活かして」は文脈に合わない。"}, "error_tags": {"を": "対象", "と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "よいところをじょうずに使って、もっとよくすること。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "前回の反省を活かして、今回の発表はもっとよくなりました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "まえかいのはんせいをいかして、こんかいのはっぴょうはもっとよくなりました。", "sentence_source": "generated"}, {"text": "町の歴史を活かした観光案内で、訪れる人が増えました。", "target_word": "活かした", "complexity_tier": "T3", "furigana": "まちのれきしをいかしたかんこうあんないで、おとずれるひとがふえました。", "sentence_source": "generated"}, {"text": "先輩の助言を活かし、レポートを書き直しました。", "target_word": "活かし", "complexity_tier": "T3", "furigana": "せんぱいのじょげんをいかし、レポートをかきなおしました。", "sentence_source": "generated"}, {"text": "古い建物の良さを活かしながら、使いやすく直しました。", "target_word": "活かしながら", "complexity_tier": "T3", "furigana": "ふるいたてもののよさをいかしながら、つかいやすくなおしました。", "sentence_source": "generated"}, {"text": "地元の特産品を活かして、新しいお菓子を開発した。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "じもとのとくさんひんをいかして、あたらしいおかしをかいはつした。", "sentence_source": "generated"}, {"text": "失敗から学んだことを活かさなければ、同じ間違いをします。", "target_word": "活かさ", "complexity_tier": "T3", "furigana": "しっぱいからまなんだことをいかさなければ、おなじまちがいをします。", "sentence_source": "generated"}, {"text": "部員それぞれの力を活かせるチームにしたいです。", "target_word": "活かせる", "complexity_tier": "T3", "furigana": "ぶいんそれぞれのちからをいかせるチームにしたいです。", "sentence_source": "generated"}, {"text": "川のある環境を活かして、町の魅力を高める。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "かわのあるかんきょうをいかして、まちのみりょくをたかめる。", "sentence_source": "generated"}, {"text": "生徒の意見を活かして、学校のルールが見直された。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "せいとのいけんをいかして、がっこうのルールがみなおされた。", "sentence_source": "generated"}, {"text": "試験の結果を活かし、勉強の方法を変えてみます。", "target_word": "活かし", "complexity_tier": "T3", "furigana": "しけんのけっかをいかし、べんきょうのほうほうをかえてみます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活かす", "label": "終止形"}, {"form": "活かし", "label": "連用形"}, {"form": "活かした", "label": "過去形"}, {"form": "活かして", "label": "て形"}, {"form": "活かさない", "label": "否定形"}, {"form": "活かせる", "label": "可能形"}, {"form": "活かされる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "よいところや学びを使って、物事をより良くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で「反省を使って、発表がよくなった」と続き、文が通る。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「反省を活かした、今回の発表は」と文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は文を終えるため、続く「今回の発表は」とつながらない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「反省を活かされ」は助詞と合わない。"}], "explanations": {"活かして": "て形で「反省を使って、発表がよくなった」と続き、文が通る。", "活かした": "連体形は名詞を修飾するが、「反省を活かした、今回の発表は」と文が切れて不自然。", "活かせ": "命令形は文を終えるため、続く「今回の発表は」とつながらない。", "活かされ": "受身形は助詞が「が」になるため、「反省を活かされ」は助詞と合わない。"}, "sentence_index": 0, "correct_answer": "活かして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先輩を大学院に活かせた。", "explanation": "ここは〈行かせる〉の意味。同じ読みの別語で、活かすは良い点を使う語なので、人を行かせる意味では使わない。"}, {"text": "古い建物の良さを活かしながら、壁の傷を隠した。", "explanation": "ここは〈隠す〉の意味。活かすは良い点を使う語で、傷を隠す意味では使わない。"}, {"text": "古い建物の良さを活かしながら、全部壊した。", "explanation": "ここは〈壊す〉の意味。良さを活かす語なので、建物を壊す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活かせる", "is_correct": true, "explanation": "可能形の連体形で、後ろの「チーム」を修飾する。力を使えるチームという意味になり、文が通る。"}, {"text": "活かして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「活かしてチーム」は不自然。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらず、「活かしチーム」は不自然。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身の連用形は「を」と合わず、「力を活かされ、チームにしたい」は文が成り立たない。"}], "explanations": {"活かせる": "可能形の連体形で、後ろの「チーム」を修飾する。力を使えるチームという意味になり、文が通る。", "活かして": "て形は名詞を修飾できず、「活かしてチーム」は不自然。", "活かし": "連用形は名詞に直接つながらず、「活かしチーム」は不自然。", "活かされ": "受身の連用形は「を」と合わず、「力を活かされ、チームにしたい」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "活かせる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月の成功を活かして、すぐに忘れた。", "explanation": "ここは〈忘れる〉の意味。活かすは良い点を使う語で、成功を忘れる意味では使わない。"}, {"text": "ろうそくの火を活かして、すぐに消した。", "explanation": "ここは〈消す〉の意味。活かすは良い点を使う語で、火を消す意味では使わない。"}, {"text": "試験の結果を活かして、勉強の意欲を損なった。", "explanation": "ここは〈損なう〉の意味。活かすは良い点を使う語で、意欲を損なう意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の畑の土を活かしで、新しい野菜を育てた。", "corrected_sentence": "祖父の畑の土を活かして、新しい野菜を育てた。", "error_description": "正しくは「活かして」（て形）。「活かしで」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "活かした", "is_correct": true, "explanation": "連体形で後ろの「観光案内」を修飾し、歴史を使った観光案内という意味になる。"}, {"text": "活かして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「活かして観光案内」は不自然。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらず、「活かし観光案内」は不自然。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「歴史を活かされ観光案内」は助詞と合わない。"}], "correct_form": "活かした", "base_form": "活かす", "form_label": "過去形", "sentence_index": 1, "explanations": {"活かした": "連体形で後ろの「観光案内」を修飾し、歴史を使った観光案内という意味になる。", "活かして": "て形は名詞を修飾できず、「活かして観光案内」は不自然。", "活かし": "連用形は名詞に直接つながらず、「活かし観光案内」は不自然。", "活かされ": "受身形は助詞が「が」になるため、「歴史を活かされ観光案内」は助詞と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の知恵を活かしに、家庭菜園を始めました。", "corrected_sentence": "祖母の知恵を活かして、家庭菜園を始めました。", "error_description": "「に」が誤りで、正しくは「活かして」（て形）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で後ろの「町の魅力を高める」へつながり、環境を使って魅力を高める意味になる。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「環境を活かした、町の魅力を」は文が切れて不自然。"}, {"text": "活かさ", "is_correct": false, "explanation": "未然形は単独で文に続かず、「活かさ、町の魅力を高める」は不自然。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「環境を活かされ」は助詞と合わない。"}], "correct_form": "活かして", "base_form": "活かす", "form_label": "て形", "sentence_index": 7, "explanations": {"活かして": "て形で後ろの「町の魅力を高める」へつながり、環境を使って魅力を高める意味になる。", "活かした": "連体形は名詞を修飾するが、「環境を活かした、町の魅力を」は文が切れて不自然。", "活かさ": "未然形は単独で文に続かず、「活かさ、町の魅力を高める」は不自然。", "活かされ": "受身形は助詞が「が」になるため、「環境を活かされ」は助詞と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（資格）を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「資格が活かして」は使う主体が資格になり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では使う対象を表せず、「資格に活かして」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「資格で活かして」は目的語の役割を果たさず不自然。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（資格）を「を」で示す。", "が": "「が」は主語を示す。「資格が活かして」は使う主体が資格になり、意味が通らない。", "に": "「に」では使う対象を表せず、「資格に活かして」は不自然。", "で": "「で」は手段を示す。「資格で活かして」は目的語の役割を果たさず不自然。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（専門）を「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「各自の専門と活かした意見」は活かす対象とつながらず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「各自の専門から活かした意見」では出どころの意味になり、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。比べる相手がなく、「各自の専門より活かした意見」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（専門）を「を」で示す。", "と": "「と」は並列を示す。「各自の専門と活かした意見」は活かす対象とつながらず不自然。", "から": "「から」は起点を示す。「各自の専門から活かした意見」では出どころの意味になり、目的語にならない。", "より": "「より」は比較を示す。比べる相手がなく、「各自の専門より活かした意見」は文脈に合わない。"}, "error_tags": {"を": "対象", "と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "持っている良い点や能力などをじょうずに使って、効果的に役立てること。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "彼の英語力は、海外の営業でこそ活かされます。", "target_word": "活かされます", "complexity_tier": "T3", "furigana": "かれのえいごりょくは、かいがいのえいぎょうでこそいかされます。", "sentence_source": "generated"}, {"text": "資格を活かして、病院で働くことにしました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "しかくをいかして、びょういんではたらくことにしました。", "sentence_source": "generated"}, {"text": "専門の知識を活かせる部署に異動を希望します。", "target_word": "活かせる", "complexity_tier": "T3", "furigana": "せんもんのちしきをいかせるぶしょにいどうをきぼうします。", "sentence_source": "generated"}, {"text": "持っている能力を活かさなければ、成長は難しい。", "target_word": "活かさ", "complexity_tier": "T3", "furigana": "もっているのうりょくをいかさなければ、せいちょうはむずかしい。", "sentence_source": "generated"}, {"text": "長年の経験を活かし、新人の指導を担当しています。", "target_word": "活かし", "complexity_tier": "T3", "furigana": "ながねんのけいけんをいかし、しんじんのしどうをたんとうしています。", "sentence_source": "generated"}, {"text": "技術者の腕を活かすには、よい道具が欠かせません。", "target_word": "活かす", "complexity_tier": "T3", "furigana": "ぎじゅつしゃのうでをいかすには、よいどうぐがかかせません。", "sentence_source": "generated"}, {"text": "彼女は絵の才能を活かして、絵本作家になった。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "かのじょはえのさいのうをいかして、えほんさっかになった。", "sentence_source": "generated"}, {"text": "会議では、各自の専門を活かした意見を出してください。", "target_word": "活かした", "complexity_tier": "T3", "furigana": "かいぎでは、かくじのせんもんをいかしたいけんをだしてください。", "sentence_source": "generated"}, {"text": "趣味の写真を活かして、会社の広報を手伝った。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "しゅみのしゃしんをいかして、かいしゃのこうほうをてつだった。", "sentence_source": "generated"}, {"text": "体力に自信があるので、その強みを活かせる仕事がしたい。", "target_word": "活かせる", "complexity_tier": "T3", "furigana": "たいりょくにじしんがあるので、そのつよみをいかせるしごとがしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活かす", "label": "終止形"}, {"form": "活かし", "label": "連用形"}, {"form": "活かした", "label": "過去形"}, {"form": "活かして", "label": "て形"}, {"form": "活かさない", "label": "否定形"}, {"form": "活かせる", "label": "可能形"}, {"form": "活かされます", "label": "受身丁寧形"}], "register": "neutral", "sense_fingerprint": "能力・資格・経験などを効果的に仕事や場面で役立てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活かされます", "is_correct": true, "explanation": "受身丁寧形で文を結び、英語力が海外の営業で活かされるという意味になる。"}, {"text": "活かして", "is_correct": false, "explanation": "て形では文が終わらず、「こそ活かして。」は文として完結しない。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形では文を終えられず、文が不完全になる。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は相手に命じる形で、説明の文には合わない。"}], "explanations": {"活かされます": "受身丁寧形で文を結び、英語力が海外の営業で活かされるという意味になる。", "活かして": "て形では文が終わらず、「こそ活かして。」は文として完結しない。", "活かし": "連用形では文を終えられず、文が不完全になる。", "活かせ": "命令形は相手に命じる形で、説明の文には合わない。"}, "sentence_index": 0, "correct_answer": "活かされます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は娘を習い事に活かせた。", "explanation": "ここは〈行かせる〉の意味。同じ読みの別語で、活かすは良い点を使う語なので、人を行かせる意味では使わない。"}, {"text": "持っている能力を活かして、道具を壊した。", "explanation": "ここは〈壊す〉の意味。活かすは能力を役立てる語で、道具を壊す意味では使わない。"}, {"text": "長年の経験を活かして、すぐに忘れた。", "explanation": "ここは〈忘れる〉の意味。活かすは経験を役立てる語で、経験を忘れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で「才能を使って、絵本作家になった」と続き、文が通る。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「才能を活かした、絵本作家になった」は文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は文を終えるため、続く「絵本作家になった」とつながらない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「才能を活かされ」は助詞と合わない。"}], "explanations": {"活かして": "て形で「才能を使って、絵本作家になった」と続き、文が通る。", "活かした": "連体形は名詞を修飾するが、「才能を活かした、絵本作家になった」は文が切れて不自然。", "活かせ": "命令形は文を終えるため、続く「絵本作家になった」とつながらない。", "活かされ": "受身形は助詞が「が」になるため、「才能を活かされ」は助詞と合わない。"}, "sentence_index": 6, "correct_answer": "活かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体力のなさを活かして、トレーニングの計画を直した。", "explanation": "ここは〈直す〉の意味。活かすは良い点を使う語で、弱点を直す意味では使わない。"}, {"text": "ろうそくの火を活かして、すぐに消した。", "explanation": "ここは〈消す〉の意味。活かすは良い点を使う語で、火を消す意味では使わない。"}, {"text": "趣味の写真を活かして、会社の広報を損なった。", "explanation": "ここは〈損なう〉の意味。活かすは良い点を使う語で、広報を損なう意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看護師の資格が活かして、病院で働いています。", "corrected_sentence": "看護師の資格を活かして、病院で働いています。", "error_description": "「活かす」は使うもの（資格）を「を」で示す。「が」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で後ろの「病院で働く」へつながり、資格を使って働く意味になる。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「資格を活かした、病院で」は文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は相手に命じる形で、説明の文には合わない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「資格を活かされ」は助詞と合わない。"}], "correct_form": "活かして", "base_form": "活かす", "form_label": "て形", "sentence_index": 1, "explanations": {"活かして": "て形で後ろの「病院で働く」へつながり、資格を使って働く意味になる。", "活かした": "連体形は名詞を修飾するが、「資格を活かした、病院で」は文が切れて不自然。", "活かせ": "命令形は相手に命じる形で、説明の文には合わない。", "活かされ": "受身形は助詞が「が」になるため、「資格を活かされ」は助詞と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の伝統を活かしで、新しい祭りを企画した。", "corrected_sentence": "地域の伝統を活かして、新しい祭りを企画した。", "error_description": "正しくは「活かして」（て形）。「活かしで」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活かした", "is_correct": true, "explanation": "連体形で後ろの「意見」を修飾し、専門を使った意見という意味になる。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらず、「活かし意見」は不自然。"}, {"text": "活かせば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「活かせば意見」は文が成り立たない。"}, {"text": "活かさ", "is_correct": false, "explanation": "未然形は単独で名詞を修飾できず、「活かさ意見」は不自然。"}], "correct_form": "活かした", "base_form": "活かす", "form_label": "過去形", "sentence_index": 7, "explanations": {"活かした": "連体形で後ろの「意見」を修飾し、専門を使った意見という意味になる。", "活かし": "連用形は名詞に直接つながらず、「活かし意見」は不自然。", "活かせば": "仮定形は名詞を修飾できず、「活かせば意見」は文が成り立たない。", "活かさ": "未然形は単独で名詞を修飾できず、「活かさ意見」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。ガラガラを握るという動作の対象にあたる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、握られる物を表す位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を表すので、握る対象を示す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、握る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。ガラガラを握るという動作の対象にあたる。", "が": "「が」は主語を示すので、握られる物を表す位置には合わない。", "に": "「に」は位置や相手を表すので、握る対象を示す位置には入らない。", "へ": "「へ」は方向を表すので、握る対象を示せない。"}, "error_tags": {"が": "主語（対象ではない）", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。ぬいぐるみを握るという動作の対象にあたる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、握る対象を示す位置には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、握る対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、握る対象を示す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。ぬいぐるみを握るという動作の対象にあたる。", "と": "「と」は並列や相手を表すので、握る対象を示す位置には合わない。", "より": "「より」は比較を表すので、握る対象を示せない。", "から": "「から」は起点を表すので、握る対象を示す位置には合わない。"}, "error_tags": {"と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手でしっかりつかむことです。おもちゃやぬいぐるみをぎゅっともつときに使います。", "primary_collocate": null, "pronunciation": "にぎりしめる", "ipa": "nigiɾiɕimeɾɯ", "syllable_count": 6, "sentences": [{"text": "男の子はお気に入りのぬいぐるみを握りしめて眠っている。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "男(おとこ)の子(こ)はお気(き)に入(い)りのぬいぐるみを握(にぎ)りしめて眠(ねむ)っている。", "sentence_source": "generated"}, {"text": "赤ちゃんが小さな手でガラガラを握りしめて、離そうとしない。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんが小(ちい)さな手(て)でガラガラを握(にぎ)りしめて、離(はな)そうとしない。", "sentence_source": "generated"}, {"text": "弟は新しいミニカーを握りしめて、うれしそうに走り回った。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "弟(おとうと)は新(あたら)しいミニカーを握(にぎ)りしめて、うれしそうに走(はし)り回(まわ)った。", "sentence_source": "generated"}, {"text": "雷が鳴ると、娘はくまの人形を握りしめて、目を閉じた。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "雷(かみなり)が鳴(な)ると、娘(むすめ)はくまの人形(にんぎょう)を握(にぎ)りしめて、目(め)を閉(と)じた。", "sentence_source": "generated"}, {"text": "公園で、女の子は砂遊びのシャベルを握りしめていた。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "公園(こうえん)で、女(おんな)の子(こ)は砂遊(すなあそ)びのシャベルを握(にぎ)りしめていた。", "sentence_source": "generated"}, {"text": "幼稚園の子どもが、折り紙の花をぎゅっと握りしめて先生に見せに来た。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "幼稚園(ようちえん)の子(こ)どもが、折(お)り紙(がみ)の花(はな)をぎゅっと握(にぎ)りしめて先生(せんせい)に見(み)せに来(き)た。", "sentence_source": "generated"}, {"text": "注射の間、息子はおもちゃの車を握りしめてがまんした。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "注射(ちゅうしゃ)の間(あいだ)、息子(むすこ)はおもちゃの車(くるま)を握(にぎ)りしめてがまんした。", "sentence_source": "generated"}, {"text": "人混みの中で、妹はうさぎのぬいぐるみを握りしめて、母のあとを歩いた。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "人混(ひとご)みの中(なか)で、妹(いもうと)はうさぎのぬいぐるみを握(にぎ)りしめて、母(はは)のあとを歩(ある)いた。", "sentence_source": "generated"}, {"text": "店で買ってもらったロボットを、彼は家まで握りしめて帰った。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "店(みせ)で買(か)ってもらったロボットを、彼(かれ)は家(いえ)まで握(にぎ)りしめて帰(かえ)った。", "sentence_source": "generated"}, {"text": "兄はヒーローのフィギュアを握りしめ、「ぼくが守る」と言った。", "target_word": "握りしめ", "complexity_tier": "T3", "furigana": "兄(あに)はヒーローのフィギュアを握(にぎ)りしめ、「ぼくが守(まも)る」と言(い)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握りしめる", "label": "辞書形"}, {"form": "握りしめ", "label": "連用形"}, {"form": "握りしめて", "label": "て形"}, {"form": "握りしめた", "label": "た形"}, {"form": "握りしめない", "label": "ない形"}], "register": "standard", "sense_fingerprint": "おもちゃなどを手でぎゅっとしっかりつかむ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形で、握ったまま「眠っている」へ続く。"}, {"text": "握りしめる", "is_correct": false, "explanation": "辞書形は「眠っている」とつながらず、文が成り立たない。"}, {"text": "握りしめた", "is_correct": false, "explanation": "た形は「眠っている」の前に続けられない。"}, {"text": "握りしめよう", "is_correct": false, "explanation": "意志形は「眠っている」と続かず、意味が合わない。"}], "explanations": {"握りしめて": "て形で、握ったまま「眠っている」へ続く。", "握りしめる": "辞書形は「眠っている」とつながらず、文が成り立たない。", "握りしめた": "た形は「眠っている」の前に続けられない。", "握りしめよう": "意志形は「眠っている」と続かず、意味が合わない。"}, "sentence_index": 0, "correct_answer": "握りしめて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "縁側で、祖父は猫の頭を握りしめて、目を細めた。", "explanation": "ここは〈撫でる〉の意味。やさしく触るのは撫でる。握りしめるは強く握る意味なので合わない。"}, {"text": "母は朝から窓を握りしめて、きれいにした。", "explanation": "ここは〈拭く〉の意味。布でこすって汚れを取るのは拭く。握りしめるは手で強く持つ意味なので合わない。"}, {"text": "母は泣いている赤ちゃんを握りしめて、あやした。", "explanation": "ここは〈抱きしめる〉の意味。子どもを腕で包むのは抱きしめる。握りしめるは手の中の物を強く持つ意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形で、握ったまま「がまんした」へ続く。"}, {"text": "握りしめなかった", "is_correct": false, "explanation": "否定の過去形は「がまんした」へつながらず、文が成り立たない。"}, {"text": "握りしめていた", "is_correct": false, "explanation": "「いた」は「がまんした」へ直接続かず、不自然になる。"}, {"text": "握りしめられた", "is_correct": false, "explanation": "受け身の形では息子が握られる意味になり、文が合わない。"}], "explanations": {"握りしめて": "て形で、握ったまま「がまんした」へ続く。", "握りしめなかった": "否定の過去形は「がまんした」へつながらず、文が成り立たない。", "握りしめていた": "「いた」は「がまんした」へ直接続かず、不自然になる。", "握りしめられた": "受け身の形では息子が握られる意味になり、文が合わない。"}, "sentence_index": 6, "correct_answer": "握りしめて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ぬいぐるみを握りしめて、ぬるま湯で洗った。", "explanation": "ここは〈洗う〉の意味。汚れを落とすのは洗う。握りしめるは手の中で強くつかむ意味で、洗う動作を表さないので合わない。"}, {"text": "レジのボタンを握りしめて、会計を終えた。", "explanation": "ここは〈押す〉の意味。ボタンを指で押すのは押す。握りしめるは手で強く持つ意味なので合わない。"}, {"text": "ノートに名前を握りしめて、先生に渡した。", "explanation": "ここは〈書く〉の意味。名前を紙に記すのは書く。握りしめるでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は、新しいお人形がぎゅっと握りしめて、笑顔になった。", "corrected_sentence": "妹は、新しいお人形をぎゅっと握りしめて、笑顔になった。", "error_description": "「握りしめる」は他動詞なので、対象には「を」を使う。「が」では誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形で、「離そうとしない」へ続ける。"}, {"text": "握りしめる", "is_correct": false, "explanation": "辞書形では文が止まり、後ろの「離そうとしない」へつながらない。"}, {"text": "握りしめさせて", "is_correct": false, "explanation": "使役の形では赤ちゃんが握らされる意味になり、文が合わない。"}, {"text": "握りしめてしまった", "is_correct": false, "explanation": "「しまった」は過去の完了で、「離そうとしない」とは続かない。"}], "correct_form": "握りしめて", "base_form": "握りしめる", "form_label": "て形", "sentence_index": 1, "explanations": {"握りしめて": "て形で、「離そうとしない」へ続ける。", "握りしめる": "辞書形では文が止まり、後ろの「離そうとしない」へつながらない。", "握りしめさせて": "使役の形では赤ちゃんが握らされる意味になり、文が合わない。", "握りしめてしまった": "「しまった」は過去の完了で、「離そうとしない」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53233, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帰り道、子どもはおもちゃのバスを握りしめ歩いていた。", "corrected_sentence": "帰り道、子どもはおもちゃのバスを握りしめて歩いていた。", "error_description": "「握りしめて」の「て」が抜けている。連用形のままでは「歩いていた」へ続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形で、ぬいぐるみを握ったまま「歩いた」へ続く。"}, {"text": "握りしめさせる", "is_correct": false, "explanation": "使役の形では誰かに握らせる意味になり、文が合わない。"}, {"text": "握りしめられる", "is_correct": false, "explanation": "受け身・可能の形ではぬいぐるみが握られる意味になり、文が合わない。"}, {"text": "握りしめさせた", "is_correct": false, "explanation": "使役の過去形では誰かに握らせた意味になり、文が合わない。"}], "correct_form": "握りしめて", "base_form": "握りしめる", "form_label": "て形", "sentence_index": 7, "explanations": {"握りしめて": "て形で、ぬいぐるみを握ったまま「歩いた」へ続く。", "握りしめさせる": "使役の形では誰かに握らせる意味になり、文が合わない。", "握りしめられる": "受け身・可能の形ではぬいぐるみが握られる意味になり、文が合わない。", "握りしめさせた": "使役の過去形では誰かに握らせた意味になり、文が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
