INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鉛筆を握りしめ」で、握る対象を示す他動詞の目的語。"}, {"text": "が", "is_correct": false, "explanation": "「鉛筆が握りしめ」では鉛筆が主語になり、握る動作の対象にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞同士をつなぐもので、動詞「握りしめ」の対象は示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では、握る対象を示す文にならず意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「鉛筆を握りしめ」で、握る対象を示す他動詞の目的語。", "が": "「鉛筆が握りしめ」では鉛筆が主語になり、握る動作の対象にならず不自然。", "の": "連体修飾の「の」は名詞同士をつなぐもので、動詞「握りしめ」の対象は示せない。", "から": "起点を表す「から」では、握る対象を示す文にならず意味が合わない。"}, "error_tags": {"が": "主語（対象ではない）", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手の中で強くつかみ、離さないようにすることです。気持ちを込めて物を持つ時によく使われます。", "primary_collocate": null, "pronunciation": "にぎりしめる", "ipa": "nigiɾiɕimeɾɯ", "syllable_count": 6, "sentences": [{"text": "それは幼い頃、何度も握りしめた懐かしい色だ。", "target_word": "握りしめた", "complexity_tier": "T3", "furigana": "それは幼(おさな)い頃(ころ)、何度(なんど)も握(にぎ)りしめた懐(なつ)かしい色(いろ)だ。", "sentence_source": "mined"}, {"text": "彼は不安で、お守りを手の中で強く握りしめていた。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "彼(かれ)は不安(ふあん)で、お守(まも)りを手(て)の中(なか)で強(つよ)く握(にぎ)りしめていた。", "sentence_source": "generated"}, {"text": "寒い朝、妹は小さな手でコインを握りしめて店へ走った。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "寒(さむ)い朝(あさ)、妹(いもうと)は小(ちい)さな手(て)でコインを握(にぎ)りしめて店(みせ)へ走(はし)った。", "sentence_source": "generated"}, {"text": "試合に負けた悔しさに、選手はこぶしを握りしめた。", "target_word": "握りしめた", "complexity_tier": "T3", "furigana": "試合(しあい)に負(ま)けた悔(くや)しさに、選手(せんしゅ)はこぶしを握(にぎ)りしめた。", "sentence_source": "generated"}, {"text": "母から受け取った手紙を、彼女は離さないように握りしめた。", "target_word": "握りしめた", "complexity_tier": "T3", "furigana": "母(はは)から受(う)け取(と)った手紙(てがみ)を、彼女(かのじょ)は離(はな)さないように握(にぎ)りしめた。", "sentence_source": "generated"}, {"text": "子どもは切符をなくさないよう、ずっと握りしめている。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "子(こ)どもは切符(きっぷ)をなくさないよう、ずっと握(にぎ)りしめている。", "sentence_source": "generated"}, {"text": "雨の中、父は傘の柄を握りしめて歩いた。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "雨(あめ)の中(なか)、父(ちち)は傘(かさ)の柄(え)を握(にぎ)りしめて歩(ある)いた。", "sentence_source": "generated"}, {"text": "受験生は鉛筆を握りしめ、問題用紙をじっと見つめた。", "target_word": "握りしめ", "complexity_tier": "T3", "furigana": "受験生(じゅけんせい)は鉛筆(えんぴつ)を握(にぎ)りしめ、問題用紙(もんだいようし)をじっと見(み)つめた。", "sentence_source": "generated"}, {"text": "迷子になった男の子は、母親の手を握りしめて離さなかった。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "迷子(まいご)になった男(おとこ)の子(こ)は、母親(ははおや)の手(て)を握(にぎ)りしめて離(はな)さなかった。", "sentence_source": "generated"}, {"text": "彼女は夢をかなえるために、もらった地図を握りしめて旅に出た。", "target_word": "握りしめて", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は夢(ゆめ)をかなえるために、もらった地図(ちず)を握(にぎ)りしめて旅(たび)に出(で)た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握りしめる", "label": "辞書形"}, {"form": "握りしめ", "label": "連用形"}, {"form": "握りしめて", "label": "て形"}, {"form": "握りしめた", "label": "た形"}, {"form": "握りしめない", "label": "ない形"}], "register": "standard", "sense_fingerprint": "気持ちを込めて手の中の物を強く持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握りしめた", "is_correct": true, "explanation": "た形で、後ろの名詞「色」を修飾する（何度も握りしめた色）。"}, {"text": "握りしめて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「懐かしい色」につながらない。"}, {"text": "握りしめ", "is_correct": false, "explanation": "連用形は名詞を修飾できず、ここでは文が切れてしまう。"}, {"text": "握りしめよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文意が成り立たない。"}], "explanations": {"握りしめた": "た形で、後ろの名詞「色」を修飾する（何度も握りしめた色）。", "握りしめて": "て形は名詞を修飾できず、「懐かしい色」につながらない。", "握りしめ": "連用形は名詞を修飾できず、ここでは文が切れてしまう。", "握りしめよう": "意志形は名詞を修飾できず、文意が成り立たない。"}, "sentence_index": 0, "correct_answer": "握りしめた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は寿司を握りしめて、お客に出した。", "explanation": "ここは〈握る〉の意味。寿司やおにぎりを作る意味の握るを使う。握りしめるは強く持つ意味なので合わない。"}, {"text": "彼はキーボードを握りしめて、長い文章を打った。", "explanation": "ここは〈打つ〉の意味。キーボードで文字を入力するのは打つ。握りしめるは手の中で強くつかむ意味なので、キーボードを打つ動作には合わない。"}, {"text": "お土産をきれいに握りしめて、箱に入れた。", "explanation": "ここは〈包む〉の意味。紙などで覆うのは包むで、握りしめるは手で強く持つ意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形で、握った状態のまま「歩いた」へつながる。"}, {"text": "握りしめた", "is_correct": false, "explanation": "た形は「歩いた」の前に続けられず、文が成り立たない。"}, {"text": "握りしめられ", "is_correct": false, "explanation": "受け身の形では父が握られる意味になり、文が合わない。"}, {"text": "握りしめさせ", "is_correct": false, "explanation": "使役の形では誰かに握らせる意味になり、文が合わない。"}], "explanations": {"握りしめて": "て形で、握った状態のまま「歩いた」へつながる。", "握りしめた": "た形は「歩いた」の前に続けられず、文が成り立たない。", "握りしめられ": "受け身の形では父が握られる意味になり、文が合わない。", "握りしめさせ": "使役の形では誰かに握らせる意味になり、文が合わない。"}, "sentence_index": 6, "correct_answer": "握りしめて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレベーターのボタンを握りしめて、ドアを閉めた。", "explanation": "ここは〈押す〉の意味。ボタンを指で押すのは押す。握りしめるは手で強く持つ意味なので合わない。"}, {"text": "子どもを握りしめて、なだめた。", "explanation": "ここは〈抱きしめる〉の意味。人を腕で包み込むのは抱きしめる。握りしめるは手の中の物を強く持つ意味なので合わない。"}, {"text": "紙に名前を握りしめて、提出した。", "explanation": "ここは〈書く〉の意味。紙に名前を記すのは書く。握りしめるでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の形見の指輪に、彼は手の中でしっかり握りしめた。", "corrected_sentence": "祖母の形見の指輪を、彼は手の中でしっかり握りしめた。", "error_description": "「握りしめる」は他動詞なので、対象には「を」を使う。「に」では誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握りしめて", "is_correct": true, "explanation": "て形＋いた（握りしめていた）で、続いていた動作を表す。"}, {"text": "握りしめる", "is_correct": false, "explanation": "辞書形に「いた」は続かず、文が成り立たない。"}, {"text": "握りしめた", "is_correct": false, "explanation": "た形に「いた」は続かず、文が成り立たない。"}, {"text": "握りしめよう", "is_correct": false, "explanation": "意志形に「いた」は続かず、不自然になる。"}], "correct_form": "握りしめて", "base_form": "握りしめる", "form_label": "て形", "sentence_index": 1, "explanations": {"握りしめて": "て形＋いた（握りしめていた）で、続いていた動作を表す。", "握りしめる": "辞書形に「いた」は続かず、文が成り立たない。", "握りしめた": "た形に「いた」は続かず、文が成り立たない。", "握りしめよう": "意志形に「いた」は続かず、不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53234, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車の中で、少女は切符を握りしめるて眠っていた。", "corrected_sentence": "電車の中で、少女は切符を握りしめて眠っていた。", "error_description": "「握りしめる」のて形は「握りしめて」。辞書形に「て」を続けるのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握りしめ", "is_correct": true, "explanation": "連用形で、読点で後ろの動作へ続ける。"}, {"text": "握りしめない", "is_correct": false, "explanation": "ない形は「〜ず」に直さないと続かない。"}, {"text": "握りしめさせ", "is_correct": false, "explanation": "使役の形では誰かに握らせる意味になり、文が合わない。"}, {"text": "握りしめられ", "is_correct": false, "explanation": "受け身の形では鉛筆が握られる意味になり、文が合わない。"}], "correct_form": "握りしめ", "base_form": "握りしめる", "form_label": "連用形", "sentence_index": 7, "explanations": {"握りしめ": "連用形で、読点で後ろの動作へ続ける。", "握りしめない": "ない形は「〜ず」に直さないと続かない。", "握りしめさせ": "使役の形では誰かに握らせる意味になり、文が合わない。", "握りしめられ": "受け身の形では鉛筆が握られる意味になり、文が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
