INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "遠くにいる人が恋しいときや、お別れをするときに感じる、ちょっとさびしくてあたたかい気持ちです。", "primary_collocate": null, "pronunciation": "せつない", "ipa": "setsɯnai", "syllable_count": 4, "sentences": [{"text": "遠くに住む友だちの写真を見ると、切ない気持ちになります。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "遠[とお]くに住[す]む友[とも]だちの写真[しゃしん]を見[み]ると、切[せつ]ない気持[きも]ちになります。", "sentence_source": "generated"}, {"text": "駅で家族と別れるとき、胸が切なくなりました。", "target_word": "切なく", "complexity_tier": "T3", "furigana": "駅[えき]で家族[かぞく]と別[わか]れるとき、胸[むね]が切[せつ]なくなりました。", "sentence_source": "generated"}, {"text": "卒業式の日、みんなと会えなくなるのが切ないです。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]の日[ひ]、みんなと会[あ]えなくなるのが切[せつ]ないです。", "sentence_source": "generated"}, {"text": "離れて暮らす母の声を聞いて、切ない気持ちになった。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "離[はな]れて暮[く]らす母[はは]の声[こえ]を聞[き]いて、切[せつ]ない気持[きも]ちになった。", "sentence_source": "generated"}, {"text": "転校する友だちを見送って、切なく感じた。", "target_word": "切なく", "complexity_tier": "T3", "furigana": "転校[てんこう]する友[とも]だちを見送[みおく]って、切[せつ]なく感[かん]じた。", "sentence_source": "generated"}, {"text": "夏休みが終わり、祖父母の家を出る朝は切ない。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが終[お]わり、祖父母[そふぼ]の家[いえ]を出[で]る朝[あさ]は切[せつ]ない。", "sentence_source": "generated"}, {"text": "遠い町にいる恋人が恋しくて、切ないです。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "遠[とお]い町[まち]にいる恋人[こいびと]が恋[こい]しくて、切[せつ]ないです。", "sentence_source": "generated"}, {"text": "空港で手を振る姿を見て、切ない思いがこみ上げた。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "空港[くうこう]で手[て]を振[ふ]る姿[すがた]を見[み]て、切[せつ]ない思[おも]いがこみ上[あ]げた。", "sentence_source": "generated"}, {"text": "旅行の最後の夜は楽しかったが、帰るのが切なかった。", "target_word": "切なかった", "complexity_tier": "T3", "furigana": "旅行[りょこう]の最後[さいご]の夜[よる]は楽[たの]しかったが、帰[かえ]るのが切[せつ]なかった。", "sentence_source": "generated"}, {"text": "会えない日が続いて、切ない気持ちでいっぱいになり、彼に電話をかけた。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "会[あ]えない日[ひ]が続[つづ]いて、切[せつ]ない気持[きも]ちでいっぱいになり、彼[かれ]に電話[でんわ]をかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切ない", "label": "終止形・連体形"}, {"form": "切なく", "label": "連用形"}, {"form": "切なかった", "label": "過去形"}, {"form": "切なくない", "label": "否定形"}, {"form": "切なければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "離れた人を恋しく思う、あたたかいさびしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "うるさい", "is_correct": false, "explanation": "音が大きく騒がしいことを表す語で、「〜な気持ちになります」にはつながらない。"}, {"text": "切ない", "is_correct": true, "explanation": "離れた人を恋しく思うさびしさを表し、「〜気持ちになります」の前に入って文の意味に合う。"}, {"text": "ぬるい", "is_correct": false, "explanation": "温度が低いことを表す語で、写真を見たときの気持ちを表すのには合わない。"}, {"text": "四角い", "is_correct": false, "explanation": "形が角ばっていることを表す語で、気持ちの様子には使えない。"}], "explanations": {"うるさい": "音が大きく騒がしいことを表す語で、「〜な気持ちになります」にはつながらない。", "切ない": "離れた人を恋しく思うさびしさを表し、「〜気持ちになります」の前に入って文の意味に合う。", "ぬるい": "温度が低いことを表す語で、写真を見たときの気持ちを表すのには合わない。", "四角い": "形が角ばっていることを表す語で、気持ちの様子には使えない。"}, "sentence_index": 0, "correct_answer": "切ない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "転んで膝が切なくて、しばらく歩けなかった。", "explanation": "ここは〈痛い〉の意味。切ないは気持ちのさびしさを表すので、体の痛みには使えない。"}, {"text": "このリュックは切なくて、持ち上げられない。", "explanation": "ここは〈重い〉の意味。切ないは気持ちの感覚を表すので、荷物の重さには使わない。"}, {"text": "このカレーはとても切なくて、一口も食べられなかった。", "explanation": "ここは〈辛い〉の意味。切ないは気持ちの感覚を表すので、食べ物の辛さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠い", "is_correct": false, "explanation": "眠気を表す語で、恋しい気持ちを説明する文脈には合わない。"}, {"text": "硬い", "is_correct": false, "explanation": "かたさを表す語で、感情の説明には使えない。"}, {"text": "切ない", "is_correct": true, "explanation": "恋しさから来るさびしさを表し、「〜です」で文を結べて文脈に合う。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "味を表す語で、恋しく思う気持ちとは結びつかない。"}], "explanations": {"眠い": "眠気を表す語で、恋しい気持ちを説明する文脈には合わない。", "硬い": "かたさを表す語で、感情の説明には使えない。", "切ない": "恋しさから来るさびしさを表し、「〜です」で文を結べて文脈に合う。", "酸っぱい": "味を表す語で、恋しく思う気持ちとは結びつかない。"}, "sentence_index": 6, "correct_answer": "切ない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この包丁は刃がとても切ない。", "explanation": "ここは〈鋭い〉の意味。切ないは気持ちの感覚を表すので、刃物の鋭さには使えない。"}, {"text": "夜更かしをしたので、体が切なくてたまらない。", "explanation": "ここは〈眠い〉の意味。切ないは気持ちのさびしさを表すので、体の眠気には使えない。"}, {"text": "みんなの前で名前を間違えられて、切なくて顔が熱くなった。", "explanation": "〈恥ずかしい〉と混同しやすい。切ないは離れた人への恋しさを表すので、人前での恥ずかしさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の駅で電車を見送ると、切ないくなります。", "corrected_sentence": "夜の駅で電車を見送ると、切なくなります。", "error_description": "形容詞「切ない」の連用形は「切なく」。「切ないく」は活用の誤り。「なります」の前には連用形の「切なく」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "切ない", "is_correct": false, "explanation": "終止形・連体形。「なる」の前に直接置くと活用が合わず、文が成り立たない。"}, {"text": "切なく", "is_correct": true, "explanation": "連用形。「なる」につながるので、「胸が切なくなりました」が成り立つ。"}, {"text": "切なかった", "is_correct": false, "explanation": "過去形。「なる」の前には置けず、「切なかったなりました」は成り立たない。"}, {"text": "切なければ", "is_correct": false, "explanation": "仮定形。「ば」の条件を表すので、「胸が〜なりました」の文には合わない。"}], "correct_form": "切なく", "base_form": "切ない", "form_label": "連用形", "sentence_index": 1, "explanations": {"切ない": "終止形・連体形。「なる」の前に直接置くと活用が合わず、文が成り立たない。", "切なく": "連用形。「なる」につながるので、「胸が切なくなりました」が成り立つ。", "切なかった": "過去形。「なる」の前には置けず、「切なかったなりました」は成り立たない。", "切なければ": "仮定形。「ば」の条件を表すので、「胸が〜なりました」の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53235, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠い町の恋人を思うと、切ないな気持ちになる。", "corrected_sentence": "遠い町の恋人を思うと、切ない気持ちになる。", "error_description": "形容詞「切ない」は名詞「気持ち」の前で語幹に「な」を付けない。「切ないな」は誤りで、正しくは「切ない気持ち」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "切ない", "is_correct": true, "explanation": "終止形・連体形。後ろの「思い」を直接修飾するので、名詞の前ではこの形が入る。"}, {"text": "切なく", "is_correct": false, "explanation": "連用形。名詞「思い」の前には直接置けず、文が成り立たない。"}, {"text": "切なければ", "is_correct": false, "explanation": "仮定形。「ば」の条件を表すので、名詞「思い」の前には入らない。"}, {"text": "切なさ", "is_correct": false, "explanation": "名詞形。「思い」の前に置くと名詞が二つ並び、文が成り立たない。"}], "correct_form": "切ない", "base_form": "切ない", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"切ない": "終止形・連体形。後ろの「思い」を直接修飾するので、名詞の前ではこの形が入る。", "切なく": "連用形。名詞「思い」の前には直接置けず、文が成り立たない。", "切なければ": "仮定形。「ば」の条件を表すので、名詞「思い」の前には入らない。", "切なさ": "名詞形。「思い」の前に置くと名詞が二つ並び、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
