INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53236, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "悲しくてさみしい気持ちになること。また、そのような様子を表します。", "primary_collocate": null, "pronunciation": "せつない", "ipa": "setsɯnai", "syllable_count": 4, "sentences": [{"text": "雨の夜に一人で聴くこの歌は、とても切ない。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "雨[あめ]の夜[よる]に一人[ひとり]で聴[き]くこの歌[うた]は、とても切[せつ]ない。", "sentence_source": "generated"}, {"text": "映画の最後の場面が切なくて、涙が出ました。", "target_word": "切なくて", "complexity_tier": "T3", "furigana": "映画[えいが]の最後[さいご]の場面[ばめん]が切[せつ]なくて、涙[なみだ]が出[で]ました。", "sentence_source": "generated"}, {"text": "秋の夕方の公園は、なんだか切ない雰囲気です。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "秋[あき]の夕方[ゆうがた]の公園[こうえん]は、なんだか切[せつ]ない雰囲気[ふんいき]です。", "sentence_source": "generated"}, {"text": "彼の切ない笑顔を見て、私も悲しくなった。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "彼[かれ]の切[せつ]ない笑顔[えがお]を見[み]て、私[わたし]も悲[かな]しくなった。", "sentence_source": "generated"}, {"text": "誰にも気づかれない片思いは切ないものだ。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "誰[だれ]にも気[き]づかれない片思[かたおも]いは切[せつ]ないものだ。", "sentence_source": "generated"}, {"text": "古いアルバムを開くと、昔を思い出して切なくなります。", "target_word": "切なく", "complexity_tier": "T3", "furigana": "古[ふる]いアルバムを開[ひら]くと、昔[むかし]を思[おも]い出[だ]して切[せつ]なくなります。", "sentence_source": "generated"}, {"text": "小説の主人公が一人で去る場面は、切なかった。", "target_word": "切なかった", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の主人公[しゅじんこう]が一人[ひとり]で去[さ]る場面[ばめん]は、切[せつ]なかった。", "sentence_source": "generated"}, {"text": "誰もいない教室に一人残って、窓の外の夕焼けを見ていると切ない。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "誰[だれ]もいない教室[きょうしつ]に一人[ひとり]残[のこ]って、窓[まど]の外[そと]の夕焼[ゆうや]けを見[み]ていると切[せつ]ない。", "sentence_source": "generated"}, {"text": "祭りが終わった後の静かな道は、切ない気持ちにさせる。", "target_word": "切ない", "complexity_tier": "T3", "furigana": "祭[まつ]りが終[お]わった後[あと]の静[しず]かな道[みち]は、切[せつ]ない気持[きも]ちにさせる。", "sentence_source": "generated"}, {"text": "返事のこない手紙を待ち続ける日々が切なかった。", "target_word": "切なかった", "complexity_tier": "T3", "furigana": "返事[へんじ]のこない手紙[てがみ]を待[ま]ち続[つづ]ける日々[ひび]が切[せつ]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切ない", "label": "終止形・連体形"}, {"form": "切なく", "label": "連用形"}, {"form": "切なかった", "label": "過去形"}, {"form": "切なくない", "label": "否定形"}, {"form": "切なければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "胸がしめつけられるような悲しさ・さみしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四角い", "is_correct": false, "explanation": "形が角ばっていることを表す語で、歌の様子を説明するには合わない。"}, {"text": "切ない", "is_correct": true, "explanation": "胸がしめつけられるような悲しさを表し、歌の様子を説明する文に合う。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "味を表す語で、歌の感じとは結びつかない。"}, {"text": "ぬるい", "is_correct": false, "explanation": "温度や熱意が低いことを表し、この歌の感じには合わない。"}], "explanations": {"四角い": "形が角ばっていることを表す語で、歌の様子を説明するには合わない。", "切ない": "胸がしめつけられるような悲しさを表し、歌の様子を説明する文に合う。", "酸っぱい": "味を表す語で、歌の感じとは結びつかない。", "ぬるい": "温度や熱意が低いことを表し、この歌の感じには合わない。"}, "sentence_index": 0, "correct_answer": "切ない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜更かしして、体が切なくて動けない。", "explanation": "ここは〈眠い〉の意味。切ないは胸にしみる悲しさを表すので、体の眠気には使えない。"}, {"text": "ミスを指摘されて、とても切なかった。", "explanation": "〈悔しい〉と混同しやすい。切ないは離れた人への恋しさやさびしさを表すので、指摘された悔しさには合わない。"}, {"text": "今日は切なくて、外に出たくない。", "explanation": "ここは〈暑い〉の意味。切ないは気持ちの感覚を表すので、気温の暑さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠かった", "is_correct": false, "explanation": "眠気を表す過去形で、場面の感じを表すには合わない。"}, {"text": "細かった", "is_correct": false, "explanation": "細いことを表す過去形で、場面の感じには使えない。"}, {"text": "煙たかった", "is_correct": false, "explanation": "煙が多く息苦しいことを表し、場面の様子には合わない。"}, {"text": "切なかった", "is_correct": true, "explanation": "さびしく胸がしめつけられる過去の感じを表し、場面の様子に合う。"}], "explanations": {"眠かった": "眠気を表す過去形で、場面の感じを表すには合わない。", "細かった": "細いことを表す過去形で、場面の感じには使えない。", "煙たかった": "煙が多く息苦しいことを表し、場面の様子には合わない。", "切なかった": "さびしく胸がしめつけられる過去の感じを表し、場面の様子に合う。"}, "sentence_index": 6, "correct_answer": "切なかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この肉は切なくて、噛み切れない。", "explanation": "ここは〈硬い〉の意味。切ないは気持ちの感覚を表すので、食べ物のかたさには使えない。"}, {"text": "みんなの前で大きな声を出して、切なかった。", "explanation": "〈恥ずかしい〉と混同しやすい。切ないは離れた人へのさびしさを表すので、人前での恥ずかしさには合わない。"}, {"text": "蚊に刺されて、切なくてたまらない。", "explanation": "ここは〈かゆい〉の意味。切ないは気持ちの感覚で、皮膚のかゆさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の雨音を聴いていると、とても切れる。", "corrected_sentence": "夜の雨音を聴いていると、とても切ない。", "error_description": "形容詞「切ない」を、刃物が切れる意味の動詞「切れる」と取り違えている。気持ちを表すには「切ない」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "切ない", "is_correct": false, "explanation": "終止形・連体形。「て」で続けられないので、ここには入らない。"}, {"text": "切なくて", "is_correct": true, "explanation": "て形。後ろの「涙が出ました」へ続けられるので、文が成り立つ。"}, {"text": "切なさ", "is_correct": false, "explanation": "名詞形。動詞「出ました」へつながる文の形にならないので、ここには入らない。"}, {"text": "切なければ", "is_correct": false, "explanation": "仮定形。「ば」の条件を表すので、「涙が出ました」へつながらない。"}], "correct_form": "切なくて", "base_form": "切ない", "form_label": "て形", "sentence_index": 1, "explanations": {"切ない": "終止形・連体形。「て」で続けられないので、ここには入らない。", "切なくて": "て形。後ろの「涙が出ました」へ続けられるので、文が成り立つ。", "切なさ": "名詞形。動詞「出ました」へつながる文の形にならないので、ここには入らない。", "切なければ": "仮定形。「ば」の条件を表すので、「涙が出ました」へつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
