INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "じぶんにまかされたしごとをおこなうことです。", "primary_collocate": null, "pronunciation": "たんとう", "ipa": "tantoː", "syllable_count": 4, "sentences": [{"text": "この仕事は私が担当します。", "target_word": "担当", "complexity_tier": "T3", "furigana": "この仕事[しごと]は私[わたし]が担当[たんとう]します。", "sentence_source": "generated"}, {"text": "来月から新しいクラスを担当することになった。", "target_word": "担当", "complexity_tier": "T3", "furigana": "来月[らいげつ]から新[あたら]しいクラスを担当[たんとう]することになった。", "sentence_source": "generated"}, {"text": "受付の仕事は山田さんが担当している。", "target_word": "担当", "complexity_tier": "T3", "furigana": "受付[うけつけ]の仕事[しごと]は山田[やまだ]さんが担当[たんとう]している。", "sentence_source": "generated"}, {"text": "先生は一年生の国語を担当しています。", "target_word": "担当", "complexity_tier": "T3", "furigana": "先生[せんせい]は一年生[いちねんせい]の国語[こくご]を担当[たんとう]しています。", "sentence_source": "generated"}, {"text": "会議の準備は、だれが担当するか決めましょう。", "target_word": "担当", "complexity_tier": "T3", "furigana": "会議[かいぎ]の準備[じゅんび]は、だれが担当[たんとう]するか決[き]めましょう。", "sentence_source": "generated"}, {"text": "私は店のそうじを担当していて、毎朝早く行きます。", "target_word": "担当", "complexity_tier": "T3", "furigana": "私[わたし]は店[みせ]のそうじを担当[たんとう]していて、毎朝[まいあさ]早[はや]く行[い]きます。", "sentence_source": "generated"}, {"text": "彼は営業を担当して三年になる。", "target_word": "担当", "complexity_tier": "T3", "furigana": "彼[かれ]は営業[えいぎょう]を担当[たんとう]して三年[さんねん]になる。", "sentence_source": "generated"}, {"text": "料理を担当する人と、かたづけを担当する人に分かれた。", "target_word": "担当", "complexity_tier": "T3", "furigana": "料理[りょうり]を担当[たんとう]する人[ひと]と、かたづけを担当[たんとう]する人[ひと]に分[わ]かれた。", "sentence_source": "generated"}, {"text": "担当する仕事が増えて、毎日いそがしい。", "target_word": "担当", "complexity_tier": "T3", "furigana": "担当[たんとう]する仕事[しごと]が増[ふ]えて、毎日[まいにち]いそがしい。", "sentence_source": "generated"}, {"text": "部長に、新しい商品の宣伝を担当するように言われた。", "target_word": "担当", "complexity_tier": "T3", "furigana": "部長[ぶちょう]に、新[あたら]しい商品[しょうひん]の宣伝[せんでん]を担当[たんとう]するように言[い]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担当", "label": "基本形"}, {"form": "担当する", "label": "サ変動詞（終止形）"}, {"form": "担当した", "label": "過去形"}, {"form": "担当している", "label": "継続形"}, {"form": "担当します", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "任された仕事を受け持って行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: かたづけ (Zipf 2.38)']::text[], 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窓", "is_correct": false, "explanation": "建物の開口部を表す語で、仕事の文には使えない。"}, {"text": "海", "is_correct": false, "explanation": "広い水の場所を表す語で、「私が〜します」の文では意味が通らない。"}, {"text": "担当", "is_correct": true, "explanation": "仕事を受け持つという意味で、「私が担当します」として文に合う。"}, {"text": "絵本", "is_correct": false, "explanation": "子ども向けの本を指す語で、仕事の文には合わない。"}], "explanations": {"窓": "建物の開口部を表す語で、仕事の文には使えない。", "海": "広い水の場所を表す語で、「私が〜します」の文では意味が通らない。", "担当": "仕事を受け持つという意味で、「私が担当します」として文に合う。", "絵本": "子ども向けの本を指す語で、仕事の文には合わない。"}, "sentence_index": 0, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家を担当にしてお金を借りた。", "explanation": "ここは〈担保〉の意味。担当は仕事を受け持つことで、お金を借りるときの抵当の意味にはならない。"}, {"text": "腰に担当を差していた。", "explanation": "同じ読みの〈短刀〉と混同しやすい。担当は仕事の受け持ちを表すので、腰に差す刃物の意味にはならない。"}, {"text": "重い荷物を担当して山を登った。", "explanation": "ここは〈担ぐ〉の意味。担当は仕事の受け持ちで、肩に荷物をのせて運ぶ意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湖", "is_correct": false, "explanation": "水をたたえた場所を表す語で、「営業を〜して」には結びつかない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書くための道具で、営業とは結びつかない。"}, {"text": "担当", "is_correct": true, "explanation": "「営業を担当して」で、営業の仕事を受け持つ意味になり、文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、営業とは結びつかない。"}], "explanations": {"湖": "水をたたえた場所を表す語で、「営業を〜して」には結びつかない。", "鉛筆": "書くための道具で、営業とは結びつかない。", "担当": "「営業を担当して」で、営業の仕事を受け持つ意味になり、文に合う。", "冷蔵庫": "食品を冷やす家電で、営業とは結びつかない。"}, "sentence_index": 6, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "けが人を担当に乗せて、病院まで運んだ。", "explanation": "ここは〈担架〉の意味。担当は仕事の受け持ちを表すので、人を乗せて運ぶ道具にはならない。"}, {"text": "家計の担当が重くて、毎月の支払いに困っている。", "explanation": "ここは〈負担〉の意味。担当は任された仕事のことで、お金の重さや支払いの苦しさには使わない。"}, {"text": "友人の悪だくみに担当してしまい、後で後悔した。", "explanation": "ここは〈加担〉の意味。担当は仕事を受け持つことで、悪いことに関わる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は来月から新しいクラスに担当します。", "corrected_sentence": "私は来月から新しいクラスを担当します。", "error_description": "「担当する」は担当する対象を「を」で示す他動詞。「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月は、私が新人を担当せるつもりです。", "corrected_sentence": "来月は、私が新人を担当するつもりです。", "error_description": "サ変動詞「担当する」の「する」の部分が「せる」になっている。「せる」は誤った活用で、正しくは「する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「担当の人」の「の」。担当を人を修飾する連体修飾の関係で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「担当を人が休み」は目的語の関係が成り立たず、文の形が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「担当へ人が休み」は行き先の意味にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「担当に人が休み」は相手を示す関係になり、「休みなので」へ続く意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「担当の人」の「の」。担当を人を修飾する連体修飾の関係で結ぶ。", "を": "「担当を人が休み」は目的語の関係が成り立たず、文の形が崩れる。", "へ": "「へ」は方向を示すため、「担当へ人が休み」は行き先の意味にならず不自然。", "に": "「担当に人が休み」は相手を示す関係になり、「休みなので」へ続く意味が通らない。"}, "error_tags": {"を": "目的語（格の誤用）", "へ": "方向（行き先）", "に": "与格（相手・受け手）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「担当が一つずつ質問に答えた」の主格。答えた人として担当を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「担当を」が答える相手のように読め、文の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「担当から答えた」は動作の主体として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「担当より答えた」と続かず、主語の位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "「担当が一つずつ質問に答えた」の主格。答えた人として担当を示す。", "を": "「を」は目的語を示すので、「担当を」が答える相手のように読め、文の意味が通らない。", "から": "「から」は起点を示すため、「担当から答えた」は動作の主体として不自然。", "より": "比較の「より」は「担当より答えた」と続かず、主語の位置に入らない。"}, "error_tags": {"を": "目的語（格の誤用）", "から": "起点（出どころ）", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の任務や責任を負い、それを取り扱うこと。また、その役割を果たす人。", "primary_collocate": null, "pronunciation": "たんとう", "ipa": "tantoː", "syllable_count": 4, "sentences": [{"text": "担当の山田が、すぐにお電話いたします。", "target_word": "担当", "complexity_tier": "T3", "furigana": "担当[たんとう]の山田[やまだ]が、すぐにお電話[でんわ]いたします。", "sentence_source": "generated"}, {"text": "担当の人が休みなので、明日もう一度来てください。", "target_word": "担当", "complexity_tier": "T3", "furigana": "担当[たんとう]の人[ひと]が休[やす]みなので、明日[あした]もう一度[いちど]来[き]てください。", "sentence_source": "generated"}, {"text": "修理の担当に、こわれた場所を説明した。", "target_word": "担当", "complexity_tier": "T3", "furigana": "修理[しゅうり]の担当[たんとう]に、こわれた場所[ばしょ]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "担当が変わったので、新しい人にあいさつをした。", "target_word": "担当", "complexity_tier": "T3", "furigana": "担当[たんとう]が変[か]わったので、新[あたら]しい人[ひと]にあいさつをした。", "sentence_source": "generated"}, {"text": "この件の担当はどなたですか。", "target_word": "担当", "complexity_tier": "T3", "furigana": "この件[けん]の担当[たんとう]はどなたですか。", "sentence_source": "generated"}, {"text": "お客様からの相談は、担当の田中さんがいつも丁寧に受けている。", "target_word": "担当", "complexity_tier": "T3", "furigana": "お客様[おきゃくさま]からの相談[そうだん]は、担当[たんとう]の田中[たなか]さんがいつも丁寧[ていねい]に受[う]けている。", "sentence_source": "generated"}, {"text": "苦情は、担当の部署に伝えておきます。", "target_word": "担当", "complexity_tier": "T3", "furigana": "苦情[くじょう]は、担当[たんとう]の部署[ぶしょ]に伝[つた]えておきます。", "sentence_source": "generated"}, {"text": "記者会見では、担当が一つずつ質問に答えた。", "target_word": "担当", "complexity_tier": "T3", "furigana": "記者会見[きしゃかいけん]では、担当[たんとう]が一つ[ひとつ]ずつ質問[しつもん]に答[こた]えた。", "sentence_source": "generated"}, {"text": "担当が代わり、手続きの方法も変わった。", "target_word": "担当", "complexity_tier": "T3", "furigana": "担当[たんとう]が代[か]わり、手続[てつづ]きの方法[ほうほう]も変[か]わった。", "sentence_source": "generated"}, {"text": "費用のことは、担当に聞けばすぐわかります。", "target_word": "担当", "complexity_tier": "T3", "furigana": "費用[ひよう]のことは、担当[たんとう]に聞[き]けばすぐわかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担当", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある件を受け持つ役割、またその係の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "「担当の山田」は、この件を受け持つ人を指す語として自然に入る。"}, {"text": "予算", "is_correct": false, "explanation": "「予算の山田」は人物の所属として成り立たず、電話をかける人にならない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は人を指さないため、「期限の山田」という人名の修飾にならない。"}, {"text": "文化", "is_correct": false, "explanation": "「文化の山田」は人物を示す修飾として不自然で、電話をかける主語にならない。"}], "explanations": {"担当": "「担当の山田」は、この件を受け持つ人を指す語として自然に入る。", "予算": "「予算の山田」は人物の所属として成り立たず、電話をかける人にならない。", "期限": "期限は人を指さないため、「期限の山田」という人名の修飾にならない。", "文化": "「文化の山田」は人物を示す修飾として不自然で、電話をかける主語にならない。"}, "sentence_index": 0, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "失敗の担当を取って、部長が辞めた。", "explanation": "〈責任〉の意味。担当は任された役目のことで、「責任を取る」（罪を引き受ける）の意味では使えない。"}, {"text": "腰に担当を差している侍がいた。", "explanation": "〈短刀〉の意味。担当は任務の意味で、刃物の名前にはならない。"}, {"text": "借金の担当に、家を入れた。", "explanation": "〈担保〉（抵当）の意味。担当は任務の意味で、借金の保証として入れる物件を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "「担当の部署」は、苦情を受け持つ部署を指す語として自然に入る。"}, {"text": "期待", "is_correct": false, "explanation": "「期待の部署」は部署の修飾として成り立たず、伝える先にならない。"}, {"text": "不安", "is_correct": false, "explanation": "「不安の部署」は組織を表す語として不自然で、伝える先にならない。"}, {"text": "感想", "is_correct": false, "explanation": "「感想の部署」は組織名の修飾として成り立たず、苦情の宛先にならない。"}], "explanations": {"担当": "「担当の部署」は、苦情を受け持つ部署を指す語として自然に入る。", "期待": "「期待の部署」は部署の修飾として成り立たず、伝える先にならない。", "不安": "「不安の部署」は組織を表す語として不自然で、伝える先にならない。", "感想": "「感想の部署」は組織名の修飾として成り立たず、苦情の宛先にならない。"}, "sentence_index": 6, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部長に担当されて、海外支社へ行くことになった。", "explanation": "〈任命〉（役職に就けること）の意味。担当は任された役目を指し、人を役目に就ける行為は表さない。"}, {"text": "新人が経理部に担当された。", "explanation": "〈配属〉の意味。担当は役目そのものを指し、人を部署に割り振る言い方ではない。"}, {"text": "業務の一部を外部に担当した。", "explanation": "〈委託〉（外部に任せること）の意味。担当は自分が受け持つことで、外部へ任せる文脈では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい担当で資料を渡しておきました。", "corrected_sentence": "新しい担当に資料を渡しておきました。", "error_description": "資料を受け取る相手を示すには「に」が必要。「で」は場所や手段を示すため、「担当で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53240, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "担当を決まったら、連絡します。", "corrected_sentence": "担当が決まったら、連絡します。", "error_description": "「決まる」は自動詞で、決まる対象の「担当」は「が」で示す。「担当を決まる」は「を」を使うため誤り。正しくは「担当が決まる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「以内に抑える」の「に」で、限度や到達点を示す。十万円以内という目標に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、抑えるの前に置くと「十万円以内が抑える」となり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、限度の範囲を表す文脈には合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す助詞で、抑えるの前に置くと意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「以内に抑える」の「に」で、限度や到達点を示す。十万円以内という目標に合う。", "が": "主語を示す助詞で、抑えるの前に置くと「十万円以内が抑える」となり不自然。", "へ": "方向を示す助詞で、限度の範囲を表す文脈には合わない。", "と": "相手や並列を示す助詞で、抑えるの前に置くと意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「広がりを抑える」の「を」で、抑える対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「広がりに抑える」は対象を示せず、不自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す助詞だが、「広がりで抑える」とは言わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「広がりから抑える」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「広がりを抑える」の「を」で、抑える対象を示す。", "に": "「広がりに抑える」は対象を示せず、不自然な文になる。", "で": "手段を示す助詞だが、「広がりで抑える」とは言わない。", "から": "起点を示す助詞で、「広がりから抑える」は成り立たない。"}, "error_tags": {"に": "位置・対象", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを下に押したり、こころや行動をじっとさせたり、かさを少なくしたりすることです。", "primary_collocate": null, "pronunciation": "おさえる", "ipa": "osaeɾɯ", "syllable_count": 4, "sentences": [{"text": "怒りを抑えて、落ち着いて話をした。", "target_word": "抑えて", "complexity_tier": "T3", "furigana": "怒[いか]りを抑[おさ]えて、落[お]ち着[つ]いて話[はなし]をした。", "sentence_source": "generated"}, {"text": "計画では、費用を十万円以内に抑える予定だ。", "target_word": "抑える", "complexity_tier": "T3", "furigana": "計画[けいかく]では、費用[ひよう]を十万円[じゅうまんえん]以内[いない]に抑[おさ]える予定[よてい]だ。", "sentence_source": "generated"}, {"text": "笑いを抑えようとしたが、どうしても我慢できなかった。", "target_word": "抑えよう", "complexity_tier": "T3", "furigana": "笑[わら]いを抑[おさ]えようとしたが、どうしても我慢[がまん]できなかった。", "sentence_source": "generated"}, {"text": "薬を飲んで、せきを抑えた。", "target_word": "抑えた", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んで、せきを抑[おさ]えた。", "sentence_source": "generated"}, {"text": "政府は、物価の上昇を抑える対策を発表した。", "target_word": "抑える", "complexity_tier": "T3", "furigana": "政府[せいふ]は、物価[ぶっか]の上昇[じょうしょう]を抑[おさ]える対策[たいさく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "エースが相手打線を二点に抑えて、チームが勝った。", "target_word": "抑えて", "complexity_tier": "T3", "furigana": "エースが相手[あいて]打線[だせん]を二点[にてん]に抑[おさ]えて、チームが勝[か]った。", "sentence_source": "generated"}, {"text": "感情を抑えられず、彼女は大声で泣いてしまった。", "target_word": "抑えられず", "complexity_tier": "T3", "furigana": "感情[かんじょう]を抑[おさ]えられず、彼女[かのじょ]は大声[おおごえ]で泣[な]いてしまった。", "sentence_source": "generated"}, {"text": "病気の広がりを抑えるため、みんながマスクをつけた。", "target_word": "抑える", "complexity_tier": "T3", "furigana": "病気[びょうき]の広[ひろ]がりを抑[おさ]えるため、みんながマスクをつけた。", "sentence_source": "generated"}, {"text": "食べすぎを抑えるために、夜はお菓子を食べないことにした。", "target_word": "抑える", "complexity_tier": "T3", "furigana": "食[た]べすぎを抑[おさ]えるために、夜[よる]はお菓子[かし]を食[た]べないことにした。", "sentence_source": "generated"}, {"text": "音量を抑えて、赤ちゃんが起きないようにテレビを見た。", "target_word": "抑えて", "complexity_tier": "T3", "furigana": "音量[おんりょう]を抑[おさ]えて、赤[あか]ちゃんが起[お]きないようにテレビを見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑える", "label": "辞書形"}, {"form": "抑えて", "label": "て形"}, {"form": "抑えた", "label": "過去形"}, {"form": "抑えない", "label": "否定形"}, {"form": "抑えられる", "label": "可能・受身形"}, {"form": "抑えよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "感情・動き・数量などが大きくならないよう、おさえて小さく保つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑えて", "is_correct": true, "explanation": "て形で「怒りを抑えて」と動作をつなぎ、後ろの「落ち着いて話をした」に続く。"}, {"text": "抑えろ", "is_correct": false, "explanation": "命令形なので、「、」の後に文が続く形では使えない。"}, {"text": "抑えよう", "is_correct": false, "explanation": "意向形は決意で文を結ぶ形で、「、」の後の文とつながらない。"}, {"text": "抑える", "is_correct": false, "explanation": "辞書形を「、」で続けると、後ろの文と接続できない。"}], "explanations": {"抑えて": "て形で「怒りを抑えて」と動作をつなぎ、後ろの「落ち着いて話をした」に続く。", "抑えろ": "命令形なので、「、」の後に文が続く形では使えない。", "抑えよう": "意向形は決意で文を結ぶ形で、「、」の後の文とつながらない。", "抑える": "辞書形を「、」で続けると、後ろの文と接続できない。"}, "sentence_index": 0, "correct_answer": "抑えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を抑えて、高く持ち上げた。", "explanation": "ここは〈持ち上げる〉の意味。抑えるは上から押さえて動かないよう保つ語で、持ち上げる動作の意味にはならない。"}, {"text": "真冬の寒さを抑えて、ずっと外で待った。", "explanation": "ここは〈我慢する・こらえる〉の意味。抑えるは感情や量、勢いを小さく保つ語で、寒さという感覚は我慢するもので、抑えるとは言わない。"}, {"text": "会社は売り場を抑えて、広く作り直した。", "explanation": "ここは〈広げる〉の意味。抑えるは小さく保つ語で、面積を広くする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑えられず", "is_correct": true, "explanation": "可能形の否定て形。抑えられなかったので泣いてしまったという因果の流れに合う。"}, {"text": "抑えます", "is_correct": false, "explanation": "丁寧形で、普通体の文の途中に入れると文体が合わず、「、」以下と続かない。"}, {"text": "抑えよう", "is_correct": false, "explanation": "意向形は決意で文を結ぶ形で、「、」の後の文とつながらない。"}, {"text": "抑えてくれ", "is_correct": false, "explanation": "依頼の形で、後ろの過去の出来事の文と接続できない。"}], "explanations": {"抑えられず": "可能形の否定て形。抑えられなかったので泣いてしまったという因果の流れに合う。", "抑えます": "丁寧形で、普通体の文の途中に入れると文体が合わず、「、」以下と続かない。", "抑えよう": "意向形は決意で文を結ぶ形で、「、」の後の文とつながらない。", "抑えてくれ": "依頼の形で、後ろの過去の出来事の文と接続できない。"}, "sentence_index": 6, "correct_answer": "抑えられず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長年の記録を抑えて、新記録を作った。", "explanation": "ここは〈塗り替える〉の意味。抑えるは勢いや量を小さくする語で、記録を超える意味では使わない。"}, {"text": "彼は目標を抑えて、ひたすら走った。", "explanation": "ここは〈目指す〉の意味。抑えるは勢いや量を小さくする語で、目標に向かう意味は表さない。"}, {"text": "大切なメールを抑えて、すぐに返信した。", "explanation": "ここは〈開いて読む〉の意味。抑えるはものを押さえて動かないよう保つ語で、メールを開く・読む意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨音が大きくても、彼は声が抑えて話し続けた。", "corrected_sentence": "雨音が大きくても、彼は声を抑えて話し続けた。", "error_description": "助詞の誤り。抑えるは「〜を抑える」と目的語を取るので、「声が抑えて」は誤り。正しくは「声を抑えて」。「が」は主語を示すため、目的語の位置には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "抑える", "is_correct": true, "explanation": "辞書形。「予定だ」の前に置く基本形で、文の内容に合う。"}, {"text": "抑えて", "is_correct": false, "explanation": "て形なので、「予定だ」に直接続かず文が成り立たない。"}, {"text": "抑えず", "is_correct": false, "explanation": "ず形なので、「予定だ」の前には置けず文が成り立たない。"}, {"text": "抑えろ", "is_correct": false, "explanation": "命令形なので、「予定だ」の前には置けず文が成り立たない。"}], "correct_form": "抑える", "base_form": "抑える", "form_label": "辞書形", "sentence_index": 1, "explanations": {"抑える": "辞書形。「予定だ」の前に置く基本形で、文の内容に合う。", "抑えて": "て形なので、「予定だ」に直接続かず文が成り立たない。", "抑えず": "ず形なので、「予定だ」の前には置けず文が成り立たない。", "抑えろ": "命令形なので、「予定だ」の前には置けず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53245, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その知らせに、彼は怒りを抑えれず、大声で叫んでしまった。", "corrected_sentence": "その知らせに、彼は怒りを抑えられず、大声で叫んでしまった。", "error_description": "可能形の誤り。抑えるは一段動詞なので、可能形は「抑えられる」。「抑えれず」は誤りで、正しくは「抑えられず」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "抑える", "is_correct": true, "explanation": "辞書形。「ため」に続けて目的を表す形で、文の内容に合う。"}, {"text": "抑えます", "is_correct": false, "explanation": "丁寧形なので、普通体の「ため」の前には続かず目的を表せない。"}, {"text": "抑えられ", "is_correct": false, "explanation": "可能・受身の語幹で単独では「ため」の前に置けず、文が成り立たない。"}, {"text": "抑えさせ", "is_correct": false, "explanation": "使役の語幹で「ため」に続かず、目的を表す文として成り立たない。"}], "correct_form": "抑える", "base_form": "抑える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"抑える": "辞書形。「ため」に続けて目的を表す形で、文の内容に合う。", "抑えます": "丁寧形なので、普通体の「ため」の前には続かず目的を表せない。", "抑えられ": "可能・受身の語幹で単独では「ため」の前に置けず、文が成り立たない。", "抑えさせ": "使役の語幹で「ため」に続かず、目的を表す文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「浮世の付き合い」は浮世を修飾する格助詞で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「浮世を付き合い」は目的語として不自然で、名詞句が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "「浮世が付き合い」は主語が不自然で、文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「浮世に付き合い」は名詞句として不自然。付き合いの相手は「と」で示す。"}], "correct_answer": "の", "explanations": {"の": "「浮世の付き合い」は浮世を修飾する格助詞で、正しい。", "を": "「浮世を付き合い」は目的語として不自然で、名詞句が成立しない。", "が": "「浮世が付き合い」は主語が不自然で、文の意味が崩れる。", "に": "「浮世に付き合い」は名詞句として不自然。付き合いの相手は「と」で示す。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "に": "格の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "このよのなかの、ふつうのせかいです。", "primary_collocate": null, "pronunciation": "うきよ", "ipa": "ɯkijo", "syllable_count": 3, "sentences": [{"text": "山の中の寺にいると、浮世の騒がしさが遠く感じられる。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]の寺[てら]にいると、浮世[うきよ]の騒[さわ]がしさが遠[とお]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "彼は浮世の付き合いが苦手で、いつも一人で本を読んでいる。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "彼[かれ]は浮世[うきよ]の付[つ]き合[あ]いが苦手[にがて]で、いつも一人[ひとり]で本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "浮世は楽しいことばかりではないが、悪いことばかりでもない。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]は楽[たの]しいことばかりではないが、悪[わる]いことばかりでもない。", "sentence_source": "generated"}, {"text": "長い休みをとって、浮世を忘れて海辺で過ごした。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "長[なが]い休[やす]みをとって、浮世[うきよ]を忘[わす]れて海辺[うみべ]で過[す]ごした。", "sentence_source": "generated"}, {"text": "浮世の暮らしは、お金がなければ思うようにならない。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]の暮[く]らしは、お金[かね]がなければ思[おも]うようにならない。", "sentence_source": "generated"}, {"text": "老人は「浮世とはそういうものだ」と笑った。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "老人[ろうじん]は「浮世[うきよ]とはそういうものだ」と笑[わら]った。", "sentence_source": "generated"}, {"text": "浮世に疲れた人々が、この静かな島を訪れる。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]に疲[つか]れた人々[ひとびと]が、この静[しず]かな島[しま]を訪[おとず]れる。", "sentence_source": "generated"}, {"text": "浮世の義理で、行きたくない会にも出ることになった。", "target_word": "浮世", "complexity_tier": "T4", "furigana": "浮世[うきよ]の義理[ぎり]で、行[い]きたくない会[かい]にも出[で]ることになった。", "sentence_source": "generated"}, {"text": "私は浮世の苦労を背負いながら、毎日仕事をして家族を支えている。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "私[わたし]は浮世[うきよ]の苦労[くろう]を背負[せお]いながら、毎日[まいにち]仕事[しごと]をして家族[かぞく]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "浮世のしがらみから離れて、のんびり暮らしたい。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]のしがらみから離[はな]れて、のんびり暮[く]らしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮世", "label": "基本形"}], "register": "やや文語的", "sense_fingerprint": "この世の中、ふつうの世俗の世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮世", "is_correct": true, "explanation": "「浮世の騒がしさ」は、この世の中の騒がしさを表し、文脈に合う。"}, {"text": "花", "is_correct": false, "explanation": "「花の騒がしさ」は意味が通らず、文脈に合わない。"}, {"text": "冬", "is_correct": false, "explanation": "「冬の騒がしさ」は不自然で、寺で遠く感じる騒がしさの文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆の騒がしさ」は文脈に合わず、意味が通らない。"}], "explanations": {"浮世": "「浮世の騒がしさ」は、この世の中の騒がしさを表し、文脈に合う。", "花": "「花の騒がしさ」は意味が通らず、文脈に合わない。", "冬": "「冬の騒がしさ」は不自然で、寺で遠く感じる騒がしさの文脈に合わない。", "鉛筆": "「鉛筆の騒がしさ」は文脈に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "浮世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い休みをとって、浮世を読みながら海辺で過ごした。", "explanation": "ここは〈本〉の意味。浮世は俗世のことで、読める文字媒体ではない。"}, {"text": "長い休みをとって、浮世の写真を撮りながら海辺で過ごした。", "explanation": "ここは〈風景〉の意味。浮世は俗世のことで、写真に写す景色を指さない。"}, {"text": "長い休みをとって、浮世を買い込んで海辺で過ごした。", "explanation": "ここは〈食料〉の意味。浮世は俗世のことで、買い込む品物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮世", "is_correct": true, "explanation": "「浮世に疲れた人々」は俗世に疲れた人を表し、文脈に合う。"}, {"text": "窓", "is_correct": false, "explanation": "「窓に疲れた人々」は意味が通らず、文脈に合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "「鍋に疲れた人々」は意味が通らず、島を訪れる文脈に合わない。"}, {"text": "寺", "is_correct": false, "explanation": "「寺に疲れた人々」は不自然で、島を訪れる文脈に合わない。"}], "explanations": {"浮世": "「浮世に疲れた人々」は俗世に疲れた人を表し、文脈に合う。", "窓": "「窓に疲れた人々」は意味が通らず、文脈に合わない。", "鍋": "「鍋に疲れた人々」は意味が通らず、島を訪れる文脈に合わない。", "寺": "「寺に疲れた人々」は不自然で、島を訪れる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "浮世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空に浮世の星が輝いて、きれいだ。", "explanation": "〈浮世〉を星の修飾に使うのは誤り。俗世の意味では天体を表せない。"}, {"text": "浮世のような景色の島で、のんびり暮らしたい。", "explanation": "ここは〈天国〉の意味。浮世は俗世のことで、眺めの美しさを表す語ではない。"}, {"text": "浮世の湖が、朝霧に包まれている。", "explanation": "ここは〈湖〉の意味。浮世は俗世のことで、霧に包まれる水面を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の人々は、浮世が喧騒を離れて暮らしている。", "corrected_sentence": "この町の人々は、浮世の喧騒を離れて暮らしている。", "error_description": "「喧騒を離れる」の主体は人々で、「浮世が」は二つ目の主語となり誤り。正しくは「浮世の喧騒」と、浮世が喧騒を修飾する「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は浮世を付き合いを大事にしている。", "corrected_sentence": "祖母は浮世の付き合いを大事にしている。", "error_description": "「浮世の付き合い」の「の」を「を」に変えると、「浮世を」が付き合いの目的語になり不自然になる。浮世は付き合いを修飾するので「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「浮世の苦労」は浮世を修飾する格助詞で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「浮世を苦労を忘れて」は目的語が二つになり、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「浮世が苦労を忘れて」は主語が不自然で、文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「浮世に苦労」は対象の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「浮世の苦労」は浮世を修飾する格助詞で、正しい。", "を": "「浮世を苦労を忘れて」は目的語が二つになり、不自然。", "が": "「浮世が苦労を忘れて」は主語が不自然で、文の意味が崩れる。", "に": "「浮世に苦労」は対象の関係が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "に": "対象の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「浮世と呼ばれる」は、言い換えの対象を示す格助詞で、正しい。"}, {"text": "で", "is_correct": false, "explanation": "「浮世で呼ばれる」は手段や場を示し、名付けの関係を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、呼ばれる関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、呼ばれる関係が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「浮世と呼ばれる」は、言い換えの対象を示す格助詞で、正しい。", "で": "「浮世で呼ばれる」は手段や場を示し、名付けの関係を表せない。", "から": "起点の「から」では、呼ばれる関係が成り立たない。", "より": "比較の「より」では、呼ばれる関係が成り立たない。"}, "error_tags": {"で": "手段の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "日常の世界や世俗のこと。また、江戸時代の町人の文化を指すこともあります。", "primary_collocate": null, "pronunciation": "うきよ", "ipa": "ɯkijo", "syllable_count": 3, "sentences": [{"text": "江戸の町人が育てた浮世の文化は、今も多くの人に親しまれている。", "target_word": "浮世", "complexity_tier": "T4", "furigana": "江戸[えど]の町人[ちょうにん]が育[そだ]てた浮世[うきよ]の文化[ぶんか]は、今[いま]も多[おお]くの人[ひと]に親[した]しまれている。", "sentence_source": "generated"}, {"text": "浮世の苦労を忘れて、山の温泉でゆっくり過ごした。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]の苦労[くろう]を忘[わす]れて、山[やま]の温泉[おんせん]でゆっくり過[す]ごした。", "sentence_source": "generated"}, {"text": "江戸時代の町人たちは、浮世の楽しみを芝居や祭りに求めた。", "target_word": "浮世", "complexity_tier": "T4", "furigana": "江戸時代[えどじだい]の町人[ちょうにん]たちは、浮世[うきよ]の楽[たの]しみを芝居[しばい]や祭[まつ]りに求[もと]めた。", "sentence_source": "generated"}, {"text": "彼は浮世を離れ、静かな山寺で暮らしている。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "彼[かれ]は浮世[うきよ]を離[はな]れ、静[しず]かな山寺[やまでら]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "浮世の義理に縛られて、自分の時間がなかなか持てない。", "target_word": "浮世", "complexity_tier": "T4", "furigana": "浮世[うきよ]の義理[ぎり]に縛[しば]られて、自分[じぶん]の時間[じかん]がなかなか持[も]てない。", "sentence_source": "generated"}, {"text": "井原西鶴は、浮世の人々の生き方を小説に描いた。", "target_word": "浮世", "complexity_tier": "T4", "furigana": "井原西鶴[いはらさいかく]は、浮世[うきよ]の人々[ひとびと]の生[い]き方[かた]を小説[しょうせつ]に描[えが]いた。", "sentence_source": "generated"}, {"text": "浮世の噂など気にせず、自分の道を進むつもりだ。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "浮世[うきよ]の噂[うわさ]など気[き]にせず、自分[じぶん]の道[みち]を進[すす]むつもりだ。", "sentence_source": "generated"}, {"text": "江戸の人々は、浮世と呼ばれる町人文化を大いに楽しんだ。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "江戸[えど]の人々[ひとびと]は、浮世[うきよ]と呼[よ]ばれる町人[ちょうにん]文化[ぶんか]を大[おお]いに楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "祖母は「浮世は思うようにならないものだ」とよく言っていた。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "祖母[そぼ]は「浮世[うきよ]は思[おも]うようにならないものだ」とよく言[い]っていた。", "sentence_source": "generated"}, {"text": "旅に出ると、浮世の悩みが小さく思えてくる。", "target_word": "浮世", "complexity_tier": "T3", "furigana": "旅[たび]に出[で]ると、浮世[うきよ]の悩[なや]みが小[ちい]さく思[おも]えてくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮世", "label": "基本形"}], "register": "やや文語的", "sense_fingerprint": "世俗の世の中、また江戸の町人文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮世", "is_correct": true, "explanation": "「浮世の文化」は江戸の町人が育てた文化を指し、文脈に合う。"}, {"text": "雲", "is_correct": false, "explanation": "「雲の文化」は意味が通らず、江戸の町人文化とは結びつかない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓の文化」は意味が通らず、江戸の町人文化とは結びつかない。"}, {"text": "岩", "is_correct": false, "explanation": "「岩の文化」は一般的な語として成立せず、江戸の町人文化とは結びつかない。"}], "explanations": {"浮世": "「浮世の文化」は江戸の町人が育てた文化を指し、文脈に合う。", "雲": "「雲の文化」は意味が通らず、江戸の町人文化とは結びつかない。", "窓": "「窓の文化」は意味が通らず、江戸の町人文化とは結びつかない。", "岩": "「岩の文化」は一般的な語として成立せず、江戸の町人文化とは結びつかない。"}, "sentence_index": 0, "correct_answer": "浮世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは、浮世で鬼ごっこをして遊んだ。", "explanation": "ここは〈公園〉の意味。浮世は俗世のことで、遊び場所を指さない。"}, {"text": "祖母は、浮世をよく読み聞かせてくれた。", "explanation": "ここは〈絵本〉の意味。浮世は俗世のことで、読み聞かせる本を指さない。"}, {"text": "庭に咲いた浮世を、そっと切って部屋に飾った。", "explanation": "ここは〈花〉の意味。浮世は俗世のことで、切って飾れる植物を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮世", "is_correct": true, "explanation": "「浮世の噂」は俗世の噂を表し、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の噂」は文脈に合わず、気にせずという意味に合わない。"}, {"text": "味噌汁", "is_correct": false, "explanation": "「味噌汁の噂」は意味が通らない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆の噂」は意味が通らず、気にせず進むという文脈に合わない。"}], "explanations": {"浮世": "「浮世の噂」は俗世の噂を表し、文脈に合う。", "天気": "「天気の噂」は文脈に合わず、気にせずという意味に合わない。", "味噌汁": "「味噌汁の噂」は意味が通らない。", "鉛筆": "「鉛筆の噂」は意味が通らず、気にせず進むという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "浮世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先で、浮世の駅から電車に乗った。", "explanation": "ここは〈駅〉の意味。浮世は俗世のことで、電車の発着する場所を指さない。"}, {"text": "夏休みに、浮世に乗って遠くの島へ出かけた。", "explanation": "ここは〈船〉の意味。浮世は俗世のことで、乗り物を指さない。"}, {"text": "祖母は、浮世を温めて夕食に出した。", "explanation": "ここは〈料理〉の意味。浮世は俗世のことで、温めて出せる食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "江戸の町人たちは、浮世が娯楽を楽しんだ。", "corrected_sentence": "江戸の町人たちは、浮世の娯楽を楽しんだ。", "error_description": "「浮世」は楽しむ主体ではなく、娯楽の範囲を示す。「浮世が」は誤りで、正しくは「浮世の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53256, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅の途中で、浮世絵を忘れる時間が一番楽しい。", "corrected_sentence": "旅の途中で、浮世を忘れる時間が一番楽しい。", "error_description": "「浮世」を「浮世絵」に変えると絵画の意味になり、俗世を忘れるという文に合わない。正しくは「浮世」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「彫っていた」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「彫師を」と人を目的語にすると、版を彫る動作の主体が示せない。"}, {"text": "に", "is_correct": false, "explanation": "「彫師に」は相手を表すので、「彫っていた」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「彫師から版を彫っていた」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「彫っていた」の主語を示す「が」。", "を": "「彫師を」と人を目的語にすると、版を彫る動作の主体が示せない。", "に": "「彫師に」は相手を表すので、「彫っていた」の主語にはならない。", "から": "「から」は起点を示し、「彫師から版を彫っていた」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「彫師の作品」で、彫師が作った作品という作者を示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「彫師が作品だ」では主語にならず、名詞同士をつなげない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「彫師を作品だ」と名詞の後に続けると成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「彫師に作品だ」は文として成り立たず、名詞をつなぐ用法もない。"}], "correct_answer": "の", "explanations": {"の": "「彫師の作品」で、彫師が作った作品という作者を示す「の」。", "が": "「彫師が作品だ」では主語にならず、名詞同士をつなげない。", "を": "「を」は目的語を示すので、「彫師を作品だ」と名詞の後に続けると成り立たない。", "に": "「彫師に作品だ」は文として成り立たず、名詞をつなぐ用法もない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木に絵や文字を刻む人です。版画を作るために、板に形を削ります。昔からある職人です。", "primary_collocate": null, "pronunciation": "ほりし", "ipa": "horiɕi", "syllable_count": 3, "sentences": [{"text": "彫師は木の板に絵を刻む職人だ。", "target_word": "彫師", "complexity_tier": "T2", "furigana": "彫師[ほりし]は木[き]の板[いた]に絵[え]を刻[きざ]む職人[しょくにん]だ。", "sentence_source": "generated"}, {"text": "町の小さな店で、彫師が年賀状用の版を彫っていた。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "町[まち]の小[ちい]さな店[みせ]で、彫師[ほりし]が年賀状用[ねんがじょうよう]の版[はん]を彫[ほ]っていた。", "sentence_source": "generated"}, {"text": "彫師の指は、長い仕事のせいで硬くなっている。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]の指[ゆび]は、長[なが]い仕事[しごと]のせいで硬[かた]くなっている。", "sentence_source": "generated"}, {"text": "昔の本は、彫師が文字を一つずつ板に彫って作った。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "昔[むかし]の本[ほん]は、彫師[ほりし]が文字[もじ]を一[ひと]つずつ板[いた]に彫[ほ]って作[つく]った。", "sentence_source": "generated"}, {"text": "彫師になるには、長い間先輩のもとで学ばなければならない。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]になるには、長[なが]い間[あいだ]先輩[せんぱい]のもとで学[まな]ばなければならない。", "sentence_source": "generated"}, {"text": "兄は彫師を目指して、有名な工房に弟子入りした。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "兄[あに]は彫師[ほりし]を目指[めざ]して、有名[ゆうめい]な工房[こうぼう]に弟子入[でしい]りした。", "sentence_source": "generated"}, {"text": "彫師が削った木くずが、床に山のように積もった。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]が削[けず]った木[き]くずが、床[ゆか]に山[やま]のように積[つ]もった。", "sentence_source": "generated"}, {"text": "この版画は、有名な彫師の作品だ。", "target_word": "彫師", "complexity_tier": "T2", "furigana": "この版画[はんが]は、有名[ゆうめい]な彫師[ほりし]の作品[さくひん]だ。", "sentence_source": "generated"}, {"text": "彫師は小さな刃物を使って、細かい模様を彫る。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]は小[ちい]さな刃物[はもの]を使[つか]って、細[こま]かい模様[もよう]を彫[ほ]る。", "sentence_source": "generated"}, {"text": "テレビで彫師の仕事を見て、私も木を彫ってみたくなった。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "テレビで彫師[ほりし]の仕事[しごと]を見[み]て、私[わたし]も木[き]を彫[ほ]ってみたくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫師", "label": "基本形"}], "register": "標準", "sense_fingerprint": "木の板に絵や文字を刻む昔ながらの職人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫師", "is_correct": true, "explanation": "木の板に絵を刻む職人を指す人物名詞で、文の主語になる。"}, {"text": "版画", "is_correct": false, "explanation": "版画は刷り上げた作品のことで、絵を刻む人にはならない。"}, {"text": "木材", "is_correct": false, "explanation": "木材は彫る素材で、職人を表す語ではないので主語にならない。"}, {"text": "刃物", "is_correct": false, "explanation": "刃物は彫るための道具で、職人を表す語としては使えない。"}], "explanations": {"彫師": "木の板に絵を刻む職人を指す人物名詞で、文の主語になる。", "版画": "版画は刷り上げた作品のことで、絵を刻む人にはならない。", "木材": "木材は彫る素材で、職人を表す語ではないので主語にならない。", "刃物": "刃物は彫るための道具で、職人を表す語としては使えない。"}, "sentence_index": 0, "correct_answer": "彫師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彫師が、庭の松を一本ずつ手入れした。", "explanation": "ここは〈庭師〉の意味。松の手入れをするのは庭師で、彫師は木に絵や文字を刻む職人。"}, {"text": "彫師が本の企画を決め、印刷所に注文した。", "explanation": "ここは〈版元〉の意味。企画を決めて印刷所に注文するのは版元で、彫師は版木を彫る職人。"}, {"text": "彫師は紙に色を重ね、一枚ずつ刷り上げた。", "explanation": "ここは〈摺師〉の意味。色を重ねて紙に刷るのは摺師の仕事で、彫師は版木を彫る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫師", "is_correct": true, "explanation": "「彫師が削った」で、木を削る職人が主語になる。"}, {"text": "墨", "is_correct": false, "explanation": "墨は書画に使う材料で、木くずを削る主語にはならない。"}, {"text": "和紙", "is_correct": false, "explanation": "和紙は紙の一種で、削る動作の主語にはならない。"}, {"text": "作業台", "is_correct": false, "explanation": "作業台は作業をする台で、削る動作の主語にはならない。"}], "explanations": {"彫師": "「彫師が削った」で、木を削る職人が主語になる。", "墨": "墨は書画に使う材料で、木くずを削る主語にはならない。", "和紙": "和紙は紙の一種で、削る動作の主語にはならない。", "作業台": "作業台は作業をする台で、削る動作の主語にはならない。"}, "sentence_index": 6, "correct_answer": "彫師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彫師は、下絵の輪郭線を筆で丁寧に描いた。", "explanation": "ここは〈絵師〉の意味。下絵の線を描くのは絵師で、彫師は描いた下絵をもとに版木を彫る。"}, {"text": "彫師で板を削ると、細かい線が出る。", "explanation": "ここは〈刃物〉の意味。道具の刃物の代わりに人を置くと、道具として意味が通らない。"}, {"text": "彫師が、客の注文を受けて大量に刷った。", "explanation": "ここは〈印刷屋〉の意味。大量に刷るのは印刷屋の仕事で、彫師は版木を彫るのが役目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作品は、彫師を技が光っている。", "corrected_sentence": "この作品は、彫師の技が光っている。", "error_description": "「彫師の技」が正しい形。「彫師」と「技」は「の」で結ぶ。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は彫師を修行を、三年間続けた。", "corrected_sentence": "兄は彫師の修行を、三年間続けた。", "error_description": "「彫師の修行」が正しい形。「彫師」と「修行」は「の」で結ぶ。「を」を続けると目的語が重なり、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「彫師が版木に彫る」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「下絵を」の後に「彫師を」を続けると目的語が重なり、主語が示せない。"}, {"text": "で", "is_correct": false, "explanation": "「彫師で」では人を手段のように扱うことになり、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、版木を彫る主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「彫師が版木に彫る」の主語を示す「が」。", "を": "「下絵を」の後に「彫師を」を続けると目的語が重なり、主語が示せない。", "で": "「彫師で」では人を手段のように扱うことになり、主語を示せない。", "へ": "「へ」は方向を示すので、版木を彫る主体を表せない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「彫る」の主語を示す「が」で、彫師が版木を彫る様子を表す。"}, {"text": "を", "is_correct": false, "explanation": "「彫師を」と人を目的語にすると、版木を彫る主体が立たず、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「彫師に」は相手を示すので、「彫る」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「彫師から版木を彫る様子」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「彫る」の主語を示す「が」で、彫師が版木を彫る様子を表す。", "を": "「彫師を」と人を目的語にすると、版木を彫る主体が立たず、文が崩れる。", "に": "「彫師に」は相手を示すので、「彫る」の主語にはならない。", "から": "「から」は起点を示し、「彫師から版木を彫る様子」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "浮世絵などの木版画を作る際、木版に絵柄を彫る専門の職人。", "primary_collocate": null, "pronunciation": "ほりし", "ipa": "horiɕi", "syllable_count": 3, "sentences": [{"text": "制作は、絵師、彫師、摺師の役割分担によって進められます。", "target_word": "彫師", "complexity_tier": "T4", "furigana": "制作[せいさく]は、絵師[えし]、彫師[ほりし]、摺師[すりし]の役割分担[やくわりぶんたん]によって進[すす]められます。", "sentence_source": "mined"}, {"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "彫師", "complexity_tier": "T4", "furigana": "絵師[えし]の描[えが]いた下絵[したえ]を彫師[ほりし]が版木[はんぎ]に彫[ほ]り、摺師[すりし]が紙[かみ]に印刷[いんさつ]するという複雑[ふくざつ]な工程[こうてい]を経[へ]ます。", "sentence_source": "mined"}, {"text": "彫師は、桜の板に細い線を一本ずつ彫っていく。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]は、桜[さくら]の板[いた]に細[ほそ]い線[せん]を一本[いっぽん]ずつ彫[ほ]っていく。", "sentence_source": "generated"}, {"text": "腕のよい彫師がいなければ、浮世絵の細かい髪の毛は表せない。", "target_word": "彫師", "complexity_tier": "T4", "furigana": "腕[うで]のよい彫師[ほりし]がいなければ、浮世絵[うきよえ]の細[こま]かい髪[かみ]の毛[け]は表[あらわ]せない。", "sentence_source": "generated"}, {"text": "彫師の仕事は、絵師の下絵を忠実に版木へ写すことだ。", "target_word": "彫師", "complexity_tier": "T4", "furigana": "彫師[ほりし]の仕事[しごと]は、絵師[えし]の下絵[したえ]を忠実[ちゅうじつ]に版木[はんぎ]へ写[うつ]すことだ。", "sentence_source": "generated"}, {"text": "彼は十年の修行を経て、一人前の彫師になった。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彼[かれ]は十年[じゅうねん]の修行[しゅぎょう]を経[へ]て、一人前[いちにんまえ]の彫師[ほりし]になった。", "sentence_source": "generated"}, {"text": "彫師が使う彫刻刀は、先が鋭くて手入れが欠かせない。", "target_word": "彫師", "complexity_tier": "T4", "furigana": "彫師[ほりし]が使[つか]う彫刻刀[ちょうこくとう]は、先[さき]が鋭[するど]くて手入[ていれ]れが欠[か]かせない。", "sentence_source": "generated"}, {"text": "展示会では、彫師が実際に版木を彫る様子を見学できた。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "展示会[てんじかい]では、彫師[ほりし]が実際[じっさい]に版木[はんぎ]を彫[ほ]る様子[ようす]を見学[けんがく]できた。", "sentence_source": "generated"}, {"text": "彫師の祖父は、毎日朝早くから作業場に座っていた。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "彫師[ほりし]の祖父[そふ]は、毎日[まいにち]朝早[あさはや]くから作業場[さぎょうば]に座[すわ]っていた。", "sentence_source": "generated"}, {"text": "絵師と彫師の息が合うと、美しい版画ができあがる。", "target_word": "彫師", "complexity_tier": "T3", "furigana": "絵師[えし]と彫師[ほりし]の息[いき]が合[あ]うと、美[うつく]しい版画[はんが]ができあがる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫師", "label": "基本形"}], "register": "標準", "sense_fingerprint": "木版画で版木に絵柄を彫る専門職人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫師", "is_correct": true, "explanation": "「絵師、彫師、摺師」の一人で、版木に絵柄を彫る職人を指す。"}, {"text": "版木", "is_correct": false, "explanation": "版木は彫られる木の板で、人の役割を表す語ではないので並べられない。"}, {"text": "下絵", "is_correct": false, "explanation": "下絵は絵の下書きで、職人の役割分担の一つにはならない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は印刷する素材で、職人の役割として並べることはできない。"}], "explanations": {"彫師": "「絵師、彫師、摺師」の一人で、版木に絵柄を彫る職人を指す。", "版木": "版木は彫られる木の板で、人の役割を表す語ではないので並べられない。", "下絵": "下絵は絵の下書きで、職人の役割分担の一つにはならない。", "紙": "紙は印刷する素材で、職人の役割として並べることはできない。"}, "sentence_index": 0, "correct_answer": "彫師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彫師が、庭の松を一本ずつ手入れした。", "explanation": "ここは〈庭師〉の意味。松の手入れをするのは庭師で、彫師は木版に絵柄を彫る職人。"}, {"text": "彫師は紙に色を重ね、一枚ずつ版画を仕上げた。", "explanation": "ここは〈摺師〉の意味。色を重ねて紙に刷るのは摺師の仕事で、彫師は版木を彫る。"}, {"text": "彫師が白い紙に下絵を描き、構図を決めた。", "explanation": "ここは〈絵師〉の意味。下絵を描いて構図を決めるのは絵師で、彫師は下絵をもとに版木を彫る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫師", "is_correct": true, "explanation": "「彫師が使う彫刻刀」で、道具を使って版木を彫る職人を指す。"}, {"text": "版画", "is_correct": false, "explanation": "版画は作品のことで、彫刻刀を使う主語にはならない。"}, {"text": "墨", "is_correct": false, "explanation": "墨は書画に使う黒い材料で、彫刻刀を使う人にはならない。"}, {"text": "和紙", "is_correct": false, "explanation": "和紙は紙の一種で、彫刻刀を使う主語にはならない。"}], "explanations": {"彫師": "「彫師が使う彫刻刀」で、道具を使って版木を彫る職人を指す。", "版画": "版画は作品のことで、彫刻刀を使う主語にはならない。", "墨": "墨は書画に使う黒い材料で、彫刻刀を使う人にはならない。", "和紙": "和紙は紙の一種で、彫刻刀を使う主語にはならない。"}, "sentence_index": 6, "correct_answer": "彫師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彫師が作品の企画を決め、出版の段取りを組んだ。", "explanation": "ここは〈版元〉の意味。企画や出版の段取りを決めるのは版元で、彫師は版木を彫る職人。"}, {"text": "彫師で木を削ると、細かい線が出る。", "explanation": "ここは〈鑿〉の意味。道具の鑿の代わりに人を置くと、道具として意味が通らない。"}, {"text": "彫師が、和紙を一枚ずつ漉いた。", "explanation": "ここは〈紙職人〉の意味。和紙を漉く仕事は紙職人のもので、彫師は版木を彫る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彫師を腕前は、版画の仕上がりを左右する。", "corrected_sentence": "彫師の腕前は、版画の仕上がりを左右する。", "error_description": "「彫師の腕前」が正しい形。「彫師」と「腕前」は「の」で結ぶ。「を」は動作の目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53258, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は彫師を弟子入りして、三年修行した。", "corrected_sentence": "彼は彫師に弟子入りして、三年修行した。", "error_description": "「彫師に弟子入りする」が正しい形。「弟子入り」は師事する相手を「に」で示すので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「版木を摺りました」で、摺る対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「版木が摺りました」は、版木が主語となって刷ったことになり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「版木と摺りました」は、版木と一緒に刷るという意味になり、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「版木へ摺りました」は方向を示す「へ」で、対象を取る文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「版木を摺りました」で、摺る対象を示す「を」。", "が": "「版木が摺りました」は、版木が主語となって刷ったことになり、不自然。", "と": "「版木と摺りました」は、版木と一緒に刷るという意味になり、目的語にならない。", "へ": "「版木へ摺りました」は方向を示す「へ」で、対象を取る文には合わない。"}, "error_tags": {"が": "主語", "と": "共同・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「魚の絵を摺りました」で、摺る対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「魚の絵に摺りました」は、絵の上に刷るという意味になりにくく、対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「魚の絵の摺りました」は所属の「の」で、動詞の目的語を導けない。"}, {"text": "と", "is_correct": false, "explanation": "「魚の絵と摺りました」は一緒に刷るという意味になり、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「魚の絵を摺りました」で、摺る対象を示す「を」。", "に": "「魚の絵に摺りました」は、絵の上に刷るという意味になりにくく、対象を示せない。", "の": "「魚の絵の摺りました」は所属の「の」で、動詞の目的語を導けない。", "と": "「魚の絵と摺りました」は一緒に刷るという意味になり、目的語にならない。"}, "error_tags": {"に": "方向・対象の「に」", "の": "修飾の「の」", "と": "共同・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かみにインクをぬって、えをうつします。", "primary_collocate": null, "pronunciation": "する", "ipa": "sɯɾɯ", "syllable_count": 2, "sentences": [{"text": "版木に墨を塗って、紙に絵を摺ります。", "target_word": "摺ります", "complexity_tier": "T3", "furigana": "版木[はんぎ]に墨[すみ]を塗[ぬ]って、紙[かみ]に絵[え]を摺[す]ります。", "sentence_source": "generated"}, {"text": "弟は初めて、自分で彫った版木を摺りました。", "target_word": "摺りました", "complexity_tier": "T3", "furigana": "弟[おとうと]は初[はじ]めて、自分[じぶん]で彫[ほ]った版木[はんぎ]を摺[す]りました。", "sentence_source": "generated"}, {"text": "年賀状の絵を、木版で一枚ずつ摺っています。", "target_word": "摺っています", "complexity_tier": "T3", "furigana": "年賀状[ねんがじょう]の絵[え]を、木版[もくはん]で一枚[いちまい]ずつ摺[す]っています。", "sentence_source": "generated"}, {"text": "色を重ねるときは、一色ずつ順番に摺ります。", "target_word": "摺ります", "complexity_tier": "T3", "furigana": "色[いろ]を重[かさ]ねるときは、一色[ひといろ]ずつ順番[じゅんばん]に摺[す]ります。", "sentence_source": "generated"}, {"text": "先生は「紙を湿らせてから摺ってください」と言いました。", "target_word": "摺ってください", "complexity_tier": "T3", "furigana": "先生[せんせい]は「紙[かみ]を湿[しめ]らせてから摺[す]ってください」と言[い]いました。", "sentence_source": "generated"}, {"text": "昨日の授業で、花の版画を三枚摺りました。", "target_word": "摺りました", "complexity_tier": "T3", "furigana": "昨日[きのう]の授業[じゅぎょう]で、花[はな]の版画[はんが]を三枚[さんまい]摺[す]りました。", "sentence_source": "generated"}, {"text": "版木が欠けたので、もう同じ絵は摺れません。", "target_word": "摺れません", "complexity_tier": "T3", "furigana": "版木[はんぎ]が欠[か]けたので、もう同[おな]じ絵[え]は摺[す]れません。", "sentence_source": "generated"}, {"text": "彼女は和紙に、青いインクで魚の絵を摺りました。", "target_word": "摺りました", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は和紙[わし]に、青[あお]いインクで魚[さかな]の絵[え]を摺[す]りました。", "sentence_source": "generated"}, {"text": "この版は何百枚も摺ったので、線が少し太くなりました。", "target_word": "摺った", "complexity_tier": "T3", "furigana": "この版[はん]は何百枚[なんびゃくまい]も摺[す]ったので、線[せん]が少[すこ]し太[ふと]くなりました。", "sentence_source": "generated"}, {"text": "上手に摺るには、均等に力を入れることが大切です。", "target_word": "摺る", "complexity_tier": "T3", "furigana": "上手[じょうず]に摺[す]るには、均等[きんとう]に力[ちから]を入[い]れることが大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摺る", "label": "辞書形"}, {"form": "摺ります", "label": "丁寧形"}, {"form": "摺った", "label": "タ形"}, {"form": "摺って", "label": "テ形"}, {"form": "摺れる", "label": "可能形"}, {"form": "摺らない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "版にインクを塗って紙に押し当て、絵を写し取る(動詞・摺る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摺ります", "is_correct": true, "explanation": "「紙に絵を摺ります」で、版を使って刷り写す動作として文に合う。"}, {"text": "掘ります", "is_correct": false, "explanation": "「紙に絵を掘る」は紙を掘る動作になり、意味が通らない。"}, {"text": "折ります", "is_correct": false, "explanation": "「紙に絵を折る」は紙を折る動作になり、絵を写す文脈に合わない。"}, {"text": "運びます", "is_correct": false, "explanation": "「紙に絵を運ぶ」は絵を移動させる意味で、写し取る動作には合わない。"}], "explanations": {"摺ります": "「紙に絵を摺ります」で、版を使って刷り写す動作として文に合う。", "掘ります": "「紙に絵を掘る」は紙を掘る動作になり、意味が通らない。", "折ります": "「紙に絵を折る」は紙を折る動作になり、絵を写す文脈に合わない。", "運びます": "「紙に絵を運ぶ」は絵を移動させる意味で、写し取る動作には合わない。"}, "sentence_index": 0, "correct_answer": "摺ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁を白いペンキで摺ります。", "explanation": "ここは「塗る」の意味。ペンキを面に広げる動作で、版画を刷る意味では使わない。"}, {"text": "靴ひもを摺って、きつく結びました。", "explanation": "ここは〈結ぶ〉の意味。靴ひもを結ぶのは結ぶで、インクを紙に写す摺とは違うので合わない。"}, {"text": "ネクタイを摺って、きつく締めました。", "explanation": "ここは〈締める〉の意味。ネクタイを締めるのは締めるで、インクを紙に押し当てる摺とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摺れません", "is_correct": true, "explanation": "「同じ絵は摺れません」で、版木が欠けて刷れないという内容に合う。"}, {"text": "運べません", "is_correct": false, "explanation": "「同じ絵は運べません」は絵の運搬の意味で、版木が欠けたことと結びつかない。"}, {"text": "乾きません", "is_correct": false, "explanation": "「同じ絵は乾きません」は乾燥の意味で、刷る文脈に合わない。"}, {"text": "折れません", "is_correct": false, "explanation": "「同じ絵は折れません」は紙を折る意味で、刷れない理由にならない。"}], "explanations": {"摺れません": "「同じ絵は摺れません」で、版木が欠けて刷れないという内容に合う。", "運べません": "「同じ絵は運べません」は絵の運搬の意味で、版木が欠けたことと結びつかない。", "乾きません": "「同じ絵は乾きません」は乾燥の意味で、刷る文脈に合わない。", "折れません": "「同じ絵は折れません」は紙を折る意味で、刷れない理由にならない。"}, "sentence_index": 6, "correct_answer": "摺れません"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木の板を摺って、薄く削りました。", "explanation": "ここは〈削る〉の意味。木の板を薄く削るのは削るで、インクを紙に押す摺とは違うので合わない。"}, {"text": "服を摺って、きれいに畳みました。", "explanation": "ここは〈畳む〉の意味。服を畳むのは畳むで、インクを紙に押す摺とは違うので合わない。"}, {"text": "ポスターを摺って、壁から剥がしました。", "explanation": "ここは〈剥がす〉の意味。貼った紙を壁から剥がすのは剥がすで、インクを紙に押す摺とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "版木を丁寧に摺らった後は、紙を乾かします。", "corrected_sentence": "版木を丁寧に摺った後は、紙を乾かします。", "error_description": "誤りは「摺る」の過去形。「摺らった」は活用の誤りで、正しくは「摺った」（五段活用の促音便）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "摺りました", "is_correct": true, "explanation": "過去の丁寧形。「初めて摺った」という一度きりの完了した出来事に合う。"}, {"text": "摺ります", "is_correct": false, "explanation": "現在・未来の丁寧形で、過去の出来事を述べる文には合わない。"}, {"text": "摺れません", "is_correct": false, "explanation": "可能形の否定で、過去にできた出来事を述べる文脈に合わない。"}, {"text": "摺らない", "is_correct": false, "explanation": "否定形で、実際に摺ったという事実と逆の内容になる。"}], "correct_form": "摺りました", "base_form": "摺る", "form_label": "丁寧形・過去", "sentence_index": 1, "explanations": {"摺りました": "過去の丁寧形。「初めて摺った」という一度きりの完了した出来事に合う。", "摺ります": "現在・未来の丁寧形で、過去の出来事を述べる文には合わない。", "摺れません": "可能形の否定で、過去にできた出来事を述べる文脈に合わない。", "摺らない": "否定形で、実際に摺ったという事実と逆の内容になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53259, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙を湿らせてから摺えると、色が均一になります。", "corrected_sentence": "紙を湿らせてから摺ると、色が均一になります。", "error_description": "誤りは動詞の活用。「摺える」は誤りで、条件の「と」に続けるには辞書形「摺る」（摺ると）が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "摺りました", "is_correct": true, "explanation": "過去の丁寧形。和紙に魚の絵を刷った一度きりの出来事に合う。"}, {"text": "摺られた", "is_correct": false, "explanation": "受身形で、「魚の絵を」と目的語を取る文として成り立たない。"}, {"text": "摺ろう", "is_correct": false, "explanation": "意志・勧誘の形で、実際に刷ったという完了した出来事を述べる文には合わない。"}, {"text": "摺って", "is_correct": false, "explanation": "テ形で文を言い切れず、「摺りました」のような完了の述べ方にならない。"}], "correct_form": "摺りました", "base_form": "摺る", "form_label": "丁寧形・過去", "sentence_index": 7, "explanations": {"摺りました": "過去の丁寧形。和紙に魚の絵を刷った一度きりの出来事に合う。", "摺られた": "受身形で、「魚の絵を」と目的語を取る文として成り立たない。", "摺ろう": "意志・勧誘の形で、実際に刷ったという完了した出来事を述べる文には合わない。", "摺って": "テ形で文を言い切れず、「摺りました」のような完了の述べ方にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「色ごとに分けて」の「に」。色ごとを基準に分けることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「色ごとが分けて」は色ごとが主語になり、分ける人が消える。"}, {"text": "へ", "is_correct": false, "explanation": "「色ごとへ分けて」は方向の「へ」で、基準を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「色ごとの分けて」は連体の「の」で、動詞の前に置くと不自然。"}], "correct_answer": "に", "explanations": {"に": "「色ごとに分けて」の「に」。色ごとを基準に分けることを示す。", "が": "「色ごとが分けて」は色ごとが主語になり、分ける人が消える。", "へ": "「色ごとへ分けて」は方向の「へ」で、基準を示せない。", "の": "「色ごとの分けて」は連体の「の」で、動詞の前に置くと不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「色ごとに集めて」の「に」。色ごとという基準で集めることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「色ごとが集めて」は色ごとが主語になり、集める人が消える。"}, {"text": "より", "is_correct": false, "explanation": "「色ごとより集めて」は比較の「より」で、集める基準を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「色ごとへ集めて」は方向の「へ」で、集める基準を示せない。"}], "correct_answer": "に", "explanations": {"に": "「色ごとに集めて」の「に」。色ごとという基準で集めることを示す。", "が": "「色ごとが集めて」は色ごとが主語になり、集める人が消える。", "より": "「色ごとより集めて」は比較の「より」で、集める基準を示せない。", "へ": "「色ごとへ集めて」は方向の「へ」で、集める基準を示せない。"}, "error_tags": {"が": "主語", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "色の違いに従って、それぞれに分けること。", "primary_collocate": null, "pronunciation": "いろごと", "ipa": "iɾoɡoto", "syllable_count": 4, "sentences": [{"text": "毛糸を色ごとに袋へ入れておくと、編むときに探しやすいです。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "毛糸[けいと]を色[いろ]ごとに袋[ふくろ]へ入[い]れておくと、編[あ]むときに探[さが]しやすいです。", "sentence_source": "generated"}, {"text": "ボタンを色ごとに分けて、小さな瓶に入れた。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "ボタンを色[いろ]ごとに分[わ]けて、小[ちい]さな瓶[びん]に入[い]れた。", "sentence_source": "generated"}, {"text": "学校では、ごみ箱が色ごとに決まっていて、何を捨てるかすぐわかる。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "学校[がっこう]では、ごみ箱[ばこ]が色[いろ]ごとに決[き]まっていて、何[なに]を捨[す]てるかすぐわかる。", "sentence_source": "generated"}, {"text": "写真を色ごとに並べたら、意外な発見があった。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "写真[しゃしん]を色[いろ]ごとに並[なら]べたら、意外[いがい]な発見[はっけん]があった。", "sentence_source": "generated"}, {"text": "電線は色ごとに役目が違うので、まちがえないように注意する。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "電線[でんせん]は色[いろ]ごとに役目[やくめ]が違[ちが]うので、まちがえないように注意[ちゅうい]する。", "sentence_source": "generated"}, {"text": "花を色ごとにまとめて花瓶に挿すと、見た目がすっきりする。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "花[はな]を色[いろ]ごとにまとめて花瓶[かびん]に挿[さ]すと、見[み]た目[め]がすっきりする。", "sentence_source": "generated"}, {"text": "色ごとに値段が違う商品なので、買う前によく確かめてください。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "色[いろ]ごとに値段[ねだん]が違[ちが]う商品[しょうひん]なので、買[か]う前[まえ]によく確[たし]かめてください。", "sentence_source": "generated"}, {"text": "積み木を色ごとに集めて、弟は高い塔を作った。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "積[つ]み木[き]を色[いろ]ごとに集[あつ]めて、弟[おとうと]は高[たか]い塔[とう]を作[つく]った。", "sentence_source": "generated"}, {"text": "私は本の背表紙を色ごとにそろえて、棚に置いている。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "私[わたし]は本[ほん]の背表紙[せびょうし]を色[いろ]ごとにそろえて、棚[たな]に置[お]いている。", "sentence_source": "generated"}, {"text": "布を色ごとに染め分けるには、時間と手間がかかる。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "布[ぬの]を色[いろ]ごとに染[そ]め分[わ]けるには、時間[じかん]と手間[てま]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色ごと", "label": "基本形"}, {"form": "色ごとに", "label": "に格（副詞的用法）"}, {"form": "色ごとの", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "色ごと：いろの違いに従ってそれぞれ分けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色ごと", "is_correct": true, "explanation": "「色ごとに袋へ入れておく」は色の区分で入れ分ける意味で、文の流れに合う。"}, {"text": "毛糸", "is_correct": false, "explanation": "「毛糸に袋へ入れておく」は毛糸を入れる先の意味になり、区分の基準にならない。"}, {"text": "手編み", "is_correct": false, "explanation": "「手編みに袋へ入れておく」は編み方を表す語で、入れ分けの基準にならない。"}, {"text": "持ち手", "is_correct": false, "explanation": "「持ち手に袋へ入れておく」は取っ手を指し、袋の中へ入れる話として不自然。"}], "explanations": {"色ごと": "「色ごとに袋へ入れておく」は色の区分で入れ分ける意味で、文の流れに合う。", "毛糸": "「毛糸に袋へ入れておく」は毛糸を入れる先の意味になり、区分の基準にならない。", "手編み": "「手編みに袋へ入れておく」は編み方を表す語で、入れ分けの基準にならない。", "持ち手": "「持ち手に袋へ入れておく」は取っ手を指し、袋の中へ入れる話として不自然。"}, "sentence_index": 0, "correct_answer": "色ごと"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は染めが不十分で、色ごとが一定しなくなった。", "explanation": "ここは〈色むら〉の意味。色ごとは色を分けて扱う語で、色が一定でない状態は指さないので〈色むら〉を使う。"}, {"text": "子どもが色ごとを食べて、お腹をこわしてしまいました。", "explanation": "ここは〈食べ物〉の意味。色ごとは色で分けることで、食べられるものは指さないので合わない。"}, {"text": "紅茶の色ごとが強くて、カップが黄色くなった。", "explanation": "ここは〈色移り〉の意味。色ごとは色で分けることで、他の物に色が移る現象は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色ごと", "is_correct": true, "explanation": "「色ごとに値段が違う」は色の区分ごとに値段が異なる意味で、文に合う。"}, {"text": "値段", "is_correct": false, "explanation": "「値段ごとに値段が違う」は同じ語の繰り返しになり、文として成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天候の状態で、商品の値段の区分にはならないので合わない。"}, {"text": "夜空", "is_correct": false, "explanation": "空の景色で、商品の値段の区分にはならないので合わない。"}], "explanations": {"色ごと": "「色ごとに値段が違う」は色の区分ごとに値段が異なる意味で、文に合う。", "値段": "「値段ごとに値段が違う」は同じ語の繰り返しになり、文として成り立たない。", "天気": "天候の状態で、商品の値段の区分にはならないので合わない。", "夜空": "空の景色で、商品の値段の区分にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "色ごと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この製品は色ごとが高く、今年いちばんの評判を得た。", "explanation": "ここは〈評価〉の意味。色ごとは色で分けることで、製品への良し悪しの評価は指さない。"}, {"text": "この金属は色ごとが強く、鏡のように光る。", "explanation": "ここは〈光沢〉の意味。色ごとは色で分けることで、表面が光を反射する度合いは指さない。"}, {"text": "同じ靴で色ごとが三つあるので、迷ってしまう。", "explanation": "ここは〈色違い〉の意味。同じ品の別の色の製品を指すには〈色違い〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お菓子を色ごと箱へ入れておくと、探しやすい。", "corrected_sentence": "お菓子を色ごとに箱へ入れておくと、探しやすい。", "error_description": "「色ごと」の後に副詞的な「に」が抜けている。「色ごとに箱へ入れる」が自然な形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色ごとの並べると、探すのに時間がかからない。", "corrected_sentence": "色ごとに並べると、探すのに時間がかからない。", "error_description": "「並べる」に続く「に」が「の」になっている。「色ごとに並べる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「色ごとに分けて」の「に」。色ごとを基準に分けることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「色ごとが分けて」は色ごとが主語になり、分ける人が消える。"}, {"text": "と", "is_correct": false, "explanation": "「色ごとと分けて」は並列の「と」で、分ける基準を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「色ごとへ分けて」は方向の「へ」で、分ける基準を示せない。"}], "correct_answer": "に", "explanations": {"に": "「色ごとに分けて」の「に」。色ごとを基準に分けることを示す。", "が": "「色ごとが分けて」は色ごとが主語になり、分ける人が消える。", "と": "「色ごとと分けて」は並列の「と」で、分ける基準を示せない。", "へ": "「色ごとへ分けて」は方向の「へ」で、分ける基準を示せない。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「色ごとに管理している」の「に」。管理の基準を示す。"}, {"text": "が", "is_correct": false, "explanation": "「色ごとが管理している」は色ごとが主語になり、管理する人が消える。"}, {"text": "より", "is_correct": false, "explanation": "「色ごとより管理している」は比較の「より」で、管理の基準を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「色ごとで管理している」は手段の「で」になり、基準として不自然。"}], "correct_answer": "に", "explanations": {"に": "「色ごとに管理している」の「に」。管理の基準を示す。", "が": "「色ごとが管理している」は色ごとが主語になり、管理する人が消える。", "より": "「色ごとより管理している」は比較の「より」で、管理の基準を示せない。", "で": "「色ごとで管理している」は手段の「で」になり、基準として不自然。"}, "error_tags": {"が": "主語", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "色の種類や単位ごとに分けて扱うこと。", "primary_collocate": null, "pronunciation": "いろごと", "ipa": "iɾoɡoto", "syllable_count": 4, "sentences": [{"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "色ごと", "complexity_tier": "T4", "furigana": "特[とく]に多色印刷[たしょくいんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "絵の具を色ごとに小さな箱へ分けて、棚にしまいました。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]を色[いろ]ごとに小[ちい]さな箱[はこ]へ分[わ]けて、棚[たな]にしまいました。", "sentence_source": "generated"}, {"text": "この版画は、色ごとに別の版を作って何度も重ねて刷ります。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "この版画[はんが]は、色[いろ]ごとに別[べつ]の版[はん]を作[つく]って何度[なんど]も重[かさ]ねて刷[す]ります。", "sentence_source": "generated"}, {"text": "洗濯物は色ごとに分けて洗わないと、色移りしてしまいます。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]は色[いろ]ごとに分[わ]けて洗[あら]わないと、色移[いろうつ]りしてしまいます。", "sentence_source": "generated"}, {"text": "色ごとに担当の係を決めたので、作業が早く終わった。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "色[いろ]ごとに担当[たんとう]の係[かかり]を決[き]めたので、作業[さぎょう]が早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "毎月の売上を色ごとに集計すると、赤い商品がいちばん人気だとわかった。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "毎月[まいつき]の売上[うりあげ]を色[いろ]ごとに集計[しゅうけい]すると、赤[あか]い商品[しょうひん]がいちばん人気[にんき]だとわかった。", "sentence_source": "generated"}, {"text": "折り紙を色ごとに並べてから、ゆっくり好きな色を選んだ。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "折[お]り紙[がみ]を色[いろ]ごとに並[なら]べてから、ゆっくり好[す]きな色[いろ]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "インクの残りは色ごとに管理しているため、足りなくなる前に注文できます。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "インクの残[のこ]りは色[いろ]ごとに管理[かんり]しているため、足[た]りなくなる前[まえ]に注文[ちゅうもん]できます。", "sentence_source": "generated"}, {"text": "子どもたちは色ごとにチームを作り、運動会で競い合った。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "子[こ]どもたちは色[いろ]ごとにチームを作[つく]り、運動会[うんどうかい]で競[きそ]い合[あ]った。", "sentence_source": "generated"}, {"text": "地図は色ごとに意味が違うので、凡例をよく見てください。", "target_word": "色ごと", "complexity_tier": "T3", "furigana": "地図[ちず]は色[いろ]ごとに意味[いみ]が違[ちが]うので、凡例[はんれい]をよく見[み]てください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色ごと", "label": "基本形"}, {"form": "色ごとに", "label": "に格（副詞的用法）"}, {"form": "色ごとの", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "色ごと：色の種類や単位ごとに分けて扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 版木 (Zipf 2.03)','sentence 9 above tier T2: contains vocabulary far above tier T2: 凡例 (Zipf 2.12)']::text[], '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色ごと", "is_correct": true, "explanation": "「色ごとに異なる版木」は色の区分ごとに版木を変える意味で、文の流れに合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気ごとに異なる版木を使い分ける」は区分の基準にならず、印刷の話として合わない。"}, {"text": "鳥", "is_correct": false, "explanation": "「鳥ごとに異なる版木を使い分ける」は区分の基準にならず、印刷の話として合わない。"}, {"text": "版木", "is_correct": false, "explanation": "「版木ごとに異なる版木」は同じ語の繰り返しになり、文として成り立たない。"}], "explanations": {"色ごと": "「色ごとに異なる版木」は色の区分ごとに版木を変える意味で、文の流れに合う。", "天気": "「天気ごとに異なる版木を使い分ける」は区分の基準にならず、印刷の話として合わない。", "鳥": "「鳥ごとに異なる版木を使い分ける」は区分の基準にならず、印刷の話として合わない。", "版木": "「版木ごとに異なる版木」は同じ語の繰り返しになり、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "色ごと"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日当たりのせいで、カーテンの色ごとが進んでしまった。", "explanation": "ここは〈色あせ〉の意味。色ごとは色を分けて扱う語で、色が薄れる現象は指さないので〈色あせ〉を使う。"}, {"text": "夕焼けの色ごとが美しく、しばらく見とれた。", "explanation": "ここは〈色合い〉の意味。色ごとは色を種類別に分けることで、全体の色の調子は指さない。"}, {"text": "このポスターは色ごとがまとまっていて、見やすい。", "explanation": "ここは〈配色〉の意味。色ごとは色を一つずつ分けて扱う語で、色の組み合わせの調和は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色ごと", "is_correct": true, "explanation": "「色ごとに並べてから」は色の区分ごとに並べる意味で、文の前段として合う。"}, {"text": "折り紙", "is_correct": false, "explanation": "「折り紙に並べてから」は折り紙を置く先の意味になり、色で分けた様子にならない。"}, {"text": "手順", "is_correct": false, "explanation": "「手順に並べてから」は順序の話になり、色で分けた様子とずれる。"}, {"text": "並べ", "is_correct": false, "explanation": "「並べ」は「並べてから」の形を作れず、文の流れが崩れる。"}], "explanations": {"色ごと": "「色ごとに並べてから」は色の区分ごとに並べる意味で、文の前段として合う。", "折り紙": "「折り紙に並べてから」は折り紙を置く先の意味になり、色で分けた様子にならない。", "手順": "「手順に並べてから」は順序の話になり、色で分けた様子とずれる。", "並べ": "「並べ」は「並べてから」の形を作れず、文の流れが崩れる。"}, "sentence_index": 6, "correct_answer": "色ごと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作品は色ごとが高く、賞を取った。", "explanation": "ここは〈評価〉の意味。色ごとは色で分けることで、作品の良し悪しの度合いは指さない。"}, {"text": "この布は色ごとが強く、特別な輝きがある。", "explanation": "ここは〈光沢〉の意味。色ごとは色を分けて扱う語で、表面が光を反射する度合いは指さない。"}, {"text": "同じ服で色ごとがあるので、迷ってしまう。", "explanation": "ここは〈色違い〉の意味。同じ品の別の色の製品を指すには〈色違い〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "絵の具を色ごと小さな袋へ分けて、箱にしまいました。", "corrected_sentence": "絵の具を色ごとに小さな袋へ分けて、箱にしまいました。", "error_description": "「色ごと」の後に副詞的な「に」が抜けている。「色ごとに分けて」が自然な形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色ごとの分けて保管すれば、足りなくなる前に気づける。", "corrected_sentence": "色ごとに分けて保管すれば、足りなくなる前に気づける。", "error_description": "「分けて」に続く「に」が「の」になっている。「色ごとに分けて」が正しく、「色ごとの分けて」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
