INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53265, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもあわてて、すぐに対応が必要な状態です。", "primary_collocate": null, "pronunciation": "きんきゅう", "ipa": "kʲiŋkʲɯː", "syllable_count": 4, "sentences": [{"text": "緊急の知らせを聞いて、母はあわてて家を出た。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の知[し]らせを聞[き]いて、母[はは]はあわてて家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "緊急の電話が入り、事務所の中が急に慌ただしくなった。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の電話[でんわ]が入[はい]り、事務所[じむしょ]の中[なか]が急[きゅう]に慌[あわ]ただしくなった。", "sentence_source": "generated"}, {"text": "緊急だと分かると、みんなすぐに動き出した。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]だと分[わ]かると、みんなすぐに動[うご]き出[だ]した。", "sentence_source": "generated"}, {"text": "夜中に緊急の呼び出しがあり、医者は病院へ走った。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "夜中[よなか]に緊急[きんきゅう]の呼[よ]び出[だ]しがあり、医者[いしゃ]は病院[びょういん]へ走[はし]った。", "sentence_source": "generated"}, {"text": "緊急の場面でも、落ち着いて行動することが大切だ。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の場面[ばめん]でも、落[お]ち着[つ]いて行動[こうどう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "緊急に対応しなければ、客からの苦情が増えてしまう。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]に対応[たいおう]しなければ、客[きゃく]からの苦情[くじょう]が増[ふ]えてしまう。", "sentence_source": "generated"}, {"text": "試合中、緊急の連絡が入って、監督の顔色が変わった。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "試合中[しあいちゅう]、緊急[きんきゅう]の連絡[れんらく]が入[はい]って、監督[かんとく]の顔色[かおいろ]が変[か]わった。", "sentence_source": "generated"}, {"text": "緊急の状態なので、説明は後にして手伝ってください。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の状態[じょうたい]なので、説明[せつめい]は後[あと]にして手伝[てつだ]ってください。", "sentence_source": "generated"}, {"text": "緊急の連絡網で、先生たちが次々に体育館へ駆けつけた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の連絡網[れんらくもう]で、先生[せんせい]たちが次々[つぎつぎ]に体育館[たいいくかん]へ駆[か]けつけた。", "sentence_source": "generated"}, {"text": "緊急の放送が流れ、乗客たちはざわついた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の放送[ほうそう]が流[なが]れ、乗客[じょうきゃく]たちはざわついた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊急だ", "label": "断定形"}, {"form": "緊急の", "label": "連体形"}, {"form": "緊急に", "label": "連用形"}, {"form": "緊急ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "あわただしく、すぐに対応しなければならない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 慌ただしく (Zipf 2.47)','sentence 9 above tier T2: contains vocabulary far above tier T2: ざわつい (Zipf 2.35)']::text[], '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53265, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "「あわただしく対応が必要な」の意味で、知らせの性質に合う。"}, {"text": "不吉", "is_correct": false, "explanation": "「不吉な知らせ」とは言えるが、「不吉の知らせ」の形では空所に入らない。"}, {"text": "鮮明", "is_correct": false, "explanation": "明瞭な様子を表す。「鮮明の知らせ」は不自然で、文に入らない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るい様子を表す。知らせの形容としては入らない。"}], "explanations": {"緊急": "「あわただしく対応が必要な」の意味で、知らせの性質に合う。", "不吉": "「不吉な知らせ」とは言えるが、「不吉の知らせ」の形では空所に入らない。", "鮮明": "明瞭な様子を表す。「鮮明の知らせ」は不自然で、文に入らない。", "陽気": "明るい様子を表す。知らせの形容としては入らない。"}, "sentence_index": 0, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖の緊急な水面が、朝日を受けて輝いていた。", "explanation": "ここは〈穏やか〉の意味（穏やかな水面）。緊急は差し迫った状況を指し、水面の静けさは表せない。"}, {"text": "ホテルのロビーには緊急なシャンデリアが並んでいた。", "explanation": "ここは〈豪華〉の意味。緊急は対応の必要性を表すため、装飾の華やかさには合わない。"}, {"text": "彼は緊急な心で、借金を許してくれた。", "explanation": "ここは〈寛大〉の意味（寛大な心）。緊急は差し迫った状況に使い、人の心の広さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53265, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "「すぐ対処が必要な」の意味で、連絡の性質として文に合う。"}, {"text": "静穏", "is_correct": false, "explanation": "静かで穏やかな様子を表す。「静穏の連絡」は成り立たず、空所に入らない。"}, {"text": "厳か", "is_correct": false, "explanation": "格式ばった重々しい様子を表す。連絡の形容としては入らない。"}, {"text": "純粋", "is_correct": false, "explanation": "混じりけのない様子を表す。「純粋の連絡」は文脈に合わない。"}], "explanations": {"緊急": "「すぐ対処が必要な」の意味で、連絡の性質として文に合う。", "静穏": "静かで穏やかな様子を表す。「静穏の連絡」は成り立たず、空所に入らない。", "厳か": "格式ばった重々しい様子を表す。連絡の形容としては入らない。", "純粋": "混じりけのない様子を表す。「純粋の連絡」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花壇には緊急な色の花が咲いていた。", "explanation": "ここは〈鮮やか〉の意味（鮮やかな色）。緊急は差し迫った状況を指し、色のあざやかさは表せない。"}, {"text": "店員は緊急な言葉遣いで説明してくれた。", "explanation": "ここは〈丁寧〉の意味（丁寧な言葉遣い）。緊急は対応の必要性を表し、話し方の丁寧さには合わない。"}, {"text": "あの子は緊急な笑顔を見せた。", "explanation": "ここは〈純真〉の意味（純真な笑顔）。緊急は差し迫った状況に使い、心の素直さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53265, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "緊急が連絡が入り、受付にいた人たちが急いで席を立った。", "corrected_sentence": "緊急の連絡が入り、受付にいた人たちが急いで席を立った。", "error_description": "「緊急」に続く「が」が誤り。名詞「連絡」を修飾するには「の」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "語幹の形で、直後に「の」を付けて名詞「電話」を修飾する「緊急の」の基になる形。"}, {"text": "緊急だ", "is_correct": false, "explanation": "断定形。名詞「電話」を直接修飾できず、文が続かない。"}, {"text": "緊急に", "is_correct": false, "explanation": "連用形。「に」で終わり、名詞「電話」を修飾できない。"}, {"text": "緊急くない", "is_correct": false, "explanation": "形容詞型の否定「くない」は形状詞に付かず、名詞「電話」の前にも「の」の前にも置けない。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 1, "explanations": {"緊急": "語幹の形で、直後に「の」を付けて名詞「電話」を修飾する「緊急の」の基になる形。", "緊急だ": "断定形。名詞「電話」を直接修飾できず、文が続かない。", "緊急に": "連用形。「に」で終わり、名詞「電話」を修飾できない。", "緊急くない": "形容詞型の否定「くない」は形状詞に付かず、名詞「電話」の前にも「の」の前にも置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53265, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊急く連絡が入って、皆すぐに動いた。", "corrected_sentence": "緊急の連絡が入って、皆すぐに動いた。", "error_description": "「緊急」の連用形の語尾「く」が誤り。名詞「連絡」を修飾するには「の」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "語幹の形で、「の」や「だ」などが付く前の基本の形。"}, {"text": "緊急で", "is_correct": false, "explanation": "断定の連用形で、名詞「状態」を修飾できず、「の状態なので」の形は成り立たない。"}, {"text": "緊急ならば", "is_correct": false, "explanation": "仮定形で、「の状態」に続けて名詞を修飾する形にならない。"}, {"text": "緊急くて", "is_correct": false, "explanation": "形容詞型のて形は形状詞には付かず、名詞「状態」の前に置けない。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 7, "explanations": {"緊急": "語幹の形で、「の」や「だ」などが付く前の基本の形。", "緊急で": "断定の連用形で、名詞「状態」を修飾できず、「の状態なので」の形は成り立たない。", "緊急ならば": "仮定形で、「の状態」に続けて名詞を修飾する形にならない。", "緊急くて": "形容詞型のて形は形状詞には付かず、名詞「状態」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
