INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53266, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "危険や事故などが起きたため、速やかな対応が求められる状態。", "primary_collocate": null, "pronunciation": "きんきゅう", "ipa": "kʲiŋkʲɯː", "syllable_count": 4, "sentences": [{"text": "事故の現場に、緊急の連絡を受けた救助隊が到着した。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "事故[じこ]の現場[げんば]に、緊急[きんきゅう]の連絡[れんらく]を受[う]けた救助隊[きゅうじょたい]が到着[とうちゃく]した。", "sentence_source": "generated"}, {"text": "火事が起きたため、緊急の避難が呼びかけられた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "火事[かじ]が起[お]きたため、緊急[きんきゅう]の避難[ひなん]が呼[よ]びかけられた。", "sentence_source": "generated"}, {"text": "ガスのにおいがして、緊急に窓を開けた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "ガスのにおいがして、緊急[きんきゅう]に窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "緊急の場合は、非常ボタンを押してください。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の場合[ばあい]は、非常[ひじょう]ボタンを押[お]してください。", "sentence_source": "generated"}, {"text": "大雨で川があふれそうになり、緊急の連絡が町中に流れた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で川[かわ]があふれそうになり、緊急[きんきゅう]の連絡[れんらく]が町中[まちじゅう]に流[なが]れた。", "sentence_source": "generated"}, {"text": "工場で爆発があり、緊急に機械を止めた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "工場[こうじょう]で爆発[ばくはつ]があり、緊急[きんきゅう]に機械[きかい]を止[と]めた。", "sentence_source": "generated"}, {"text": "けが人が出たので、緊急で病院に運ばれた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "けが人[にん]が出[で]たので、緊急[きんきゅう]で病院[びょういん]に運[はこ]ばれた。", "sentence_source": "generated"}, {"text": "地震のあと、緊急の放送が何度も繰り返された。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、緊急[きんきゅう]の放送[ほうそう]が何度[なんど]も繰[く]り返[かえ]された。", "sentence_source": "generated"}, {"text": "緊急のときに使うため、懐中電灯をかばんに入れている。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]のときに使[つか]うため、懐中電灯[かいちゅうでんとう]をかばんに入[い]れている。", "sentence_source": "generated"}, {"text": "山で道に迷った登山者が、緊急に助けを求めた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]った登山者[とざんしゃ]が、緊急[きんきゅう]に助[たす]けを求[もと]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊急だ", "label": "断定形"}, {"form": "緊急の", "label": "連体形"}, {"form": "緊急に", "label": "連用形"}, {"form": "緊急で", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "事故や災害などの危険のため、速やかな対応が求められる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53266, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "事故などで速やかな対応が必要なことを表し、連絡の性質に合う。"}, {"text": "鮮明", "is_correct": false, "explanation": "輪郭がはっきりした様子を表す。連絡の形容には合わない。"}, {"text": "不吉", "is_correct": false, "explanation": "縁起が悪い様子を表す。「不吉の連絡」は文脈に合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るい様子を表す。連絡の性質としては入らない。"}], "explanations": {"緊急": "事故などで速やかな対応が必要なことを表し、連絡の性質に合う。", "鮮明": "輪郭がはっきりした様子を表す。連絡の形容には合わない。", "不吉": "縁起が悪い様子を表す。「不吉の連絡」は文脈に合わない。", "陽気": "明るい様子を表す。連絡の性質としては入らない。"}, "sentence_index": 0, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緊急な暑さで、夜も眠れない日が続いた。", "explanation": "ここは〈猛烈〉の意味（猛烈な暑さ）。緊急は危険や事故への速やかな対応を表す語で、気温の激しさには使わない。"}, {"text": "この時計は緊急な精度で、毎日正確に時を刻む。", "explanation": "ここは〈正確〉の意味（正確な精度）。緊急は差し迫った状態を表し、精度の高さは表せない。"}, {"text": "緊急な被害が出た。", "explanation": "ここは〈甚大〉の意味（甚大な被害）。緊急は速やかな対応が必要な状態を表し、被害の大きさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53266, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "速やかな対応が必要な状況を表し、「緊急で」の形で搬送の状況に合う。"}, {"text": "静穏", "is_correct": false, "explanation": "静かで穏やかな様子を表す。「静穏で病院に運ばれた」とは言えない。"}, {"text": "厳か", "is_correct": false, "explanation": "重々しい様子を表す。搬送の状況には合わない。"}, {"text": "純粋", "is_correct": false, "explanation": "混じりけのない様子を表す。搬送の状況には合わない。"}], "explanations": {"緊急": "速やかな対応が必要な状況を表し、「緊急で」の形で搬送の状況に合う。", "静穏": "静かで穏やかな様子を表す。「静穏で病院に運ばれた」とは言えない。", "厳か": "重々しい様子を表す。搬送の状況には合わない。", "純粋": "混じりけのない様子を表す。搬送の状況には合わない。"}, "sentence_index": 6, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店のスープは緊急な味つけで、おいしい。", "explanation": "ここは〈濃厚〉の意味（濃厚な味つけ）。緊急は危険や事故への速やかな対応を表し、味の濃さには使わない。"}, {"text": "彼女の緊急な指が、ピアノの鍵盤の上を滑らかに踊った。", "explanation": "ここは〈器用〉の意味（器用な指先）。緊急は差し迫った状態を指すので、指先の巧みさは表せない。"}, {"text": "緊急な水が谷を流れている。", "explanation": "ここは〈清らか〉の意味（清らかな水）。緊急は差し迫った状態を表し、水の澄んださまは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53266, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "緊急を連絡が入ったので、現場へ向かった。", "corrected_sentence": "緊急の連絡が入ったので、現場へ向かった。", "error_description": "「緊急」に続く「を」が誤り。名詞「連絡」を修飾するには「の」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "語幹の形で、「の」や「だ」などが付く前の基本の形。"}, {"text": "緊急だ", "is_correct": false, "explanation": "断定形。名詞「避難」を直接修飾できず、文が続かない。"}, {"text": "緊急に", "is_correct": false, "explanation": "連用形。「に」で終わり、名詞「避難」を修飾できない。"}, {"text": "緊急くない", "is_correct": false, "explanation": "形容詞型の否定「くない」は形状詞に付かず、名詞「避難」の前にも「の」の前にも置けない。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 1, "explanations": {"緊急": "語幹の形で、「の」や「だ」などが付く前の基本の形。", "緊急だ": "断定形。名詞「避難」を直接修飾できず、文が続かない。", "緊急に": "連用形。「に」で終わり、名詞「避難」を修飾できない。", "緊急くない": "形容詞型の否定「くない」は形状詞に付かず、名詞「避難」の前にも「の」の前にも置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53266, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊急く病院へ運ばれた。", "corrected_sentence": "緊急で病院へ運ばれた。", "error_description": "「緊急」の語尾が誤り。「く」ではなく「で」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "語幹の形で、「の」や「だ」などが付く前の基本の形。"}, {"text": "緊急ではありません", "is_correct": false, "explanation": "丁寧な否定形。名詞「放送」の前に置けず、文が続かない。"}, {"text": "緊急ではなく", "is_correct": false, "explanation": "「ではなく」で文をつなぐ中止形。名詞「放送」を修飾できない。"}, {"text": "緊急ではなければ", "is_correct": false, "explanation": "仮定形の否定。名詞「放送」を修飾できず、文が続かない。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 7, "explanations": {"緊急": "語幹の形で、「の」や「だ」などが付く前の基本の形。", "緊急ではありません": "丁寧な否定形。名詞「放送」の前に置けず、文が続かない。", "緊急ではなく": "「ではなく」で文をつなぐ中止形。名詞「放送」を修飾できない。", "緊急ではなければ": "仮定形の否定。名詞「放送」を修飾できず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「連想を使う」で、連想を使う対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「連想が使って」となり文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、使う対象を表す語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すので、「連想へ使って」は文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「連想を使う」で、連想を使う対象を示す「を」。", "が": "「が」は主語を示すため、「連想が使って」となり文が成り立たない。", "と": "「と」は相手や並列を示すので、使う対象を表す語にはならない。", "へ": "「へ」は向かう先を示すので、「連想へ使って」は文に合わない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "頭の中で、あるものともう一つのものをつなげて考えること。", "primary_collocate": null, "pronunciation": "れんそう", "ipa": "ɾeɴsoː", "syllable_count": 4, "sentences": [{"text": "「海」という言葉から、どんなことを連想しますか。", "target_word": "連想", "complexity_tier": "T3", "furigana": "「海[うみ]」という言葉[ことば]から、どんなことを連想[れんそう]しますか。", "sentence_source": "generated"}, {"text": "先生は連想を使って、単語を覚える方法を教えてくれた。", "target_word": "連想", "complexity_tier": "T3", "furigana": "先生[せんせい]は連想[れんそう]を使[つか]って、単語[たんご]を覚[おぼ]える方法[ほうほう]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "彼の連想は面白くて、いつも話が思わぬ方向へ進む。", "target_word": "連想", "complexity_tier": "T3", "furigana": "彼[かれ]の連想[れんそう]は面白[おもしろ]くて、いつも話[はなし]が思[おも]わぬ方向[ほうこう]へ進[すす]む。", "sentence_source": "generated"}, {"text": "黒い雲を見て、嵐を連想する人は多い。", "target_word": "連想", "complexity_tier": "T3", "furigana": "黒[くろ]い雲[くも]を見[み]て、嵐[あらし]を連想[れんそう]する人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "連想が得意な妹は、一つの絵から長い物語を作った。", "target_word": "連想", "complexity_tier": "T3", "furigana": "連想[れんそう]が得意[とくい]な妹[いもうと]は、一[ひと]つの絵[え]から長[なが]い物語[ものがたり]を作[つく]った。", "sentence_source": "generated"}, {"text": "名前が似ているため、別の人物を連想してしまった。", "target_word": "連想", "complexity_tier": "T3", "furigana": "名前[なまえ]が似[に]ているため、別[べつ]の人物[じんぶつ]を連想[れんそう]してしまった。", "sentence_source": "generated"}, {"text": "単語を絵と結びつけて連想すると、頭に残りやすい。", "target_word": "連想", "complexity_tier": "T3", "furigana": "単語[たんご]を絵[え]と結[むす]びつけて連想[れんそう]すると、頭[あたま]に残[のこ]りやすい。", "sentence_source": "generated"}, {"text": "このゲームでは、ヒントから答えを連想して当てる。", "target_word": "連想", "complexity_tier": "T3", "furigana": "このゲームでは、ヒントから答[こた]えを連想[れんそう]して当[あ]てる。", "sentence_source": "generated"}, {"text": "連想がうまくいかず、新しい言葉がなかなか覚えられない。", "target_word": "連想", "complexity_tier": "T3", "furigana": "連想[れんそう]がうまくいかず、新[あたら]しい言葉[ことば]がなかなか覚[おぼ]えられない。", "sentence_source": "generated"}, {"text": "雪から白い花を連想し、詩の最初の一行を書いた。", "target_word": "連想", "complexity_tier": "T3", "furigana": "雪[ゆき]から白[しろ]い花[はな]を連想[れんそう]し、詩[し]の最初[さいしょ]の一行[いちぎょう]を書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連想する", "label": "基本形"}, {"form": "連想した", "label": "過去形"}, {"form": "連想しない", "label": "否定形"}, {"form": "連想して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "ある物事から別の物事を結びつけて思い浮かべること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連想", "is_correct": true, "explanation": "「海」から別のことを頭に思い浮かべる意味の「連想」で、どんなことを思い浮かべるかを尋ねる文に入る。"}, {"text": "反発", "is_correct": false, "explanation": "相手の意見や力に逆らう意味。「どんなことを反発しますか」は文として成り立たない。"}, {"text": "感激", "is_correct": false, "explanation": "強く心を動かされる意味で、「に」を取る語。「どんなことを感激しますか」は文に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩く行為。言葉からどんなことを思い浮かべるかという文には入らない。"}], "explanations": {"連想": "「海」から別のことを頭に思い浮かべる意味の「連想」で、どんなことを思い浮かべるかを尋ねる文に入る。", "反発": "相手の意見や力に逆らう意味。「どんなことを反発しますか」は文として成り立たない。", "感激": "強く心を動かされる意味で、「に」を取る語。「どんなことを感激しますか」は文に合わない。", "散歩": "外を歩く行為。言葉からどんなことを思い浮かべるかという文には入らない。"}, "sentence_index": 0, "correct_answer": "連想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二台のポンプが連想して動き出した。", "explanation": "ここは〈連動〉の意味。連想は人の頭の中の働きで、機械の連動には使わない。"}, {"text": "ボタンを押すと、扉が連想して開く。", "explanation": "ここは〈連動〉の意味。連想は人の頭の中の働きで、機械の動きには使わない。"}, {"text": "熱いものに触れて、手が連想して引っ込んだ。", "explanation": "ここは〈反射〉の意味。連想は意識して考えを結びつける働きで、体の無意識の動きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連想", "is_correct": true, "explanation": "頭の中で結びつけて思い浮かべる意味の「連想する」。「連想すると」の形で、頭に残りやすいという結果につながる。"}, {"text": "拍手", "is_correct": false, "explanation": "手を打ち鳴らす行為。単語を絵と結びつける場面には合わない。"}, {"text": "開業", "is_correct": false, "explanation": "事業を始める意味。単語を覚える文脈には入らない。"}, {"text": "解雇", "is_correct": false, "explanation": "雇用を終わらせる意味。文脈と全く合わない。"}], "explanations": {"連想": "頭の中で結びつけて思い浮かべる意味の「連想する」。「連想すると」の形で、頭に残りやすいという結果につながる。", "拍手": "手を打ち鳴らす行為。単語を絵と結びつける場面には合わない。", "開業": "事業を始める意味。単語を覚える文脈には入らない。", "解雇": "雇用を終わらせる意味。文脈と全く合わない。"}, "sentence_index": 6, "correct_answer": "連想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの数字を連想して、足し算の答えを出した。", "explanation": "ここは〈計算〉の意味。連想は考えを結びつけて思い浮かべることで、数の計算には使わない。"}, {"text": "壊れた時計を連想して、すぐに直した。", "explanation": "ここは〈修理〉の意味。連想は思い浮かべる働きで、物を直す行為には使わない。"}, {"text": "先生が生徒の名前を連想して、宿題を出した。", "explanation": "ここは〈指示〉の意味。連想は個人の頭の中の働きで、他人に何かを命じる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その曲を聞くと、夏の海を連想す人が多い。", "corrected_sentence": "その曲を聞くと、夏の海を連想する人が多い。", "error_description": "「連想す」は誤った形。辞書形は「連想する」で、後ろの「人」を修飾する形も「連想する」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53267, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図と言葉を結びつけて覚える子は、連想を得意だ。", "corrected_sentence": "図と言葉を結びつけて覚える子は、連想が得意だ。", "error_description": "「連想を得意だ」は誤り。「得意だ」は対象を「が」で示すので、「連想が得意だ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
