INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを見たときや聞いたときに、それに関連する別のイメージや記憶が自然に浮かぶこと。", "primary_collocate": null, "pronunciation": "れんそう", "ipa": "ɾeɴsoː", "syllable_count": 4, "sentences": [{"text": "この香りは、子どものころの台所を連想させる。", "target_word": "連想", "complexity_tier": "T3", "furigana": "この香[かお]りは、子[こ]どものころの台所[だいどころ]を連想[れんそう]させる。", "sentence_source": "generated"}, {"text": "古い歌を聞くと、あの夏の日の海が連想される。", "target_word": "連想", "complexity_tier": "T3", "furigana": "古[ふる]い歌[うた]を聞[き]くと、あの夏[なつ]の日[ひ]の海[うみ]が連想[れんそう]される。", "sentence_source": "generated"}, {"text": "彼の笑顔は、春の日だまりを連想させた。", "target_word": "連想", "complexity_tier": "T3", "furigana": "彼[かれ]の笑顔[えがお]は、春[はる]の日[ひ]だまりを連想[れんそう]させた。", "sentence_source": "generated"}, {"text": "古い写真を見て、亡くなった祖母の家を連想した。", "target_word": "連想", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]て、亡[な]くなった祖母[そぼ]の家[いえ]を連想[れんそう]した。", "sentence_source": "generated"}, {"text": "その名前は、有名な映画の主人公を連想させる。", "target_word": "連想", "complexity_tier": "T3", "furigana": "その名前[なまえ]は、有名[ゆうめい]な映画[えいが]の主人公[しゅじんこう]を連想[れんそう]させる。", "sentence_source": "generated"}, {"text": "雨の音を聞くと、なぜか古い駅を連想する。", "target_word": "連想", "complexity_tier": "T3", "furigana": "雨[あめ]の音[おと]を聞[き]くと、なぜか古[ふる]い駅[えき]を連想[れんそう]する。", "sentence_source": "generated"}, {"text": "青い空と白い雲は、夏休みを連想させる。", "target_word": "連想", "complexity_tier": "T3", "furigana": "青[あお]い空[そら]と白[しろ]い雲[くも]は、夏休[なつやす]みを連想[れんそう]させる。", "sentence_source": "generated"}, {"text": "彼女の声から、鳥のさえずりを連想する人もいる。", "target_word": "連想", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の声[こえ]から、鳥[とり]のさえずりを連想[れんそう]する人[ひと]もいる。", "sentence_source": "generated"}, {"text": "煙のにおいで、キャンプの夜を連想した。", "target_word": "連想", "complexity_tier": "T3", "furigana": "煙[けむり]のにおいで、キャンプの夜[よる]を連想[れんそう]した。", "sentence_source": "generated"}, {"text": "広告は、商品から楽しい家族の時間を連想させるように作られている。", "target_word": "連想", "complexity_tier": "T3", "furigana": "広告[こうこく]は、商品[しょうひん]から楽[たの]しい家族[かぞく]の時間[じかん]を連想[れんそう]させるように作[つく]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連想する", "label": "基本形"}, {"form": "連想した", "label": "過去形"}, {"form": "連想させる", "label": "使役形"}, {"form": "連想される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "見聞きしたものから関連するイメージや記憶が自然に浮かぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 日だまり (Zipf 1.86)']::text[], '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53268, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連想", "is_correct": true, "explanation": "「〜を連想させる」の形で、香りが台所のイメージを浮かばせる意味になる。"}, {"text": "拍手", "is_correct": false, "explanation": "手を打ち鳴らす行為で、台所を対象にできない。"}, {"text": "解雇", "is_correct": false, "explanation": "雇用を終える意味で、台所を対象にできない。"}, {"text": "開業", "is_correct": false, "explanation": "事業を始める意味で、台所を対象にできない。"}], "explanations": {"連想": "「〜を連想させる」の形で、香りが台所のイメージを浮かばせる意味になる。", "拍手": "手を打ち鳴らす行為で、台所を対象にできない。", "解雇": "雇用を終える意味で、台所を対象にできない。", "開業": "事業を始める意味で、台所を対象にできない。"}, "sentence_index": 0, "correct_answer": "連想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つのスイッチが連想して、照明が一斉に点いた。", "explanation": "ここは〈連動〉の意味。連想は人の頭の中の働きで、機械の連動には使わない。"}, {"text": "壊れた時計を見て、連想して直した。", "explanation": "ここは〈修理〉の意味。連想は思い浮かべる働きで、物を直す行為には使わない。"}, {"text": "校長が職員の名前を連想して、会議を開くよう指示した。", "explanation": "ここは〈命令〉の意味。連想は個人の頭の中の働きで、他人に何かをするよう命じる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53268, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連想", "is_correct": true, "explanation": "「夏休みを連想させる」の形で、青い空と白い雲が夏休みを思い浮かばせる意味になる。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す意味で、夏休みを対象にできない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録する意味で、夏休みを対象にできない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べる意味で、夏休みを対象にできない。"}], "explanations": {"連想": "「夏休みを連想させる」の形で、青い空と白い雲が夏休みを思い浮かばせる意味になる。", "修理": "壊れたものを直す意味で、夏休みを対象にできない。", "録音": "音を記録する意味で、夏休みを対象にできない。", "点検": "状態を調べる意味で、夏休みを対象にできない。"}, "sentence_index": 6, "correct_answer": "連想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紙の数字を連想させて、計算の答えを出した。", "explanation": "ここは〈算出〉の意味。連想は思い浮かべる働きで、数字から答えを割り出す行為には使わない。"}, {"text": "眩しい光を浴びて、目が連想して閉じた。", "explanation": "ここは〈反射〉の意味。連想は意識的な思い浮かべの働きで、体の無意識の動きには使わない。"}, {"text": "この英語の文章を連想して、日本語に訳した。", "explanation": "ここは〈翻訳〉の意味。連想は思い浮かべる働きで、言語を別の言語に置き換える行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53268, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このにおいは、祖父の家の台所を連想せる。", "corrected_sentence": "このにおいは、祖父の家の台所を連想させる。", "error_description": "「連想せる」は誤り。使役の形は「連想させる」で、語幹に「さ」を入れる必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53268, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この曲を聞くと、夏休みが連想させる。", "corrected_sentence": "この曲を聞くと、夏休みが連想される。", "error_description": "「連想させる」は他動詞の形で、「夏休みが」を主語にして思い浮かべられる文では「連想される」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「あなたの」の「の」。アイデンティティの持ち主を示す修飾として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「あなたをアイデンティティだ」では述語が成り立たず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や帰着点を示す。「あなたにアイデンティティだ」では所属が示せず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「あなたとアイデンティティだ」では所属の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「あなたの」の「の」。アイデンティティの持ち主を示す修飾として正しい。", "を": "「を」は目的語を示す。「あなたをアイデンティティだ」では述語が成り立たず不自然。", "に": "「に」は対象や帰着点を示す。「あなたにアイデンティティだ」では所属が示せず合わない。", "と": "「と」は並列や相手を示す。「あなたとアイデンティティだ」では所属の関係が成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着・対象", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「感じる」の対象を示す「を」。アイデンティティに直接付き、目的語として正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「アイデンティティへ感じている」では感じる対象にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「アイデンティティより感じている」では比べる対象がなく意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示す。「アイデンティティの感じている」では動詞の目的語が立たない。"}], "correct_answer": "を", "explanations": {"を": "「感じる」の対象を示す「を」。アイデンティティに直接付き、目的語として正しい。", "へ": "「へ」は方向を示す。「アイデンティティへ感じている」では感じる対象にならず不自然。", "より": "「より」は比較を示す。「アイデンティティより感じている」では比べる対象がなく意味が通らない。", "の": "「の」は所属や修飾を示す。「アイデンティティの感じている」では動詞の目的語が立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あなたがあなたであるという気持ちです。みんなとちがうあなたのすてきなところのことです。", "primary_collocate": null, "pronunciation": "あいでんてぃてぃ", "ipa": "aideɴtiti", "syllable_count": 6, "sentences": [{"text": "自分のアイデンティティを大切にしてください。", "target_word": "アイデンティティ", "complexity_tier": "T2", "furigana": "自分(じぶん)のアイデンティティを大切(たいせつ)にしてください。", "sentence_source": "generated"}, {"text": "みんなと違うところが、あなたのアイデンティティだ。", "target_word": "アイデンティティ", "complexity_tier": "T2", "furigana": "みんなと違(ちが)うところが、あなたのアイデンティティだ。", "sentence_source": "generated"}, {"text": "友達をまねしすぎると、自分のアイデンティティが分からなくなる。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "友達(ともだち)をまねしすぎると、自分(じぶん)のアイデンティティが分(わ)からなくなる。", "sentence_source": "generated"}, {"text": "絵が好きなことは、私のアイデンティティだと思う。", "target_word": "アイデンティティ", "complexity_tier": "T2", "furigana": "絵(え)が好(す)きなことは、私(わたし)のアイデンティティだと思(おも)う。", "sentence_source": "generated"}, {"text": "先生は、一人一人のアイデンティティを認めてくれる。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "先生(せんせい)は、一人一人(ひとりひとり)のアイデンティティを認(みと)めてくれる。", "sentence_source": "generated"}, {"text": "名前は、自分のアイデンティティを表す大切なものだ。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "名前(なまえ)は、自分(じぶん)のアイデンティティを表(あらわ)す大切(たいせつ)なものだ。", "sentence_source": "generated"}, {"text": "人と同じにしなくても、アイデンティティは変わらない。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "人(ひと)と同(おな)じにしなくても、アイデンティティは変(か)わらない。", "sentence_source": "generated"}, {"text": "彼は、歌うことで自分のアイデンティティを感じている。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "彼(かれ)は、歌(うた)うことで自分(じぶん)のアイデンティティを感(かん)じている。", "sentence_source": "generated"}, {"text": "自分らしさを守ることは、アイデンティティを持つことだ。", "target_word": "アイデンティティ", "complexity_tier": "T3", "furigana": "自分(じぶん)らしさを守(まも)ることは、アイデンティティを持(も)つことだ。", "sentence_source": "generated"}, {"text": "アイデンティティがはっきりしている人は、迷っても自分を信じられる。", "target_word": "アイデンティティ", "complexity_tier": "T4", "furigana": "アイデンティティがはっきりしている人(ひと)は、迷(まよ)っても自分(じぶん)を信(しん)じられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイデンティティ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分が自分であるという気持ちと、人と違う自分らしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイデンティティ", "is_correct": true, "explanation": "自分が自分であるという気持ちを指し、大切にする対象として自然。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの日時で、大切にする対象としては不自然。"}, {"text": "手数料", "is_correct": false, "explanation": "手数料は取引にかかる費用で、自分の大切なものとしては言わない。"}, {"text": "配線", "is_correct": false, "explanation": "配線は電気の線のことで、人が大切にするものとしては合わない。"}], "explanations": {"アイデンティティ": "自分が自分であるという気持ちを指し、大切にする対象として自然。", "期限": "期限は締め切りの日時で、大切にする対象としては不自然。", "手数料": "手数料は取引にかかる費用で、自分の大切なものとしては言わない。", "配線": "配線は電気の線のことで、人が大切にするものとしては合わない。"}, "sentence_index": 0, "correct_answer": "アイデンティティ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車のアイデンティティが遅れて、会議に間に合わなかった。", "explanation": "ここは〈時刻〉の意味。遅れるのは時刻や時間に関わるもので、アイデンティティは時間を表さないので誤り。"}, {"text": "スマホのアイデンティティが割れて、修理に出した。", "explanation": "ここは〈画面〉の意味。割れるのは物の表面を指すので、形のないアイデンティティには使わない。"}, {"text": "その部屋のアイデンティティは十畳で、一人で住むには十分だ。", "explanation": "ここは〈広さ〉の意味。畳の数で表す面積を指すので、アイデンティティを十畳と測るのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイデンティティ", "is_correct": true, "explanation": "自分が自分であるという感覚を指し、変わらないものとして文に合う。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音の高さの並びで、人のあり方について変わらないとは言わない。"}, {"text": "印鑑", "is_correct": false, "explanation": "印鑑は判を押す道具で、人と同じにしなくても変わらないものではない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分量で、人の生き方について変わらないと言う文には入らない。"}], "explanations": {"アイデンティティ": "自分が自分であるという感覚を指し、変わらないものとして文に合う。", "音階": "音階は音の高さの並びで、人のあり方について変わらないとは言わない。", "印鑑": "印鑑は判を押す道具で、人と同じにしなくても変わらないものではない。", "湿度": "湿度は空気中の水分量で、人の生き方について変わらないと言う文には入らない。"}, "sentence_index": 6, "correct_answer": "アイデンティティ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はアイデンティティが温かく、誰にでも優しい。", "explanation": "ここは〈人柄〉の意味。温かい・冷たいは人柄の評価で、アイデンティティを温かさで言うのは不自然で誤り。"}, {"text": "彼のアイデンティティは鋭く、色の違いにすぐ気づく。", "explanation": "ここは〈感性〉の意味。鋭い・鈍いで表す感じ取る力を指すので、アイデンティティを鋭さで評価するのは誤り。"}, {"text": "あの人はアイデンティティが穏やかで、言葉づかいが丁寧だ。", "explanation": "ここは〈品性〉の意味。穏やかさや品のよさは品性で表すので、アイデンティティを穏やかさで言うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は、自分のアイデンティティに確かめた。", "corrected_sentence": "彼女は、自分のアイデンティティを確かめた。", "error_description": "「確かめる」は確認する対象を「を」で示す。「に」は相手を示す言い方で、アイデンティティを相手にできないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "迷ったときこそ、自分のアイデンティティを見つめ直しことが大切だ。", "corrected_sentence": "迷ったときこそ、自分のアイデンティティを見つめ直すことが大切だ。", "error_description": "「見つめ直す」を名詞にするには「見つめ直すこと」とする。「見つめ直しこと」は連用形に「こと」を付けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『影』が『織りなす』の主語となり、『光と影が織りなす模様』で文が成り立つ。"}, {"text": "は", "is_correct": false, "explanation": "主題の『は』は連体修飾節の主語になれないため、『光と影は織りなす模様』は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『影に』では主体を示せず、織りなすの相手としても合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』で、『影より織りなす』は文として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『影』が『織りなす』の主語となり、『光と影が織りなす模様』で文が成り立つ。", "は": "主題の『は』は連体修飾節の主語になれないため、『光と影は織りなす模様』は成り立たない。", "に": "『影に』では主体を示せず、織りなすの相手としても合わない。", "より": "比較の『より』で、『影より織りなす』は文として意味が通らない。"}, "error_tags": {"を": "目的語の格で、織りなす主語にならない", "に": "帰着・相手の格で、主語を示せない", "より": "比較の格で、主語の役割を果たさない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『文化』が『織りなす』の主語となり、『文化が織りなす町』で文が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の『と』で、『文化と織りなす』では織りなす主語の関係が成立しない。"}, {"text": "は", "is_correct": false, "explanation": "主題の『は』は連体修飾節の主語になれないため、『文化は織りなす町』は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』で、文化が織りなす主体にならない。"}], "correct_answer": "が", "explanations": {"が": "『文化』が『織りなす』の主語となり、『文化が織りなす町』で文が成り立つ。", "と": "並列・共同の『と』で、『文化と織りなす』では織りなす主語の関係が成立しない。", "は": "主題の『は』は連体修飾節の主語になれないため、『文化は織りなす町』は成り立たない。", "から": "起点の『から』で、文化が織りなす主体にならない。"}, "error_tags": {"と": "並列・共同の格", "で": "手段・場所の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いろいろなものを組み合わせて、一つにまとめることです。糸と糸を交えて布を作る様子から言葉になりました。色や形を上手につなげて、きれいなものを作ります。", "primary_collocate": null, "pronunciation": "おりなす", "ipa": "oɾinasɯ", "syllable_count": 4, "sentences": [{"text": "秋の山は、赤や黄色の葉が織りなす美しい景色で有名だ。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "秋[あき]の山[やま]は、赤[あか]や黄色[きいろ]の葉[は]が織[お]りなす美[うつく]しい景色[けしき]で有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "光と影が織りなす模様を、写真に撮った。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "光[ひかり]と影[かげ]が織[お]りなす模様[もよう]を、写真[しゃしん]に撮[と]った。", "sentence_source": "generated"}, {"text": "この映画は、家族の愛と別れが織りなす物語だ。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "この映画[えいが]は、家族[かぞく]の愛[あい]と別[わか]れが織[お]りなす物語[ものがたり]だ。", "sentence_source": "generated"}, {"text": "楽器の音が織りなす音楽に、会場全体が静かになった。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "楽器[がっき]の音[おと]が織[お]りなす音楽[おんがく]に、会場[かいじょう]全体[ぜんたい]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "祖母の庭では、色の違う花々が織りなす模様が一面に広がっていた。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "祖母[そぼ]の庭[にわ]では、色[いろ]の違[ちが]う花々[はなばな]が織[お]りなす模様[もよう]が一面[いちめん]に広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "川と森が織りなす自然の中で、三日間ゆっくり過ごした。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "川[かわ]と森[もり]が織[お]りなす自然[しぜん]の中[なか]で、三日間[みっかかん]ゆっくり過[す]ごした。", "sentence_source": "generated"}, {"text": "古い町並みは、歴史と人々の暮らしが織りなした風景だ。", "target_word": "織りなした", "complexity_tier": "T3", "furigana": "古[ふる]い町並[まちな]みは、歴史[れきし]と人々[ひとびと]の暮[く]らしが織[お]りなした風景[ふうけい]だ。", "sentence_source": "generated"}, {"text": "いろいろな国の文化が織りなす町なので、毎日がおもしろい。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "いろいろな国[くに]の文化[ぶんか]が織[お]りなす町[まち]なので、毎日[まいにち]がおもしろい。", "sentence_source": "generated"}, {"text": "二人の歌声が織りなすハーモニーは、とても美しかった。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "二人[ふたり]の歌声[うたごえ]が織[お]りなすハーモニーは、とても美[うつく]しかった。", "sentence_source": "generated"}, {"text": "夕方の空は、赤と紫が織りなす不思議な色に染まった。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]の空[そら]は、赤[あか]と紫[むらさき]が織[お]りなす不思議[ふしぎ]な色[いろ]に染[そ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "織りなす", "label": "終止形"}, {"form": "織りなし", "label": "連用形"}, {"form": "織りなして", "label": "て形"}, {"form": "織りなした", "label": "た形"}, {"form": "織りなさない", "label": "否定形"}, {"form": "織りなせば", "label": "仮定形"}, {"form": "織りなそう", "label": "意志形"}], "register": "書き言葉（やや文学的）", "sense_fingerprint": "色・光・音・人などいろいろなものを組み合わせて、一つの景色や作品、物語を作り上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "葉が集まって一つの美しい景色を作るという意味で、『景色』を修飾する連体形として文に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "『眺める』は見る動作なので、葉を主語にすると『葉が景色を眺める』となり意味が通らない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "『運ぶ』は物を移す動作で、葉が景色を運ぶという文にはならない。"}, {"text": "壊す", "is_correct": false, "explanation": "『壊す』は物を壊す動作で、葉が景色を壊すという文脈では意味が成り立たない。"}], "explanations": {"織りなす": "葉が集まって一つの美しい景色を作るという意味で、『景色』を修飾する連体形として文に合う。", "眺める": "『眺める』は見る動作なので、葉を主語にすると『葉が景色を眺める』となり意味が通らない。", "運ぶ": "『運ぶ』は物を移す動作で、葉が景色を運ぶという文にはならない。", "壊す": "『壊す』は物を壊す動作で、葉が景色を壊すという文脈では意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "織りなす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい料理のために、いくつかの調味料を織りなした。", "explanation": "ここは〈混ぜ合わせる〉の意味。織りなすは景色・模様・音楽など美しく一つにまとまったものを作る語なので、調味料を混ぜる意味では使わない。"}, {"text": "祖母は冬のために、毛糸で手袋を織りなした。", "explanation": "ここは〈編む〉の意味。織りなすは模様や景色など全体の美しさを指し、手袋のような完成品を作る意味では使わない。"}, {"text": "引っ越しの日、新しい机を織りなして部屋の隅に置いた。", "explanation": "ここは〈組み立てる〉の意味。織りなすは景色や模様など美しく仕上がったまとまりに使い、家具の組み立てには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "織りなした", "is_correct": true, "explanation": "歴史と暮らしが組み合わさって一つの風景を作ったという意味で、過去の連体形として文に合う。"}, {"text": "叫んだ", "is_correct": false, "explanation": "『叫んだ』は声を出す動作で、歴史や暮らしが叫ぶ風景という文にはならない。"}, {"text": "注いだ", "is_correct": false, "explanation": "『注いだ』は液体を移す動作で、暮らしが風景に注ぐという文では意味が通らない。"}, {"text": "飲んだ", "is_correct": false, "explanation": "『飲んだ』は口にする動作で、歴史と暮らしが風景を飲むという文は成り立たない。"}], "explanations": {"織りなした": "歴史と暮らしが組み合わさって一つの風景を作ったという意味で、過去の連体形として文に合う。", "叫んだ": "『叫んだ』は声を出す動作で、歴史や暮らしが叫ぶ風景という文にはならない。", "注いだ": "『注いだ』は液体を移す動作で、暮らしが風景に注ぐという文では意味が通らない。", "飲んだ": "『飲んだ』は口にする動作で、歴史と暮らしが風景を飲むという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "織りなした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい委員会を織りなして、三人の代表を選んだ。", "explanation": "ここは〈組織する〉の意味。織りなすは景色や模様など感覚的な美しさを作る語で、委員会のような組織には使わない。"}, {"text": "散らかった本を、高さ順に織りなした。", "explanation": "ここは〈整える〉の意味。織りなすは一つにまとまった美しいものを作る語で、本を揃えたり片付けたりする動作には合わない。"}, {"text": "二人は旅行の計画を織りなした。", "explanation": "ここは〈立てる〉の意味。織りなすは色・音・景色など美しく一つにまとまったものを作る語なので、計画を立てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕焼けと波の音が織りなし景色が、海辺の町を包んでいる。", "corrected_sentence": "夕焼けと波の音が織りなす景色が、海辺の町を包んでいる。", "error_description": "『織りなし』は連用形で、名詞『景色』を修飾できない。名詞を修飾する連体形『織りなす』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "『模様』を修飾する連体形で、ここに合う。"}, {"text": "織りなして", "is_correct": false, "explanation": "て形は後ろに続く文を作る形で、名詞『模様』を修飾できない。"}, {"text": "織りなせ", "is_correct": false, "explanation": "命令形で、名詞『模様』を修飾できず文が成り立たない。"}, {"text": "織りなそう", "is_correct": false, "explanation": "意志形で、名詞『模様』を修飾する形ではなく文が成り立たない。"}], "correct_form": "織りなす", "base_form": "織りなす", "form_label": "連体形", "sentence_index": 1, "explanations": {"織りなす": "『模様』を修飾する連体形で、ここに合う。", "織りなして": "て形は後ろに続く文を作る形で、名詞『模様』を修飾できない。", "織りなせ": "命令形で、名詞『模様』を修飾できず文が成り立たない。", "織りなそう": "意志形で、名詞『模様』を修飾する形ではなく文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山あいの村では、朝霧と陽の光が織りなさ幻想的な風景が広がっている。", "corrected_sentence": "山あいの村では、朝霧と陽の光が織りなす幻想的な風景が広がっている。", "error_description": "『織りなさ』は未然形で、名詞『風景』を修飾できない。正しくは連体形『織りなす』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "『文化が織りなす町』の連体形で、『町』を修飾するので文に合う。"}, {"text": "織りなさ", "is_correct": false, "explanation": "未然形で、名詞「町」を修飾できないので合わない。"}, {"text": "織りなし", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、『町なので』の前に置く形として合わない。"}, {"text": "織りなします", "is_correct": false, "explanation": "丁寧形で、名詞「町」を修飾できないので合わない。"}], "correct_form": "織りなす", "base_form": "織りなす", "form_label": "連体形", "sentence_index": 7, "explanations": {"織りなす": "『文化が織りなす町』の連体形で、『町』を修飾するので文に合う。", "織りなさ": "未然形で、名詞「町」を修飾できないので合わない。", "織りなし": "連用形は名詞を直接修飾できず、『町なので』の前に置く形として合わない。", "織りなします": "丁寧形で、名詞「町」を修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「今日の売上」で、今日の売上という修飾関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「今日を売上は」は、名詞「今日」に「を」を付けても文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「今日へ売上」は意味が通らない。"}, {"text": "か", "is_correct": false, "explanation": "「今日か売上は」では、「か」が名詞の間に入って文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「今日の売上」で、今日の売上という修飾関係を表す。", "を": "「今日を売上は」は、名詞「今日」に「を」を付けても文が成り立たない。", "へ": "「へ」は方向を表すので、「今日へ売上」は意味が通らない。", "か": "「今日か売上は」では、「か」が名詞の間に入って文が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "か": "question_or_choice"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支出", "is_correct": true, "explanation": "売上が入るお金なら、支出は出ていくお金で、反対の関係。"}, {"text": "収入", "is_correct": false, "explanation": "売上に近い意味で、反対ではない。"}, {"text": "利益", "is_correct": false, "explanation": "売上から費用を引いた残りで、反対の関係ではない。"}, {"text": "代金", "is_correct": false, "explanation": "商品の支払い額で、反対の関係ではない。"}], "correct_answer": "支出", "explanations": {"支出": "売上が入るお金なら、支出は出ていくお金で、反対の関係。", "収入": "売上に近い意味で、反対ではない。", "利益": "売上から費用を引いた残りで、反対の関係ではない。", "代金": "商品の支払い額で、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「去年より増える」で比較の基準を表す。"}, {"text": "を", "is_correct": false, "explanation": "「去年を増えて」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、比較の基準には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「去年と増えて」では比較の意味にならず、文法的に不自然。"}], "correct_answer": "より", "explanations": {"より": "「去年より増える」で比較の基準を表す。", "を": "「去年を増えて」は文法的に成り立たない。", "へ": "「へ」は方向を表すので、比較の基準には使えない。", "と": "「去年と増えて」では比較の意味にならず、文法的に不自然。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comparison_with"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仕入れ", "is_correct": true, "explanation": "売る側の売上に対し、仕入れは買い入れる側で、反対の関係。"}, {"text": "収益", "is_correct": false, "explanation": "売上に近い収入の意味で、反対ではない。"}, {"text": "利益", "is_correct": false, "explanation": "売上から費用を引いた残りで、反対の関係ではない。"}, {"text": "料金", "is_correct": false, "explanation": "サービスに対する支払い額で、反対の関係ではない。"}], "correct_answer": "仕入れ", "explanations": {"仕入れ": "売る側の売上に対し、仕入れは買い入れる側で、反対の関係。", "収益": "売上に近い収入の意味で、反対ではない。", "利益": "売上から費用を引いた残りで、反対の関係ではない。", "料金": "サービスに対する支払い額で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを売って、もらったおかねのことです。", "primary_collocate": null, "pronunciation": "うりあげ", "ipa": "uɾiaɡe", "syllable_count": 4, "sentences": [{"text": "今日の売上は多い。", "target_word": "売上", "complexity_tier": "T1", "furigana": "今日[きょう]の売上[うりあげ]は多[おお]い。", "sentence_source": "generated"}, {"text": "売上を数える。", "target_word": "売上", "complexity_tier": "T1", "furigana": "売上[うりあげ]を数[かぞ]える。", "sentence_source": "generated"}, {"text": "売上が少ない。", "target_word": "売上", "complexity_tier": "T1", "furigana": "売上[うりあげ]が少[すく]ない。", "sentence_source": "generated"}, {"text": "今日の売上は一万円でした。", "target_word": "売上", "complexity_tier": "T2", "furigana": "今日[きょう]の売上[うりあげ]は一万円[いちまんえん]でした。", "sentence_source": "generated"}, {"text": "店の人が売上を数えています。", "target_word": "売上", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]が売上[うりあげ]を数[かぞ]えています。", "sentence_source": "generated"}, {"text": "夏はアイスの売上がよく伸びます。", "target_word": "売上", "complexity_tier": "T2", "furigana": "夏[なつ]はアイスの売上[うりあげ]がよく伸[の]びます。", "sentence_source": "generated"}, {"text": "売上の一部で本を買った。", "target_word": "売上", "complexity_tier": "T3", "furigana": "売上[うりあげ]の一部[いちぶ]で本[ほん]を買[か]った。", "sentence_source": "generated"}, {"text": "売上が去年より増えて、店の人は喜んだ。", "target_word": "売上", "complexity_tier": "T3", "furigana": "売上[うりあげ]が去年[きょねん]より増[ふ]えて、店[みせ]の人[ひと]は喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "売上を銀行に預けに行きました。", "target_word": "売上", "complexity_tier": "T2", "furigana": "売上[うりあげ]を銀行[ぎんこう]に預[あず]けに行[い]きました。", "sentence_source": "generated"}, {"text": "雨が降ると、売上が減ってしまう。", "target_word": "売上", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、売上[うりあげ]が減[へ]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売上高", "label": "派生"}, {"form": "売上金", "label": "派生"}, {"form": "総売上", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 売って得たお金のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "売上", "is_correct": true, "explanation": "見出し語そのもの。うりあげ。"}, {"text": "打ち上げ", "is_correct": false, "explanation": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。"}, {"text": "取り上げ", "is_correct": false, "explanation": "とりあげ。1拍目の「う」が「と」に変わるだけの別語。"}, {"text": "盛り上げ", "is_correct": false, "explanation": "もりあげ。1拍目の「う」が「も」に変わるだけの別語。"}, {"text": "繰り上げ", "is_correct": false, "explanation": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。"}], "explanations": {"売上": "見出し語そのもの。うりあげ。", "打ち上げ": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。", "取り上げ": "とりあげ。1拍目の「う」が「と」に変わるだけの別語。", "盛り上げ": "もりあげ。1拍目の「う」が「も」に変わるだけの別語。", "繰り上げ": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "売上"}, "level_3": {"options": [{"text": "売上", "is_correct": true, "explanation": "「多い」と合い、今日の店の収入を表す。"}, {"text": "天気", "is_correct": false, "explanation": "名詞として形は合うが、天気は「多い」とは言わないので意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、気温は「高い」で「多い」とは言わないので意味が合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "形は合うが、速さは「多い」ではなく「速い」と言うので意味が合わない。"}], "explanations": {"売上": "「多い」と合い、今日の店の収入を表す。", "天気": "名詞として形は合うが、天気は「多い」とは言わないので意味が合わない。", "気温": "形は合うが、気温は「高い」で「多い」とは言わないので意味が合わない。", "速さ": "形は合うが、速さは「多い」ではなく「速い」と言うので意味が合わない。"}, "sentence_index": 0, "correct_answer": "売上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の売上は晴れでした。", "explanation": "売上は金額で、天気を表す語ではない。"}, {"text": "売上を着て、寒い外に出かけた。", "explanation": "売上は金額で、服ではないので「着る」の対象にならない。"}, {"text": "売上は店で売っている、おいしい甘い果物だ。", "explanation": "売上はお金のことで、食べ物の果物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "売上", "is_correct": true, "explanation": "見出し語そのもの。うりあげ。"}, {"text": "繰り上げ", "is_correct": false, "explanation": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。"}, {"text": "釣り上げ", "is_correct": false, "explanation": "つりあげ。1拍目の「う」が「つ」に変わるだけの別語。"}, {"text": "打ち上げ", "is_correct": false, "explanation": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。"}, {"text": "刈り上げ", "is_correct": false, "explanation": "かりあげ。1拍目の「う」が「か」に変わるだけの別語。"}], "explanations": {"売上": "見出し語そのもの。うりあげ。", "繰り上げ": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。", "釣り上げ": "つりあげ。1拍目の「う」が「つ」に変わるだけの別語。", "打ち上げ": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。", "刈り上げ": "かりあげ。1拍目の「う」が「か」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "売上"}, "level_3": {"options": [{"text": "売上", "is_correct": true, "explanation": "売って得たお金の一部で本を買った、という文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "名詞として形は合うが、天気の一部で本は買えないので意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節の一部で本は買えないので意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、時間の一部で本を買うことはできないので意味が合わない。"}], "explanations": {"売上": "売って得たお金の一部で本を買った、という文脈に合う。", "天気": "名詞として形は合うが、天気の一部で本は買えないので意味が合わない。", "季節": "形は合うが、季節の一部で本は買えないので意味が合わない。", "時間": "形は合うが、時間の一部で本を買うことはできないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "売上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ると、売上が眠ってしまう。", "explanation": "売上は金額で、人や動物ではないので「眠る」の主語にならない。"}, {"text": "売上を食べて、お腹がいっぱいになった。", "explanation": "売上はお金のことで、食べ物ではないので「食べる」の対象にならない。"}, {"text": "雨が降ると、売上が長くなってしまう。", "explanation": "売上は金額なので、長さを表す「長い」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "売上を多いので、店の人は笑っている。", "corrected_sentence": "売上が多いので、店の人は笑っている。", "error_description": "「多い」の主語になる売上には、「を」ではなく「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の売上に三千円でした。", "corrected_sentence": "昨日の売上は三千円でした。", "error_description": "「売上＝三千円」と述べる文なので、「に」ではなく主題の「は」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「先月より多い」で比較の基準を表す。"}, {"text": "を", "is_correct": false, "explanation": "「先月を多い」は形容詞の前で使えず、文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「先月と多い」では比較の意味にならず、文法的に不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、比較の基準には使えない。"}], "correct_answer": "より", "explanations": {"より": "「先月より多い」で比較の基準を表す。", "を": "「先月を多い」は形容詞の前で使えず、文法的に成り立たない。", "と": "「先月と多い」では比較の意味にならず、文法的に不自然。", "へ": "「へ」は方向を表すので、比較の基準には使えない。"}, "error_tags": {"を": "object_marker", "と": "comparison_with", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支出", "is_correct": true, "explanation": "売上が入ってくる金なら、支出は出ていく金で、反対の関係。"}, {"text": "収入", "is_correct": false, "explanation": "売上に近い意味で、反対ではない。"}, {"text": "利益", "is_correct": false, "explanation": "売上から費用を引いた残りで、反対の関係ではない。"}, {"text": "代金", "is_correct": false, "explanation": "商品の支払い額で、反対の関係ではない。"}], "correct_answer": "支出", "explanations": {"支出": "売上が入ってくる金なら、支出は出ていく金で、反対の関係。", "収入": "売上に近い意味で、反対ではない。", "利益": "売上から費用を引いた残りで、反対の関係ではない。", "代金": "商品の支払い額で、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「売上の一部」で、売上全体のうちの一部という所有・部分を表す。"}, {"text": "を", "is_correct": false, "explanation": "「売上を一部を」と目的語が重なり、文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「売上へ一部」は意味が通らない。"}, {"text": "まで", "is_correct": false, "explanation": "「売上まで一部を」は範囲の意味にならず、文法的に不自然。"}], "correct_answer": "の", "explanations": {"の": "「売上の一部」で、売上全体のうちの一部という所有・部分を表す。", "を": "「売上を一部を」と目的語が重なり、文法的に成り立たない。", "へ": "「へ」は方向を表すので、「売上へ一部」は意味が通らない。", "まで": "「売上まで一部を」は範囲の意味にならず、文法的に不自然。"}, "error_tags": {"を": "double_object", "へ": "direction", "まで": "limit"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仕入れ", "is_correct": true, "explanation": "売る側の売上に対し、仕入れは買い入れる側で、反対の関係。"}, {"text": "収益", "is_correct": false, "explanation": "売上に近い収入の意味で、反対ではない。"}, {"text": "利益", "is_correct": false, "explanation": "売上から費用を引いた残りで、反対の関係ではない。"}, {"text": "料金", "is_correct": false, "explanation": "サービスに対する支払い額で、反対の関係ではない。"}], "correct_answer": "仕入れ", "explanations": {"仕入れ": "売る側の売上に対し、仕入れは買い入れる側で、反対の関係。", "収益": "売上に近い収入の意味で、反対ではない。", "利益": "売上から費用を引いた残りで、反対の関係ではない。", "料金": "サービスに対する支払い額で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物やサービスを売って得た代金の総額。商業活動において、商品が売れた際に発生する収入額。", "primary_collocate": null, "pronunciation": "うりあげ", "ipa": "uɾiaɡe", "syllable_count": 4, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "売上", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "今月の売上は先月より多いです。", "target_word": "売上", "complexity_tier": "T2", "furigana": "今月[こんげつ]の売上[うりあげ]は先月[せんげつ]より多[おお]いです。", "sentence_source": "generated"}, {"text": "売上を毎日ノートに書きます。", "target_word": "売上", "complexity_tier": "T2", "furigana": "売上[うりあげ]を毎日[まいにち]ノートに書[か]きます。", "sentence_source": "generated"}, {"text": "店の売上が少しずつ上がっている。", "target_word": "売上", "complexity_tier": "T3", "furigana": "店[みせ]の売上[うりあげ]が少[すこ]しずつ上[あ]がっている。", "sentence_source": "generated"}, {"text": "雨の日は、売上が下がってしまった。", "target_word": "売上", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、売上[うりあげ]が下[さ]がってしまった。", "sentence_source": "generated"}, {"text": "新しい商品のおかげで、売上が二倍になった。", "target_word": "売上", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]のおかげで、売上[うりあげ]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "売上を伸ばすために、広告を出した。", "target_word": "売上", "complexity_tier": "T3", "furigana": "売上[うりあげ]を伸[の]ばすために、広告[こうこく]を出[だ]した。", "sentence_source": "generated"}, {"text": "売上の一部を学校に寄付した。", "target_word": "売上", "complexity_tier": "T3", "furigana": "売上[うりあげ]の一部[いちぶ]を学校[がっこう]に寄付[きふ]した。", "sentence_source": "generated"}, {"text": "天気が悪いと売上が減ってしまうと店長は言った。", "target_word": "売上", "complexity_tier": "T4", "furigana": "天気[てんき]が悪[わる]いと売上[うりあげ]が減[へ]ってしまうと店長[てんちょう]は言[い]った。", "sentence_source": "generated"}, {"text": "この店は夏の売上に大きく支えられている。", "target_word": "売上", "complexity_tier": "T4", "furigana": "この店[みせ]は夏[なつ]の売上[うりあげ]に大[おお]きく支[ささ]えられている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売上高", "label": "派生"}, {"form": "売上金", "label": "派生"}, {"form": "総売上", "label": "派生"}, {"form": "売り上げ", "label": "異表記"}], "register": "plain", "sense_fingerprint": "名詞 | 商品が売れて得た収入の金額", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "売上", "is_correct": true, "explanation": "見出し語そのもの。うりあげ。"}, {"text": "打ち上げ", "is_correct": false, "explanation": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。"}, {"text": "繰り上げ", "is_correct": false, "explanation": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。"}, {"text": "釣り上げ", "is_correct": false, "explanation": "つりあげ。1拍目の「う」が「つ」に変わるだけの別語。"}, {"text": "刈り上げ", "is_correct": false, "explanation": "かりあげ。1拍目の「う」が「か」に変わるだけの別語。"}], "explanations": {"売上": "見出し語そのもの。うりあげ。", "打ち上げ": "うちあげ。2拍目の「り」が「ち」に変わるだけの別語。", "繰り上げ": "くりあげ。1拍目の「う」が「く」に変わるだけの別語。", "釣り上げ": "つりあげ。1拍目の「う」が「つ」に変わるだけの別語。", "刈り上げ": "かりあげ。1拍目の「う」が「か」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "売上"}, "level_3": {"options": [{"text": "売上", "is_correct": true, "explanation": "少年の努力が小さな収入という実を結んだ、という文脈に合う。"}, {"text": "損失", "is_correct": false, "explanation": "名詞として形は合うが、「実を結ぶ」という前向きな結果とは意味が合わない。"}, {"text": "出費", "is_correct": false, "explanation": "形は合うが、努力が実を結んだ結果が出費というのは意味が合わない。"}, {"text": "借金", "is_correct": false, "explanation": "形は合うが、努力が実を結んだ結果が借金というのは意味が合わない。"}], "explanations": {"売上": "少年の努力が小さな収入という実を結んだ、という文脈に合う。", "損失": "名詞として形は合うが、「実を結ぶ」という前向きな結果とは意味が合わない。", "出費": "形は合うが、努力が実を結んだ結果が出費というのは意味が合わない。", "借金": "形は合うが、努力が実を結んだ結果が借金というのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "売上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レジで売上を払って、パンを買った。", "explanation": "売上は店側が得る収入で、客が払うものではない。客が払うのは「代金」。"}, {"text": "この山の売上はとても高くて、頂上が雲に隠れている。", "explanation": "売上は金額で、山の高さを表す語ではない。"}, {"text": "売上を飲んだら、のどが少しいたくなった。", "explanation": "売上は金額のことで、飲み物ではないので「飲む」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "売上", "is_correct": true, "explanation": "見出し語そのもの。うりあげ。"}, {"text": "取り上げ", "is_correct": false, "explanation": "とりあげ。1拍目の「う」が「と」に変わるだけの別語。"}, {"text": "切り上げ", "is_correct": false, "explanation": "きりあげ。1拍目の「う」が「き」に変わるだけの別語。"}, {"text": "盛り上げ", "is_correct": false, "explanation": "もりあげ。1拍目の「う」が「も」に変わるだけの別語。"}, {"text": "振り上げ", "is_correct": false, "explanation": "ふりあげ。1拍目の「う」が「ふ」に変わるだけの別語。"}], "explanations": {"売上": "見出し語そのもの。うりあげ。", "取り上げ": "とりあげ。1拍目の「う」が「と」に変わるだけの別語。", "切り上げ": "きりあげ。1拍目の「う」が「き」に変わるだけの別語。", "盛り上げ": "もりあげ。1拍目の「う」が「も」に変わるだけの別語。", "振り上げ": "ふりあげ。1拍目の「う」が「ふ」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "売上"}, "level_3": {"options": [{"text": "売上", "is_correct": true, "explanation": "広告で伸ばしたいのは売上、という文脈に合う。"}, {"text": "経費", "is_correct": false, "explanation": "形は合うが、広告を出すのは経費を伸ばすためではないので意味が合わない。"}, {"text": "借金", "is_correct": false, "explanation": "形は合うが、借金を伸ばすために広告を出すのは意味が合わない。"}, {"text": "損失", "is_correct": false, "explanation": "形は合うが、損失を伸ばしたい人はいないので意味が合わない。"}], "explanations": {"売上": "広告で伸ばしたいのは売上、という文脈に合う。", "経費": "形は合うが、広告を出すのは経費を伸ばすためではないので意味が合わない。", "借金": "形は合うが、借金を伸ばすために広告を出すのは意味が合わない。", "損失": "形は合うが、損失を伸ばしたい人はいないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "売上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は売上が好きで、毎日公園で一緒に散歩している。", "explanation": "売上は金額で、一緒に散歩するペットや人ではない。"}, {"text": "今日の売上は三十度で、とても暑い。", "explanation": "売上は金額で、気温を表す語ではない。"}, {"text": "私は売上を読んで、とても面白い話だと思った。", "explanation": "売上は金額で、読んで楽しむ本や物語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53278, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年は売上を去年の二倍になった。", "corrected_sentence": "今年は売上が去年の二倍になった。", "error_description": "「なる」の主語になる売上には、「を」ではなく「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
