INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53293, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「アイデアがあります」で、あるものを表す主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「アイデアをあります」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「アイデアへあります」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「アイデアのあります」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「アイデアがあります」で、あるものを表す主語になる。", "を": "「アイデアをあります」は文法的に成り立たない。", "へ": "「アイデアへあります」は文法的に成り立たない。", "の": "「アイデアのあります」は文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "の": "possessive"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53293, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「アイデアが出ない」で、アイデアが「出る」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞なので「アイデアを出ない」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「アイデアへ出ない」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「アイデアと出ない」は文法的に成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「アイデアが出ない」で、アイデアが「出る」の主語になる。", "を": "「出る」は自動詞なので「アイデアを出ない」とは言えない。", "へ": "「アイデアへ出ない」は文法的に成り立たない。", "と": "「アイデアと出ない」は文法的に成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "quotation"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53293, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "頭の中に出てきた新しい考えです。", "primary_collocate": null, "pronunciation": "あいであ", "ipa": "aide̞a", "syllable_count": 4, "sentences": [{"text": "アイデアが浮かんだ。", "target_word": "アイデア", "complexity_tier": "T1", "furigana": "アイデアが浮(う)かんだ。", "sentence_source": "generated"}, {"text": "いいアイデアだね。", "target_word": "アイデア", "complexity_tier": "T1", "furigana": "いいアイデアだね。", "sentence_source": "generated"}, {"text": "私にアイデアがあります。", "target_word": "アイデア", "complexity_tier": "T2", "furigana": "私(わたし)にアイデアがあります。", "sentence_source": "generated"}, {"text": "アイデアを教えてください。", "target_word": "アイデア", "complexity_tier": "T2", "furigana": "アイデアを教(おし)えてください。", "sentence_source": "generated"}, {"text": "相談して、いいアイデアを思いついた。", "target_word": "アイデア", "complexity_tier": "T3", "furigana": "相談(そうだん)して、いいアイデアを思(おも)いついた。", "sentence_source": "generated"}, {"text": "アイデアをノートに書いておく。", "target_word": "アイデア", "complexity_tier": "T3", "furigana": "アイデアをノートに書(か)いておく。", "sentence_source": "generated"}, {"text": "アイデアは頭の中で生まれる。", "target_word": "アイデア", "complexity_tier": "T3", "furigana": "アイデアは頭(あたま)の中(なか)で生(う)まれる。", "sentence_source": "generated"}, {"text": "アイデアが出ないときは、散歩に行くことにしている。", "target_word": "アイデア", "complexity_tier": "T4", "furigana": "アイデアが出(で)ないときは、散歩(さんぽ)に行(い)くことにしている。", "sentence_source": "generated"}, {"text": "彼女のアイデアのおかげで、問題が解決した。", "target_word": "アイデア", "complexity_tier": "T4", "furigana": "彼女(かのじょ)のアイデアのおかげで、問題(もんだい)が解決(かいけつ)した。", "sentence_source": "generated"}, {"text": "面白いアイデアを思いついても、実行しなければ何も変わらない。", "target_word": "アイデア", "complexity_tier": "T5", "furigana": "面白(おもしろ)いアイデアを思(おも)いついても、実行(じっこう)しなければ何(なに)も変(か)わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイデア商品", "label": "派生"}, {"form": "アイデアマン", "label": "派生"}, {"form": "アイディア", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 頭に浮かんだ新しい考え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53293, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイデア", "is_correct": true, "explanation": "「アイデアが浮かんだ」は考えが頭に出てきた意味で自然。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "形は合うが意味が合わない。冷蔵庫が浮かぶのは不自然。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが意味が合わない。天井が浮かぶのは不自然。"}, {"text": "掃除機", "is_correct": false, "explanation": "形は合うが意味が合わない。掃除機が浮かんだとは普通言わない。"}], "explanations": {"アイデア": "「アイデアが浮かんだ」は考えが頭に出てきた意味で自然。", "冷蔵庫": "形は合うが意味が合わない。冷蔵庫が浮かぶのは不自然。", "天井": "形は合うが意味が合わない。天井が浮かぶのは不自然。", "掃除機": "形は合うが意味が合わない。掃除機が浮かんだとは普通言わない。"}, "sentence_index": 0, "correct_answer": "アイデア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、アイデアを洗濯機に入れて洗いました。", "explanation": "アイデアは物ではないので、洗濯機で洗えない。"}, {"text": "このアイデアは長さが二メートルもある。", "explanation": "アイデアは形のない考えで、長さを測れない。"}, {"text": "彼はアイデアを着て出かけた。", "explanation": "アイデアは服ではないので「着る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53293, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイデア", "is_correct": true, "explanation": "「アイデアは頭の中で生まれる」で意味が通る。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震は頭の中で生まれない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが意味が合わない。電車が頭の中で生まれるとは言わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。野菜は頭の中で生まれない。"}], "explanations": {"アイデア": "「アイデアは頭の中で生まれる」で意味が通る。", "地震": "形は合うが意味が合わない。地震は頭の中で生まれない。", "電車": "形は合うが意味が合わない。電車が頭の中で生まれるとは言わない。", "野菜": "形は合うが意味が合わない。野菜は頭の中で生まれない。"}, "sentence_index": 6, "correct_answer": "アイデア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は面白いアイデアを冷蔵庫に入れて、夕食に温めた。", "explanation": "アイデアは食べ物ではないので、入れて温めることはできない。"}, {"text": "電車の中でアイデアを踏んでしまい、足が痛い。", "explanation": "アイデアは形のない考えで、踏むことはできない。"}, {"text": "彼は毎日アイデアで顔を洗っている。", "explanation": "アイデアは水のような物ではなく、顔を洗う道具にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
