INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事について新しく浮かぶ考えや発想。", "primary_collocate": null, "pronunciation": "あいであ", "ipa": "aide̞a", "syllable_count": 4, "sentences": [{"text": "スタートアップは、革新的なアイデアを種として創業される。", "target_word": "アイデア", "complexity_tier": "T6", "furigana": "スタートアップは、革新的(かくしんてき)なアイデアを種(たね)として創業(そうぎょう)される。", "sentence_source": "mined"}, {"text": "いいアイデアだ。", "target_word": "アイデア", "complexity_tier": "T1", "furigana": "いいアイデアだ。", "sentence_source": "generated"}, {"text": "アイデアを出す。", "target_word": "アイデア", "complexity_tier": "T1", "furigana": "アイデアを出(だ)す。", "sentence_source": "generated"}, {"text": "新しいアイデアを考えます。", "target_word": "アイデア", "complexity_tier": "T2", "furigana": "新(あたら)しいアイデアを考(かんが)えます。", "sentence_source": "generated"}, {"text": "彼のアイデアは面白いです。", "target_word": "アイデア", "complexity_tier": "T2", "furigana": "彼(かれ)のアイデアは面白(おもしろ)いです。", "sentence_source": "generated"}, {"text": "会議で、みんなのアイデアを聞いた。", "target_word": "アイデア", "complexity_tier": "T3", "furigana": "会議(かいぎ)で、みんなのアイデアを聞(き)いた。", "sentence_source": "generated"}, {"text": "アイデアを形にして、商品として売り出した。", "target_word": "アイデア", "complexity_tier": "T3", "furigana": "アイデアを形(かたち)にして、商品(しょうひん)として売(う)り出(だ)した。", "sentence_source": "generated"}, {"text": "そのアイデアが採用されて、新事業が始まった。", "target_word": "アイデア", "complexity_tier": "T4", "furigana": "そのアイデアが採用(さいよう)されて、新事業(しんじぎょう)が始(はじ)まった。", "sentence_source": "generated"}, {"text": "独創的なアイデアがなければ、競争には勝てない。", "target_word": "アイデア", "complexity_tier": "T4", "furigana": "独創的(どくそうてき)なアイデアがなければ、競争(きょうそう)には勝(か)てない。", "sentence_source": "generated"}, {"text": "起業家は一つのアイデアから出発して、何度も試作を重ね、製品を完成させる。", "target_word": "アイデア", "complexity_tier": "T5", "furigana": "起業家(きぎょうか)は一(ひと)つのアイデアから出発(しゅっぱつ)して、何度(なんど)も試作(しさく)を重(かさ)ね、製品(せいひん)を完成(かんせい)させる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイデア商品", "label": "派生"}, {"form": "アイデアマン", "label": "派生"}, {"form": "アイディア", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事について新しく浮かぶ考え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイデア", "is_correct": true, "explanation": "「革新的なアイデアを種として創業される」で意味が通る。"}, {"text": "在庫", "is_correct": false, "explanation": "形は合うが意味が合わない。在庫は創業の種にならない。"}, {"text": "騒音", "is_correct": false, "explanation": "形は合うが意味が合わない。騒音を種に創業はしない。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが意味が合わない。渋滞は「革新的」とも合わない。"}], "explanations": {"アイデア": "「革新的なアイデアを種として創業される」で意味が通る。", "在庫": "形は合うが意味が合わない。在庫は創業の種にならない。", "騒音": "形は合うが意味が合わない。騒音を種に創業はしない。", "渋滞": "形は合うが意味が合わない。渋滞は「革新的」とも合わない。"}, "sentence_index": 0, "correct_answer": "アイデア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、アイデアを食べてから学校に行きます。", "explanation": "アイデアは考えであり、食べ物ではないので「食べる」とは使えない。"}, {"text": "このアイデアは足が四本あって、庭をよく走ります。", "explanation": "アイデアは形のない考えで、足もなく走ることもできない。"}, {"text": "雨が降っていたので、アイデアをさして出かけた。", "explanation": "アイデアを傘のようにさすことはできず、考えの意味から外れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイデア", "is_correct": true, "explanation": "「アイデアを形にして商品として売り出した」で意味が通る。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は形にして商品にできない。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが意味が合わない。渋滞を商品にして売るとは言わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが意味が合わない。空腹を形にして売り出すことはない。"}], "explanations": {"アイデア": "「アイデアを形にして商品として売り出した」で意味が通る。", "天気": "形は合うが意味が合わない。天気は形にして商品にできない。", "渋滞": "形は合うが意味が合わない。渋滞を商品にして売るとは言わない。", "空腹": "形は合うが意味が合わない。空腹を形にして売り出すことはない。"}, "sentence_index": 6, "correct_answer": "アイデア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "起業家は新しいアイデアに乗って、会社まで通っている。", "explanation": "アイデアは乗り物ではないので「乗る」とは使えない。"}, {"text": "起業家はアイデアを着て、会議に出席した。", "explanation": "アイデアは服ではなく考えなので「着る」と合わない。"}, {"text": "このアイデアは重さが五キロもあり、持ち上げられない。", "explanation": "アイデアは形のない考えで、重さを持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいアイデアを飲んで会議に出た。", "corrected_sentence": "新しいアイデアを考えて会議に出た。", "error_description": "「アイデア」は飲めないので、「飲む」ではなく「考える」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいアイデアが空を飛んだ。", "corrected_sentence": "新しいアイデアが頭に浮かんだ。", "error_description": "アイデアは空を飛ばない。「頭に浮かぶ」が自然な言い方。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買入を増やす」で、増やす対象を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「買入に増やした」は他動詞の目的語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「買入と増やした」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「買入へ増やした」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「買入を増やす」で、増やす対象を示す「を」が入る。", "に": "「買入に増やした」は他動詞の目的語として成り立たない。", "と": "「買入と増やした」は文として成り立たない。", "へ": "「へ」は方向を表すので、「買入へ増やした」は成り立たない。"}, "error_tags": {"に": "target_vs_goal", "と": "wrong_relation", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売却", "is_correct": true, "explanation": "物や資産を売ることで、買入の反対の取引を表す。"}, {"text": "購入", "is_correct": false, "explanation": "買入とほぼ同じ意味で、反対ではない。"}, {"text": "調達", "is_correct": false, "explanation": "必要な物を集めて入手することで、反対ではなく近い意味。"}, {"text": "取得", "is_correct": false, "explanation": "手に入れることで、買入と同じ方向の意味。"}], "correct_answer": "売却", "explanations": {"売却": "物や資産を売ることで、買入の反対の取引を表す。", "購入": "買入とほぼ同じ意味で、反対ではない。", "調達": "必要な物を集めて入手することで、反対ではなく近い意味。", "取得": "手に入れることで、買入と同じ方向の意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「買入の値段」で、買入と値段をつなぐ「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「買入を値段が」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「買入へ値段が」は方向を表す「へ」で、名詞どうしがつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「買入に値段が」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「買入の値段」で、買入と値段をつなぐ「の」が入る。", "を": "「買入を値段が」は文として成り立たない。", "へ": "「買入へ値段が」は方向を表す「へ」で、名詞どうしがつながらない。", "に": "「買入に値段が」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "wrong_relation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売渡", "is_correct": true, "explanation": "物を売って相手に渡すことで、買入の反対の行為。"}, {"text": "仕入れ", "is_correct": false, "explanation": "商品を買い入れることで、買入に近い意味。"}, {"text": "入手", "is_correct": false, "explanation": "手に入れることで、買入と同じ方向の意味。"}, {"text": "取得", "is_correct": false, "explanation": "手に入れることで、反対ではない。"}], "correct_answer": "売渡", "explanations": {"売渡": "物を売って相手に渡すことで、買入の反対の行為。", "仕入れ": "商品を買い入れることで、買入に近い意味。", "入手": "手に入れることで、買入と同じ方向の意味。", "取得": "手に入れることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や資産をお金と引きかえに取得すること。特に企業や機関が業務の一環として購入する場合を指す。", "primary_collocate": null, "pronunciation": "かいいれ", "ipa": "kaiiɾe", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "買入", "complexity_tier": "T6", "furigana": "中央銀行[ちゅうおうぎんこう]による大規模[だいきぼ]な資産[しさん]買入[かいいれ]オペレーション、すなわち量的緩和政策[りょうてきかんわせいさく]は、単[たん]なる流動性[りゅうどうせい]の供給[きょうきゅう]にとどまらず、国債市場[こくさいしじょう]における価格発見機能[かかくはっけんきのう]を歪曲[わいきょく]せしめる側面[そくめん]を孕[はら]んでいる。", "sentence_source": "mined"}, {"text": "会社は原料の買入を増やした。", "target_word": "買入", "complexity_tier": "T2", "furigana": "会社[かいしゃ]は原料[げんりょう]の買入[かいいれ]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "銀行が国債の買入を始めます。", "target_word": "買入", "complexity_tier": "T2", "furigana": "銀行[ぎんこう]が国債[こくさい]の買入[かいいれ]を始[はじ]めます。", "sentence_source": "generated"}, {"text": "買入の価格は来週決まります。", "target_word": "買入", "complexity_tier": "T2", "furigana": "買入[かいいれ]の価格[かかく]は来週[らいしゅう]決[き]まります。", "sentence_source": "generated"}, {"text": "工場では毎月、部品の買入を行っている。", "target_word": "買入", "complexity_tier": "T3", "furigana": "工場[こうじょう]では毎月[まいつき]、部品[ぶひん]の買入[かいいれ]を行[おこな]っている。", "sentence_source": "generated"}, {"text": "買入を急いだせいで、在庫が多くなった。", "target_word": "買入", "complexity_tier": "T3", "furigana": "買入[かいいれ]を急[いそ]いだせいで、在庫[ざいこ]が多[おお]くなった。", "sentence_source": "generated"}, {"text": "日銀は株式の買入を続ける方針を発表した。", "target_word": "買入", "complexity_tier": "T3", "furigana": "日銀[にちぎん]は株式[かぶしき]の買入[かいいれ]を続[つづ]ける方針[ほうしん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "買入の値段が高すぎると、会社の利益は減ってしまう。", "target_word": "買入", "complexity_tier": "T4", "furigana": "買入[かいいれ]の値段[ねだん]が高[たか]すぎると、会社[かいしゃ]の利益[りえき]は減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "設備の買入が決まったのは、需要が増えると見られたからだ。", "target_word": "買入", "complexity_tier": "T4", "furigana": "設備[せつび]の買入[かいいれ]が決[き]まったのは、需要[じゅよう]が増[ふ]えると見[み]られたからだ。", "sentence_source": "generated"}, {"text": "政府が穀物の買入を行うことで、農家の収入は守られている。", "target_word": "買入", "complexity_tier": "T4", "furigana": "政府[せいふ]が穀物[こくもつ]の買入[かいいれ]を行[おこな]うことで、農家[のうか]の収入[しゅうにゅう]は守[まも]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "買入する", "label": "派生"}, {"form": "買い入れる", "label": "派生"}, {"form": "買入額", "label": "派生"}, {"form": "買入先", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 組織が物や資産を購入する取引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "買入", "is_correct": true, "explanation": "資産を購入する量的緩和のオペレーションを表すので意味が合う。"}, {"text": "返済", "is_correct": false, "explanation": "形は合うが、量的緩和政策を説明する「資産◯◯オペレーション」としては意味が合わない。"}, {"text": "廃棄", "is_correct": false, "explanation": "形は合うが、中央銀行が資産を廃棄するという意味になり、量的緩和と合わない。"}, {"text": "観察", "is_correct": false, "explanation": "形は合うが、観察では市場に資金を供給する政策にならず意味が合わない。"}], "explanations": {"買入": "資産を購入する量的緩和のオペレーションを表すので意味が合う。", "返済": "形は合うが、量的緩和政策を説明する「資産◯◯オペレーション」としては意味が合わない。", "廃棄": "形は合うが、中央銀行が資産を廃棄するという意味になり、量的緩和と合わない。", "観察": "形は合うが、観察では市場に資金を供給する政策にならず意味が合わない。"}, "sentence_index": 0, "correct_answer": "買入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は昨日の夜、おいしい買入を食べた。", "explanation": "買入は購入する行為であり、食べ物ではないので「食べる」の対象にならない。"}, {"text": "あの会社は工場の買入を売って利益を出した。", "explanation": "買入は買う取引なので、「売って」と結びつけるのは意味の使い方が逆で誤り。"}, {"text": "雨の日は買入が降るので傘が必要だ。", "explanation": "買入は取引を表す語で、天気のように「降る」ものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "買入", "is_correct": true, "explanation": "株式を購入する方針を示すので意味が合う。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが、株式を修理するという意味になり合わない。"}, {"text": "栽培", "is_correct": false, "explanation": "形は合うが、株式は栽培するものではなく意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、株式を洗濯するという意味になり合わない。"}], "explanations": {"買入": "株式を購入する方針を示すので意味が合う。", "修理": "形は合うが、株式を修理するという意味になり合わない。", "栽培": "形は合うが、株式は栽培するものではなく意味が合わない。", "洗濯": "形は合うが、株式を洗濯するという意味になり合わない。"}, "sentence_index": 6, "correct_answer": "買入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちは公園で買入に乗って遊んでいる。", "explanation": "買入は取引の行為で、乗り物ではないので「乗る」の対象にならない。"}, {"text": "社長は不要になった機械の買入をして、代金を受け取った。", "explanation": "買入は代金を払って買うことなので、代金を受け取る場面には使えない。"}, {"text": "この買入はとても長くて、川のように流れている。", "explanation": "買入は流れる物ではなく、形の描写に使う語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は新しい機械の買入が決めた。", "corrected_sentence": "会社は新しい機械の買入を決めた。", "error_description": "「買入」は「決める」の目的語なので、「が」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は新しい消防車の買入に行う予定だ。", "corrected_sentence": "町は新しい消防車の買入を行う予定だ。", "error_description": "「買入」は「行う」の目的語なので、「に」ではなく「を」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「後悔が拭えず」の「が」。拭える対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、「拭えず」を名詞に続けられず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」になり、後悔を拭える対象として示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」になり、拭える対象を示せない。"}], "correct_answer": "が", "explanations": {"が": "「後悔が拭えず」の「が」。拭える対象を示す。", "の": "連体修飾の「の」では、「拭えず」を名詞に続けられず不自然。", "から": "起点の「から」になり、後悔を拭える対象として示せない。", "と": "並列の「と」になり、拭える対象を示せない。"}, "error_tags": {"の": "連体", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "こころのなかの不安や疑問をなくすことができることです。", "primary_collocate": null, "pronunciation": "ぬぐえる", "ipa": "nɯɡɯeɾɯ", "syllable_count": 4, "sentences": [{"text": "何度説明を聞いても、不安が拭えない。", "target_word": "拭えない", "complexity_tier": "T3", "furigana": "何度[なんど]説明[せつめい]を聞[き]いても、不安[ふあん]が拭[ぬぐ]えない。", "sentence_source": "generated"}, {"text": "この証拠があれば、疑いが拭えるはずだ。", "target_word": "拭える", "complexity_tier": "T3", "furigana": "この証拠[しょうこ]があれば、疑[うたが]いが拭[ぬぐ]えるはずだ。", "sentence_source": "generated"}, {"text": "事故の記憶が頭に残り、車に乗るたび恐怖が拭えなかった。", "target_word": "拭えなかった", "complexity_tier": "T3", "furigana": "事故[じこ]の記憶[きおく]が頭[あたま]に残[のこ]り、車[くるま]に乗[の]るたび恐怖[きょうふ]が拭[ぬぐ]えなかった。", "sentence_source": "generated"}, {"text": "先生に励まされても、試験に落ちるという心配は拭えない。", "target_word": "拭えない", "complexity_tier": "T3", "furigana": "先生[せんせい]に励[はげ]まされても、試験[しけん]に落[お]ちるという心配[しんぱい]は拭[ぬぐ]えない。", "sentence_source": "generated"}, {"text": "彼が何か隠しているという疑念が、どうしても拭えない。", "target_word": "拭えない", "complexity_tier": "T3", "furigana": "彼[かれ]が何[なに]か隠[かく]しているという疑念[ぎねん]が、どうしても拭[ぬぐ]えない。", "sentence_source": "generated"}, {"text": "契約書を読み返しても、不信感は拭えなかった。", "target_word": "拭えなかった", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]を読[よ]み返[かえ]しても、不信感[ふしんかん]は拭[ぬぐ]えなかった。", "sentence_source": "generated"}, {"text": "説明会を開けば、住民の不安も少しは拭えるだろう。", "target_word": "拭える", "complexity_tier": "T3", "furigana": "説明会[せつめいかい]を開[ひら]けば、住民[じゅうみん]の不安[ふあん]も少[すこ]しは拭[ぬぐ]えるだろう。", "sentence_source": "generated"}, {"text": "失敗した過去への後悔が拭えず、彼は新しい仕事に踏み出せない。", "target_word": "拭えず", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した過去[かこ]への後悔[こうかい]が拭[ぬぐ]えず、彼[かれ]は新[あたら]しい仕事[しごと]に踏[ふ]み出[だ]せない。", "sentence_source": "generated"}, {"text": "医者の丁寧な説明のおかげで、病気への不安がようやく拭えた。", "target_word": "拭えた", "complexity_tier": "T3", "furigana": "医者[いしゃ]の丁寧[ていねい]な説明[せつめい]のおかげで、病気[びょうき]への不安[ふあん]がようやく拭[ぬぐ]えた。", "sentence_source": "generated"}, {"text": "本当に大丈夫なのかという疑問は、最後まで拭えなかった。", "target_word": "拭えなかった", "complexity_tier": "T3", "furigana": "本当[ほんとう]に大丈夫[だいじょうぶ]なのかという疑問[ぎもん]は、最後[さいご]まで拭[ぬぐ]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拭える", "label": "終止形"}, {"form": "拭えない", "label": "否定形"}, {"form": "拭えた", "label": "過去形"}, {"form": "拭えなかった", "label": "否定過去形"}, {"form": "拭えず", "label": "連用中止形"}], "register": "やや硬い書き言葉（普通体）", "sense_fingerprint": "不安・疑いなどを消し去ることができる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拭えない", "is_correct": true, "explanation": "可能形の否定で、説明を聞いても不安が消えないという意味になる。"}, {"text": "拭う", "is_correct": false, "explanation": "「拭う」は「を」を取る動詞なので、「不安が拭う」では文が成り立たない。"}, {"text": "拭いた", "is_correct": false, "explanation": "過去形でも「を」が必要な動詞のため、「不安が拭いた」は不自然。"}, {"text": "拭えたら", "is_correct": false, "explanation": "条件形で文が終わらず、「ても」の文の結論にならない。"}], "explanations": {"拭えない": "可能形の否定で、説明を聞いても不安が消えないという意味になる。", "拭う": "「拭う」は「を」を取る動詞なので、「不安が拭う」では文が成り立たない。", "拭いた": "過去形でも「を」が必要な動詞のため、「不安が拭いた」は不自然。", "拭えたら": "条件形で文が終わらず、「ても」の文の結論にならない。"}, "sentence_index": 0, "correct_answer": "拭えない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、長年の名誉を拭えた。", "explanation": "拭えるは不安や疑いを消す語で、評判を取り戻す場面には使わない。"}, {"text": "この問題をついに拭えた。", "explanation": "拭えるは不安や疑いといった気持ちに使い、問題を解消する場面には使わない。"}, {"text": "不要なファイルを拭えた。", "explanation": "拭えるは汚れや不安のように拭き取れるものに使い、データの消去には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拭える", "is_correct": true, "explanation": "「拭えるだろう」で、住民の不安が少し消えるという推量になる。"}, {"text": "拭えよう", "is_correct": false, "explanation": "可能動詞には意志形がないため、不自然。"}, {"text": "拭えろ", "is_correct": false, "explanation": "可能動詞には命令形がないため、文の結論にならない。"}, {"text": "拭えて", "is_correct": false, "explanation": "て形では「だろう」に続かず、文が成り立たない。"}], "explanations": {"拭える": "「拭えるだろう」で、住民の不安が少し消えるという推量になる。", "拭えよう": "可能動詞には意志形がないため、不自然。", "拭えろ": "可能動詞には命令形がないため、文の結論にならない。", "拭えて": "て形では「だろう」に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "拭える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "薬で、痛みを拭えた。", "explanation": "拭えるは不安や疑いのように心にあるものを消す語で、体の痛みには使わない。"}, {"text": "不安の原因を拭えた。", "explanation": "拭えるは不安や疑いの気持ちに使い、原因そのものを取り除く場面には合わない。"}, {"text": "蚊を拭えた。", "explanation": "拭えるは不安や疑いを消すときに使い、虫を追い払う場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この説明があれば、疑いが拭えはずだ。", "corrected_sentence": "この説明があれば、疑いが拭えるはずだ。", "error_description": "「はず」の前は連体形の「拭える」が必要。「拭えは」では「る」が抜けている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拭える", "is_correct": true, "explanation": "「はず」の前に置く終止・連体形。"}, {"text": "拭えず", "is_correct": false, "explanation": "「はず」の前には置けず、文が成り立たない。"}, {"text": "拭えて", "is_correct": false, "explanation": "て形は「はず」に直接続かず、文が成り立たない。"}, {"text": "拭えれば", "is_correct": false, "explanation": "仮定形は「はず」に続かず、文が成り立たない。"}], "correct_form": "拭える", "base_form": "拭える", "form_label": "連体形", "sentence_index": 1, "explanations": {"拭える": "「はず」の前に置く終止・連体形。", "拭えず": "「はず」の前には置けず、文が成り立たない。", "拭えて": "て形は「はず」に直接続かず、文が成り立たない。", "拭えれば": "仮定形は「はず」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の丁寧な謝罪で、わだかまりに拭えた。", "corrected_sentence": "彼の丁寧な謝罪で、わだかまりが拭えた。", "error_description": "「拭える」の対象は「が」で示す。「に」では、わだかまりを消す対象にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拭えず", "is_correct": true, "explanation": "連用中止形で「ず」に続け、「踏み出せない」につなげる形。"}, {"text": "拭えて", "is_correct": false, "explanation": "「拭えて」では否定の続きにならず、「踏み出せない」の理由として続かない。"}, {"text": "拭えろ", "is_correct": false, "explanation": "命令形は文の途中に入らず、文が成り立たない。"}, {"text": "拭える", "is_correct": false, "explanation": "終止・連体形では、後ろの「、」に続く形として意味が合わない。"}], "correct_form": "拭えず", "base_form": "拭える", "form_label": "連用中止形", "sentence_index": 7, "explanations": {"拭えず": "連用中止形で「ず」に続け、「踏み出せない」につなげる形。", "拭えて": "「拭えて」では否定の続きにならず、「踏み出せない」の理由として続かない。", "拭えろ": "命令形は文の途中に入らず、文が成り立たない。", "拭える": "終止・連体形では、後ろの「、」に続く形として意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
