INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53331, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "このような、今述べた通りのことです。こうなっている状態を言います。", "primary_collocate": null, "pronunciation": "かよう", "ipa": "kajoː", "syllable_count": 3, "sentences": [{"text": "斯様な事態になるとは、誰も予想しなかった。", "target_word": "斯様な", "complexity_tier": "T4", "furigana": "斯様[かよう]な事態[じたい]になるとは、誰[だれ]も予想[よそう]しなかった。", "sentence_source": "generated"}, {"text": "事情は斯様でございます。", "target_word": "斯様", "complexity_tier": "T3", "furigana": "事情[じじょう]は斯様[かよう]でございます。", "sentence_source": "generated"}, {"text": "斯様な場所で先生にお会いするとは思いませんでした。", "target_word": "斯様な", "complexity_tier": "T4", "furigana": "斯様[かよう]な場所[ばしょ]で先生[せんせい]にお会[あ]いするとは思[おも]いませんでした。", "sentence_source": "generated"}, {"text": "現在の状況は斯様である。", "target_word": "斯様", "complexity_tier": "T3", "furigana": "現在[げんざい]の状況[じょうきょう]は斯様[かよう]である。", "sentence_source": "generated"}, {"text": "斯様な問題は、早急に解決すべきだ。", "target_word": "斯様な", "complexity_tier": "T4", "furigana": "斯様[かよう]な問題[もんだい]は、早急[さっきゅう]に解決[かいけつ]すべきだ。", "sentence_source": "generated"}, {"text": "斯様な事態を招いた責任は、経営陣にある。", "target_word": "斯様", "complexity_tier": "T3", "furigana": "斯様[かよう]な事態[じたい]を招[まね]いた責任[せきにん]は、経営陣[けいえいじん]にある。", "sentence_source": "generated"}, {"text": "斯様な結果に終わったことを、深くお詫びします。", "target_word": "斯様な", "complexity_tier": "T4", "furigana": "斯様[かよう]な結果[けっか]に終[お]わったことを、深[ふか]くお詫[わ]びします。", "sentence_source": "generated"}, {"text": "斯様な大雨の日に出かけるのは危険だ。", "target_word": "斯様な", "complexity_tier": "T3", "furigana": "斯様[かよう]な大雨[おおあめ]の日[ひ]に出[で]かけるのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "話の内容は斯様なものであった。", "target_word": "斯様な", "complexity_tier": "T3", "furigana": "話[はなし]の内容[ないよう]は斯様[かよう]なものであった。", "sentence_source": "generated"}, {"text": "斯様な扱いを受けて、彼は黙っていられなかった。", "target_word": "斯様な", "complexity_tier": "T4", "furigana": "斯様[かよう]な扱[あつか]いを受[う]けて、彼[かれ]は黙[だま]っていられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "斯様", "label": "基本形"}, {"form": "斯様な", "label": "連体形"}, {"form": "斯様だ", "label": "終止形"}, {"form": "斯様で", "label": "連用形(で)"}, {"form": "斯様に", "label": "連用形(に)"}], "register": "改まった書き言葉(文章語)", "sense_fingerprint": "形状詞。「斯様な」「斯様だ」の形で、今述べた通りの、このような状態・事柄を指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53331, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "斯様な", "is_correct": true, "explanation": "今述べた通りの事柄を指す連体形。「事態」を修飾し、予想外の出来事を表す文に合う。"}, {"text": "可憐な", "is_correct": false, "explanation": "「可愛らしく美しい」の意。予想外の事態を言う文の内容とは合わない。"}, {"text": "無邪気な", "is_correct": false, "explanation": "子どもらしく屈託のない様子を表す。事態の性質を述べる文には当てはまらない。"}, {"text": "上品な", "is_correct": false, "explanation": "品位があることを表す。予想外の事態を述べる文の内容とはずれる。"}], "explanations": {"斯様な": "今述べた通りの事柄を指す連体形。「事態」を修飾し、予想外の出来事を表す文に合う。", "可憐な": "「可愛らしく美しい」の意。予想外の事態を言う文の内容とは合わない。", "無邪気な": "子どもらしく屈託のない様子を表す。事態の性質を述べる文には当てはまらない。", "上品な": "品位があることを表す。予想外の事態を述べる文の内容とはずれる。"}, "sentence_index": 0, "correct_answer": "斯様な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ねえ、斯様だよね。今日は本当に暑いね。", "explanation": "ここは〈そう〉（会話での相づち・同意）の意味。斯様は文章語で、友達との会話には合わない。"}, {"text": "（目の前の箱を指して）斯様な箱は重すぎる。", "explanation": "ここは〈こんな〉（目の前の物や今の様子を指す）の意味。斯様は前に述べた事柄を指すので、目の前の物には使えない。"}, {"text": "斯様、お茶を飲もう。", "explanation": "斯様は事柄や状態を指す語で、話を切り出す言葉としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53331, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "斯様な", "is_correct": true, "explanation": "今述べた通りの事柄を指す連体形。「結果」を修飾し、事態を受けてお詫びする文に合う。"}, {"text": "華麗な", "is_correct": false, "explanation": "派手で美しいことを表す。お詫びの対象となる結果とは合わない。"}, {"text": "爽快な", "is_correct": false, "explanation": "さっぱりして気持ちがよいことを表す。失敗を詫びる文の結果とは合わない。"}, {"text": "温厚な", "is_correct": false, "explanation": "穏やかで人柄がよいことを表す。結果を修飾する語としては成り立たない。"}], "explanations": {"斯様な": "今述べた通りの事柄を指す連体形。「結果」を修飾し、事態を受けてお詫びする文に合う。", "華麗な": "派手で美しいことを表す。お詫びの対象となる結果とは合わない。", "爽快な": "さっぱりして気持ちがよいことを表す。失敗を詫びる文の結果とは合わない。", "温厚な": "穏やかで人柄がよいことを表す。結果を修飾する語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "斯様な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "代金は斯様ですか。", "explanation": "斯様は事柄や状態を指す語で、値段や数量を尋ねる言葉としては使えない。"}, {"text": "ねえ、斯様なこと言わないでよ。", "explanation": "ここは〈そんな〉（会話で軽く言う語）の意味。斯様は堅い文章語で、くだけた会話には合わない。"}, {"text": "（別れ際に）斯様、またね。", "explanation": "斯様は挨拶の言葉ではないので、別れの場面の挨拶には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53331, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "斯様の天気が続くとは、誰も思わなかった。", "corrected_sentence": "斯様な天気が続くとは、誰も思わなかった。", "error_description": "「斯様の」は誤り。「斯様」は形状詞なので、名詞を修飾するときは「斯様な」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "斯様", "is_correct": true, "explanation": "語幹で、断定の「でございます」の前に置く形。ここで正しい。", "base_form": "斯様", "form_label": "語幹（断定の前）"}, {"text": "斯様な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。述語の位置には置けない。", "base_form": "斯様", "form_label": "連体形"}, {"text": "斯様に", "is_correct": false, "explanation": "連用形（に）で、動詞や形容詞を修飾する形。「でございます」とは続かない。", "base_form": "斯様", "form_label": "連用形（に）"}, {"text": "斯様だ", "is_correct": false, "explanation": "終止形の断定。丁寧な「でございます」と重ねて使えない。", "base_form": "斯様", "form_label": "終止形"}], "correct_form": "斯様", "base_form": "斯様", "form_label": "語幹（断定の前）", "sentence_index": 1, "explanations": {"斯様": "語幹で、断定の「でございます」の前に置く形。ここで正しい。", "斯様な": "連体形で名詞を修飾する形。述語の位置には置けない。", "斯様に": "連用形（に）で、動詞や形容詞を修飾する形。「でございます」とは続かない。", "斯様だ": "終止形の断定。丁寧な「でございます」と重ねて使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53331, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "斯様なだ寒さが続いた年は、記録にない。", "corrected_sentence": "斯様な寒さが続いた年は、記録にない。", "error_description": "「斯様な」の直後に「だ」は付かない。連体形「斯様な」で名詞「寒さ」を修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "斯様な", "is_correct": true, "explanation": "連体形で、直後の「大雨」を修飾する形。ここで正しい。", "base_form": "斯様", "form_label": "連体形"}, {"text": "斯様", "is_correct": false, "explanation": "語幹だけでは名詞を直接修飾できない。「大雨」の前には置けない。", "base_form": "斯様", "form_label": "語幹"}, {"text": "斯様で", "is_correct": false, "explanation": "連用形（で）で述語の一部になる形。名詞の前には立たない。", "base_form": "斯様", "form_label": "連用形（で）"}, {"text": "斯様だ", "is_correct": false, "explanation": "終止形で、名詞の前に「だ」は置けない。", "base_form": "斯様", "form_label": "終止形"}], "correct_form": "斯様な", "base_form": "斯様", "form_label": "連体形", "sentence_index": 7, "explanations": {"斯様な": "連体形で、直後の「大雨」を修飾する形。ここで正しい。", "斯様": "語幹だけでは名詞を直接修飾できない。「大雨」の前には置けない。", "斯様で": "連用形（で）で述語の一部になる形。名詞の前には立たない。", "斯様だ": "終止形で、名詞の前に「だ」は置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
