INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53332, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "このように。このような様子や状態を表す言葉です。主に文章や物語で使われます。", "primary_collocate": null, "pronunciation": "かよう", "ipa": "kajoː", "syllable_count": 3, "sentences": [{"text": "斯様に説明すれば、誰にでも分かるだろう。", "target_word": "斯様に", "complexity_tier": "T3", "furigana": "斯様[かよう]に説明[せつめい]すれば、誰[だれ]にでも分[わ]かるだろう。", "sentence_source": "generated"}, {"text": "物語は斯様にして幕を閉じた。", "target_word": "斯様に", "complexity_tier": "T4", "furigana": "物語[ものがたり]は斯様[かよう]にして幕[まく]を閉[と]じた。", "sentence_source": "generated"}, {"text": "彼は斯様に語り、静かに席を立った。", "target_word": "斯様に", "complexity_tier": "T3", "furigana": "彼[かれ]は斯様[かよう]に語[かた]り、静[しず]かに席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "斯様に美しい景色は、他に見たことがない。", "target_word": "斯様に", "complexity_tier": "T3", "furigana": "斯様[かよう]に美[うつく]しい景色[けしき]は、他[ほか]に見[み]たことがない。", "sentence_source": "generated"}, {"text": "世の中は斯様に変わっていくものだ。", "target_word": "斯様に", "complexity_tier": "T3", "furigana": "世[よ]の中[なか]は斯様[かよう]に変[か]わっていくものだ。", "sentence_source": "generated"}, {"text": "斯様にして二人は再会を果たした。", "target_word": "斯様に", "complexity_tier": "T4", "furigana": "斯様[かよう]にして二人[ふたり]は再会[さいかい]を果[は]たした。", "sentence_source": "generated"}, {"text": "老人は斯様に言い残して村を去った。", "target_word": "斯様に", "complexity_tier": "T3", "furigana": "老人[ろうじん]は斯様[かよう]に言[い]い残[のこ]して村[むら]を去[さ]った。", "sentence_source": "generated"}, {"text": "斯様に事が運んだのは、偶然ではない。", "target_word": "斯様に", "complexity_tier": "T4", "furigana": "斯様[かよう]に事[こと]が運[はこ]んだのは、偶然[ぐうぜん]ではない。", "sentence_source": "generated"}, {"text": "手順は斯様に進めるのが望ましい。", "target_word": "斯様に", "complexity_tier": "T4", "furigana": "手順[てじゅん]は斯様[かよう]に進[すす]めるのが望[のぞ]ましい。", "sentence_source": "generated"}, {"text": "斯様に努力を重ねても、報われないことはある。", "target_word": "斯様に", "complexity_tier": "T4", "furigana": "斯様[かよう]に努力[どりょく]を重[かさ]ねても、報[むく]われないことはある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "斯様", "label": "基本形"}, {"form": "斯様に", "label": "連用形(に)"}, {"form": "斯様な", "label": "連体形"}, {"form": "斯様だ", "label": "終止形"}], "register": "文章語・物語調", "sense_fingerprint": "「斯様に」の形で、動作や出来事がこのような仕方で行われることを表す副詞的用法。物語や文章で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "斯様に", "is_correct": true, "explanation": "「このように」の意の副詞。「説明すれば」と方法を述べる文に合う。"}, {"text": "決して", "is_correct": false, "explanation": "後ろに打ち消しの語を求める副詞。「説明すれば」とは続かない。"}, {"text": "もはや", "is_correct": false, "explanation": "「もう」の意で、説明の方法を述べる文の中では成り立たない。"}, {"text": "まるで", "is_correct": false, "explanation": "「〜ような」と呼応する比喩の副詞。この文にはその形がない。"}], "explanations": {"斯様に": "「このように」の意の副詞。「説明すれば」と方法を述べる文に合う。", "決して": "後ろに打ち消しの語を求める副詞。「説明すれば」とは続かない。", "もはや": "「もう」の意で、説明の方法を述べる文の中では成り立たない。", "まるで": "「〜ような」と呼応する比喩の副詞。この文にはその形がない。"}, "sentence_index": 0, "correct_answer": "斯様に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "（目の前の花束を指して）斯様に綺麗な花ですね。", "explanation": "ここは〈こんなに〉（目の前のものを指す）の意味。斯様には前に述べた事柄を受けるので、目の前の物には使えない。"}, {"text": "ねえ、どうも斯様にありがとう！", "explanation": "斯様は文章語で、軽いお礼の言葉には合わない。"}, {"text": "斯様、元気？", "explanation": "斯様は副詞で、あいさつの言葉としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "斯様に", "is_correct": true, "explanation": "「このように」の意の副詞。「言い残して」と動作の仕方を述べる文に合う。"}, {"text": "なおさら", "is_correct": false, "explanation": "「いっそう」の意の副詞で、動作の仕方を述べる文とは合わない。"}, {"text": "まことに", "is_correct": false, "explanation": "「本当に」の意の副詞で、「言い残して」とは呼応しない。"}, {"text": "決して", "is_correct": false, "explanation": "後ろに打ち消しの語を求める副詞。「言い残して」とは続かない。"}], "explanations": {"斯様に": "「このように」の意の副詞。「言い残して」と動作の仕方を述べる文に合う。", "なおさら": "「いっそう」の意の副詞で、動作の仕方を述べる文とは合わない。", "まことに": "「本当に」の意の副詞で、「言い残して」とは呼応しない。", "決して": "後ろに打ち消しの語を求める副詞。「言い残して」とは続かない。"}, "sentence_index": 6, "correct_answer": "斯様に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "（遠くの山を指して）斯様に高い山だ。", "explanation": "ここは〈あんなに〉（遠くのものを指す）の意味。斯様は前に述べた事柄を受けるので、遠くの物を指すには使えない。"}, {"text": "ねえ、斯様に行こうよ。", "explanation": "斯様は堅い文章語で、軽い誘いには合わない。"}, {"text": "斯様に、本当にごめんなさい。", "explanation": "斯様は様子や状態を受ける語で、謝罪の気持ちを強める言葉としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "斯様が静かな夜は、初めてだ。", "corrected_sentence": "斯様に静かな夜は、初めてだ。", "error_description": "「斯様が」は誤り。「斯様」は副詞なので、「斯様に静かな」と続けて形容詞を修飾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "斯様を寒い日が続いた年は、今までにない。", "corrected_sentence": "斯様に寒い日が続いた年は、今までにない。", "error_description": "「斯様を」は誤り。「斯様」は副詞なので、「斯様に寒い」と続けて形容詞を修飾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
