INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53343, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外から入ってくるものを防ぐ壁です。", "primary_collocate": null, "pronunciation": "ばりあー", "ipa": "baɾiaː", "syllable_count": 4, "sentences": [{"text": "川沿いの町は、水を防ぐバリアーを作って洪水に備えた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "川沿[かわぞ]いの町[まち]は、水[みず]を防[ふせ]ぐバリアーを作[つく]って洪水[こうずい]に備[そな]えた。", "sentence_source": "generated"}, {"text": "工事現場では、砂ぼこりが道に出ないよう、周りにバリアーが置かれている。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "工事現場[こうじげんば]では、砂[すな]ぼこりが道[みち]に出[で]ないよう、周[まわ]りにバリアーが置[お]かれている。", "sentence_source": "generated"}, {"text": "肌の表面にあるバリアーが弱ると、乾燥や汚れの影響を受けやすい。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "肌[はだ]の表面[ひょうめん]にあるバリアーが弱[よわ]ると、乾燥[かんそう]や汚[よご]れの影響[えいきょう]を受[う]けやすい。", "sentence_source": "generated"}, {"text": "空港の警備員は、車が入れないようにバリアーを置いた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "空港[くうこう]の警備員[けいびいん]は、車[くるま]が入[はい]れないようにバリアーを置[お]いた。", "sentence_source": "generated"}, {"text": "海辺の家は、強い風を防ぐバリアーとして高い木を植えた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "海辺[うみべ]の家[いえ]は、強[つよ]い風[かぜ]を防[ふせ]ぐバリアーとして高[たか]い木[き]を植[う]えた。", "sentence_source": "generated"}, {"text": "このカーテンは、外の光を通さないバリアーのような働きをする。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "このカーテンは、外[そと]の光[ひかり]を通[とお]さないバリアーのような働[はたら]きをする。", "sentence_source": "generated"}, {"text": "虫が入らないよう、窓にバリアーとなる網を取りつけた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "虫[むし]が入[はい]らないよう、窓[まど]にバリアーとなる網[あみ]を取[と]りつけた。", "sentence_source": "generated"}, {"text": "細菌は、体を守るバリアーを通り抜けて内部に入ることがある。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "細菌[さいきん]は、体[からだ]を守[まも]るバリアーを通[とお]り抜[ぬ]けて内部[ないぶ]に入[はい]ることがある。", "sentence_source": "generated"}, {"text": "冬は寒さを防ぐバリアーとして、窓の外に厚いシートを張る。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]さを防[ふせ]ぐバリアーとして、窓[まど]の外[そと]に厚[あつ]いシートを張[は]る。", "sentence_source": "generated"}, {"text": "川の汚れが海に出ないようにバリアーを設けて、ごみを止めた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "川[かわ]の汚[よご]れが海[うみ]に出[で]ないようにバリアーを設[もう]けて、ごみを止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バリアー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "外から入るものを止める壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53343, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バリアー", "is_correct": true, "explanation": "水を防ぐ壁を作って洪水に備えた、という意味に合う。"}, {"text": "振り子", "is_correct": false, "explanation": "振り子は揺れる器具で、水を防ぐ働きとは合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を入れる器で、洪水に備えるものではない。"}, {"text": "腕時計", "is_correct": false, "explanation": "腕時計は時刻を示す道具で、洪水対策とは結びつかない。"}], "explanations": {"バリアー": "水を防ぐ壁を作って洪水に備えた、という意味に合う。", "振り子": "振り子は揺れる器具で、水を防ぐ働きとは合わない。", "花瓶": "花瓶は花を入れる器で、洪水に備えるものではない。", "腕時計": "腕時計は時刻を示す道具で、洪水対策とは結びつかない。"}, "sentence_index": 0, "correct_answer": "バリアー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い日差しの中、バリアーをかぶって外に出た。", "explanation": "ここは〈帽子〉の意味。頭にかぶって日差しを避ける物で、外から入るものを防ぐ壁ではない。"}, {"text": "改札でバリアーを見せて、ホームに入った。", "explanation": "ここは〈切符〉の意味。通行の証明に見せる紙で、入ってくるものを防ぐ壁ではない。"}, {"text": "ズボンがゆるいので、バリアーをきつく締めた。", "explanation": "ここは〈ベルト〉の意味。腰に締める帯で、外から入るものを防ぐ壁とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53343, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バリアー", "is_correct": true, "explanation": "虫が入らないよう窓に取りつける、外から入るものを防ぐ網の意味に合う。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡は姿を映す物で、虫を防ぐ網の説明には合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文章を送る物で、虫を防ぐ網の代わりにはならない。"}, {"text": "缶詰", "is_correct": false, "explanation": "缶詰は食品の容器で、窓に取りつける網とは合わない。"}], "explanations": {"バリアー": "虫が入らないよう窓に取りつける、外から入るものを防ぐ網の意味に合う。", "鏡": "鏡は姿を映す物で、虫を防ぐ網の説明には合わない。", "手紙": "手紙は文章を送る物で、虫を防ぐ網の代わりにはならない。", "缶詰": "缶詰は食品の容器で、窓に取りつける網とは合わない。"}, "sentence_index": 6, "correct_answer": "バリアー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い夜、バリアーを体にかけて眠った。", "explanation": "ここは〈布団〉の意味。体を覆って寝る寝具で、外からのものを防ぐ壁とは違う。"}, {"text": "夏祭りの夜、大輪のバリアーが夜空に咲いた。", "explanation": "ここは〈花火〉の意味。空に咲いて光る物で、外から入るものを防ぐ壁ではない。"}, {"text": "店の前に、大きなバリアーを出した。", "explanation": "ここは〈看板〉の意味。客に店を知らせる札で、外から入るものを防ぐ壁ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53343, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベランダに、強い風を防ぐバリアーが立てた。", "corrected_sentence": "ベランダに、強い風を防ぐバリアーを立てた。", "error_description": "〈立てる〉は目的語に〈を〉をとる他動詞。バリアーに〈が〉を付けると、文の形が合わなくなる。正しくは〈を〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53343, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の花を守るため、霜を防ぐバリアーに立てた。", "corrected_sentence": "庭の花を守るため、霜を防ぐバリアーを立てた。", "error_description": "〈立てる〉は目的語に〈を〉をとる他動詞。バリアーに〈に〉を付けると、バリアーが立てる場所になってしまい誤り。正しくは〈を〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『バリアーの役割』の〈の〉。役割の中身を示す。"}, {"text": "を", "is_correct": false, "explanation": "『バリアーを役割』は続かず、役割は〈の〉で続ける。"}, {"text": "に", "is_correct": false, "explanation": "『バリアーに役割』は成り立たず、役割の内容を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「バリアーへ役割をしている」は方向を示す〈へ〉が合わず、役割の内容も示せない。"}], "correct_answer": "の", "explanations": {"の": "『バリアーの役割』の〈の〉。役割の中身を示す。", "を": "『バリアーを役割』は続かず、役割は〈の〉で続ける。", "に": "『バリアーに役割』は成り立たず、役割の内容を示せない。", "へ": "「バリアーへ役割をしている」は方向を示す〈へ〉が合わず、役割の内容も示せない。"}, "error_tags": {"を": "目的語", "に": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『バリアーのおかげ』の〈の〉。〈おかげ〉を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "『バリアーがおかげで』は〈が〉で主語になり、〈おかげ〉を修飾できず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『バリアーへおかげで』は方向を示すが、原因の〈おかげ〉とはつながらない。"}, {"text": "から", "is_correct": false, "explanation": "『バリアーからおかげで』は起点を示すが、〈おかげ〉を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "『バリアーのおかげ』の〈の〉。〈おかげ〉を修飾する。", "が": "『バリアーがおかげで』は〈が〉で主語になり、〈おかげ〉を修飾できず文が成り立たない。", "へ": "『バリアーへおかげで』は方向を示すが、原因の〈おかげ〉とはつながらない。", "から": "『バリアーからおかげで』は起点を示すが、〈おかげ〉を修飾する形にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外からの侵入や影響を防ぐために設けられた壁や障がい物。", "primary_collocate": null, "pronunciation": "ばりあー", "ipa": "baɾiaː", "syllable_count": 4, "sentences": [{"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "バリアー", "complexity_tier": "T4", "furigana": "この際[さい]、脂質[ししつ]の膜[まく]がジャムの水分浸透[すいぶんしんとう]を防[ふせ]ぐバリアーとして機能[きのう]するという科学的[かがくてき]裏付[うらづ]けも無視[むし]できない。", "sentence_source": "mined"}, {"text": "皮膚は、細菌が体に入らないようにするバリアーの役割をしている。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "皮膚[ひふ]は、細菌[さいきん]が体[からだ]に入[はい]らないようにするバリアーの役割[やくわり]をしている。", "sentence_source": "generated"}, {"text": "高波を防ぐバリアーが港の入り口に設けられている。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "高波[たかなみ]を防[ふせ]ぐバリアーが港[みなと]の入[い]り口[ぐち]に設[もう]けられている。", "sentence_source": "generated"}, {"text": "工場は、外の粉じんが入らないように、入り口にバリアーを設けた。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、外[そと]の粉[ふん]じんが入[はい]らないように、入[い]り口[ぐち]にバリアーを設[もう]けた。", "sentence_source": "generated"}, {"text": "ワクチンは、ウイルスから体を守るバリアーになる。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "ワクチンは、ウイルスから体[からだ]を守[まも]るバリアーになる。", "sentence_source": "generated"}, {"text": "化粧品の会社は、肌を紫外線から守るバリアーになるクリームを開発した。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "化粧品[けしょうひん]の会社[かいしゃ]は、肌[はだ]を紫外線[しがいせん]から守[まも]るバリアーになるクリームを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "言葉の違いがバリアーとなって、二人はなかなか親しくなれなかった。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "言葉[ことば]の違[ちが]いがバリアーとなって、二人[ふたり]はなかなか親[した]しくなれなかった。", "sentence_source": "generated"}, {"text": "道路に沿ったバリアーのおかげで、雪が車道に入ってこない。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "道路[どうろ]に沿[そ]ったバリアーのおかげで、雪[ゆき]が車道[しゃどう]に入[はい]ってこない。", "sentence_source": "generated"}, {"text": "この窓には騒音を防ぐバリアーがないので、夜も外の音が聞こえる。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "この窓[まど]には騒音[そうおん]を防[ふせ]ぐバリアーがないので、夜[よる]も外[そと]の音[おと]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "国境にバリアーを築いても、情報の流入を完全に止めることは難しい。", "target_word": "バリアー", "complexity_tier": "T3", "furigana": "国境[こっきょう]にバリアーを築[きず]いても、情報[じょうほう]の流入[りゅうにゅう]を完全[かんぜん]に止[と]めることは難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バリアー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "外からの侵入や影響を防ぐために設けた壁や障害物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バリアー", "is_correct": true, "explanation": "脂質の膜が水分の浸透を防ぐ障壁として働く、という文脈に合う。"}, {"text": "旋律", "is_correct": false, "explanation": "旋律は音の連なりで、膜が水分を防ぐ機能とは結びつかない。"}, {"text": "大雨", "is_correct": false, "explanation": "大雨は天気の状態で、膜が機能するという説明と合わない。"}, {"text": "偏西風", "is_correct": false, "explanation": "偏西風は風の流れで、ジャムの膜の働きとは関係がない。"}], "explanations": {"バリアー": "脂質の膜が水分の浸透を防ぐ障壁として働く、という文脈に合う。", "旋律": "旋律は音の連なりで、膜が水分を防ぐ機能とは結びつかない。", "大雨": "大雨は天気の状態で、膜が機能するという説明と合わない。", "偏西風": "偏西風は風の流れで、ジャムの膜の働きとは関係がない。"}, "sentence_index": 0, "correct_answer": "バリアー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震の後、体育館のバリアーに大勢が集まった。", "explanation": "ここは〈避難所〉の意味。人が身を寄せる場所で、外からの侵入や影響を防ぐ壁とは違うので、この文脈では合わない。"}, {"text": "階段を上るとき、バリアーにしっかりつかまった。", "explanation": "ここは〈手すり〉の意味。体を支えるための棒で、侵入や影響を防ぐ壁とは違う。"}, {"text": "寒い夜は、バリアーをかぶって寝た。", "explanation": "ここは〈布団〉の意味。体を覆って寝る寝具で、外からの侵入を防ぐ壁とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バリアー", "is_correct": true, "explanation": "言葉の違いが二人の間を隔てる障壁になった、という意味に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時の流れを表す語で、二人が親しくなれない理由とは結びつかない。"}, {"text": "新聞", "is_correct": false, "explanation": "新聞は情報を伝える紙で、言葉の違いが二人を隔てる働きとは合わない。"}, {"text": "絨毯", "is_correct": false, "explanation": "絨毯は床に敷く布で、二人の関係を隔てる働きとは違う。"}], "explanations": {"バリアー": "言葉の違いが二人の間を隔てる障壁になった、という意味に合う。", "季節": "季節は時の流れを表す語で、二人が親しくなれない理由とは結びつかない。", "新聞": "新聞は情報を伝える紙で、言葉の違いが二人を隔てる働きとは合わない。", "絨毯": "絨毯は床に敷く布で、二人の関係を隔てる働きとは違う。"}, "sentence_index": 6, "correct_answer": "バリアー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の街に、ネオンのバリアーがきらめいた。", "explanation": "ここは〈ネオン〉の意味。光を放つ看板で、外からの侵入を防ぐ壁ではない。"}, {"text": "寒い朝、首にバリアーを巻いて出かけた。", "explanation": "ここは〈マフラー〉の意味。首に巻く布で、外からの侵入や影響を防ぐ壁とは違うので合わない。"}, {"text": "夜空に大きなバリアーが上がった。", "explanation": "ここは〈花火〉の意味。空に上がって光る物で、外からの侵入を防ぐ壁ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の日は、高潮を防ぐバリアーが港の入り口に設ける。", "corrected_sentence": "台風の日は、高潮を防ぐバリアーが港の入り口に設けられる。", "error_description": "〈設ける〉は人が主語の他動詞。バリアーは設けられる側なので、受身の〈設けられる〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の日は、玄関にバリアーに置いて、冷たい風を防いだ。", "corrected_sentence": "雪の日は、玄関にバリアーを置いて、冷たい風を防いだ。", "error_description": "〈置く〉は目的語に〈を〉をとる他動詞。バリアーの後ろに〈に〉を付けると、動詞と文の形が合わなくなる。正しくは〈を〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
