INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53347, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "あまいこと。あめをたべたときのこころもちです。", "primary_collocate": null, "pronunciation": "あまみ", "ipa": "amami", "syllable_count": 3, "sentences": [{"text": "子どもは飴をなめて、口いっぱいの甘味を楽しんでいる。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "子[こ]どもは飴[あめ]をなめて、口[くち]いっぱいの甘味[あまみ]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "飴を口に入れると、やさしい甘味がゆっくり広がった。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "飴[あめ]を口[くち]に入[い]れると、やさしい甘味[あまみ]がゆっくり広[ひろ]がった。", "sentence_source": "generated"}, {"text": "疲れていたので、チョコレートの甘味が体にしみた。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "疲[つか]れていたので、チョコレートの甘味[あまみ]が体[からだ]にしみた。", "sentence_source": "generated"}, {"text": "このあめは甘味が長く続くので、子どもに人気だ。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "このあめは甘味[あまみ]が長[なが]く続[つづ]くので、子[こ]どもに人気[にんき]だ。", "sentence_source": "generated"}, {"text": "ジュースは甘味が強すぎて、全部は飲めなかった。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "ジュースは甘味[あまみ]が強[つよ]すぎて、全部[ぜんぶ]は飲[の]めなかった。", "sentence_source": "generated"}, {"text": "祖母がくれたキャンディーの甘味を、今も覚えている。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "祖母[そぼ]がくれたキャンディーの甘味[あまみ]を、今[いま]も覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "薬が苦かったので、あとで飴の甘味でごまかした。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "薬[くすり]が苦[にが]かったので、あとで飴[あめ]の甘味[あまみ]でごまかした。", "sentence_source": "generated"}, {"text": "砂糖を控えたクッキーは、甘味がやさしくて食べやすい。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "砂糖[さとう]を控[ひか]えたクッキーは、甘味[あまみ]がやさしくて食[た]べやすい。", "sentence_source": "generated"}, {"text": "かき氷にシロップをかけると、冷たさと一緒に甘味が口に広がる。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "かき氷[ごおり]にシロップをかけると、冷[つめ]たさと一緒[いっしょ]に甘味[あまみ]が口[くち]に広[ひろ]がる。", "sentence_source": "generated"}, {"text": "果物のゼリーは、自然な甘味で後味がすっきりしている。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "果物[くだもの]のゼリーは、自然[しぜん]な甘味[あまみ]で後味[あとあじ]がすっきりしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘味", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "あめなどを食べたときに口の中で感じる、あまいという感覚。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 苦かっ (Zipf 1.71)']::text[], 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53347, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甘味", "is_correct": true, "explanation": "飴をなめて口いっぱいに広がる味わいを楽しむ、という文脈に合う。"}, {"text": "体温", "is_correct": false, "explanation": "口いっぱいの体温を楽しむとは言わず、飴の味わいを表さない。"}, {"text": "重さ", "is_correct": false, "explanation": "口いっぱいの重さを楽しむのは不自然で、飴の味わいを表さない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は口の中の味覚ではなく、文が成り立たない。"}], "explanations": {"甘味": "飴をなめて口いっぱいに広がる味わいを楽しむ、という文脈に合う。", "体温": "口いっぱいの体温を楽しむとは言わず、飴の味わいを表さない。", "重さ": "口いっぱいの重さを楽しむのは不自然で、飴の味わいを表さない。", "音量": "音量は口の中の味覚ではなく、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "甘味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお香は甘味が長く続くので、寝室で使っている。", "explanation": "ここは〈香り〉の意味。長く続くのはお香の香りで、甘味は口に入れた味を指す。"}, {"text": "この鍋は甘味が長く続くので、冷めにくい。", "explanation": "ここは〈熱さ〉の意味。冷めにくいのは熱さで、甘味は当てはまらない。"}, {"text": "このわさびは甘味が鼻に抜けて、つんとする。", "explanation": "ここは〈刺激〉の意味。つんと鼻に抜けるのは刺激で、甘味は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53347, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘味", "is_correct": true, "explanation": "苦さを甘さで打ち消す、という文脈に合う。"}, {"text": "形", "is_correct": false, "explanation": "飴の形でごまかすとは言えず、苦さを消す話にならない。"}, {"text": "硬さ", "is_correct": false, "explanation": "飴の硬さでは苦さを消せず、文脈に合わない。"}, {"text": "色", "is_correct": false, "explanation": "飴の色で苦さを隠すという意味にはならない。"}], "explanations": {"甘味": "苦さを甘さで打ち消す、という文脈に合う。", "形": "飴の形でごまかすとは言えず、苦さを消す話にならない。", "硬さ": "飴の硬さでは苦さを消せず、文脈に合わない。", "色": "飴の色で苦さを隠すという意味にはならない。"}, "sentence_index": 6, "correct_answer": "甘味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この揚げ物は甘味がぎとぎとして、胃にもたれる。", "explanation": "ここは〈脂っこさ〉の意味。ぎとぎとして胃にもたれるのは脂で、甘味とは言わない。"}, {"text": "この納豆は甘味が糸を引き、ねばりが強い。", "explanation": "ここは〈粘り〉の意味。糸を引くのは粘りで、甘味は味を指すので使わない。"}, {"text": "この梅干しは甘味がきつく、口がすぼまる。", "explanation": "ここは〈酸味〉の意味。口がすぼまるのは酸味で、甘味は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53347, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は飴をなめて、口いっぱいの甘味が楽しんでいた。", "corrected_sentence": "祖父は飴をなめて、口いっぱいの甘味を楽しんでいた。", "error_description": "「楽しむ」は他動詞で目的語に「を」を取る。「甘味が楽しむ」は誤りで、正しくは「甘味を楽しむ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53347, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "砂糖を控えたこのクッキーは、甘味をやさしくて食べやすい。", "corrected_sentence": "砂糖を控えたこのクッキーは、甘味がやさしくて食べやすい。", "error_description": "形容詞「やさしい」は主語に「が」を取るので、「甘味をやさしい」は誤り。正しくは「甘味がやさしい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
