INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53348, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "砂糖などのように、口に入れたときに感じるあまい味。また、その性質。", "primary_collocate": null, "pronunciation": "あまみ", "ipa": "amami", "syllable_count": 3, "sentences": [{"text": "甘味と塩気が口の中で合わさると、味わいに深みが出る。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "甘味[あまみ]と塩気[しおけ]が口[くち]の中[なか]で合[あ]わさると、味[あじ]わいに深[ふか]みが出[で]る。", "sentence_source": "generated"}, {"text": "このりんごは酸味が少なく、甘味が強い。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "このりんごは酸味[さんみ]が少[すく]なく、甘味[あまみ]が強[つよ]い。", "sentence_source": "generated"}, {"text": "砂糖を減らしたら、紅茶の甘味がずいぶん弱くなった。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "砂糖[さとう]を減[へ]らしたら、紅茶[こうちゃ]の甘味[あまみ]がずいぶん弱[よわ]くなった。", "sentence_source": "generated"}, {"text": "この桃は熟すほど甘味が増す。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "この桃[もも]は熟[じゅく]すほど甘味[あまみ]が増[ま]す。", "sentence_source": "generated"}, {"text": "塩をひとつまみ加えると、スイカの甘味が引き立つ。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "塩[しお]をひとつまみ加[くわ]えると、スイカの甘味[あまみ]が引[ひ]き立[た]つ。", "sentence_source": "generated"}, {"text": "ハチミツには砂糖とは違う、やさしい甘味がある。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "ハチミツには砂糖[さとう]とは違[ちが]う、やさしい甘味[あまみ]がある。", "sentence_source": "generated"}, {"text": "煮込むと、玉ねぎの甘味が出てスープがおいしくなる。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "煮込[にこ]むと、玉[たま]ねぎの甘味[あまみ]が出[で]てスープがおいしくなる。", "sentence_source": "generated"}, {"text": "苦いお茶を飲んだ後は、和菓子の甘味がいっそう心地よい。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "苦[にが]いお茶[ちゃ]を飲[の]んだ後[あと]は、和菓子[わがし]の甘味[あまみ]がいっそう心地[ここち]よい。", "sentence_source": "generated"}, {"text": "甘味が足りなかったので、私は蜂蜜を少し足した。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "甘味[あまみ]が足[た]りなかったので、私[わたし]は蜂蜜[はちみつ]を少[すこ]し足[た]した。", "sentence_source": "generated"}, {"text": "この果物は見た目は地味だが、上品な甘味が人気だ。", "target_word": "甘味", "complexity_tier": "T3", "furigana": "この果物[くだもの]は見[み]た目[め]は地味[じみ]だが、上品[じょうひん]な甘味[あまみ]が人気[にんき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘味", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "口に入れたときに感じる、砂糖のようなあまい味。味覚の性質としての甘さ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甘味", "is_correct": true, "explanation": "塩気と並んで、口の中で味わいに深みを出す要素として自然に続く。"}, {"text": "音", "is_correct": false, "explanation": "音は味覚ではなく、塩気や食感と並べて口腔内のハーモニーを述べる要素にならない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は視覚の要素で、口腔内で織りなす味わいの列には入らない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は味の要素ではなく、塩気や食感と並べると意味が通らない。"}], "explanations": {"甘味": "塩気と並んで、口の中で味わいに深みを出す要素として自然に続く。", "音": "音は味覚ではなく、塩気や食感と並べて口腔内のハーモニーを述べる要素にならない。", "色彩": "色彩は視覚の要素で、口腔内で織りなす味わいの列には入らない。", "体温": "体温は味の要素ではなく、塩気や食感と並べると意味が通らない。"}, "sentence_index": 0, "correct_answer": "甘味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は生徒への甘味が強く、宿題を減らしてしまった。", "explanation": "ここは〈甘やかし〉の意味。甘味は味のことなので、人に対する甘やかしの度合いには使わない。"}, {"text": "このスープは甘味が舌を刺し、むせそうになった。", "explanation": "ここは〈辛味〉の意味。舌を刺してむせさせるのは辛味で、甘味とは言わない。"}, {"text": "この香水は甘味が上品で、ほのかに香る。", "explanation": "ここは〈香り〉の意味。甘味は口に入れたときの味で、香水の香りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘味", "is_correct": true, "explanation": "煮込んで玉ねぎの甘さが引き出され、スープがおいしくなるという文脈に合う。"}, {"text": "硬さ", "is_correct": false, "explanation": "煮込むと玉ねぎは柔らかくなるが、硬さが出るとは言わず、スープの味の話に合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さが出るとは言わず、スープがおいしくなる理由にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は食材の味を表さず、文として成り立たない。"}], "explanations": {"甘味": "煮込んで玉ねぎの甘さが引き出され、スープがおいしくなるという文脈に合う。", "硬さ": "煮込むと玉ねぎは柔らかくなるが、硬さが出るとは言わず、スープの味の話に合わない。", "重さ": "重さが出るとは言わず、スープがおいしくなる理由にならない。", "寿命": "寿命は食材の味を表さず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "甘味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このせんべいは甘味が硬く、歯が折れそうだ。", "explanation": "ここは〈歯ごたえ〉の意味。硬いのは食感で、甘味は味を指すので使わない。"}, {"text": "このヨーグルトは甘味が鋭く、口がすぼまる。", "explanation": "ここは〈酸味〉の意味。口がすぼまるのは酸味で、甘味は当てはまらない。"}, {"text": "このお茶は甘味がきゅっと渋く、後口が引き締まる。", "explanation": "ここは〈渋味〉の意味。後口を引き締める渋さは渋味で、甘味とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この果汁は酸味が少なく、甘味を強い。", "corrected_sentence": "この果汁は酸味が少なく、甘味が強い。", "error_description": "「強い」は形容詞なので主語に「が」を付ける。「甘味を強い」は誤りで、正しくは「甘味が強い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煮込むと、玉ねぎの甘味を出て、スープがおいしくなった。", "corrected_sentence": "煮込むと、玉ねぎの甘味が出て、スープがおいしくなった。", "error_description": "「出る」は主語に「が」を取るので、「甘味を出る」は誤り。正しくは「甘味が出る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「百人を超える」の対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すため、「百人に超えて」では対象を示せず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、対象を示す「百人で超えて」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「百人へ超えて」は対象の関係が合わず不自然。"}], "correct_answer": "を", "explanations": {"を": "正しい。「百人を超える」の対象を示す「を」。", "に": "「に」は到達点や相手を示すため、「百人に超えて」では対象を示せず成り立たない。", "で": "「で」は手段や場所を示すため、対象を示す「百人で超えて」は文として成り立たない。", "へ": "「へ」は方向を示すため、「百人へ超えて」は対象の関係が合わず不自然。"}, "error_tags": {"に": "対象の格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「記録を超える」の対象を示す「を」。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、動詞「超える」の対象にはならない。「父の記録の超える」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「記録と超える」では対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「記録から超える」は対象の関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "正しい。「記録を超える」の対象を示す「を」。", "の": "「の」は名詞を修飾するため、動詞「超える」の対象にはならない。「父の記録の超える」は成り立たない。", "と": "「と」は並列や相手を示すため、「記録と超える」では対象を表せない。", "から": "「から」は起点を示すため、「記録から超える」は対象の関係が合わない。"}, "error_tags": {"の": "修飾", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "基準や限界を上回り、それより大きくなること。", "primary_collocate": null, "pronunciation": "こえる", "ipa": "koeɾɯ", "syllable_count": 3, "sentences": [{"text": "今日の気温は35度を超えたので、外に出るのが危ないです。", "target_word": "超えた", "complexity_tier": "T3", "furigana": "今日[きょう]の気温[きおん]は35度[ど]を超[こ]えたので、外[そと]に出[で]るのが危[あぶ]ないです。", "sentence_source": "generated"}, {"text": "参加者は百人を超えて、会場に入れない人もいた。", "target_word": "超えて", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は百人[ひゃくにん]を超[こ]えて、会場[かいじょう]に入[はい]れない人[ひと]もいた。", "sentence_source": "generated"}, {"text": "彼の演技は私の予想を超えていて、思わず拍手した。", "target_word": "超えて", "complexity_tier": "T3", "furigana": "彼[かれ]の演技[えんぎ]は私[わたし]の予想[よそう]を超[こ]えていて、思[おも]わず拍手[はくしゅ]した。", "sentence_source": "generated"}, {"text": "制限速度を超えて走ると、警察に止められます。", "target_word": "超えて", "complexity_tier": "T3", "furigana": "制限速度[せいげんそくど]を超[こ]えて走[はし]ると、警察[けいさつ]に止[と]められます。", "sentence_source": "generated"}, {"text": "練習を重ねて、ついに自分の限界を超えることができた。", "target_word": "超える", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を重[かさ]ねて、ついに自分[じぶん]の限界[げんかい]を超[こ]えることができた。", "sentence_source": "generated"}, {"text": "この店の料理は期待を超える味で、また来たいと思った。", "target_word": "超える", "complexity_tier": "T3", "furigana": "この店[みせ]の料理[りょうり]は期待[きたい]を超[こ]える味[あじ]で、また来[き]たいと思[おも]った。", "sentence_source": "generated"}, {"text": "荷物が二十キロを超えると、追加料金がかかります。", "target_word": "超える", "complexity_tier": "T3", "furigana": "荷物[にもつ]が二十[にじゅう]キロを超[こ]えると、追加[ついか]料金[りょうきん]がかかります。", "sentence_source": "generated"}, {"text": "兄は去年、父の記録を超える成績を出した。", "target_word": "超える", "complexity_tier": "T3", "furigana": "兄[あに]は去年[きょねん]、父[ちち]の記録[きろく]を超[こ]える成績[せいせき]を出[だ]した。", "sentence_source": "generated"}, {"text": "想像を超える大雨で、川の水があふれた。", "target_word": "超える", "complexity_tier": "T3", "furigana": "想像[そうぞう]を超[こ]える大雨[おおあめ]で、川[かわ]の水[みず]があふれた。", "sentence_source": "generated"}, {"text": "彼女は言葉の壁を超えて、外国の友達をたくさん作った。", "target_word": "超えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言葉[ことば]の壁[かべ]を超[こ]えて、外国[がいこく]の友達[ともだち]をたくさん作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "超える", "label": "基本形"}, {"form": "超えます", "label": "丁寧形"}, {"form": "超えた", "label": "過去形"}, {"form": "超えて", "label": "て形"}, {"form": "超えない", "label": "否定形"}, {"form": "超えれば", "label": "仮定形"}, {"form": "超えよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "数・程度・限界などの基準を上回る、それより大きくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超えた", "is_correct": true, "explanation": "正しい。過去の形「超えた」に「ので」がつながり、「35度を超えたので、外に出るのが危ない」と理由を述べる文になる。"}, {"text": "増えた", "is_correct": false, "explanation": "「増える」は到達や変化の先を「に」で示す自動詞なので、「35度を増えた」とは言えない。"}, {"text": "減った", "is_correct": false, "explanation": "「減る」は対象を「を」で取れない自動詞なので、「35度を減った」は成り立たない。"}, {"text": "届いた", "is_correct": false, "explanation": "「届く」は到達点を「に」で示すので、「35度を届いた」は文として成り立たない。"}], "explanations": {"超えた": "正しい。過去の形「超えた」に「ので」がつながり、「35度を超えたので、外に出るのが危ない」と理由を述べる文になる。", "増えた": "「増える」は到達や変化の先を「に」で示す自動詞なので、「35度を増えた」とは言えない。", "減った": "「減る」は対象を「を」で取れない自動詞なので、「35度を減った」は成り立たない。", "届いた": "「届く」は到達点を「に」で示すので、「35度を届いた」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "超えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谷の深い川を超えて、向こう岸へ渡った。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}, {"text": "山の尾根を超えて、隣の村へ下りた。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}, {"text": "国境を超えて、隣国へ入った。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超える", "is_correct": true, "explanation": "正しい。辞書形「超える」に条件の「と」がつながり「超えると」となる。"}, {"text": "割って", "is_correct": false, "explanation": "て形は「と」に続かないため、「二十キロを割ってと」は文が成り立たない。"}, {"text": "積んで", "is_correct": false, "explanation": "て形は「と」に続かず、重さの話でも「積む」は「と」の前に置けない。"}, {"text": "運んで", "is_correct": false, "explanation": "て形は「と」に続かないため、「運んでと」は不自然で文が続かない。"}], "explanations": {"超える": "正しい。辞書形「超える」に条件の「と」がつながり「超えると」となる。", "割って": "て形は「と」に続かないため、「二十キロを割ってと」は文が成り立たない。", "積んで": "て形は「と」に続かず、重さの話でも「積む」は「と」の前に置けない。", "運んで": "て形は「と」に続かないため、「運んでと」は不自然で文が続かない。"}, "sentence_index": 6, "correct_answer": "超える"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "川を超えて、対岸の村へ渡った。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}, {"text": "塀を超えて、庭へ侵入した。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}, {"text": "柵を超えて、牧場に入った。", "explanation": "ここは〈越える〉（へだたりを横切る）の意味。基準を上回る義項とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボーナスの額が一万円を超えと、税金がかかります。", "corrected_sentence": "ボーナスの額が一万円を超えると、税金がかかります。", "error_description": "条件の「と」は辞書形に続くので「超えると」が正しい。「超えと」は接続として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "超えて", "is_correct": true, "explanation": "正しい。「超えて、」の形で後ろの文へ続くて形。"}, {"text": "超えよう", "is_correct": false, "explanation": "意志形は言い切りの形で、「、」で続けると文の意味が成り立たない。"}, {"text": "超えます", "is_correct": false, "explanation": "丁寧形は文末などで使う形で、「超えます、」では後ろの文へ続かない。"}, {"text": "超えろ", "is_correct": false, "explanation": "命令形は強い言い切りで、「超えろ、」では後ろの文へ続かない。"}], "correct_form": "超えて", "base_form": "超える", "form_label": "て形", "sentence_index": 1, "explanations": {"超えて": "正しい。「超えて、」の形で後ろの文へ続くて形。", "超えよう": "意志形は言い切りの形で、「、」で続けると文の意味が成り立たない。", "超えます": "丁寧形は文末などで使う形で、「超えます、」では後ろの文へ続かない。", "超えろ": "命令形は強い言い切りで、「超えろ、」では後ろの文へ続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53351, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "期待に超える結果に、みんな驚いた。", "corrected_sentence": "期待を超える結果に、みんな驚いた。", "error_description": "「超える」の対象は「を」で示すので「期待を超える」が正しい。「期待に超える」は助詞が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "超える", "is_correct": true, "explanation": "正しい。名詞「成績」を修飾する基本形で、「記録を超える成績」となる。"}, {"text": "超えよう", "is_correct": false, "explanation": "意志形は名詞を直接修飾できず、「超えよう成績」は成り立たない。"}, {"text": "超えず", "is_correct": false, "explanation": "打ち消しの連用形「超えず」は名詞を修飾できず、「超えず成績」は成り立たない。"}, {"text": "超えたら", "is_correct": false, "explanation": "条件形は名詞を修飾できず、「超えたら成績」は成り立たない。"}], "correct_form": "超える", "base_form": "超える", "form_label": "基本形", "sentence_index": 7, "explanations": {"超える": "正しい。名詞「成績」を修飾する基本形で、「記録を超える成績」となる。", "超えよう": "意志形は名詞を直接修飾できず、「超えよう成績」は成り立たない。", "超えず": "打ち消しの連用形「超えず」は名詞を修飾できず、「超えず成績」は成り立たない。", "超えたら": "条件形は名詞を修飾できず、「超えたら成績」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
