INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53353, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あることが起きたら、そのあとに別のことが起こるという意味です。", "primary_collocate": null, "pronunciation": "もし", "ipa": "moɕi", "syllable_count": 2, "sentences": [{"text": "もしこのボタンを押せば、ドアが自動で開きます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしこのボタンを押[お]せば、ドアが自動[じどう]で開[あ]きます。", "sentence_source": "generated"}, {"text": "もし水を百度まで熱したら、水は湯気になります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし水[みず]を百度[ひゃくど]まで熱[ねっ]したら、水[みず]は湯気[ゆげ]になります。", "sentence_source": "generated"}, {"text": "もし毎日三十分歩けば、体の調子がよくなります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし毎日[まいにち]三十分[さんじゅっぷん]歩[ある]けば、体[からだ]の調子[ちょうし]がよくなります。", "sentence_source": "generated"}, {"text": "もし朝六時に起きたら、散歩をしてから学校へ行きます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし朝[あさ]六時[ろくじ]に起[お]きたら、散歩[さんぽ]をしてから学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "もし宿題が早く終わったら、ゲームをしてもいいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし宿題[しゅくだい]が早[はや]く終[お]わったら、ゲームをしてもいいです。", "sentence_source": "generated"}, {"text": "もし夜遅くコーヒーを飲めば、なかなか寝られなくなります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし夜遅[よるおそ]くコーヒーを飲[の]めば、なかなか寝[ね]られなくなります。", "sentence_source": "generated"}, {"text": "もし試験に合格したら、両親が旅行に連れて行ってくれます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし試験[しけん]に合格[ごうかく]したら、両親[りょうしん]が旅行[りょこう]に連[つ]れて行[い]ってくれます。", "sentence_source": "generated"}, {"text": "もしこの薬を飲めば、熱は一時間ぐらいで下がります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしこの薬[くすり]を飲[の]めば、熱[ねつ]は一時間[いちじかん]ぐらいで下[さ]がります。", "sentence_source": "generated"}, {"text": "もし冬に雪がたくさん降ったら、学校が休みになります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし冬[ふゆ]に雪[ゆき]がたくさん降[ふ]ったら、学校[がっこう]が休[やす]みになります。", "sentence_source": "generated"}, {"text": "もし友達に手紙を書けば、きっと返事が来ます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし友達[ともだち]に手紙[てがみ]を書[か]けば、きっと返事[へんじ]が来[き]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もし", "label": "基本形"}, {"form": "若し", "label": "漢字表記"}], "register": "丁寧", "sense_fingerprint": "ある出来事が起きたあとに、別の出来事や結果が続くことを示す副詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53353, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "文頭で仮定の条件を示す副詞。後ろの「ば」と呼応して、ある操作の後の結果を導く。"}, {"text": "はい", "is_correct": false, "explanation": "感動詞で、ここに入れると「はいこのボタンを押せば」となり文が成り立たない。"}, {"text": "どうして", "is_correct": false, "explanation": "理由を問う語で、平叙の文に入ると呼応せず文が成り立たない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}], "explanations": {"もし": "文頭で仮定の条件を示す副詞。後ろの「ば」と呼応して、ある操作の後の結果を導く。", "はい": "感動詞で、ここに入れると「はいこのボタンを押せば」となり文が成り立たない。", "どうして": "理由を問う語で、平叙の文に入ると呼応せず文が成り立たない。", "なぜ": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}, "sentence_index": 0, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし夢のような一日でした。", "explanation": "ここは比喩〈まるで〉の意味。〈もし〉は条件を示すので、「夢のようだ」と例える文には合わない。"}, {"text": "もしほとんど終わりました。", "explanation": "ここは大部分を表す〈ほとんど〉の意味。〈もし〉は条件の副詞で、程度を表す文には合わない。"}, {"text": "もしとても寒くてたまりません。", "explanation": "ここは程度の強調〈とても〉の意味。〈もし〉は条件を示すだけで、程度の強調には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53353, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "文頭で条件を示す副詞。後ろの「たら」と呼応して、合格の後の結果を導く。"}, {"text": "ずいぶん", "is_correct": false, "explanation": "程度を表す副詞で、条件の「たら」と呼応せず、この文では成り立たない。"}, {"text": "さっそく", "is_correct": false, "explanation": "すぐにという副詞で、条件の文頭に置いても「たら」と呼応せず文が成り立たない。"}, {"text": "ねえ", "is_correct": false, "explanation": "呼びかけの感動詞で、ここに入れると条件の文として呼応が崩れる。"}], "explanations": {"もし": "文頭で条件を示す副詞。後ろの「たら」と呼応して、合格の後の結果を導く。", "ずいぶん": "程度を表す副詞で、条件の「たら」と呼応せず、この文では成り立たない。", "さっそく": "すぐにという副詞で、条件の文頭に置いても「たら」と呼応せず文が成り立たない。", "ねえ": "呼びかけの感動詞で、ここに入れると条件の文として呼応が崩れる。"}, "sentence_index": 6, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もし三時です。", "explanation": "ここは〈ちょうど〉（その時刻）の意味。〈もし〉は条件を示すので、時刻を指す文には合わない。"}, {"text": "もしその通りでした。", "explanation": "ここは〈まさに〉（ちょうどその通り）の意味。〈もし〉は条件の副詞で、断定の強調には合わない。"}, {"text": "もしついに夢が叶いました。", "explanation": "ここは〈ついに〉（とうとう実現した）の意味。〈もし〉は条件で、結末の強調には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53353, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "もし明日晴れたので、ピクニックに行きます。", "corrected_sentence": "もし明日晴れたら、ピクニックに行きます。", "error_description": "「もし」は「たら」と呼応して、ある出来事の後に別のことが起こる条件を示す。「ので」は理由を表すため、ここでは「晴れたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53353, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "もし雪が降るので、学校が休みになります。", "corrected_sentence": "もし雪が降ったら、学校が休みになります。", "error_description": "「もし」に続く動詞の形が誤っている。「ので」は理由を表すため、仮定の条件では「降ったら」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
