INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53354, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "仮定を表す副詞です。ある条件が満たされた場合に、それによる結果や推論を示します。", "primary_collocate": null, "pronunciation": "もし", "ipa": "moɕi", "syllable_count": 2, "sentences": [{"text": "もし彼が犯人なら、あの時間に駅にいたはずがありません。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし彼[かれ]が犯人[はんにん]なら、あの時間[じかん]に駅[えき]にいたはずがありません。", "sentence_source": "generated"}, {"text": "もしこの地図が正しければ、宝は山の北側にあるはずです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしこの地図[ちず]が正[ただ]しければ、宝[たから]は山[やま]の北側[きたがわ]にあるはずです。", "sentence_source": "generated"}, {"text": "もし彼女が本当に病気なら、今日の会議には来られないでしょう。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし彼女[かのじょ]が本当[ほんとう]に病気[びょうき]なら、今日[きょう]の会議[かいぎ]には来[こ]られないでしょう。", "sentence_source": "generated"}, {"text": "もしこの数字が間違っていなければ、売り上げは去年の二倍です。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしこの数字[すうじ]が間違[まちが]っていなければ、売[う]り上[あ]げは去年[きょねん]の二倍[にばい]です。", "sentence_source": "generated"}, {"text": "もし弟が先に家に着いたのなら、もう夕飯を食べているでしょう。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし弟[おとうと]が先[さき]に家[いえ]に着[つ]いたのなら、もう夕飯[ゆうはん]を食[た]べているでしょう。", "sentence_source": "generated"}, {"text": "もし私の計算が合っていれば、この荷物は明日の朝に届きます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし私[わたし]の計算[けいさん]が合[あ]っていれば、この荷物[にもつ]は明日[あした]の朝[あさ]に届[とど]きます。", "sentence_source": "generated"}, {"text": "もし電気がついていないなら、店はもう閉まっているのでしょう。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし電気[でんき]がついていないなら、店[みせ]はもう閉[し]まっているのでしょう。", "sentence_source": "generated"}, {"text": "もし窓が開いていたとすれば、犬はそこから外へ出たと思います。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし窓[まど]が開[あ]いていたとすれば、犬[いぬ]はそこから外[そと]へ出[で]たと思[おも]います。", "sentence_source": "generated"}, {"text": "もしこの話が本当なら、町の人はとても驚くでしょう。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしこの話[はなし]が本当[ほんとう]なら、町[まち]の人[ひと]はとても驚[おどろ]くでしょう。", "sentence_source": "generated"}, {"text": "もし彼が約束を覚えていたなら、もうここに着いているはずです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし彼[かれ]が約束[やくそく]を覚[おぼ]えていたなら、もうここに着[つ]いているはずです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もし", "label": "基本形"}, {"form": "若し", "label": "漢字表記"}], "register": "丁寧", "sense_fingerprint": "ある条件が正しいとしたら何が言えるか、結果や推論を導くときの「もし」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "ある条件が正しいとしたら何が言えるかを示す副詞。後ろの「なら」と呼応する。"}, {"text": "どうして", "is_correct": false, "explanation": "理由を問う語で、平叙の文に入ると呼応せず文が成り立たない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}, {"text": "はい", "is_correct": false, "explanation": "感動詞で、ここに入れると文が成り立たない。"}], "explanations": {"もし": "ある条件が正しいとしたら何が言えるかを示す副詞。後ろの「なら」と呼応する。", "どうして": "理由を問う語で、平叙の文に入ると呼応せず文が成り立たない。", "なぜ": "理由を問う語で、仮定の文の頭に置くと意味が通らない。", "はい": "感動詞で、ここに入れると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし夢のような一日でした。", "explanation": "ここは比喩〈まるで〉の意味。〈もし〉は推論の条件で、「夢のようだ」と例える文には合わない。"}, {"text": "もしほとんど終わりました。", "explanation": "ここは大部分を表す〈ほとんど〉の意味。〈もし〉は条件を示すので、程度を表す文には合わない。"}, {"text": "もしとても寒くてたまりません。", "explanation": "ここは程度の強調〈とても〉の意味。〈もし〉は推論の条件で、程度の強調には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "ある条件が正しいとしたら何が言えるかを示す副詞。後ろの「なら」と呼応する。"}, {"text": "さっそく", "is_correct": false, "explanation": "すぐにという副詞で、推論の条件の文頭に置いても「なら」と呼応せず文が成り立たない。"}, {"text": "ずいぶん", "is_correct": false, "explanation": "程度を表す副詞で、条件を示す「なら」と呼応せず、この文では意味が通らない。"}, {"text": "ねえ", "is_correct": false, "explanation": "呼びかけの感動詞で、ここに入れると推論の条件文として成り立たない。"}], "explanations": {"もし": "ある条件が正しいとしたら何が言えるかを示す副詞。後ろの「なら」と呼応する。", "さっそく": "すぐにという副詞で、推論の条件の文頭に置いても「なら」と呼応せず文が成り立たない。", "ずいぶん": "程度を表す副詞で、条件を示す「なら」と呼応せず、この文では意味が通らない。", "ねえ": "呼びかけの感動詞で、ここに入れると推論の条件文として成り立たない。"}, "sentence_index": 6, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もし彼に会えました。", "explanation": "ここは〈ようやく〉（長い末に実現した）の意味。〈もし〉は推論の条件で、実現の報告には合わない。"}, {"text": "もしついに夢が叶いました。", "explanation": "ここは〈ついに〉（とうとう実現した）の意味。〈もし〉は条件で、結末の強調には合わない。"}, {"text": "もしその通りでした。", "explanation": "ここは〈まさに〉（ちょうどその通り）の意味。〈もし〉は条件の副詞で、断定の強調には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "もし電気が消えたので、店は閉まったでしょう。", "corrected_sentence": "もし電気が消えたら、店は閉まったでしょう。", "error_description": "「もし」は「たら」と呼応して、条件から推論を導く。「ので」は理由を表すため、推論の条件では「消えたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "もし店が開いているでしょう、買い物に行きます。", "corrected_sentence": "もし店が開いていれば、買い物に行きます。", "error_description": "「もし」に続く形が推量の「でしょう」になっている。条件を表すには「開いていれば」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「格闘と」の「と」。使い方が相手なので「と」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は直接目的語を示す。格闘は「と」を取るので誤り。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。ここは動作の相手なので「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や対象を表すが、格闘には付かない。"}], "correct_answer": "と", "explanations": {"と": "「格闘と」の「と」。使い方が相手なので「と」が正しい。", "を": "「を」は直接目的語を示す。格闘は「と」を取るので誤り。", "が": "「が」は主語を示す。ここは動作の相手なので「が」は合わない。", "に": "「に」は到達点や対象を表すが、格闘には付かない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "到達点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「格闘と」の「と」。難しい本が相手なので「と」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。格闘の相手には付かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。格闘の相手を示すことはできない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ語。格闘の相手を示すことはできない。"}], "correct_answer": "と", "explanations": {"と": "「格闘と」の「と」。難しい本が相手なので「と」が正しい。", "へ": "「へ」は方向を表す。格闘の相手には付かない。", "から": "「から」は起点を表す。格闘の相手を示すことはできない。", "の": "「の」は名詞をつなぐ語。格闘の相手を示すことはできない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "むずかしいことと戦って、がんばることです。", "primary_collocate": null, "pronunciation": "かくとう", "ipa": "kakɯtoː", "syllable_count": 4, "sentences": [{"text": "私は毎晩、むずかしい宿題と格闘している。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "私[わたし]は毎晩[まいばん]、むずかしい宿題[しゅくだい]と格闘[かくとう]している。", "sentence_source": "generated"}, {"text": "新しいパソコンの使い方と格闘して、一日が終わった。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "新[あたら]しいパソコンの使[つか]い方[かた]と格闘[かくとう]して、一日[いちにち]が終[お]わった。", "sentence_source": "generated"}, {"text": "弟は算数の問題と二時間も格闘した。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "弟[おとうと]は算数[さんすう]の問題[もんだい]と二時間[にじかん]も格闘[かくとう]した。", "sentence_source": "generated"}, {"text": "母は重い荷物と格闘しながら、階段をのぼった。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "母[はは]は重[おも]い荷物[にもつ]と格闘[かくとう]しながら、階段[かいだん]をのぼった。", "sentence_source": "generated"}, {"text": "彼は日本語の漢字と格闘する毎日を送っている。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "彼[かれ]は日本語[にほんご]の漢字[かんじ]と格闘[かくとう]する毎日[まいにち]を送[おく]っている。", "sentence_source": "generated"}, {"text": "絡まったコードと十分ほど格闘して、やっとほどけた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "絡[から]まったコードと十分[じゅっぷん]ほど格闘[かくとう]して、やっとほどけた。", "sentence_source": "generated"}, {"text": "初めての料理と格闘したが、結局うまくできなかった。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "初[はじ]めての料理[りょうり]と格闘[かくとう]したが、結局[けっきょく]うまくできなかった。", "sentence_source": "generated"}, {"text": "私は長い間、この難しい本と格闘してきた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "私[わたし]は長[なが]い間[あいだ]、この難[むずか]しい本[ほん]と格闘[かくとう]してきた。", "sentence_source": "generated"}, {"text": "説明書がなく、機械の修理と格闘するしかなかった。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]がなく、機械[きかい]の修理[しゅうり]と格闘[かくとう]するしかなかった。", "sentence_source": "generated"}, {"text": "試験の前は、山のような資料と格闘する日が続いた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、山[やま]のような資料[しりょう]と格闘[かくとう]する日[ひ]が続[つづ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格闘", "label": "基本形"}, {"form": "格闘する", "label": "サ変動詞形"}, {"form": "格闘した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "むずかしい物事に必死に取り組んで、苦労すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格闘", "is_correct": true, "explanation": "「格闘」は難しいことと必死に戦う意味。宿題と毎晩取り組む様子に合う。"}, {"text": "交換", "is_correct": false, "explanation": "「交換」は物を取り替えること。宿題と交換しても文の意味が通らない。"}, {"text": "雑談", "is_correct": false, "explanation": "「雑談」は気軽に話すこと。宿題とは雑談しないので合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は歩くこと。宿題と散歩するという意味にはならない。"}], "explanations": {"格闘": "「格闘」は難しいことと必死に戦う意味。宿題と毎晩取り組む様子に合う。", "交換": "「交換」は物を取り替えること。宿題と交換しても文の意味が通らない。", "雑談": "「雑談」は気軽に話すこと。宿題とは雑談しないので合わない。", "散歩": "「散歩」は歩くこと。宿題と散歩するという意味にはならない。"}, "sentence_index": 0, "correct_answer": "格闘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝、子猫と格闘して遊んだ。", "explanation": "ここは〈じゃれ合う〉の意味。格闘は難題と戦う意味なので、遊ぶ文には合わない。"}, {"text": "兄は友人と格闘して、夕食の準備を手伝った。", "explanation": "ここは〈手伝う〉の意味。格闘は戦う意味なので、協力する文には合わない。"}, {"text": "週末は家で格闘して、本を読んで過ごした。", "explanation": "ここは〈読書をして過ごす〉の意味。格闘は苦労して戦う意味なので、くつろぐ文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格闘", "is_correct": true, "explanation": "「格闘」は難しいことと必死に戦う意味。初めての料理に苦労した流れに合う。"}, {"text": "観察", "is_correct": false, "explanation": "「観察」は注意深く見ること。苦労した結果を述べる文の空欄には合わない。"}, {"text": "見学", "is_correct": false, "explanation": "「見学」は実際の様子を見て学ぶこと。料理と見学する意味にはならない。"}, {"text": "放置", "is_correct": false, "explanation": "「放置」はそのままにしておくこと。苦労して取り組んだ流れと矛盾する。"}], "explanations": {"格闘": "「格闘」は難しいことと必死に戦う意味。初めての料理に苦労した流れに合う。", "観察": "「観察」は注意深く見ること。苦労した結果を述べる文の空欄には合わない。", "見学": "「見学」は実際の様子を見て学ぶこと。料理と見学する意味にはならない。", "放置": "「放置」はそのままにしておくこと。苦労して取り組んだ流れと矛盾する。"}, "sentence_index": 6, "correct_answer": "格闘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休暇中は、子犬と格闘ごっこをして遊んだ。", "explanation": "ここは〈じゃれ合う〉の意味。格闘は難題と戦う意味なので、遊ぶ文には合わない。"}, {"text": "先生は新入生と格闘して歓迎した。", "explanation": "ここは〈歓迎〉の意味。格闘は戦う意味なので、迎える文には合わない。"}, {"text": "彼は料理を格闘して味わった。", "explanation": "ここは〈味わう〉の意味。格闘は苦労して戦う意味なので、料理を楽しむ文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究チームは、新薬の副作用の原因を格闘している。", "corrected_sentence": "研究チームは、新薬の副作用の原因と格闘している。", "error_description": "「格闘する」は「と」で難題を示す。「を」は誤り（格闘と）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53357, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "難しい課題を格闘してきた。", "corrected_sentence": "難しい課題と格闘してきた。", "error_description": "「格闘する」は「と」で難題を示す。「を」は誤り（格闘と）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
