INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53358, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "むずかしい問題や困難に直面し、それを解決しようと懸命に取り組むこと。", "primary_collocate": null, "pronunciation": "かくとう", "ipa": "kakɯtoː", "syllable_count": 4, "sentences": [{"text": "開発チームは、システムの不具合の解決に向けて数週間格闘した。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "開発[かいはつ]チームは、システムの不具合[ふぐあい]の解決[かいけつ]に向[む]けて数週間[すうしゅうかん]格闘[かくとう]した。", "sentence_source": "generated"}, {"text": "彼女は育児と仕事の両立という問題と格闘している。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は育児[いくじ]と仕事[しごと]の両立[りょうりつ]という問題[もんだい]と格闘[かくとう]している。", "sentence_source": "generated"}, {"text": "市は財政難と格闘しながら、新しい図書館を作った。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "市[し]は財政難[ざいせいなん]と格闘[かくとう]しながら、新[あたら]しい図書館[としょかん]を作[つく]った。", "sentence_source": "generated"}, {"text": "作家は最後の一行が書けず、締め切りまで原稿と格闘した。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "作家[さっか]は最後[さいご]の一行[いちぎょう]が書[か]けず、締[し]め切[き]りまで原稿[げんこう]と格闘[かくとう]した。", "sentence_source": "generated"}, {"text": "医師たちは、新しい病気の治療法を見つけようと格闘している。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "医師[いし]たちは、新[あたら]しい病気[びょうき]の治療法[ちりょうほう]を見[み]つけようと格闘[かくとう]している。", "sentence_source": "generated"}, {"text": "彼は借金の返済と格闘し、十年かけて完済した。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "彼[かれ]は借金[しゃっきん]の返済[へんさい]と格闘[かくとう]し、十年[じゅうねん]かけて完済[かんさい]した。", "sentence_source": "generated"}, {"text": "新入社員は慣れない仕事との格闘の毎日だ。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]は慣[な]れない仕事[しごと]との格闘[かくとう]の毎日[まいにち]だ。", "sentence_source": "generated"}, {"text": "農家の人々は、不作という困難と格闘してきた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "農家[のうか]の人々[ひとびと]は、不作[ふさく]という困難[こんなん]と格闘[かくとう]してきた。", "sentence_source": "generated"}, {"text": "研究者は何年も、この難問と格闘したすえに答えを見つけた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は何年[なんねん]も、この難問[なんもん]と格闘[かくとう]したすえに答[こた]えを見[み]つけた。", "sentence_source": "generated"}, {"text": "彼は病気と格闘しながら、最後まで舞台に立ち続けた。", "target_word": "格闘", "complexity_tier": "T3", "furigana": "彼[かれ]は病気[びょうき]と格闘[かくとう]しながら、最後[さいご]まで舞台[ぶたい]に立[た]ち続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格闘", "label": "基本形"}, {"form": "格闘する", "label": "サ変動詞形"}, {"form": "格闘した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "困難や問題の解決に向けて、長く懸命に取り組むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格闘", "is_correct": true, "explanation": "「格闘」は困難な問題に懸命に取り組む意味。不具合の解決に数週間かけた文に合う。"}, {"text": "交換", "is_correct": false, "explanation": "「交換」は取り替えること。不具合の解決の文には入らない。"}, {"text": "雑談", "is_correct": false, "explanation": "「雑談」は気軽に話すこと。解決に取り組む文の空欄には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は歩くこと。問題の解決を表す文には合わない。"}], "explanations": {"格闘": "「格闘」は困難な問題に懸命に取り組む意味。不具合の解決に数週間かけた文に合う。", "交換": "「交換」は取り替えること。不具合の解決の文には入らない。", "雑談": "「雑談」は気軽に話すこと。解決に取り組む文の空欄には合わない。", "散歩": "「散歩」は歩くこと。問題の解決を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "格闘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は孫と格闘して、昼寝をした。", "explanation": "ここは〈昼寝〉の意味。格闘は戦う意味なので、眠る文には合わない。"}, {"text": "二人は話し合いの末、腕相撲で格闘した。", "explanation": "ここは〈腕相撲で勝負する〉の意味。格闘は難題に懸命に取り組む意味で、ゲームの勝負の文には合わない。"}, {"text": "週末は、庭で弟と格闘して、花を植えた。", "explanation": "ここは〈取っ組み合い〉の意味。格闘は難題に懸命に取り組む意味なので、植える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格闘", "is_correct": true, "explanation": "「格闘」は困難と懸命に戦うこと。慣れない仕事との苦労の日々を表す。"}, {"text": "観光", "is_correct": false, "explanation": "「観光」は名所を見て回ること。仕事との毎日には合わない。"}, {"text": "交流", "is_correct": false, "explanation": "「交流」は人と関わること。仕事との苦労の毎日には合わない。"}, {"text": "休憩", "is_correct": false, "explanation": "「休憩」は一休みすること。仕事との苦労の毎日とは意味が合わない。"}], "explanations": {"格闘": "「格闘」は困難と懸命に戦うこと。慣れない仕事との苦労の日々を表す。", "観光": "「観光」は名所を見て回ること。仕事との毎日には合わない。", "交流": "「交流」は人と関わること。仕事との苦労の毎日には合わない。", "休憩": "「休憩」は一休みすること。仕事との苦労の毎日とは意味が合わない。"}, "sentence_index": 6, "correct_answer": "格闘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姉は、枕と格闘して笑い転げた。", "explanation": "ここは〈じゃれ合う〉の意味。格闘は難題と戦う意味なので、ふざける文には合わない。"}, {"text": "昼休みは、同僚と格闘ごっこをして、昼食を食べた。", "explanation": "ここは〈取っ組み合いのふざけ〉の意味。格闘は難題と戦う意味なので、食事の文には合わない。"}, {"text": "息子はおもちゃの車と格闘して、大笑いした。", "explanation": "ここは〈笑う〉の意味。格闘は難題に懸命に取り組む意味なので、笑う文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は財政難を格闘しながら、新しい施設を作った。", "corrected_sentence": "市は財政難と格闘しながら、新しい施設を作った。", "error_description": "「格闘する」は「と」で難題を示す。「を」は誤り（格闘と）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "難病と格闘しなながら、研究を続けた。", "corrected_sentence": "難病と格闘しながら、研究を続けた。", "error_description": "「格闘する」の連用形は「格闘し」。「しなながら」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
