INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「負けを覚悟した」で、負けを受け入れる心構えの対象を示す。文の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「負けに覚悟した」は不自然で、文の意味に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「負けと覚悟した」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「負けへ覚悟した」は方向を示す助詞で、不自然。"}], "correct_answer": "を", "explanations": {"を": "「負けを覚悟した」で、負けを受け入れる心構えの対象を示す。文の意味に合う。", "に": "「負けに覚悟した」は不自然で、文の意味に合わない。", "と": "「負けと覚悟した」は意味が通らない。", "へ": "「負けへ覚悟した」は方向を示す助詞で、不自然。"}, "error_tags": {"に": "場所・対象", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "難しいことや怖いことに備えて、心で準備することです。", "primary_collocate": null, "pronunciation": "かくご", "ipa": "kakɯɡo", "syllable_count": 3, "sentences": [{"text": "厳しい冬になる覚悟はしていたが、想像より寒かった。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "厳[きび]しい冬[ふゆ]になる覚悟[かくご]はしていたが、想像[そうぞう]より寒[さむ]かった。", "sentence_source": "generated"}, {"text": "試験に落ちる覚悟で、私は問題を最後まで解いた。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "試験[しけん]に落[お]ちる覚悟[かくご]で、私[わたし]は問題[もんだい]を最後[さいご]まで解[と]いた。", "sentence_source": "generated"}, {"text": "医者から長い入院になると聞き、母は覚悟を決めた。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "医者[いしゃ]から長[なが]い入院[にゅういん]になると聞[き]き、母[はは]は覚悟[かくご]を決[き]めた。", "sentence_source": "generated"}, {"text": "山の天気は変わりやすいので、雨に降られる覚悟が必要だ。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "山[やま]の天気[てんき]は変[か]わりやすいので、雨[あめ]に降[ふ]られる覚悟[かくご]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "知らない国で暮らすには、それなりの覚悟がいる。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "知[し]らない国[くに]で暮[く]らすには、それなりの覚悟[かくご]がいる。", "sentence_source": "generated"}, {"text": "彼は叱られる覚悟で、本当のことを先生に話した。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "彼[かれ]は叱[しか]られる覚悟[かくご]で、本当[ほんとう]のことを先生[せんせい]に話[はな]した。", "sentence_source": "generated"}, {"text": "大きな台風が来ると知り、停電を覚悟して水を用意した。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "大[おお]きな台風[たいふう]が来[く]ると知[し]り、停電[ていでん]を覚悟[かくご]して水[みず]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "負けを覚悟した瞬間、かえって気持ちが軽くなった。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "負[ま]けを覚悟[かくご]した瞬間[しゅんかん]、かえって気持[きも]ちが軽[かる]くなった。", "sentence_source": "generated"}, {"text": "遅れる覚悟はしていたけれど、三時間も待つとは思わなかった。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "遅[おく]れる覚悟[かくご]はしていたけれど、三時間[さんじかん]も待[ま]つとは思[おも]わなかった。", "sentence_source": "generated"}, {"text": "会社をやめる覚悟ができたので、家族に話した。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "会社[かいしゃ]をやめる覚悟[かくご]ができたので、家族[かぞく]に話[はな]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚悟", "label": "基本形"}, {"form": "覚悟する", "label": "サ変動詞終止形"}, {"form": "覚悟した", "label": "過去形"}, {"form": "覚悟して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "悪い結果や困難を受け入れる心の準備", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚悟", "is_correct": true, "explanation": "「覚悟はしていた」で、寒さを予想して心構えをしていたことを表す。この文で意味が通る語。"}, {"text": "窓", "is_correct": false, "explanation": "「窓はしていた」は意味をなさない。"}, {"text": "扉", "is_correct": false, "explanation": "「扉はしていた」は文に合わない。"}, {"text": "歌", "is_correct": false, "explanation": "「歌はしていた」は不自然で、冬の予想の文には合わない。"}], "explanations": {"覚悟": "「覚悟はしていた」で、寒さを予想して心構えをしていたことを表す。この文で意味が通る語。", "窓": "「窓はしていた」は意味をなさない。", "扉": "「扉はしていた」は文に合わない。", "歌": "「歌はしていた」は不自然で、冬の予想の文には合わない。"}, "sentence_index": 0, "correct_answer": "覚悟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい単語を一晩で覚悟した。", "explanation": "ここは〈覚える〉の意味。覚悟は困難に備える心構えを指し、単語を暗記する意味では使わないので合わない。"}, {"text": "出発前に食料を覚悟しておいた。", "explanation": "ここは〈用意〉の意味。覚悟は心の準備で、物を整える意味はないので合わない。"}, {"text": "朝六時に、目を覚悟して起きた。", "explanation": "ここは〈目覚める〉の意味。覚悟は目を覚ます意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚悟", "is_correct": true, "explanation": "「停電を覚悟して」で、停電が起きることを受け入れる心構えを表す。この文で意味が通る語。"}, {"text": "観察", "is_correct": false, "explanation": "「停電を観察して」は停電を調べる意味になり、水を用意する流れに合わない。"}, {"text": "歓迎", "is_correct": false, "explanation": "「停電を歓迎して」は意味が合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「停電を採点して」は文に合わない。"}], "explanations": {"覚悟": "「停電を覚悟して」で、停電が起きることを受け入れる心構えを表す。この文で意味が通る語。", "観察": "「停電を観察して」は停電を調べる意味になり、水を用意する流れに合わない。", "歓迎": "「停電を歓迎して」は意味が合わない。", "採点": "「停電を採点して」は文に合わない。"}, "sentence_index": 6, "correct_answer": "覚悟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の気持ちを覚悟して、そっと席を外した。", "explanation": "ここは〈察する〉の意味。覚悟は心の準備で、相手の気持ちを推し量る意味にはならないので合わない。"}, {"text": "卒業式の日、覚悟にふけった。", "explanation": "ここは〈感慨にふける〉の感慨。覚悟にふけるという使い方はないので合わない。"}, {"text": "勝利を覚悟し、堂々と宣言した。", "explanation": "ここは〈確信〉の意味。覚悟は困難に備える心構えで、勝つと信じる意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は長い行列に並ぶ覚悟を、早めに家を出た。", "corrected_sentence": "今日は長い行列に並ぶ覚悟で、早めに家を出た。", "error_description": "誤りは「覚悟を」の「を」。「覚悟」は「家を出た」の目的語にならず、様態を示す「覚悟で」の「で」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53365, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨に濡れる覚悟を果たして、自転車で出かけた。", "corrected_sentence": "雨に濡れる覚悟を決めて、自転車で出かけた。", "error_description": "「覚悟を決める」が正しい。「果たす」は責任や役目に使う動詞で、覚悟とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「隊員たちの覚悟」で、覚悟の持ち主を示す。文の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「隊員たちで覚悟は」は手段や場所を示す格で、主語の位置に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「隊員たちを覚悟は」は目的語の形になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「隊員たちに覚悟は」は対象や方向を示すが、ここでは意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「隊員たちの覚悟」で、覚悟の持ち主を示す。文の意味に合う。", "で": "「隊員たちで覚悟は」は手段や場所を示す格で、主語の位置に合わない。", "を": "「隊員たちを覚悟は」は目的語の形になり、文が成り立たない。", "に": "「隊員たちに覚悟は」は対象や方向を示すが、ここでは意味が通らない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "に": "対象・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
