INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "困難や不測の事態に備えて、心構えを整えること。また、その強い気持ち。", "primary_collocate": null, "pronunciation": "かくご", "ipa": "kakɯɡo", "syllable_count": 3, "sentences": [{"text": "彼は最後まで責任を果たす覚悟を、記者会見で語った。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "彼[かれ]は最後[さいご]まで責任[せきにん]を果[は]たす覚悟[かくご]を、記者会見[きしゃかいけん]で語[かた]った。", "sentence_source": "generated"}, {"text": "危険な任務に向かう隊員たちの覚悟は、固かった。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "危険[きけん]な任務[にんむ]に向[む]かう隊員[たいいん]たちの覚悟[かくご]は、固[かた]かった。", "sentence_source": "generated"}, {"text": "起業するなら、失敗を恐れない覚悟が求められる。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "起業[きぎょう]するなら、失敗[しっぱい]を恐[おそ]れない覚悟[かくご]が求[もと]められる。", "sentence_source": "generated"}, {"text": "彼女の覚悟のこもった言葉に、会場は静まり返った。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の覚悟[かくご]のこもった言葉[ことば]に、会場[かいじょう]は静[しず]まり返[かえ]った。", "sentence_source": "generated"}, {"text": "医師は、患者の命を預かる覚悟をもって手術に臨んだ。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "医師[いし]は、患者[かんじゃ]の命[いのち]を預[あず]かる覚悟[かくご]をもって手術[しゅじゅつ]に臨[のぞ]んだ。", "sentence_source": "generated"}, {"text": "覚悟がなければ、この道を進むことはできない。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "覚悟[かくご]がなければ、この道[みち]を進[すす]むことはできない。", "sentence_source": "generated"}, {"text": "首相は、改革をやり遂げる覚悟を国民に示した。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "首相[しゅしょう]は、改革[かいかく]をやり遂[と]げる覚悟[かくご]を国民[こくみん]に示[しめ]した。", "sentence_source": "generated"}, {"text": "父は、家族を守るために戦う覚悟を決めていた。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "父[ちち]は、家族[かぞく]を守[まも]るために戦[たたか]う覚悟[かくご]を決[き]めていた。", "sentence_source": "generated"}, {"text": "彼の覚悟の強さは、誰の目にも明らかだった。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "彼[かれ]の覚悟[かくご]の強[つよ]さは、誰[だれ]の目[め]にも明[あき]らかだった。", "sentence_source": "generated"}, {"text": "長い闘病を支える覚悟が、夫婦の間に生まれた。", "target_word": "覚悟", "complexity_tier": "T3", "furigana": "長[なが]い闘病[とうびょう]を支[ささ]える覚悟[かくご]が、夫婦[ふうふ]の間[あいだ]に生[う]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚悟", "label": "基本形"}, {"form": "覚悟する", "label": "サ変動詞終止形"}, {"form": "覚悟した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "困難に立ち向かうための固い心構えと決意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 固かっ (Zipf 2.3)','sentence 3 above tier T2: contains vocabulary far above tier T2: 静まり返っ (Zipf 2.4)']::text[], '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚悟", "is_correct": true, "explanation": "「覚悟を語った」で、困難に立ち向かう固い心構えを表す。この文で意味が通る語。"}, {"text": "請求", "is_correct": false, "explanation": "「請求を語った」は意味が通らない。"}, {"text": "地図", "is_correct": false, "explanation": "「地図を語った」は文脈に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を語った」は不自然で、文の意味に合わない。"}], "explanations": {"覚悟": "「覚悟を語った」で、困難に立ち向かう固い心構えを表す。この文で意味が通る語。", "請求": "「請求を語った」は意味が通らない。", "地図": "「地図を語った」は文脈に合わない。", "窓": "「窓を語った」は不自然で、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "覚悟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夢から覚悟して目を開けた。", "explanation": "ここは〈覚める〉の意味（眠りから目が覚める）。覚悟はそのような意味では使わないので合わない。"}, {"text": "明日は雨になりそうな覚悟がした。", "explanation": "ここは〈予感〉の意味。覚悟は困難に備える心構えで、予感を感じる意味にはならないので合わない。"}, {"text": "子どもたちは、その話に覚悟をそそられた。", "explanation": "ここは〈好奇心〉の意味（心をそそられる）。覚悟は困難に備える心構えで、好奇心をそそられる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚悟", "is_correct": true, "explanation": "「改革をやり遂げる覚悟を国民に示した」で、目標を達成する決意の心構えを表す。この文で意味が通る語。"}, {"text": "請求", "is_correct": false, "explanation": "「請求を国民に示した」は意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点を国民に示した」は不自然で、文の意味に合わない。"}, {"text": "門", "is_correct": false, "explanation": "「門を国民に示した」は文脈に合わない。"}], "explanations": {"覚悟": "「改革をやり遂げる覚悟を国民に示した」で、目標を達成する決意の心構えを表す。この文で意味が通る語。", "請求": "「請求を国民に示した」は意味が通らない。", "採点": "「採点を国民に示した」は不自然で、文の意味に合わない。", "門": "「門を国民に示した」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "覚悟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "被災者に覚悟を寄せた。", "explanation": "ここは〈同情〉の意味（同情を寄せる）。覚悟は相手に寄せる気持ちではないので合わない。"}, {"text": "道順を覚悟している。", "explanation": "ここは〈覚える〉の意味。覚悟は道順を覚えるという使い方はないので合わない。"}, {"text": "彼の言葉に覚悟を覚えた。", "explanation": "ここは〈怒り〉の意味（怒りを覚える）を覚悟に置き換えた形。覚悟は覚えるような感情ではないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大臣は、不祥事の責任を取る覚悟が記者団に伝えた。", "corrected_sentence": "大臣は、不祥事の責任を取る覚悟を記者団に伝えた。", "error_description": "「伝えた」の対象は「を」で示す。「が」は主語を示す助詞で、覚悟を伝える文では「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53366, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手は、ケガを抱えたまま試合に出る覚悟に決めた。", "corrected_sentence": "選手は、ケガを抱えたまま試合に出る覚悟を決めた。", "error_description": "「覚悟を決める」の「を」が正しい。「に」を使うと、決める対象の関係が合わず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
