INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53367, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "部屋の中の空気のあたたかさやひやすさのことです。", "primary_collocate": null, "pronunciation": "しつおん", "ipa": "ɕitsɯoɴ", "syllable_count": 4, "sentences": [{"text": "冬は室温が低いので、朝起きるのがつらい。", "target_word": "室温", "complexity_tier": "T3", "furigana": "冬[ふゆ]は室温[しつおん]が低[ひく]いので、朝[あさ]起[お]きるのがつらい。", "sentence_source": "generated"}, {"text": "室温が高すぎるから、窓を少し開けてください。", "target_word": "室温", "complexity_tier": "T3", "furigana": "室温[しつおん]が高[たか]すぎるから、窓[まど]を少[すこ]し開[あ]けてください。", "sentence_source": "generated"}, {"text": "暖房をつけたら、室温がゆっくり上がってきた。", "target_word": "室温", "complexity_tier": "T3", "furigana": "暖房[だんぼう]をつけたら、室温[しつおん]がゆっくり上[あ]がってきた。", "sentence_source": "generated"}, {"text": "赤ちゃんが寝ている部屋は、室温に気をつけている。", "target_word": "室温", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが寝[ね]ている部屋[へや]は、室温[しつおん]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "部屋に温度計を置いて、室温をいつも確かめている。", "target_word": "室温", "complexity_tier": "T3", "furigana": "部屋[へや]に温度計[おんどけい]を置[お]いて、室温[しつおん]をいつも確[たし]かめている。", "sentence_source": "generated"}, {"text": "夏の夜は、室温が下がらなくてなかなか眠れない。", "target_word": "室温", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]は、室温[しつおん]が下[さ]がらなくてなかなか眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "エアコンのおかげで、室温はいつも快適だ。", "target_word": "室温", "complexity_tier": "T3", "furigana": "エアコンのおかげで、室温[しつおん]はいつも快適[かいてき]だ。", "sentence_source": "generated"}, {"text": "窓を閉めきって料理を続けたら、室温が上がって汗が出てきた。", "target_word": "室温", "complexity_tier": "T3", "furigana": "窓[まど]を閉[し]めきって料理[りょうり]を続[つづ]けたら、室温[しつおん]が上[あ]がって汗[あせ]が出[で]てきた。", "sentence_source": "generated"}, {"text": "教室の室温が低かったので、生徒たちはコートを着たまま授業を受けた。", "target_word": "室温", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の室温[しつおん]が低[ひく]かったので、生徒[せいと]たちはコートを着[き]たまま授業[じゅぎょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "猫は室温が下がると、ストーブの前に集まってくる。", "target_word": "室温", "complexity_tier": "T3", "furigana": "猫[ねこ]は室温[しつおん]が下[さ]がると、ストーブの前[まえ]に集[あつ]まってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "室温", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "部屋の中が暖かいか寒いかという感覚的な空気の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53367, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "室温", "is_correct": true, "explanation": "部屋の空気の温かさや冷たさを表す語で、冬に「低い」と続く文脈に合う。"}, {"text": "室内", "is_correct": false, "explanation": "「室内」は部屋の中の空間を指し、温度の高さや低さとしては「低い」と言えない。"}, {"text": "湯気", "is_correct": false, "explanation": "「湯気」は湯から立ち上る蒸気で、部屋全体の温かさの高低には使わない。"}, {"text": "廊下", "is_correct": false, "explanation": "「廊下」は通路の場所を指し、温度が低いとは言わないので文が成り立たない。"}], "explanations": {"室温": "部屋の空気の温かさや冷たさを表す語で、冬に「低い」と続く文脈に合う。", "室内": "「室内」は部屋の中の空間を指し、温度の高さや低さとしては「低い」と言えない。", "湯気": "「湯気」は湯から立ち上る蒸気で、部屋全体の温かさの高低には使わない。", "廊下": "「廊下」は通路の場所を指し、温度が低いとは言わないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "室温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の室温は三十度まで上がるでしょう。", "explanation": "ここは〈気温〉の意味。屋外の空気の温かさは気温と言う。室温は部屋の中の温度を指すので、天気予報の文には合わない。"}, {"text": "熱っぽいので、私の室温を測ったら三十八度あった。", "explanation": "ここは〈体温〉の意味。人の体の温かさは体温と言う。室温は部屋の空気の温度なので、人の体には使えない。"}, {"text": "畑の室温を測って、種をまく時期を決めた。", "explanation": "ここは〈地温〉の意味。土の温度は地温と言う。室温は部屋の中の空気の温度なので、畑の土には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53367, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室温", "is_correct": true, "explanation": "エアコンが整える部屋の空気の温度を表し、「いつも快適だ」と続けて自然に読める。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼け」は空の色の光景を指し、エアコンで快適にする対象ではないので文が通らない。"}, {"text": "足音", "is_correct": false, "explanation": "「足音」は歩く音を指し、エアコンのおかげで快適になるものではない。"}, {"text": "雷鳴", "is_correct": false, "explanation": "「雷鳴」は雷の音を指し、エアコンで快適になる対象ではないので合わない。"}], "explanations": {"室温": "エアコンが整える部屋の空気の温度を表し、「いつも快適だ」と続けて自然に読める。", "夕焼け": "「夕焼け」は空の色の光景を指し、エアコンで快適にする対象ではないので文が通らない。", "足音": "「足音」は歩く音を指し、エアコンのおかげで快適になるものではない。", "雷鳴": "「雷鳴」は雷の音を指し、エアコンで快適になる対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "室温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯の室温を確かめてから、赤ちゃんを入れた。", "explanation": "ここは〈温度〉の意味。お湯の温かさは温度と言う。室温は部屋の空気の温度を指すので、お湯には使えない。"}, {"text": "窓を開けると、室温が部屋に入ってきた。", "explanation": "ここは〈外気〉の意味。屋外の空気は外気と言う。室温は部屋の中の空気の状態を指すので、外から入る空気には使えない。"}, {"text": "室温は四十パーセントに保つのがよい。", "explanation": "ここは〈湿度〉の意味。空気中の水分の割合は湿度と言う。室温は温度を表す語で、パーセントの値とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53367, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に暖房を消したので、室温を急に下がってしまった。", "corrected_sentence": "夜中に暖房を消したので、室温が急に下がってしまった。", "error_description": "「下がる」は主語を「が」で示す自動詞。「室温を下がる」は誤りで、正しくは「室温が下がる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の午後は室温が高くので、扇風機をつけた。", "corrected_sentence": "夏の午後は室温が高いので、扇風機をつけた。", "error_description": "形容詞「高い」は「ので」の前で「高いので」と活用する。「高くので」は活用の誤りで、正しくは「高いので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
