INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "室内の空気の温度。部屋の暑さや寒さを表す数値。", "primary_collocate": null, "pronunciation": "しつおん", "ipa": "ɕitsɯoɴ", "syllable_count": 4, "sentences": [{"text": "今朝の室温は十八度で、思ったより寒かった。", "target_word": "室温", "complexity_tier": "T3", "furigana": "今朝[けさ]の室温[しつおん]は十八度[じゅうはちど]で、思[おも]ったより寒[さむ]かった。", "sentence_source": "generated"}, {"text": "室温は二十度から二十五度に保つよう決められている。", "target_word": "室温", "complexity_tier": "T3", "furigana": "室温[しつおん]は二十度[にじゅうど]から二十五度[にじゅうごど]に保[たも]つよう決[き]められている。", "sentence_source": "generated"}, {"text": "実験では、室温を一定にしてから薬を混ぜた。", "target_word": "室温", "complexity_tier": "T3", "furigana": "実験[じっけん]では、室温[しつおん]を一定[いってい]にしてから薬[くすり]を混[ま]ぜた。", "sentence_source": "generated"}, {"text": "室温が三十度を超えたら、警報が鳴る。", "target_word": "室温", "complexity_tier": "T3", "furigana": "室温[しつおん]が三十度[さんじゅうど]を超[こ]えたら、警報[けいほう]が鳴[な]る。", "sentence_source": "generated"}, {"text": "このパンは、室温で一時間置いてから焼いてください。", "target_word": "室温", "complexity_tier": "T3", "furigana": "このパンは、室温[しつおん]で一時間[いちじかん]置[お]いてから焼[や]いてください。", "sentence_source": "generated"}, {"text": "博物館では、作品を守るために室温を毎日記録している。", "target_word": "室温", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、作品[さくひん]を守[まも]るために室温[しつおん]を毎日[まいにち]記録[きろく]している。", "sentence_source": "generated"}, {"text": "ワインは室温が高いと味が変わるので、涼しい場所に保管する。", "target_word": "室温", "complexity_tier": "T3", "furigana": "ワインは室温[しつおん]が高[たか]いと味[あじ]が変[か]わるので、涼[すず]しい場所[ばしょ]に保管[ほかん]する。", "sentence_source": "generated"}, {"text": "医者は、患者の部屋の室温を二十二度に設定した。", "target_word": "室温", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、患者[かんじゃ]の部屋[へや]の室温[しつおん]を二十二度[にじゅうにど]に設定[せってい]した。", "sentence_source": "generated"}, {"text": "冷蔵庫から出した卵を、室温に戻してから使う。", "target_word": "室温", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]から出[だ]した卵[たまご]を、室温[しつおん]に戻[もど]してから使[つか]う。", "sentence_source": "generated"}, {"text": "室温のグラフを見ると、夜に大きく下がっているのが分かる。", "target_word": "室温", "complexity_tier": "T3", "furigana": "室温[しつおん]のグラフを見[み]ると、夜[よる]に大[おお]きく下[さ]がっているのが分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "室温", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "室内の空気の温度を度数で表した数値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "室温", "is_correct": true, "explanation": "室内の空気の温度を度数で表す語で、「十八度」という数値と寒さの文脈に合う。"}, {"text": "体温", "is_correct": false, "explanation": "「体温」は人の体の温度で、部屋の状態を十八度と述べる文には合わない。"}, {"text": "足音", "is_correct": false, "explanation": "「足音」は歩く音を指し、部屋の温度を数値で表す語ではない。"}, {"text": "氷点", "is_correct": false, "explanation": "「氷点」は水が凍る基準の温度で、今朝の室内の温度を表す語としては合わない。"}], "explanations": {"室温": "室内の空気の温度を度数で表す語で、「十八度」という数値と寒さの文脈に合う。", "体温": "「体温」は人の体の温度で、部屋の状態を十八度と述べる文には合わない。", "足音": "「足音」は歩く音を指し、部屋の温度を数値で表す語ではない。", "氷点": "「氷点」は水が凍る基準の温度で、今朝の室内の温度を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "室温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の室温は三十五度に達する見込みだ。", "explanation": "ここは〈気温〉の意味。屋外の空気の温度は気温と言う。室温は建物の中の空気の温度を指すので、天気の予報には合わない。"}, {"text": "熱っぽいので、自分の室温を測ったら三十八度だった。", "explanation": "ここは〈体温〉の意味。人の体の温かさは体温と言う。室温は部屋の空気の温度なので、人の体には使えない。"}, {"text": "土の室温が十度を下回ると、球根は動き出さない。", "explanation": "ここは〈地温〉の意味。土の温度は地温と言う。室温は室内の空気の温度なので、土には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室温", "is_correct": true, "explanation": "保管場所の温度を表し、ワインの味に関わる条件として自然に続く。"}, {"text": "音量", "is_correct": false, "explanation": "「音量」は音の大きさを表し、ワインの保管温度とは結びつかない。"}, {"text": "融点", "is_correct": false, "explanation": "「融点」は固体が溶け始める温度で、ワインの保管環境の話には当てはまらない。"}, {"text": "熱量", "is_correct": false, "explanation": "「熱量」は熱の総量を表し、温度の高さとは違うので、保管条件としての文が成り立たない。"}], "explanations": {"室温": "保管場所の温度を表し、ワインの味に関わる条件として自然に続く。", "音量": "「音量」は音の大きさを表し、ワインの保管温度とは結びつかない。", "融点": "「融点」は固体が溶け始める温度で、ワインの保管環境の話には当てはまらない。", "熱量": "「熱量」は熱の総量を表し、温度の高さとは違うので、保管条件としての文が成り立たない。"}, "sentence_index": 6, "correct_answer": "室温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の室温は八十パーセントもあって、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。空気中の水分の割合は湿度と言う。室温は温度を表す数値なので、パーセントで示す値ではない。"}, {"text": "オーブンの室温を百八十度に予熱する。", "explanation": "ここは〈温度〉の意味。機器の内部の熱さは温度と言う。室温は部屋の空気の温度を指すので、オーブンには使えない。"}, {"text": "この部屋は室温が暗すぎて、字が読めない。", "explanation": "ここは〈照度〉の意味。部屋の明るさは照度で表す。室温は空気の温度を指すので、明るさの話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に室温を二十度を切ったので、暖房を入れた。", "corrected_sentence": "夜中に室温が二十度を切ったので、暖房を入れた。", "error_description": "主語の「室温」には「が」を付ける。「室温を」は誤りで、正しくは「室温が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は、機械を守るため室温を二十五度に設置した。", "corrected_sentence": "工場は、機械を守るため室温を二十五度に設定した。", "error_description": "室温は数値として「設定」する。「設置」は機器などを据え付ける意味で、室温には使えない。正しくは「設定」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "運ぶ手段を表す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「を」が二つ並び、文が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「が」が二つ並び、文が成り立たない。"}, {"text": "は", "is_correct": false, "explanation": "「は」では主題になり、運ぶ先を示せない。"}], "correct_answer": "で", "explanations": {"で": "運ぶ手段を表す「で」。", "を": "「を」が二つ並び、文が崩れる。", "が": "「が」が二つ並び、文が成り立たない。", "は": "「は」では主題になり、運ぶ先を示せない。"}, "error_tags": {"を": "二重の格", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さな車です。人を乗せて走ります。荷物を積むこともできます。", "primary_collocate": null, "pronunciation": "ばん", "ipa": "vaɴ", "syllable_count": 2, "sentences": [{"text": "家族が多いので、父は七人乗りのヴァンを買った。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "家族[かぞく]が多[おお]いので、父[ちち]は七人乗[ななにんの]りのヴァンを買[か]った。", "sentence_source": "generated"}, {"text": "引っ越しの日、友達がヴァンで荷物を運んでくれた。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、友達[ともだち]がヴァンで荷物[にもつ]を運[はこ]んでくれた。", "sentence_source": "generated"}, {"text": "配達のヴァンが、毎朝八時に店の前へ荷物を届けに来る。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "配達[はいたつ]のヴァンが、毎朝[まいあさ]八時[はちじ]に店[みせ]の前[まえ]へ荷物[にもつ]を届[とど]けに来[く]る。", "sentence_source": "generated"}, {"text": "後ろの席をたたむと、ヴァンは大きな荷物も積める。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "後[うし]ろの席[せき]をたたむと、ヴァンは大[おお]きな荷物[にもつ]も積[つ]める。", "sentence_source": "generated"}, {"text": "私たちはキャンプに行くため、ヴァンに椅子とテントを積んだ。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "私[わたし]たちはキャンプに行[い]くため、ヴァンに椅子[いす]とテントを積[つ]んだ。", "sentence_source": "generated"}, {"text": "駅から遠い村では、ヴァンが小さなバスの代わりをしている。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "駅[えき]から遠[とお]い村[むら]では、ヴァンが小[ちい]さなバスの代[か]わりをしている。", "sentence_source": "generated"}, {"text": "音楽家たちはヴァンに楽器を積んで、次の町へ向かった。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "音楽家[おんがくか]たちはヴァンに楽器[がっき]を積[つ]んで、次[つぎ]の町[まち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "このヴァンは小さいが、大人五人が乗れる。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "このヴァンは小[ちい]さいが、大人[おとな]五人[ごにん]が乗[の]れる。", "sentence_source": "generated"}, {"text": "雨の日、母はヴァンで子どもたちを学校まで送った。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]、母[はは]はヴァンで子[こ]どもたちを学校[がっこう]まで送[おく]った。", "sentence_source": "generated"}, {"text": "運転手はヴァンのドアを開けて、お客さんを乗せた。", "target_word": "ヴァン", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]はヴァンのドアを開[あ]けて、お客[きゃく]さんを乗[の]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヴァン", "label": "基本形"}, {"form": "ヴァンの", "label": "連体形"}, {"form": "ヴァンで", "label": "格助詞つき"}], "register": "中立（普通体）", "sense_fingerprint": "人も荷物も運べる小型の箱形の車", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヴァン", "is_correct": true, "explanation": "七人乗りの箱形の車として、家族のために買う。"}, {"text": "自転車", "is_correct": false, "explanation": "一人乗りの乗り物で、七人乗りとは言わない。"}, {"text": "三輪車", "is_correct": false, "explanation": "大人が七人で乗る車ではない。"}, {"text": "電車", "is_correct": false, "explanation": "個人で買う乗り物ではなく、七人乗りとも言わない。"}], "explanations": {"ヴァン": "七人乗りの箱形の車として、家族のために買う。", "自転車": "一人乗りの乗り物で、七人乗りとは言わない。", "三輪車": "大人が七人で乗る車ではない。", "電車": "個人で買う乗り物ではなく、七人乗りとも言わない。"}, "sentence_index": 0, "correct_answer": "ヴァン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖の岸で、ヴァンを借りて水の上を進んだ。", "explanation": "ヴァンは陸を走る車で、水の上は進めないので、この文は成り立たない。"}, {"text": "ヴァンのかごに荷物を入れた。", "explanation": "かごは自転車の部品で、箱形の車であるヴァンには合わない。"}, {"text": "車夫は、ヴァンを引いて観光客を乗せた。", "explanation": "ヴァンは引いて走らせる乗り物ではないので、車夫が引く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヴァン", "is_correct": true, "explanation": "楽器を積んで移動する車として、音楽家が使う。"}, {"text": "花", "is_correct": false, "explanation": "楽器を積んで運ぶものではなく、移動の車にならない。"}, {"text": "砂", "is_correct": false, "explanation": "楽器を載せて移動する対象にならない。"}, {"text": "窓", "is_correct": false, "explanation": "楽器を積んで運ぶものではない。"}], "explanations": {"ヴァン": "楽器を積んで移動する車として、音楽家が使う。", "花": "楽器を積んで運ぶものではなく、移動の車にならない。", "砂": "楽器を載せて移動する対象にならない。", "窓": "楽器を積んで運ぶものではない。"}, "sentence_index": 6, "correct_answer": "ヴァン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ヴァンの翼を点検した。", "explanation": "ヴァンには翼がなく、空を飛ぶ乗り物には使わない。"}, {"text": "ヴァンの改札を通った。", "explanation": "改札は鉄道の設備で、ヴァンには使わない。"}, {"text": "ヴァンの手綱を握った。", "explanation": "手綱は馬を操る道具で、ヴァンには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は七人乗りのヴァンを会社へ行った。", "corrected_sentence": "父は七人乗りのヴァンで会社へ行った。", "error_description": "移動の手段は「で」で示す。「を」では「会社へ行った」の手段にならず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53375, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の雨の中、父はヴァンに子どもたちを駅まで送った。", "corrected_sentence": "夜の雨の中、父はヴァンで子どもたちを駅まで送った。", "error_description": "移動の手段は「で」で示す。「に」では、ヴァンが行き先になり、送る手段にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
