INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53377, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもよいにおいがする。", "primary_collocate": null, "pronunciation": "ほうじゅん", "ipa": "hoːdʑɯɴ", "syllable_count": 4, "sentences": [{"text": "このワインは、芳醇な香りがする。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "このワインは、芳醇[ほうじゅん]な香[かお]りがする。", "sentence_source": "generated"}, {"text": "部屋に入ると、芳醇なコーヒーの香りが広がっていた。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "部屋[へや]に入[はい]ると、芳醇[ほうじゅん]なコーヒーの香[かお]りが広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "焼きたてのパンから芳醇な香りがして、おなかが鳴った。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンから芳醇[ほうじゅん]な香[かお]りがして、おなかが鳴[な]った。", "sentence_source": "generated"}, {"text": "春になると、庭の花から芳醇な香りがただよってくる。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "春[はる]になると、庭[にわ]の花[はな]から芳醇[ほうじゅん]な香[かお]りがただよってくる。", "sentence_source": "generated"}, {"text": "紅茶のふたを開けると、芳醇な香りが立ちのぼった。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "紅茶[こうちゃ]のふたを開[あ]けると、芳醇[ほうじゅん]な香[かお]りが立[た]ちのぼった。", "sentence_source": "generated"}, {"text": "熟したももは香りが芳醇で、店じゅうを満たしていた。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "熟[じゅく]したももは香[かお]りが芳醇[ほうじゅん]で、店[みせ]じゅうを満[み]たしていた。", "sentence_source": "generated"}, {"text": "古い木の樽から、芳醇な香りがしてきた。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の樽[たる]から、芳醇[ほうじゅん]な香[かお]りがしてきた。", "sentence_source": "generated"}, {"text": "台所から芳醇な香りがしたので、夕食が楽しみになった。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "台所[だいどころ]から芳醇[ほうじゅん]な香[かお]りがしたので、夕食[ゆうしょく]が楽[たの]しみになった。", "sentence_source": "generated"}, {"text": "このお酒は、開けた瞬間に芳醇な香りが鼻をくすぐる。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "このお酒[さけ]は、開[あ]けた瞬間[しゅんかん]に芳醇[ほうじゅん]な香[かお]りが鼻[はな]をくすぐる。", "sentence_source": "generated"}, {"text": "芳醇な香りにつられて、私は店の中に入った。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "芳醇[ほうじゅん]な香[かお]りにつられて、私[わたし]は店[みせ]の中[なか]に入[はい]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "芳醇", "label": "語幹"}, {"form": "芳醇な", "label": "連体形"}, {"form": "芳醇だ", "label": "終止形"}, {"form": "芳醇で", "label": "連用形"}], "register": "literary", "sense_fingerprint": "酒や食べ物などの香りが豊かでとてもよい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。香りが豊かでよいという意味の形状詞で、香りの説明に使える。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るく浮き立つ性格を表す。香りの説明には使わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫で壊れにくいことを表す。香りには当てはまらない。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は静かなことを表す。香りの豊かさを言う文脈には合わない。"}], "explanations": {"芳醇": "正解。香りが豊かでよいという意味の形状詞で、香りの説明に使える。", "陽気": "陽気は明るく浮き立つ性格を表す。香りの説明には使わない。", "頑丈": "頑丈は丈夫で壊れにくいことを表す。香りには当てはまらない。", "静粛": "静粛は静かなことを表す。香りの豊かさを言う文脈には合わない。"}, "sentence_index": 0, "correct_answer": "芳醇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕焼けが空を芳醇な赤に染めていた。", "explanation": "ここは〈色がはっきりしている〉の意味で、鮮やかが適切。芳醇は香りや味の豊かさにだけ使い、色には言わない。"}, {"text": "彼は芳醇な眠りに落ちた。", "explanation": "ここは〈深くしっかりしている〉の意味で、深いが適切。芳醇は香りや味にだけ使うので、眠りの深さには合わない。"}, {"text": "芳醇な朝日が部屋に差し込んだ。", "explanation": "ここは〈光が強くまぶしい〉の意味で、眩しいが適切。芳醇は香りや味にだけ使い、光には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。木の樽から香る豊かな香りを表す形状詞で、文の内容に合う。"}, {"text": "機敏", "is_correct": false, "explanation": "機敏は動きがすばやいことを表す。香りには使わない。"}, {"text": "豪快", "is_correct": false, "explanation": "豪快は大胆で勢いがあることを表す。香りの説明にはならない。"}, {"text": "頑健", "is_correct": false, "explanation": "頑健は体が丈夫なことを表す。香りには当てはまらない。"}], "explanations": {"芳醇": "正解。木の樽から香る豊かな香りを表す形状詞で、文の内容に合う。", "機敏": "機敏は動きがすばやいことを表す。香りには使わない。", "豪快": "豪快は大胆で勢いがあることを表す。香りの説明にはならない。", "頑健": "頑健は体が丈夫なことを表す。香りには当てはまらない。"}, "sentence_index": 6, "correct_answer": "芳醇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は芳醇で、持ち上げるのが大変だ。", "explanation": "ここは〈重い〉の意味で、重いが適切。芳醇は香りや味の豊かさを表し、物の重さには使わない。"}, {"text": "芳醇な教室で、先生の声が聞こえなかった。", "explanation": "ここは〈騒がしい〉の意味で、騒がしいが適切。芳醇は香りや味に使い、騒々しさには使わない。"}, {"text": "彼は芳醇な性格で、いつも人の輪の中心にいる。", "explanation": "ここは〈陽気〉の意味で、陽気が適切。芳醇は香りや味にだけ使うので、人の性格には言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この香水は芳醇の香りがする。", "corrected_sentence": "この香水は芳醇な香りがする。", "error_description": "形状詞の誤り。芳醇は形状詞なので名詞を修飾するときは〈な〉を付ける。〈の〉は使えない。正しくは〈芳醇な香り〉。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。文中の「芳醇な」の語幹にあたる形。"}, {"text": "芳醇だ", "is_correct": false, "explanation": "終止形。コーヒーの香りを修飾する位置には〈な〉が必要で、〈だ〉では文が切れる。"}, {"text": "芳醇で", "is_correct": false, "explanation": "連用形。中止の形で、名詞を修飾する位置には合わない。"}, {"text": "芳醇に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、香りを直接修飾できない。"}], "correct_form": "芳醇", "base_form": "芳醇", "form_label": "語幹", "sentence_index": 1, "explanations": {"芳醇": "正解。文中の「芳醇な」の語幹にあたる形。", "芳醇だ": "終止形。コーヒーの香りを修飾する位置には〈な〉が必要で、〈だ〉では文が切れる。", "芳醇で": "連用形。中止の形で、名詞を修飾する位置には合わない。", "芳醇に": "連用形。動詞や形容詞を修飾する形で、香りを直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この古酒は、寝かせるほどに芳醇くなる。", "corrected_sentence": "この古酒は、寝かせるほどに芳醇になる。", "error_description": "連用形の誤り。形状詞の芳醇は〈に〉で連用形を作る。〈く〉は形容詞用なので使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。文中の「芳醇な」の語幹にあたる形。"}, {"text": "芳醇だった", "is_correct": false, "explanation": "過去の終止形。「したので」と時制が重なり、香りを修飾する語形としては合わない。"}, {"text": "芳醇ではない", "is_correct": false, "explanation": "否定形。香りが豊かだという内容を打ち消す形で、文の意味に合わない。"}, {"text": "芳醇でした", "is_correct": false, "explanation": "丁寧な過去の形。普通体で書かれた文に合わず、香りを修飾する形としても不自然。"}], "correct_form": "芳醇", "base_form": "芳醇", "form_label": "語幹", "sentence_index": 7, "explanations": {"芳醇": "正解。文中の「芳醇な」の語幹にあたる形。", "芳醇だった": "過去の終止形。「したので」と時制が重なり、香りを修飾する語形としては合わない。", "芳醇ではない": "否定形。香りが豊かだという内容を打ち消す形で、文の意味に合わない。", "芳醇でした": "丁寧な過去の形。普通体で書かれた文に合わず、香りを修飾する形としても不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
