INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53378, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "においや味が深く、とてもよい。", "primary_collocate": null, "pronunciation": "ほうじゅん", "ipa": "hoːdʑɯɴ", "syllable_count": 4, "sentences": [{"text": "この赤ワインは、味わいが芳醇で、長く余韻が残る。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "この赤[あか]ワインは、味[あじ]わいが芳醇[ほうじゅん]で、長[なが]く余韻[よいん]が残[のこ]る。", "sentence_source": "generated"}, {"text": "時間をかけて熟成させたチーズは、芳醇な味がする。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "時間[じかん]をかけて熟成[じゅくせい]させたチーズは、芳醇[ほうじゅん]な味[あじ]がする。", "sentence_source": "generated"}, {"text": "彼は芳醇な日本酒を、ゆっくり味わっていた。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "彼[かれ]は芳醇[ほうじゅん]な日本酒[にほんしゅ]を、ゆっくり味[あじ]わっていた。", "sentence_source": "generated"}, {"text": "芳醇な香りとこくのあるスープに、客はみな満足した。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "芳醇[ほうじゅん]な香[かお]りとこくのあるスープに、客[きゃく]はみな満足[まんぞく]した。", "sentence_source": "generated"}, {"text": "この茶葉は、淹れるほどに芳醇な風味が出てくる。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "この茶葉[ちゃば]は、淹[い]れるほどに芳醇[ほうじゅん]な風味[ふうみ]が出[で]てくる。", "sentence_source": "generated"}, {"text": "芳醇なバターを使ったケーキは、口の中でとろけた。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "芳醇[ほうじゅん]なバターを使[つか]ったケーキは、口[くち]の中[なか]でとろけた。", "sentence_source": "generated"}, {"text": "樽で十年ねかせたウイスキーは、驚くほど芳醇だ。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "樽[たる]で十年[じゅうねん]ねかせたウイスキーは、驚[おどろ]くほど芳醇[ほうじゅん]だ。", "sentence_source": "generated"}, {"text": "味噌は、長く熟成させるほど芳醇になる。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "味噌[みそ]は、長[なが]く熟成[じゅくせい]させるほど芳醇[ほうじゅん]になる。", "sentence_source": "generated"}, {"text": "芳醇なソースが肉の味を引き立てている。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "芳醇[ほうじゅん]なソースが肉[にく]の味[あじ]を引[ひ]き立[た]てている。", "sentence_source": "generated"}, {"text": "秋の新酒は、軽やかでありながら芳醇な味わいだ。", "target_word": "芳醇", "complexity_tier": "T3", "furigana": "秋[あき]の新酒[しんしゅ]は、軽[かろ]やかでありながら芳醇[ほうじゅん]な味[あじ]わいだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "芳醇", "label": "語幹"}, {"form": "芳醇な", "label": "連体形"}, {"form": "芳醇だ", "label": "終止形"}, {"form": "芳醇に", "label": "連用形"}], "register": "literary", "sense_fingerprint": "熟成した酒や食べ物の香りと味に深みがある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。味が深く豊かでよいという意味の形状詞で、味わいの説明に使える。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るく浮き立つ性格を表す。味わいには使わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫で壊れにくいことを表す。味わいの説明にはならない。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は静かなことを表す。味わいの評価には当てはまらない。"}], "explanations": {"芳醇": "正解。味が深く豊かでよいという意味の形状詞で、味わいの説明に使える。", "陽気": "陽気は明るく浮き立つ性格を表す。味わいには使わない。", "頑丈": "頑丈は丈夫で壊れにくいことを表す。味わいの説明にはならない。", "静粛": "静粛は静かなことを表す。味わいの評価には当てはまらない。"}, "sentence_index": 0, "correct_answer": "芳醇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "芳醇な痛みが朝から続いている。", "explanation": "ここは〈感覚がはっきりしない〉の意味で、鈍いが適切。芳醇は味や香りの豊かさを表し、痛みには使わない。"}, {"text": "芳醇な石の床が、磨かれて光っている。", "explanation": "ここは〈硬い〉の意味で、硬いが適切。芳醇は味や香りに使う語で、石の硬さには当てはまらない。"}, {"text": "彼は芳醇な色の服を選んだ。", "explanation": "ここは〈派手〉の意味で、派手が適切。芳醇は味や香りに限られ、色の派手さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。熟成した香味が豊かで深いことを表す形状詞で、文の内容に合う。"}, {"text": "機敏", "is_correct": false, "explanation": "機敏は動きがすばやいことを表す。味わいの深さには当てはまらない。"}, {"text": "厚顔", "is_correct": false, "explanation": "厚顔は図々しいことを表す。酒の味には当てはまらない。"}, {"text": "寡黙", "is_correct": false, "explanation": "寡黙は口数が少ないことを表す。味の深さを表す文脈には合わない。"}], "explanations": {"芳醇": "正解。熟成した香味が豊かで深いことを表す形状詞で、文の内容に合う。", "機敏": "機敏は動きがすばやいことを表す。味わいの深さには当てはまらない。", "厚顔": "厚顔は図々しいことを表す。酒の味には当てはまらない。", "寡黙": "寡黙は口数が少ないことを表す。味の深さを表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "芳醇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "芳醇な桃色の花が庭に咲いた。", "explanation": "ここは〈色が淡い〉の意味で、淡いが適切。芳醇は香りや味の豊かさを表し、色の薄さには使わない。"}, {"text": "芳醇な値段で売られた。", "explanation": "ここは〈値段が高い〉の意味で、高いが適切。芳醇は味や香りを言う語で、値段には使えない。"}, {"text": "彼は芳醇な目をこすった。", "explanation": "ここは〈眠気がある〉の意味で、眠いが適切。芳醇は香味に限られ、目や眠気の状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この酒は、味わいが芳醇な。", "corrected_sentence": "この酒は、味わいが芳醇だ。", "error_description": "文末の誤り。芳醇は形状詞なので文末では〈だ〉を使う。〈な〉は連体形で、文を終えられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。文中の「芳醇な」の語幹にあたる形。"}, {"text": "芳醇だ", "is_correct": false, "explanation": "終止形。味を修飾する位置には〈な〉が必要で、〈だ〉では文が成り立たない。"}, {"text": "芳醇に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、味を直接修飾できない。"}, {"text": "芳醇で", "is_correct": false, "explanation": "連用形。中止の形で、味を修飾する位置には合わない。"}], "correct_form": "芳醇", "base_form": "芳醇", "form_label": "語幹", "sentence_index": 1, "explanations": {"芳醇": "正解。文中の「芳醇な」の語幹にあたる形。", "芳醇だ": "終止形。味を修飾する位置には〈な〉が必要で、〈だ〉では文が成り立たない。", "芳醇に": "連用形。動詞や形容詞を修飾する形で、味を直接修飾できない。", "芳醇で": "連用形。中止の形で、味を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このソースは、煮込むほどに芳醇くなる。", "corrected_sentence": "このソースは、煮込むほどに芳醇になる。", "error_description": "連用形の誤り。形状詞の芳醇は〈に〉で連用形を作る。〈く〉は形容詞用なので使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "芳醇", "is_correct": true, "explanation": "正解。文中の「芳醇な」の語幹にあたる形。"}, {"text": "芳醇だった", "is_correct": false, "explanation": "過去の終止形。「なる」と続く位置には合わず、現在の変化を述べる文の時制とも合わない。"}, {"text": "芳醇ではない", "is_correct": false, "explanation": "否定形。熟成で深まる味わいの肯定的な評価を打ち消すので、文の意味に合わない。"}, {"text": "芳醇でした", "is_correct": false, "explanation": "丁寧な過去の形。普通体の文に合わず、「なる」の前の語形としても合わない。"}], "correct_form": "芳醇", "base_form": "芳醇", "form_label": "語幹", "sentence_index": 7, "explanations": {"芳醇": "正解。文中の「芳醇な」の語幹にあたる形。", "芳醇だった": "過去の終止形。「なる」と続く位置には合わず、現在の変化を述べる文の時制とも合わない。", "芳醇ではない": "否定形。熟成で深まる味わいの肯定的な評価を打ち消すので、文の意味に合わない。", "芳醇でした": "丁寧な過去の形。普通体の文に合わず、「なる」の前の語形としても合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「細かい」の主語（状態の持ち主）を示す「が」。「網目が細かい」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「細かい」は状態を表す形容詞なので、目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「網目で細かい」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「網目と細かい」は文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「細かい」の主語（状態の持ち主）を示す「が」。「網目が細かい」で文が成り立つ。", "を": "「細かい」は状態を表す形容詞なので、目的語の「を」は取らない。", "で": "「で」は手段や場所を示すので、「網目で細かい」は成り立たない。", "と": "「と」は並列や相手を示すので、「網目と細かい」は文として不自然。"}, "error_tags": {"を": "対象", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「粗い」の主語（状態の持ち主）を示す「が」。「網目が粗い袋」で文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や着点を示すので、「網目に粗い」という状態の説明は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、状態を表す「粗い」の主語にはできない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「網目から粗い」は状態の説明にならない。"}], "correct_answer": "が", "explanations": {"が": "「粗い」の主語（状態の持ち主）を示す「が」。「網目が粗い袋」で文が成り立つ。", "に": "「に」は場所や着点を示すので、「網目に粗い」という状態の説明は成り立たない。", "へ": "「へ」は方向を示すので、状態を表す「粗い」の主語にはできない。", "から": "「から」は起点を示すので、「網目から粗い」は状態の説明にならない。"}, "error_tags": {"に": "着点・場所", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "線が横と縦に交わってできた、すだれのような形です。", "primary_collocate": null, "pronunciation": "あみめ", "ipa": "amime", "syllable_count": 3, "sentences": [{"text": "魚は、網目を通り抜けて逃げてしまった。", "target_word": "網目", "complexity_tier": "T3", "furigana": "魚[さかな]は、網目[あみめ]を通[とお]り抜[ぬ]けて逃[に]げてしまった。", "sentence_source": "generated"}, {"text": "虫かごの網目が細かいので、小さな虫は出られない。", "target_word": "網目", "complexity_tier": "T3", "furigana": "虫[むし]かごの網目[あみめ]が細[こま]かいので、小[ちい]さな虫[むし]は出[で]られない。", "sentence_source": "generated"}, {"text": "窓の網戸は網目が細かく、蚊が入ってこない。", "target_word": "網目", "complexity_tier": "T3", "furigana": "窓[まど]の網戸[あみど]は網目[あみめ]が細[こま]かく、蚊[か]が入[はい]ってこない。", "sentence_source": "generated"}, {"text": "漁師は、網目の大きさを変えて魚を選んで取る。", "target_word": "網目", "complexity_tier": "T3", "furigana": "漁師[りょうし]は、網目[あみめ]の大[おお]きさを変[か]えて魚[さかな]を選[えら]んで取[と]る。", "sentence_source": "generated"}, {"text": "地図の道路は網目のように、町じゅうに広がっている。", "target_word": "網目", "complexity_tier": "T3", "furigana": "地図[ちず]の道路[どうろ]は網目[あみめ]のように、町[まち]じゅうに広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "クモの巣の網目に、朝の水滴が光っていた。", "target_word": "網目", "complexity_tier": "T3", "furigana": "クモの巣[す]の網目[あみめ]に、朝[あさ]の水滴[すいてき]が光[ひか]っていた。", "sentence_source": "generated"}, {"text": "金網の網目から、犬が鼻を出してこちらを見ていた。", "target_word": "網目", "complexity_tier": "T3", "furigana": "金網[かなあみ]の網目[あみめ]から、犬[いぬ]が鼻[はな]を出[だ]してこちらを見[み]ていた。", "sentence_source": "generated"}, {"text": "網目が粗い袋に入れると、野菜がよく乾く。", "target_word": "網目", "complexity_tier": "T3", "furigana": "網目[あみめ]が粗[あら]い袋[ふくろ]に入[い]れると、野菜[やさい]がよく乾[かわ]く。", "sentence_source": "generated"}, {"text": "川の水は、細かい網目のふるいを通してから使う。", "target_word": "網目", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は、細[こま]かい網目[あみめ]のふるいを通[とお]してから使[つか]う。", "sentence_source": "generated"}, {"text": "古い魚網は、網目が切れて穴だらけだった。", "target_word": "網目", "complexity_tier": "T3", "furigana": "古[ふる]い魚網[ぎょもう]は、網目[あみめ]が切[き]れて穴[あな]だらけだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "網目", "label": "基本形"}], "register": "標準", "sense_fingerprint": "網の線が交わってできる小さな穴の並び", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "網目", "is_correct": true, "explanation": "網の線の間にできた隙間で、魚が通り抜けて逃げる文脈が成り立つ。"}, {"text": "壁", "is_correct": false, "explanation": "壁には隙間がなく、魚が通り抜ける対象にはならないので文脈に合わない。"}, {"text": "鉄板", "is_correct": false, "explanation": "鉄板は隙間のない板なので、魚が通り抜ける文脈に合わない。"}, {"text": "砂利", "is_correct": false, "explanation": "砂利は石の粒で、そこを通り抜けて魚が逃げる文脈にはならないので合わない。"}], "explanations": {"網目": "網の線の間にできた隙間で、魚が通り抜けて逃げる文脈が成り立つ。", "壁": "壁には隙間がなく、魚が通り抜ける対象にはならないので文脈に合わない。", "鉄板": "鉄板は隙間のない板なので、魚が通り抜ける文脈に合わない。", "砂利": "砂利は石の粒で、そこを通り抜けて魚が逃げる文脈にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "網目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "セーターの網目を一目ずつ数えながら編んだ。", "explanation": "ここは〈編み目〉の意味。編み物の一目は編み目で、網目は網の線の隙間なので合わない。"}, {"text": "子どもがボールで壁に網目を開けた。", "explanation": "ここは〈穴〉の意味。開けてできるのは穴で、網目は線が交わってできた格子状の模様なので合わない。"}, {"text": "船が網目を海に投げ入れて、魚を捕まえた。", "explanation": "ここは〈網〉の意味。海に投げ入れて魚を捕るのは網で、網目は線の隙間なので投げ入れられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "網目", "is_correct": true, "explanation": "金網の線の間にできた穴で、そこから犬が鼻を出せるという文脈が成り立つ。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は柔らかい土で、金網の一部にも穴にもならないので文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は金網の部品にはならず、隙間から鼻を出す文脈と合わないので誤り。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールは金網の部品にはならず、隙間から鼻を出す文脈と合わないので誤り。"}], "explanations": {"網目": "金網の線の間にできた穴で、そこから犬が鼻を出せるという文脈が成り立つ。", "粘土": "粘土は柔らかい土で、金網の一部にも穴にもならないので文脈に合わない。", "紙": "紙は金網の部品にはならず、隙間から鼻を出す文脈と合わないので誤り。", "段ボール": "段ボールは金網の部品にはならず、隙間から鼻を出す文脈と合わないので誤り。"}, "sentence_index": 6, "correct_answer": "網目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の夜は、網目を閉めて寝た。", "explanation": "ここは〈網戸〉の意味。網戸は閉めるものだが、網目は線の隙間で、閉めることはできないので合わない。"}, {"text": "雨の日は、網目を差して出かけた。", "explanation": "ここは〈傘〉の意味。傘は差すものだが、網目は差せないので合わない。"}, {"text": "強風で、網目が割れてしまった。", "explanation": "ここは〈窓ガラス〉の意味。窓ガラスは割れるものだが、網目は線の隙間なので割れて砕けることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この茶こしは網目が細かいくて、茶葉が落ちにくい。", "corrected_sentence": "この茶こしは網目が細かくて、茶葉が落ちにくい。", "error_description": "「細かい」は連用形（〜くて）で「細かく」になる。「細かいくて」は活用の誤り。正しくは「細かくて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53381, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "網目を細かいネットを選ぶと、虫が入りにくい。", "corrected_sentence": "網目が細かいネットを選ぶと、虫が入りにくい。", "error_description": "「細かい」の主語（状態の持ち主）は「が」で示す。「網目を」は誤り。正しくは「網目が細かい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
