INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「叡智を伝える」の伝える対象を示す格助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「子どもに」と重なり、「叡智に伝える」では伝える対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「叡智と伝える」は共同の相手を示すが、伝える内容としては不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「叡智へ伝える」は方向を示すが、知恵を伝える対象としては使わない。"}], "correct_answer": "を", "explanations": {"を": "「叡智を伝える」の伝える対象を示す格助詞で、文に合う。", "に": "「子どもに」と重なり、「叡智に伝える」では伝える対象を示せない。", "と": "「叡智と伝える」は共同の相手を示すが、伝える内容としては不自然。", "へ": "「叡智へ伝える」は方向を示すが、知恵を伝える対象としては使わない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "と": "共同・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもよく考えて、よいことを選ぶ力のことです。", "primary_collocate": null, "pronunciation": "えいち", "ipa": "eːtɕi", "syllable_count": 2, "sentences": [{"text": "先生は、子どもたちの叡智を信じて、考える時間をたくさん与えた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもたちの叡智[えいち]を信[しん]じて、考[かんが]える時間[じかん]をたくさん与[あた]えた。", "sentence_source": "generated"}, {"text": "村の長老は叡智のある人で、困った時はいつも皆が相談に行った。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "村[むら]の長老[ちょうろう]は叡智[えいち]のある人[ひと]で、困[こま]った時[とき]はいつも皆[みな]が相談[そうだん]に行[い]った。", "sentence_source": "generated"}, {"text": "この本には、昔の人の叡智がたくさん書かれている。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "この本[ほん]には、昔[むかし]の人[ひと]の叡智[えいち]がたくさん書[か]かれている。", "sentence_source": "generated"}, {"text": "叡智があれば、目の前の誘惑に負けず、よい道を選べるはずだ。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "叡智[えいち]があれば、目[め]の前[まえ]の誘惑[ゆうわく]に負[ま]けず、よい道[みち]を選[えら]べるはずだ。", "sentence_source": "generated"}, {"text": "彼は若いのに叡智があり、友達の悩みにも正しい答えを出す。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]いのに叡智[えいち]があり、友達[ともだち]の悩[なや]みにも正[ただ]しい答[こた]えを出[だ]す。", "sentence_source": "generated"}, {"text": "叡智とは、ただ物を知っていることではなく、よい選び方を知っていることだ。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "叡智[えいち]とは、ただ物[もの]を知[し]っていることではなく、よい選[えら]び方[かた]を知[し]っていることだ。", "sentence_source": "generated"}, {"text": "嵐の前に船を港に戻した船長の叡智が、全員の命を救った。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "嵐[あらし]の前[まえ]に船[ふね]を港[みなと]に戻[もど]した船長[せんちょう]の叡智[えいち]が、全員[ぜんいん]の命[いのち]を救[すく]った。", "sentence_source": "generated"}, {"text": "昔話には、子どもに叡智を伝える物語が多い。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "昔話[むかしばなし]には、子[こ]どもに叡智[えいち]を伝[つた]える物語[ものがたり]が多[おお]い。", "sentence_source": "generated"}, {"text": "経験が増えるにつれて、人は少しずつ叡智を身につけていく。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "経験[けいけん]が増[ふ]えるにつれて、人[ひと]は少[すこ]しずつ叡智[えいち]を身[み]につけていく。", "sentence_source": "generated"}, {"text": "王様は、叡智ある大臣の助言を聞いて、戦争をやめることにした。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "王様[おうさま]は、叡智[えいち]ある大臣[だいじん]の助言[じょげん]を聞[き]いて、戦争[せんそう]をやめることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叡智", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "よく考えて、よいことを選び取る力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叡智", "is_correct": true, "explanation": "本文の形。子どもたちが持つ、よく考えて選ぶ力を指し、信じる対象として文に合う。"}, {"text": "残高", "is_correct": false, "explanation": "預金などの金額を指す語で、「子どもたちの残高を信じて」は意味をなさない。"}, {"text": "運賃", "is_correct": false, "explanation": "乗り物の料金を指す語で、信じる対象にはならず文が成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを指す語で、「子どもたちの体重を信じて」は文脈に合わない。"}], "explanations": {"叡智": "本文の形。子どもたちが持つ、よく考えて選ぶ力を指し、信じる対象として文に合う。", "残高": "預金などの金額を指す語で、「子どもたちの残高を信じて」は意味をなさない。", "運賃": "乗り物の料金を指す語で、信じる対象にはならず文が成り立たない。", "体重": "体の重さを指す語で、「子どもたちの体重を信じて」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "叡智"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は叡智が多く、歴史の年号をすべて覚えている。", "explanation": "ここは〈知識〉の意味。叡智は深く考えて判断する力で、覚えている事実の量を言う語ではないので合わない。"}, {"text": "彼は叡智が強く、一日中走り続けられる。", "explanation": "ここは〈体力〉の意味。叡智は心の判断力で、体の強さや持久力には使わないので合わない。"}, {"text": "彼は叡智がよく、昔の出来事を正確に覚えている。", "explanation": "ここは〈記憶〉の意味。叡智は判断の深さを表し、出来事を覚えておく力は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叡智", "is_correct": true, "explanation": "本文の形。船長の判断力を指し、命を救った主語として文脈に合う。"}, {"text": "誤差", "is_correct": false, "explanation": "測定値と真の値のずれを指す語で、「船長の誤差が命を救った」は成り立たない。"}, {"text": "年金", "is_correct": false, "explanation": "老後の給付を指す語で、「船長の年金が命を救った」は文脈に合わない。"}, {"text": "時給", "is_correct": false, "explanation": "一時間ごとの賃金を指す語で、「船長の時給が命を救った」は意味をなさない。"}], "explanations": {"叡智": "本文の形。船長の判断力を指し、命を救った主語として文脈に合う。", "誤差": "測定値と真の値のずれを指す語で、「船長の誤差が命を救った」は成り立たない。", "年金": "老後の給付を指す語で、「船長の年金が命を救った」は文脈に合わない。", "時給": "一時間ごとの賃金を指す語で、「船長の時給が命を救った」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "叡智"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は叡智に長けていて、細かな手仕事では誰にも負けない。", "explanation": "ここは〈技量〉の意味。手仕事の腕前を指す語で、叡智は深く考えて判断する力なので合わない。"}, {"text": "祖父は叡智の数が多く、この畑で六十年働いてきた。", "explanation": "ここは〈経験〉の意味。積み重ねた体験の多さを表す語で、叡智の数という言い方はしないので合わない。"}, {"text": "彼は叡智が熱く、どんな課題にも挑み続ける。", "explanation": "ここは〈熱意〉の意味。やる気の強さを指す語で、叡智は冷静な判断力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "とっさの判断で叡智を働いた。", "corrected_sentence": "とっさの判断で叡智が働いた。", "error_description": "「働く」は「〜が働く」の形で主語を取る。「叡智を働いた」は誤りで、正しくは「叡智が働いた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叡智な長は、若い者の意見にも耳を傾けた。", "corrected_sentence": "叡智ある長は、若い者の意見にも耳を傾けた。", "error_description": "「叡智」は名詞なので「叡智ある〜」の形で連体修飾する。「叡智な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「叡智を集める」の集める対象を示す格助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「叡智に集める」は不自然。集める対象は「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「人々は」がすでにあるため、「叡智が集めて」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「叡智と集めて」は共同の相手を示すが、集める対象としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「叡智を集める」の集める対象を示す格助詞で、文に合う。", "に": "「叡智に集める」は不自然。集める対象は「を」で示す。", "が": "主語の「人々は」がすでにあるため、「叡智が集めて」では文が成り立たない。", "と": "「叡智と集めて」は共同の相手を示すが、集める対象としては成り立たない。"}, "error_tags": {"を": "対象", "に": "方向・帰着", "が": "主語", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
