INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "深く物事を考え、正しく判断する高い知恵や洞察力。", "primary_collocate": null, "pronunciation": "えいち", "ipa": "eːtɕi", "syllable_count": 3, "sentences": [{"text": "この一連の工程は、自然の摂理と人間の叡智が交差する、紛れもなく芸術的な創造物である。", "target_word": "叡智", "complexity_tier": "T4", "furigana": "この一連[いちれん]の工程[こうてい]は、自然[しぜん]の摂理[せつり]と人間[にんげん]の叡智[えいち]が交差[こうさ]する、紛[まぎ]れもなく芸術的[げいじゅつてき]な創造物[そうぞうぶつ]である。", "sentence_source": "mined"}, {"text": "長い歴史の中で、人々は叡智を集めて大きな困難を乗り越えてきた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "長[なが]い歴史[れきし]の中[なか]で、人々[ひとびと]は叡智[えいち]を集[あつ]めて大[おお]きな困難[こんなん]を乗[の]り越[こ]えてきた。", "sentence_source": "generated"}, {"text": "王は、国を治めるために、学者たちの叡智を求めた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "王[おう]は、国[くに]を治[おさ]めるために、学者[がくしゃ]たちの叡智[えいち]を求[もと]めた。", "sentence_source": "generated"}, {"text": "この図書館には、昔の人々の叡智が詰まっている。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "この図書館[としょかん]には、昔[むかし]の人々[ひとびと]の叡智[えいち]が詰[つ]まっている。", "sentence_source": "generated"}, {"text": "祖父は、八十年の経験から得た叡智で、家族の争いを静かに収めた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "祖父[そふ]は、八十年[はちじゅうねん]の経験[けいけん]から得[え]た叡智[えいち]で、家族[かぞく]の争[あらそ]いを静[しず]かに収[おさ]めた。", "sentence_source": "generated"}, {"text": "若い研究者は、先人の叡智に学びながら新しい理論を築いた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "若[わか]い研究者[けんきゅうしゃ]は、先人[せんじん]の叡智[えいち]に学[まな]びながら新[あたら]しい理論[りろん]を築[きず]いた。", "sentence_source": "generated"}, {"text": "環境問題の解決には、科学者だけでなく、市民の叡智も必要である。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]の解決[かいけつ]には、科学者[かがくしゃ]だけでなく、市民[しみん]の叡智[えいち]も必要[ひつよう]である。", "sentence_source": "generated"}, {"text": "彼女の叡智は、難しい交渉の場で皆を正しい結論へ導いた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の叡智[えいち]は、難[むずか]しい交渉[こうしょう]の場[ば]で皆[みな]を正[ただ]しい結論[けつろん]へ導[みちび]いた。", "sentence_source": "generated"}, {"text": "叡智ある指導者は、目先の利益よりも百年後の国の姿を考える。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "叡智[えいち]ある指導者[しどうしゃ]は、目先[めさき]の利益[りえき]よりも百年後[ひゃくねんご]の国[くに]の姿[すがた]を考[かんが]える。", "sentence_source": "generated"}, {"text": "古い寺の僧侶は、深い叡智を持つ人として村人に尊敬されていた。", "target_word": "叡智", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]の僧侶[そうりょ]は、深[ふか]い叡智[えいち]を持[も]つ人[ひと]として村人[むらびと]に尊敬[そんけい]されていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叡智", "label": "基本形"}], "register": "formal", "sense_fingerprint": "深い思考と正しい判断に基づく高度な知恵・洞察力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叡智", "is_correct": true, "explanation": "本文の形。「人間の叡智」は深く考えて正しく判断する力を表し、「交差する」の主語として成り立つ。"}, {"text": "時効", "is_correct": false, "explanation": "法律上の期間の満了を指す語で、「人間の時効が交差する」では意味が通らない。"}, {"text": "関税", "is_correct": false, "explanation": "輸入品に課す税金を指す語で、「人間の関税」は空欄に入らない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを指す語で、「人間の体重が交差する」は文脈に合わない。"}], "explanations": {"叡智": "本文の形。「人間の叡智」は深く考えて正しく判断する力を表し、「交差する」の主語として成り立つ。", "時効": "法律上の期間の満了を指す語で、「人間の時効が交差する」では意味が通らない。", "関税": "輸入品に課す税金を指す語で、「人間の関税」は空欄に入らない。", "体重": "体の重さを指す語で、「人間の体重が交差する」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "叡智"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は叡智が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。叡智は深く考えて正しく判断する力で、知っている事実の量は言わないので合わない。"}, {"text": "この子は叡智が速く、計算問題を一瞬で解いてしまう。", "explanation": "ここは〈処理速度〉の意味。叡智は時間をかけて深める判断力で、速さは言わない。"}, {"text": "彼は叡智が重く、荷物を運ぶ仕事で誰より力を出す。", "explanation": "ここは〈体力〉の意味。叡智は心の判断力で、体の力や重さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叡智", "is_correct": true, "explanation": "本文の形。「市民の叡智」は判断力や知恵の意味で、必要とされるものとして文に合う。"}, {"text": "時給", "is_correct": false, "explanation": "一時間ごとの賃金を指す語で、「市民の時給も必要である」は文脈上意味をなさない。"}, {"text": "誤差", "is_correct": false, "explanation": "測定値と真の値のずれを指す語で、「市民の誤差」は空欄に入らない。"}, {"text": "残高", "is_correct": false, "explanation": "預金などの金額を指す語で、「市民の残高も必要」は意味が通らない。"}], "explanations": {"叡智": "本文の形。「市民の叡智」は判断力や知恵の意味で、必要とされるものとして文に合う。", "時給": "一時間ごとの賃金を指す語で、「市民の時給も必要である」は文脈上意味をなさない。", "誤差": "測定値と真の値のずれを指す語で、「市民の誤差」は空欄に入らない。", "残高": "預金などの金額を指す語で、「市民の残高も必要」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "叡智"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は叡智が優れていて、大工仕事では誰よりも速い。", "explanation": "ここは〈技量〉の意味。手先の腕前や作業の速さは指すが、叡智は深く考えて判断する力なので合わない。"}, {"text": "祖父は叡智が長く、この畑で六十年働いてきた。", "explanation": "ここは〈経験〉の意味。積み重ねた年数の長さを表す語で、叡智の長さという言い方はしないので合わない。"}, {"text": "彼は叡智に恵まれ、どんな楽器も一週間で弾きこなす。", "explanation": "ここは〈才能〉の意味。生まれ持った素質を指す語で、叡智は後から深めた判断力を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は長年の経験で身につけた叡智に、息子に静かに伝えた。", "corrected_sentence": "父は長年の経験で身につけた叡智を、息子に静かに伝えた。", "error_description": "「伝える」は伝える内容を「〜を」で示す。「叡智に」は誤りで、正しくは「叡智を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53388, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叡智な王は、戦を避けて民の暮らしを守った。", "corrected_sentence": "叡智ある王は、戦を避けて民の暮らしを守った。", "error_description": "「叡智」は名詞なので「叡智ある〜」の形で連体修飾する。「叡智な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
