INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53413, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "温度が下がって、すごく寒くなります。水が氷になるくらい冷えます。", "primary_collocate": null, "pronunciation": "いてつく", "ipa": "itetsɯkɯ", "syllable_count": 4, "sentences": [{"text": "冬の夜は凍てつくほど寒くて、窓ガラスの内側まで白くなった。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]は凍[い]てつくほど寒[さむ]くて、窓[まど]ガラスの内側[うちがわ]まで白[しろ]くなった。", "sentence_source": "generated"}, {"text": "凍てつく風が吹いて、外に出た子どもたちは顔を赤くした。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "凍[い]てつく風[かぜ]が吹[ふ]いて、外[そと]に出[で]た子[こ]どもたちは顔[かお]を赤[あか]くした。", "sentence_source": "generated"}, {"text": "昨日の夜は気温が氷点下になり、道の水たまりが凍てついた。", "target_word": "凍てついた", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]は気温[きおん]が氷点下[ひょうてんか]になり、道[みち]の水[みず]たまりが凍[い]てついた。", "sentence_source": "generated"}, {"text": "朝になると、バケツの水が凍てついて、さわると石のようにかたかった。", "target_word": "凍てついて", "complexity_tier": "T3", "furigana": "朝[あさ]になると、バケツの水[みず]が凍[い]てついて、さわると石[いし]のようにかたかった。", "sentence_source": "generated"}, {"text": "山の上は凍てつく寒さなので、厚い服を何枚も着てください。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は凍[い]てつく寒[さむ]さなので、厚[あつ]い服[ふく]を何枚[なんまい]も着[き]てください。", "sentence_source": "generated"}, {"text": "池の水が凍てつく季節になると、散歩する人が少なくなる。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]が凍[い]てつく季節[きせつ]になると、散歩[さんぽ]する人[ひと]が少[すく]なくなる。", "sentence_source": "generated"}, {"text": "凍てついた窓を見て、祖母は今日は一段と寒いと言った。", "target_word": "凍てついた", "complexity_tier": "T3", "furigana": "凍[い]てついた窓[まど]を見[み]て、祖母[そぼ]は今日[きょう]は一段[いちだん]と寒[さむ]いと言[い]った。", "sentence_source": "generated"}, {"text": "雪の降る夜、凍てつく道を急いで駅まで歩いた。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "雪[ゆき]の降[ふ]る夜[よる]、凍[い]てつく道[みち]を急[いそ]いで駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "海の近くは風が冷たく、洗った洗濯物が外ですぐに凍てついた。", "target_word": "凍てついた", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くは風[かぜ]が冷[つめ]たく、洗[あら]った洗濯物[せんたくもの]が外[そと]ですぐに凍[い]てついた。", "sentence_source": "generated"}, {"text": "凍てつくような朝の空気を吸うと、頭がはっきりした。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "凍[い]てつくような朝[あさ]の空気[くうき]を吸[す]うと、頭[あたま]がはっきりした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凍てつく", "label": "終止形"}, {"form": "凍てつき", "label": "連用形"}, {"form": "凍てつか", "label": "未然形"}, {"form": "凍てつけ", "label": "仮定形"}, {"form": "凍てついた", "label": "タ形"}, {"form": "凍てついて", "label": "テ形"}], "register": "やや文語的", "sense_fingerprint": "凍てつく|水が氷になるほど気温が下がり、ひどく寒くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53413, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凍てつく", "is_correct": true, "explanation": "「凍てつくほど寒い」で、水が氷になるほどの寒さを表すので「凍てつく」。"}, {"text": "輝く", "is_correct": false, "explanation": "「輝くほど寒い」とは言わず、寒さの程度を表せない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠るほど寒い」は寒さの程度を表す言い方にならない。"}, {"text": "燃える", "is_correct": false, "explanation": "「燃えるほど寒い」は意味をなさず、文が成り立たない。"}], "explanations": {"凍てつく": "「凍てつくほど寒い」で、水が氷になるほどの寒さを表すので「凍てつく」。", "輝く": "「輝くほど寒い」とは言わず、寒さの程度を表せない。", "眠る": "「眠るほど寒い」は寒さの程度を表す言い方にならない。", "燃える": "「燃えるほど寒い」は意味をなさず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "凍てつく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんが静かに凍てついた。", "explanation": "ここは〈眠る〉の意味。凍てつくは寒さで水が固まるさまなので、人が眠る様子には合わない。"}, {"text": "お湯が凍てついて、湯気が立った。", "explanation": "ここは〈煮える〉の意味。熱で沸く現象を言うので、寒さで凍る凍てつくとは合わない。"}, {"text": "ろうそくが凍てついた。", "explanation": "ここは〈燃える〉の意味。凍てつくは寒さで凍ることなので、燃えるろうそくには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53413, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凍てついた", "is_correct": true, "explanation": "「凍てついた窓」と名詞を修飾する連体形（タ形）なので「凍てついた」。"}, {"text": "凍てつき", "is_correct": false, "explanation": "連用形では窓を修飾できず、「凍てつき窓」とはならない。"}, {"text": "凍てつか", "is_correct": false, "explanation": "未然形は名詞を修飾しないので、この位置に入らない。"}, {"text": "凍てつけ", "is_correct": false, "explanation": "命令・仮定形は名詞を修飾せず、文が成り立たない。"}], "explanations": {"凍てついた": "「凍てついた窓」と名詞を修飾する連体形（タ形）なので「凍てついた」。", "凍てつき": "連用形では窓を修飾できず、「凍てつき窓」とはならない。", "凍てつか": "未然形は名詞を修飾しないので、この位置に入らない。", "凍てつけ": "命令・仮定形は名詞を修飾せず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "凍てついた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちが凍てついて、笑いながら走り回った。", "explanation": "ここは〈はしゃぐ〉の意味（走り回る）。凍てつくは温度が下がって水が氷になるさまなので、人の動きには使わない。"}, {"text": "花が凍てついて、きれいに咲いた。", "explanation": "ここは〈咲く〉の意味。凍てつくは寒さで凍ることなので、花が咲く様子には使わない。"}, {"text": "彼はジュースを凍てついて飲んだ。", "explanation": "ここは〈飲む〉の意味。凍てつくは寒さで凍る状態を表すので、飲み物を飲む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53413, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の池は凍てつけて、鳥も寄りつかなかった。", "corrected_sentence": "夜の池は凍てついて、鳥も寄りつかなかった。", "error_description": "テ形は「凍てついて」。「凍てつけて」は仮定形からの誤った形で、活用を誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "凍てつく", "is_correct": true, "explanation": "連体形で、直後の「風」を修飾している。"}, {"text": "凍てつき", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「凍てつき風」とはならない。"}, {"text": "凍てつか", "is_correct": false, "explanation": "未然形の後に名詞は続かないので、「風」を修飾できない。"}, {"text": "凍てつけ", "is_correct": false, "explanation": "命令・仮定形は名詞を修飾しないので、この位置に入らない。"}], "correct_form": "凍てつく", "base_form": "凍てつく", "form_label": "連体形", "sentence_index": 1, "explanations": {"凍てつく": "連体形で、直後の「風」を修飾している。", "凍てつき": "連用形は名詞を直接修飾できず、「凍てつき風」とはならない。", "凍てつか": "未然形の後に名詞は続かないので、「風」を修飾できない。", "凍てつけ": "命令・仮定形は名詞を修飾しないので、この位置に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53413, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の降る朝、凍てつき道で転んでしまった。", "corrected_sentence": "雪の降る朝、凍てついた道で転んでしまった。", "error_description": "連体形（タ形）は「凍てついた」。「凍てつき」では道を修飾できず、活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "凍てつく", "is_correct": true, "explanation": "連体形で、直後の「道」を修飾している。"}, {"text": "凍てつけば", "is_correct": false, "explanation": "仮定形（ば）は後ろに名詞を直接続けられず、「凍てつけば道」とはならない。"}, {"text": "凍てついて", "is_correct": false, "explanation": "テ形は名詞を修飾できず、「凍てついて道」とはならない。"}, {"text": "凍てつかせて", "is_correct": false, "explanation": "使役のテ形は名詞を直接修飾できず、「凍てつかせて道」は成り立たない。"}], "correct_form": "凍てつく", "base_form": "凍てつく", "form_label": "連体形", "sentence_index": 7, "explanations": {"凍てつく": "連体形で、直後の「道」を修飾している。", "凍てつけば": "仮定形（ば）は後ろに名詞を直接続けられず、「凍てつけば道」とはならない。", "凍てついて": "テ形は名詞を修飾できず、「凍てついて道」とはならない。", "凍てつかせて": "使役のテ形は名詞を直接修飾できず、「凍てつかせて道」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
