INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53414, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "気温や水温が下がり、非常に冷えて固まること。また、そのように冷たい状態になるさま。", "primary_collocate": null, "pronunciation": "いてつく", "ipa": "itetsɯkɯ", "syllable_count": 4, "sentences": [{"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "凍てつか", "complexity_tier": "T3", "furigana": "凛[りん]とした寒気[かんき]が窓[まど]ガラスを伝[つた]い、室内[しつない]の空気[くうき]を凍[い]てつかせようとしている。", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "凍てつく", "complexity_tier": "T4", "furigana": "凍[い]てつく空気[くうき]の中[なか]、ボタンを一[ひと]つひとつ留[と]める仕草[しぐさ]には、未知[みち]の領域[りょういき]へ挑[いど]む戦士[せんし]のような厳粛[げんしゅく]ささえ漂[ただよ]っていた。", "sentence_source": "mined"}, {"text": "凍てつく朝、庭の池の水はすっかり固まり、鳥も近づかなかった。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "凍[い]てつく朝[あさ]、庭[にわ]の池[いけ]の水[みず]はすっかり固[かた]まり、鳥[とり]も近[ちか]づかなかった。", "sentence_source": "generated"}, {"text": "北国の冬は厳しく、凍てついた道を歩くときは足元に気をつけなければならない。", "target_word": "凍てついた", "complexity_tier": "T3", "furigana": "北国[きたぐに]の冬[ふゆ]は厳[きび]しく、凍[い]てついた道[みち]を歩[ある]くときは足元[あしもと]に気[き]をつけなければならない。", "sentence_source": "generated"}, {"text": "夜のうちに湖の水面が凍てつき、朝には厚い氷になっていた。", "target_word": "凍てつき", "complexity_tier": "T3", "furigana": "夜[よる]のうちに湖[みずうみ]の水面[すいめん]が凍[い]てつき、朝[あさ]には厚[あつ]い氷[こおり]になっていた。", "sentence_source": "generated"}, {"text": "凍てつくような寒さのなか、彼は手袋もせずに雪かきを続けた。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "凍[い]てつくような寒[さむ]さのなか、彼[かれ]は手袋[てぶくろ]もせずに雪[ゆき]かきを続[つづ]けた。", "sentence_source": "generated"}, {"text": "川が凍てついているので、釣りの客は一人もいなかった。", "target_word": "凍てついて", "complexity_tier": "T3", "furigana": "川[かわ]が凍[い]てついているので、釣[つ]りの客[きゃく]は一人[ひとり]もいなかった。", "sentence_source": "generated"}, {"text": "凍てついた大地に春の光が差し、ようやく雪が溶けはじめた。", "target_word": "凍てついた", "complexity_tier": "T3", "furigana": "凍[い]てついた大地[だいち]に春[はる]の光[ひかり]が差[さ]し、ようやく雪[ゆき]が溶[と]けはじめた。", "sentence_source": "generated"}, {"text": "風が強くなるにつれて、港の海水までも凍てつき始めた。", "target_word": "凍てつき", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くなるにつれて、港[みなと]の海水[かいすい]までも凍[い]てつき始[はじ]めた。", "sentence_source": "generated"}, {"text": "凍てつく夜空の下で、星だけがはっきりと光っていた。", "target_word": "凍てつく", "complexity_tier": "T3", "furigana": "凍[い]てつく夜空[よぞら]の下[した]で、星[ほし]だけがはっきりと光[ひか]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凍てつく", "label": "終止形"}, {"form": "凍てつき", "label": "連用形"}, {"form": "凍てつか", "label": "未然形"}, {"form": "凍てつけ", "label": "仮定形"}, {"form": "凍てついた", "label": "タ形"}, {"form": "凍てついて", "label": "テ形"}], "register": "やや文語的", "sense_fingerprint": "凍てつく|極寒で水などが凍って固まる、また凍るほど冷えきる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53414, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凍てつか", "is_correct": true, "explanation": "「空気を凍てつかせよう」の未然形＋せる（使役）なので「凍てつか」。"}, {"text": "凍てつき", "is_correct": false, "explanation": "連用形では「空気を凍てつき…せよう」と続けられず、使役の形にならない。"}, {"text": "凍てつけ", "is_correct": false, "explanation": "命令・仮定形では「凍てつけよう」と続かず、文が成り立たない。"}, {"text": "凍てついた", "is_correct": false, "explanation": "タ形では「凍てついたせよう」となり、使役の形にならない。"}], "explanations": {"凍てつか": "「空気を凍てつかせよう」の未然形＋せる（使役）なので「凍てつか」。", "凍てつき": "連用形では「空気を凍てつき…せよう」と続けられず、使役の形にならない。", "凍てつけ": "命令・仮定形では「凍てつけよう」と続かず、文が成り立たない。", "凍てついた": "タ形では「凍てついたせよう」となり、使役の形にならない。"}, "sentence_index": 0, "correct_answer": "凍てつか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パンがオーブンで凍てついて、黒く焦げた。", "explanation": "ここは〈焦げる〉の意味。凍てつくは極寒で冷え固まるさまなので、オーブンで焦げるパンには使わない。"}, {"text": "祖父はソファで凍てついて、いびきをかいていた。", "explanation": "ここは〈眠る〉の意味。凍てつくは寒さで冷え固まるさまなので、眠る人の様子には使わない。"}, {"text": "夏の日差しで、道路のアスファルトが凍てついた。", "explanation": "ここは〈熱くなる〉の意味。凍てつくは極寒で凍るさまなので、夏の日差しで熱くなる路面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53414, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凍てついて", "is_correct": true, "explanation": "「川が凍てついている」のテ形＋いる（継続）なので「凍てついて」。"}, {"text": "燃えて", "is_correct": false, "explanation": "「川が燃えている」は意味をなさず、寒さの文脈に合わない。"}, {"text": "澄んで", "is_correct": false, "explanation": "「川が澄んでいる」では釣り客がいない理由にならず、文脈に合わない。"}, {"text": "焦げて", "is_correct": false, "explanation": "「川が焦げている」は成立せず、文の内容に合わない。"}], "explanations": {"凍てついて": "「川が凍てついている」のテ形＋いる（継続）なので「凍てついて」。", "燃えて": "「川が燃えている」は意味をなさず、寒さの文脈に合わない。", "澄んで": "「川が澄んでいる」では釣り客がいない理由にならず、文脈に合わない。", "焦げて": "「川が焦げている」は成立せず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "凍てついて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は夕食を食べながら凍てついていた。", "explanation": "ここは〈食べる〉の意味（食べながら）。凍てつくは寒さで凍る状態を表すので、食事の動作には使わない。"}, {"text": "赤ちゃんが静かに凍てついていた。", "explanation": "ここは〈眠る〉の意味。凍てつくは寒さで凍るさまなので、人が眠る様子には使えない。"}, {"text": "薪が暖炉で凍てついていた。", "explanation": "ここは〈燃える〉の意味。凍てつくは寒さで凍ることなので、燃える薪には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53414, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の湖が凍てつくて、スケートはできなかった。", "corrected_sentence": "夜の湖が凍てついて、スケートはできなかった。", "error_description": "テ形は「凍てついて」。「凍てつくて」は活用を誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "凍てつく", "is_correct": true, "explanation": "連体形で、直後の「空気」を修飾している。"}, {"text": "凍てつき", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「凍てつき空気」とはならない。"}, {"text": "凍てつか", "is_correct": false, "explanation": "未然形の後に名詞は続かないので、「空気」を修飾できない。"}, {"text": "凍てつけ", "is_correct": false, "explanation": "命令・仮定形は名詞を修飾しないので、この位置に入らない。"}], "correct_form": "凍てつく", "base_form": "凍てつく", "form_label": "連体形", "sentence_index": 1, "explanations": {"凍てつく": "連体形で、直後の「空気」を修飾している。", "凍てつき": "連用形は名詞を直接修飾できず、「凍てつき空気」とはならない。", "凍てつか": "未然形の後に名詞は続かないので、「空気」を修飾できない。", "凍てつけ": "命令・仮定形は名詞を修飾しないので、この位置に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53414, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜のうちに池が凍てつくた。", "corrected_sentence": "夜のうちに池が凍てついた。", "error_description": "タ形は「凍てついた」。「凍てつくた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "凍てついた", "is_correct": true, "explanation": "タ形。過去の状態を表し、後ろの名詞「大地」を修飾する。"}, {"text": "凍てついて", "is_correct": false, "explanation": "テ形は名詞を修飾できず、「凍てついて大地」とはならない。"}, {"text": "凍てつこう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「凍てつこう大地」は成り立たない。"}, {"text": "凍てつかせて", "is_correct": false, "explanation": "使役のテ形は名詞を直接修飾できず、「凍てつかせて大地」は成り立たない。"}], "correct_form": "凍てついた", "base_form": "凍てつく", "form_label": "タ形", "sentence_index": 7, "explanations": {"凍てついた": "タ形。過去の状態を表し、後ろの名詞「大地」を修飾する。", "凍てついて": "テ形は名詞を修飾できず、「凍てついて大地」とはならない。", "凍てつこう": "意志形は名詞を修飾できず、「凍てつこう大地」は成り立たない。", "凍てつかせて": "使役のテ形は名詞を直接修飾できず、「凍てつかせて大地」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
