INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53415, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "子どものころであり、体や心がまだ小さく未熟なさま。おとなになる前の時期を言う。", "primary_collocate": null, "pronunciation": "おさなし", "ipa": "osanaɕi", "syllable_count": 4, "sentences": [{"text": "幼き頃、私は祖母の家で夏を過ごした。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き頃(ころ)、私(わたし)は祖母(そぼ)の家(いえ)で夏(なつ)を過(す)ごした。", "sentence_source": "generated"}, {"text": "幼き日の思い出は、今も心にあたたかく残っている。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き日(ひ)の思(おも)い出(で)は、今(いま)も心(こころ)にあたたかく残(のこ)っている。", "sentence_source": "generated"}, {"text": "幼き妹の手を引いて、兄は坂道をのぼった。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き妹(いもうと)の手(て)を引(ひ)いて、兄(あに)は坂道(さかみち)をのぼった。", "sentence_source": "generated"}, {"text": "幼くして父を亡くした彼は、母と二人で暮らした。", "target_word": "幼く", "complexity_tier": "T3", "furigana": "幼(おさな)くして父(ちち)を亡(な)くした彼(かれ)は、母(はは)と二人(ふたり)で暮(く)らした。", "sentence_source": "generated"}, {"text": "私はまだ幼く、世の中のことを何も知らなかった。", "target_word": "幼く", "complexity_tier": "T3", "furigana": "私(わたし)はまだ幼(おさな)く、世(よ)の中(なか)のことを何(なに)も知(し)らなかった。", "sentence_source": "generated"}, {"text": "幼き心にも、母の悲しみははっきりと伝わった。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き心(こころ)にも、母(はは)の悲(かな)しみははっきりと伝(つた)わった。", "sentence_source": "generated"}, {"text": "弟はなほ幼ければ、兄ぞ荷を持つ。", "target_word": "幼けれ", "complexity_tier": "T3", "furigana": "おとうとはなほおさなければ、あにぞにをもつ。", "sentence_source": "generated"}, {"text": "幼き子らの歌声が、夕暮れの野に響いた。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き子(こ)らの歌声(うたごえ)が、夕暮(ゆうぐ)れの野(の)に響(ひび)いた。", "sentence_source": "generated"}, {"text": "幼き時に覚えた歌は、年を取っても忘れない。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き時(とき)に覚(おぼ)えた歌(うた)は、年(とし)を取(と)っても忘(わす)れない。", "sentence_source": "generated"}, {"text": "幼く小さな体で、少女は重い桶を運んでいた。", "target_word": "幼く", "complexity_tier": "T3", "furigana": "幼(おさな)く小(ちい)さな体(からだ)で、少女(しょうじょ)は重(おも)い桶(おけ)を運(はこ)んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幼し", "label": "終止形"}, {"form": "幼き", "label": "連体形"}, {"form": "幼く", "label": "連用形"}, {"form": "幼けれ", "label": "已然形"}], "register": "文語", "sense_fingerprint": "幼し：子ども時代で、体も心もまだ小さい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53415, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「頃」を修飾する連体形で、「幼き頃」の形が自然。"}, {"text": "幼く", "is_correct": false, "explanation": "連用形で、名詞「頃」の前には置けない。"}, {"text": "幼し", "is_correct": false, "explanation": "終止形で言い切りになり、名詞を修飾できない。"}, {"text": "遠けれ", "is_correct": false, "explanation": "「遠し」の已然形で、「頃」にかからず意味が通らない。"}], "explanations": {"幼き": "名詞「頃」を修飾する連体形で、「幼き頃」の形が自然。", "幼く": "連用形で、名詞「頃」の前には置けない。", "幼し": "終止形で言い切りになり、名詞を修飾できない。", "遠けれ": "「遠し」の已然形で、「頃」にかからず意味が通らない。"}, "sentence_index": 0, "correct_answer": "幼き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建物は幼く、壁がまだきれいだ。", "explanation": "ここは〈新しい〉の意味。幼しは子どもや成長途中の生き物に使い、建物には合わない。"}, {"text": "祖父は八十歳で、今も幼く畑を耕している。", "explanation": "ここは〈元気だ〉の意味。幼しは成長しきっていない段階を表し、年配の人の様子には使わない。"}, {"text": "朝寝坊して、学校には幼く着いた。", "explanation": "ここは〈遅く〉の意味。幼しは成長の段階を表し、到着の時間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53415, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼けれ", "is_correct": true, "explanation": "已然形で「ば」に続き、弟が幼いという理由を表す。文の意味に合う。"}, {"text": "遠けれ", "is_correct": false, "explanation": "「遠し」の已然形だが、「弟はなほ遠ければ」では年齢や荷の文脈が成り立たない。"}, {"text": "高けれ", "is_correct": false, "explanation": "「高し」の已然形で、年齢の幼さを表さず意味が合わない。"}, {"text": "薄けれ", "is_correct": false, "explanation": "「薄し」の已然形だが、弟の年齢や荷物の文脈に合わず意味が通らない。"}], "explanations": {"幼けれ": "已然形で「ば」に続き、弟が幼いという理由を表す。文の意味に合う。", "遠けれ": "「遠し」の已然形だが、「弟はなほ遠ければ」では年齢や荷の文脈が成り立たない。", "高けれ": "「高し」の已然形で、年齢の幼さを表さず意味が合わない。", "薄けれ": "「薄し」の已然形だが、弟の年齢や荷物の文脈に合わず意味が通らない。"}, "sentence_index": 6, "correct_answer": "幼けれ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は幼く、片手で持てる。", "explanation": "ここは〈小さい〉の意味。幼しは子どもや未熟な生き物に使い、箱の大きさには合わない。"}, {"text": "昨夜は眠りが幼く、何度も目が覚めた。", "explanation": "ここは〈浅い〉の意味。幼しは成長の段階を表し、眠りの深さには使えない。"}, {"text": "その井戸は幼く、底が見えない。", "explanation": "ここは〈深い〉の意味。幼しは年や成長の段階を表し、井戸の深さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼けき日の夢は、今も私を導いている。", "corrected_sentence": "幼き日の夢は、今も私を導いている。", "error_description": "連体形は「幼き」で、「幼けき」という形はない。名詞「日」を修飾する「幼き」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「日」を修飾する連体形なので、「幼き日」になる。"}, {"text": "幼く", "is_correct": false, "explanation": "連用形で、後ろに用言が続く形。名詞「日」には直接かからない。"}, {"text": "幼し", "is_correct": false, "explanation": "終止形で言い切りの形。名詞を修飾できない。"}, {"text": "幼けれ", "is_correct": false, "explanation": "已然形で、「ば」などが続く形。名詞の前には使わない。"}], "correct_form": "幼き", "base_form": "幼し", "form_label": "連体形", "sentence_index": 1, "explanations": {"幼き": "名詞「日」を修飾する連体形なので、「幼き日」になる。", "幼く": "連用形で、後ろに用言が続く形。名詞「日」には直接かからない。", "幼し": "終止形で言い切りの形。名詞を修飾できない。", "幼けれ": "已然形で、「ば」などが続く形。名詞の前には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53415, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕暮れの野で、幼さ子らが歌った。", "corrected_sentence": "夕暮れの野で、幼き子らが歌った。", "error_description": "「幼さ」は名詞で、直接「子ら」を修飾できない。連体形の「幼き」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「子ら」を修飾する連体形なので、「幼き子ら」になる。"}, {"text": "幼から", "is_correct": false, "explanation": "未然形で、「ず」「む」などに続く形。名詞の前には置けない。"}, {"text": "幼かり", "is_correct": false, "explanation": "連用形の古い形で、「あり」などに続く。名詞を直接修飾しない。"}, {"text": "幼かれ", "is_correct": false, "explanation": "命令形で、名詞を修飾する働きはない。"}], "correct_form": "幼き", "base_form": "幼し", "form_label": "連体形", "sentence_index": 7, "explanations": {"幼き": "名詞「子ら」を修飾する連体形なので、「幼き子ら」になる。", "幼から": "未然形で、「ず」「む」などに続く形。名詞の前には置けない。", "幼かり": "連用形の古い形で、「あり」などに続く。名詞を直接修飾しない。", "幼かれ": "命令形で、名詞を修飾する働きはない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
