INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53416, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "年齢が若く、まだ成長しきっていないさま。特に子供や若い生物に対して使われる。文語的な表現である。", "primary_collocate": null, "pronunciation": "おさなし", "ipa": "osanaɕi", "syllable_count": 4, "sentences": [{"text": "幼き獣は、母の後ろをついて森の中を歩いた。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き獣(けもの)は、母(はは)の後(うし)ろをついて森(もり)の中(なか)を歩(ある)いた。", "sentence_source": "generated"}, {"text": "巣の中の幼き鳥は、まだ羽が生えそろっていない。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "巣(す)の中(なか)の幼(おさな)き鳥(とり)は、まだ羽(はね)が生(は)えそろっていない。", "sentence_source": "generated"}, {"text": "幼き王は、国を治めるには年が足りなかった。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き王(おう)は、国(くに)を治(おさ)めるには年(とし)が足(た)りなかった。", "sentence_source": "generated"}, {"text": "その木はまだ幼く、風が吹くたびに細い幹が揺れた。", "target_word": "幼く", "complexity_tier": "T3", "furigana": "その木(き)はまだ幼(おさな)く、風(かぜ)が吹(ふ)くたびに細(ほそ)い幹(みき)が揺(ゆ)れた。", "sentence_source": "generated"}, {"text": "幼き者を守るのが、大人の務めである。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き者(もの)を守(まも)るのが、大人(おとな)の務(つと)めである。", "sentence_source": "generated"}, {"text": "この子鹿はまだ幼し。母から離れれば生きられない。", "target_word": "幼し", "complexity_tier": "T3", "furigana": "この子鹿(こじか)はまだ幼(おさな)し。母(はは)から離(はな)れれば生(い)きられない。", "sentence_source": "generated"}, {"text": "幼き身で戦に出た少年を、人々は哀れんだ。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き身(み)で戦(いくさ)に出(で)た少年(しょうねん)を、人々(ひとびと)は哀(あわ)れんだ。", "sentence_source": "generated"}, {"text": "春になり、幼き芽が土の下から顔を出した。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "春(はる)になり、幼(おさな)き芽(め)が土(つち)の下(した)から顔(かお)を出(だ)した。", "sentence_source": "generated"}, {"text": "幼き姫は、ただ一人、城の庭で遊んでいた。", "target_word": "幼き", "complexity_tier": "T3", "furigana": "幼(おさな)き姫(ひめ)は、ただ一人(ひとり)、城(しろ)の庭(にわ)で遊(あそ)んでいた。", "sentence_source": "generated"}, {"text": "幼く無力な雛を、親鳥は命がけで守った。", "target_word": "幼く", "complexity_tier": "T3", "furigana": "幼(おさな)く無力(むりょく)な雛(ひな)を、親鳥(おやどり)は命(いのち)がけで守(まも)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幼し", "label": "終止形"}, {"form": "幼き", "label": "連体形"}, {"form": "幼く", "label": "連用形"}, {"form": "幼けれ", "label": "已然形"}], "register": "文語", "sense_fingerprint": "幼し：年が若く成長しきっていない子供や若い生物（文語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「獣」を修飾する連体形で、「幼き獣」が自然。"}, {"text": "幼く", "is_correct": false, "explanation": "連用形で、名詞「獣」の前には置けない。"}, {"text": "幼し", "is_correct": false, "explanation": "終止形で言い切りになり、名詞を修飾できない。"}, {"text": "幼けれ", "is_correct": false, "explanation": "已然形で「ば」が続く形なので、名詞の前には入らない。"}], "explanations": {"幼き": "名詞「獣」を修飾する連体形で、「幼き獣」が自然。", "幼く": "連用形で、名詞「獣」の前には置けない。", "幼し": "終止形で言い切りになり、名詞を修飾できない。", "幼けれ": "已然形で「ば」が続く形なので、名詞の前には入らない。"}, "sentence_index": 0, "correct_answer": "幼き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は幼く、片手で持てる。", "explanation": "ここは〈小さい〉の意味。幼しは成長の途中にある生き物や人に使い、箱の大きさには合わない。"}, {"text": "昨夜は眠りが幼く、何度も目が覚めた。", "explanation": "ここは〈浅い〉の意味。幼しは成長の段階を表し、眠りの深さには使わない。"}, {"text": "朝寝坊して、学校には幼く着いた。", "explanation": "ここは〈遅く〉の意味。幼しは成長の段階を表し、到着の時間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「身」を修飾する連体形で、「幼き身」の形が自然。"}, {"text": "遠き", "is_correct": false, "explanation": "「遠し」の連体形で、年齢の幼さを表さず意味が合わない。"}, {"text": "浅き", "is_correct": false, "explanation": "「浅し」の連体形だが、「浅き身で戦に出た少年」は年齢や身の状態の意味として成り立たない。"}, {"text": "黒き", "is_correct": false, "explanation": "「黒し」の連体形で、戦に出る年齢や身の状態を表さず意味が合わない。"}], "explanations": {"幼き": "名詞「身」を修飾する連体形で、「幼き身」の形が自然。", "遠き": "「遠し」の連体形で、年齢の幼さを表さず意味が合わない。", "浅き": "「浅し」の連体形だが、「浅き身で戦に出た少年」は年齢や身の状態の意味として成り立たない。", "黒き": "「黒し」の連体形で、戦に出る年齢や身の状態を表さず意味が合わない。"}, "sentence_index": 6, "correct_answer": "幼き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この建物は幼く、壁がまだきれいだ。", "explanation": "ここは〈新しい〉の意味。幼しは子どもや成長途中の生き物に使い、建物には合わない。"}, {"text": "祖父は八十歳で、今も幼く畑を耕している。", "explanation": "ここは〈元気だ〉の意味。幼しは成長しきっていない段階を表し、年配の人の様子には使わない。"}, {"text": "その井戸は幼く、底が見えない。", "explanation": "ここは〈深い〉の意味。幼しは年や成長の段階を表し、井戸の深さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼かり獣は、親のそばを離れられない。", "corrected_sentence": "幼き獣は、親のそばを離れられない。", "error_description": "名詞「獣」の前に置く形は連体形の「幼き」。「幼かり」は連用形の古い形で、名詞を修飾できないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「鳥」を修飾する連体形なので、「幼き鳥」になる。"}, {"text": "幼く", "is_correct": false, "explanation": "連用形で、後ろに用言が続く形。名詞「鳥」には直接かからない。"}, {"text": "幼し", "is_correct": false, "explanation": "終止形で言い切りの形。名詞を修飾できない。"}, {"text": "幼けれ", "is_correct": false, "explanation": "已然形で、「ば」などが続く形。名詞の前には使わない。"}], "correct_form": "幼き", "base_form": "幼し", "form_label": "連体形", "sentence_index": 1, "explanations": {"幼き": "名詞「鳥」を修飾する連体形なので、「幼き鳥」になる。", "幼く": "連用形で、後ろに用言が続く形。名詞「鳥」には直接かからない。", "幼し": "終止形で言い切りの形。名詞を修飾できない。", "幼けれ": "已然形で、「ば」などが続く形。名詞の前には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼さ子は、まだ一人で服も着られない。", "corrected_sentence": "幼き子は、まだ一人で服も着られない。", "error_description": "「幼さ」は名詞で、直接「子」を修飾できない。連体形の「幼き」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幼き", "is_correct": true, "explanation": "名詞「芽」を修飾する連体形なので、「幼き芽」になる。"}, {"text": "幼から", "is_correct": false, "explanation": "未然形で、「ず」「む」などに続く形。名詞の前には置けない。"}, {"text": "幼かり", "is_correct": false, "explanation": "連用形の古い形で、「あり」などに続く。名詞を直接修飾しない。"}, {"text": "幼かれ", "is_correct": false, "explanation": "命令形で、名詞を修飾する働きはない。"}], "correct_form": "幼き", "base_form": "幼し", "form_label": "連体形", "sentence_index": 7, "explanations": {"幼き": "名詞「芽」を修飾する連体形なので、「幼き芽」になる。", "幼から": "未然形で、「ず」「む」などに続く形。名詞の前には置けない。", "幼かり": "連用形の古い形で、「あり」などに続く。名詞を直接修飾しない。", "幼かれ": "命令形で、名詞を修飾する働きはない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『留めた』の目的語『シャツのボタン』に付く格助詞で、留める対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、ボタンが留める主体のように読めてしまい、目的語の役割に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、ボタンを留める動作の対象としては成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、ボタンと留める動作を正しく結びつけられない。"}], "correct_answer": "を", "explanations": {"を": "『留めた』の目的語『シャツのボタン』に付く格助詞で、留める対象を示す。正解。", "が": "主語を示すため、ボタンが留める主体のように読めてしまい、目的語の役割に合わない。", "へ": "方向を示すので、ボタンを留める動作の対象としては成り立たない。", "より": "比較を示すため、ボタンと留める動作を正しく結びつけられない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『留める』の目的語『ボタン』に付く格助詞で、留める対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「ボタンが留めるとき」は他動詞の目的語が主語になり成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すため、『ボタンと留める』では動作の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体や所有を示すため、『ボタンの留めるとき』では動作の対象と結びつかない。"}], "correct_answer": "を", "explanations": {"を": "『留める』の目的語『ボタン』に付く格助詞で、留める対象を示す。正解。", "が": "主語を示すため、「ボタンが留めるとき」は他動詞の目的語が主語になり成り立たない。", "と": "相手や並列を示すため、『ボタンと留める』では動作の対象を示せない。", "の": "連体や所有を示すため、『ボタンの留めるとき』では動作の対象と結びつかない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "服のボタンをつなぐことです。手でしっかり閉じます。", "primary_collocate": "ボタン", "pronunciation": "とめる", "ipa": "tomeɾɯ", "syllable_count": 3, "sentences": [{"text": "寒いので、コートのボタンを上まで留める。", "target_word": "留める", "complexity_tier": "T3", "furigana": "寒[さむ]いので、コートのボタンを上[うえ]まで留[と]める。", "sentence_source": "generated"}, {"text": "娘は朝、自分でシャツのボタンを留めた。", "target_word": "留めた", "complexity_tier": "T3", "furigana": "娘[むすめ]は朝[あさ]、自分[じぶん]でシャツのボタンを留[と]めた。", "sentence_source": "generated"}, {"text": "手がかじかんで、ボタンがうまく留められない。", "target_word": "留められない", "complexity_tier": "T3", "furigana": "手[て]がかじかんで、ボタンがうまく留[と]められない。", "sentence_source": "generated"}, {"text": "医者は、白衣のボタンを留めながら部屋に入ってきた。", "target_word": "留めながら", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、白衣[はくい]のボタンを留[と]めながら部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "出かける前に、ジャケットのボタンを留めてください。", "target_word": "留めて", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、ジャケットのボタンを留[と]めてください。", "sentence_source": "generated"}, {"text": "祖父のために、袖のボタンを留めてあげた。", "target_word": "留めてあげた", "complexity_tier": "T3", "furigana": "祖父[そふ]のために、袖[そで]のボタンを留[と]めてあげた。", "sentence_source": "generated"}, {"text": "急いでいたので、ボタンを一つずつ留める余裕がなかった。", "target_word": "留める", "complexity_tier": "T3", "furigana": "急[いそ]いでいたので、ボタンを一[ひと]つずつ留[と]める余裕[よゆう]がなかった。", "sentence_source": "generated"}, {"text": "ボタンを留めるとき、一つずつ穴に通す。", "target_word": "留める", "complexity_tier": "T3", "furigana": "ボタンを留[と]めるとき、一[ひと]つずつ穴[あな]に通[とお]す。", "sentence_source": "generated"}, {"text": "制服のボタンを最後まで留めて、式に出席した。", "target_word": "留めて", "complexity_tier": "T3", "furigana": "制服[せいふく]のボタンを最後[さいご]まで留[と]めて、式[しき]に出席[しゅっせき]した。", "sentence_source": "generated"}, {"text": "小さなボタンを留めるのに、五分もかかった。", "target_word": "留める", "complexity_tier": "T3", "furigana": "小[ちい]さなボタンを留[と]めるのに、五分[ごふん]もかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "留める", "label": "終止形"}, {"form": "留めた", "label": "過去形"}, {"form": "留めて", "label": "て形"}, {"form": "留めない", "label": "否定形"}, {"form": "留められる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "服のボタンを穴に通してつなぎ、閉じる(とめると読む)", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留める", "is_correct": true, "explanation": "「コートのボタンを上まで留める」で、ボタンを閉じる動作を表し文脈に合う。"}, {"text": "挑む", "is_correct": false, "explanation": "「挑む」は相手や困難に立ち向かう意味で、ボタンを上まで動かす文の動詞にはならない。"}, {"text": "凍らせる", "is_correct": false, "explanation": "「凍らせる」は物を冷やして固くする意味で、ボタンを上まで凍らせるという文は成り立たない。"}, {"text": "漂わせる", "is_correct": false, "explanation": "「漂わせる」は雰囲気や香りを広げる意味で、ボタンを対象にとるとこの文は意味をなさない。"}], "explanations": {"留める": "「コートのボタンを上まで留める」で、ボタンを閉じる動作を表し文脈に合う。", "挑む": "「挑む」は相手や困難に立ち向かう意味で、ボタンを上まで動かす文の動詞にはならない。", "凍らせる": "「凍らせる」は物を冷やして固くする意味で、ボタンを上まで凍らせるという文は成り立たない。", "漂わせる": "「漂わせる」は雰囲気や香りを広げる意味で、ボタンを対象にとるとこの文は意味をなさない。"}, "sentence_index": 0, "correct_answer": "留める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターに乗ったので、階数のボタンを留めた。", "explanation": "ここは〈押す〉の意味。『ボタンを押す』が自然で、『留める』は布などを固定する意味なので、階数ボタンの操作には使わない。"}, {"text": "ちょうど出かける時間になったので、ドアの鍵を留めた。", "explanation": "ここは〈施錠〉（かける）の意味。『鍵をかける』が自然で、『留める』は物を固定する意味なので、施錠の動作には使わない。"}, {"text": "お茶を淹れるため、急須に湯を留めた。", "explanation": "ここは〈注ぐ〉の意味。『湯を注ぐ』が自然で、『留める』は固定する意味なので液体を移す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留める", "is_correct": true, "explanation": "「ボタンを一つずつ留める余裕がなかった」で、ボタンを閉じる動作を表し文脈に合う。"}, {"text": "震わせる", "is_correct": false, "explanation": "「震わせる」は物を小刻みに揺らす意味で、ボタンを一つずつ震わせる余裕という文は成り立たない。"}, {"text": "噛む", "is_correct": false, "explanation": "「噛む」は歯で物を砕く動作で、ボタンを一つずつ噛む余裕という表現は意味をなさない。"}, {"text": "唱える", "is_correct": false, "explanation": "「唱える」は言葉や念仏を声に出す動詞で、ボタンを目的語にとれず、この文には合わない。"}], "explanations": {"留める": "「ボタンを一つずつ留める余裕がなかった」で、ボタンを閉じる動作を表し文脈に合う。", "震わせる": "「震わせる」は物を小刻みに揺らす意味で、ボタンを一つずつ震わせる余裕という文は成り立たない。", "噛む": "「噛む」は歯で物を砕く動作で、ボタンを一つずつ噛む余裕という表現は意味をなさない。", "唱える": "「唱える」は言葉や念仏を声に出す動詞で、ボタンを目的語にとれず、この文には合わない。"}, "sentence_index": 6, "correct_answer": "留める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "じゃがいもを留めて、ピーラーで皮を薄く剥いた。", "explanation": "ここは〈皮むき〉の意味。『皮をむく』が自然で、『留める』は固定する意味なので、じゃがいもの皮を取る動作には使わない。"}, {"text": "鍋のスープを、おたまで留めた。", "explanation": "ここは〈かき混ぜる〉の意味。『スープをかき混ぜる』が自然で、『留める』は固定する意味なので混ぜる動作には使わない。"}, {"text": "食器を留めて、水で洗った。", "explanation": "ここは〈洗浄〉の意味。食器の汚れを落とす動作に『留める』は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降ってきたので、ジャケットのボタンを留めるてから外に出た。", "corrected_sentence": "雨が降ってきたので、ジャケットのボタンを留めてから外に出た。", "error_description": "『留める』に『て』を続けるには『留めて』の形にする必要がある。『留めるて』は誤りで、『留めてから』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "留めた", "is_correct": true, "explanation": "過去形で、朝に娘が実際に留めた出来事を表し、文脈に合う。"}, {"text": "留めたり", "is_correct": false, "explanation": "「たり」形は文末で文が完結しないため成り立たない。"}, {"text": "留め", "is_correct": false, "explanation": "連用形のみで、文末に置くと文が終わらない。"}, {"text": "留めて", "is_correct": false, "explanation": "て形なので、文末に置くと文が終わらない。"}], "correct_form": "留めた", "base_form": "留める", "form_label": "過去形", "sentence_index": 1, "explanations": {"留めた": "過去形で、朝に娘が実際に留めた出来事を表し、文脈に合う。", "留めたり": "「たり」形は文末で文が完結しないため成り立たない。", "留め": "連用形のみで、文末に置くと文が終わらない。", "留めて": "て形なので、文末に置くと文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの袖のボタンを留めしてあげよう。", "corrected_sentence": "子どもの袖のボタンを留めてあげよう。", "error_description": "『留める』の連用形に『し』が付いている。て形の『留めて』が正しく、『留めしてあげよう』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "留める", "is_correct": true, "explanation": "連体形で、直後の『とき』に続けて『留めるとき』と時点を表す形。文に合う。"}, {"text": "留めれば", "is_correct": false, "explanation": "仮定形なので、「ボタンを留めれば」は条件を述べる形になり、「とき」に続けると文として成り立たない。"}, {"text": "留めます", "is_correct": false, "explanation": "丁寧形なので名詞を修飾できず、「とき」に続けると文として成り立たない。"}, {"text": "留めよう", "is_correct": false, "explanation": "意志形なので話し手の意図を表し、『留めようとき』とは続かず、動作の説明に合わない。"}], "correct_form": "留める", "base_form": "留める", "form_label": "連体形", "sentence_index": 7, "explanations": {"留める": "連体形で、直後の『とき』に続けて『留めるとき』と時点を表す形。文に合う。", "留めれば": "仮定形なので、「ボタンを留めれば」は条件を述べる形になり、「とき」に続けると文として成り立たない。", "留めます": "丁寧形なので名詞を修飾できず、「とき」に続けると文として成り立たない。", "留めよう": "意志形なので話し手の意図を表し、『留めようとき』とは続かず、動作の説明に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
