INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『留める』の目的語『ボタン』に付く格助詞で、他動詞の対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、ボタンが留める主体のように読めてしまい、目的語の役割に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、ボタンを留める動作の対象としては成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示すため、ボタンと留める動作を正しく結びつけられない。"}], "correct_answer": "を", "explanations": {"を": "『留める』の目的語『ボタン』に付く格助詞で、他動詞の対象を示す。正解。", "が": "主語を示すため、ボタンが留める主体のように読めてしまい、目的語の役割に合わない。", "へ": "方向を示すので、ボタンを留める動作の対象としては成り立たない。", "より": "比較や起点を示すため、ボタンと留める動作を正しく結びつけられない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物同士をつなぎ合わせたり、固定したりすることです。", "primary_collocate": null, "pronunciation": "とめる", "ipa": "tomeɾɯ", "syllable_count": 3, "sentences": [{"text": "強い風の日は、帽子をピンで留める。", "target_word": "留める", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]の日[ひ]は、帽子[ぼうし]をピンで留[と]める。", "sentence_source": "generated"}, {"text": "風が強いので、コートの前をしっかり留める。", "target_word": "留める", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、コートの前[まえ]をしっかり留[と]める。", "sentence_source": "generated"}, {"text": "母は私の髪をピンで留めてくれた。", "target_word": "留めてくれた", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の髪[かみ]をピンで留[と]めてくれた。", "sentence_source": "generated"}, {"text": "壁に地図を画鋲で留める作業を手伝った。", "target_word": "留める", "complexity_tier": "T3", "furigana": "壁[かべ]に地図[ちず]を画鋲[がびょう]で留[と]める作業[さぎょう]を手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "書類が散らばらないように、クリップで留める。", "target_word": "留める", "complexity_tier": "T3", "furigana": "書類[しょるい]が散[ち]らばらないように、クリップで留[と]める。", "sentence_source": "generated"}, {"text": "祖母はブローチをセーターの胸に留めた。", "target_word": "留めた", "complexity_tier": "T3", "furigana": "祖母[そぼ]はブローチをセーターの胸[むね]に留[と]めた。", "sentence_source": "generated"}, {"text": "緊張で手が震え、シャツの袖のボタンがなかなか留められなかった。", "target_word": "留められなかった", "complexity_tier": "T3", "furigana": "緊張[きんちょう]で手[て]が震[ふる]え、シャツの袖[そで]のボタンがなかなか留[と]められなかった。", "sentence_source": "generated"}, {"text": "子どもが自分でボタンを留めるのを、辛抱強く待った。", "target_word": "留める", "complexity_tier": "T3", "furigana": "子[こ]どもが自分[じぶん]でボタンを留[と]めるのを、辛抱強[しんぼうづよ]く待[ま]った。", "sentence_source": "generated"}, {"text": "資料はホチキスで留めてから提出してください。", "target_word": "留めて", "complexity_tier": "T3", "furigana": "資料[しりょう]はホチキスで留[と]めてから提出[ていしゅつ]してください。", "sentence_source": "generated"}, {"text": "風でカーテンが揺れないよう、端をテープで留めた。", "target_word": "留めた", "complexity_tier": "T3", "furigana": "風[かぜ]でカーテンが揺[ゆ]れないよう、端[はし]をテープで留[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "留める", "label": "終止形"}, {"form": "留めた", "label": "過去形"}, {"form": "留めて", "label": "て形"}, {"form": "留めない", "label": "否定形"}, {"form": "留められる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "ボタン・ピン・クリップなどで物を固定してつなぎとめる(とめると読む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T4: contains vocabulary far above tier T4: 散らばら (Zipf 1.31)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留める", "is_correct": true, "explanation": "「帽子をピンで留める」で、ピンで物を固定する動作を表し文脈に合う。"}, {"text": "挑む", "is_correct": false, "explanation": "相手や困難に立ち向かう意味で、帽子を目的語にとれない。"}, {"text": "凍らせる", "is_correct": false, "explanation": "物を冷やして固くする意味で、ピンで留める文脈には合わない。"}, {"text": "漂わせる", "is_correct": false, "explanation": "雰囲気や香りを広げる意味で、ピンで物を固定する文には合わない。"}], "explanations": {"留める": "「帽子をピンで留める」で、ピンで物を固定する動作を表し文脈に合う。", "挑む": "相手や困難に立ち向かう意味で、帽子を目的語にとれない。", "凍らせる": "物を冷やして固くする意味で、ピンで留める文脈には合わない。", "漂わせる": "雰囲気や香りを広げる意味で、ピンで物を固定する文には合わない。"}, "sentence_index": 0, "correct_answer": "留める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に、部屋の電気を留めた。", "explanation": "ここは〈消す〉の意味。『電気を消す』が自然で、『留める』は固定する意味なので照明の操作には使わない。"}, {"text": "散らかった机を留めて、きれいにした。", "explanation": "ここは〈整える〉の意味。『机を整える』が自然で、『留める』は固定する意味なので、散らかったものの整理には使わない。"}, {"text": "切れ味が落ちたので、台所で包丁を留めた。", "explanation": "ここは〈研ぐ〉の意味。『包丁を研ぐ』が自然で、『留める』は固定する意味なので刃物の手入れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留められなかった", "is_correct": true, "explanation": "可能形の否定過去で、「ボタンがなかなか〜」と文脈に合う。"}, {"text": "囁けなかった", "is_correct": false, "explanation": "「囁く」は人が小声で話す動詞で、ボタンを主語にすると意味が成り立たない。"}, {"text": "唱えられなかった", "is_correct": false, "explanation": "「唱える」は言葉や念仏を声に出す動詞で、ボタンが主語の文には合わない。"}, {"text": "叫べなかった", "is_correct": false, "explanation": "「叫ぶ」は大声を出す動詞で、ボタンを主語にすると文として意味をなさない。"}], "explanations": {"留められなかった": "可能形の否定過去で、「ボタンがなかなか〜」と文脈に合う。", "囁けなかった": "「囁く」は人が小声で話す動詞で、ボタンを主語にすると意味が成り立たない。", "唱えられなかった": "「唱える」は言葉や念仏を声に出す動詞で、ボタンが主語の文には合わない。", "叫べなかった": "「叫ぶ」は大声を出す動詞で、ボタンを主語にすると文として意味をなさない。"}, "sentence_index": 6, "correct_answer": "留められなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉が渇いたので、コップに水を留めた。", "explanation": "ここは〈注ぐ〉の意味。『水を注ぐ』が自然で、『留める』は物をつなぎ固定する意味なので液体には使わない。"}, {"text": "書きやすくするため、ナイフで鉛筆を留めた。", "explanation": "ここは〈削る〉の意味。『鉛筆を削る』が正しく、『留める』は固定する意味で削る動作には合わない。"}, {"text": "夏の飲み物に入れるため、氷を留めた。", "explanation": "ここは〈砕く〉の意味。『氷を砕く』が自然で、『留める』は固定する意味なので氷を割る動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒いので、コートの前を留めからお出かけしよう。", "corrected_sentence": "寒いので、コートの前を留めてからお出かけしよう。", "error_description": "『留める』のて形『留めて』の『て』が抜けている。『留めてから』（留めた後に）の形が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "留める", "is_correct": true, "explanation": "文末の終止形で、動作を述べて文を締める形。「風が強いので、〜留める。」の文に合う。"}, {"text": "留めたり", "is_correct": false, "explanation": "「たり」形は文末で文が完結しないため成り立たない。"}, {"text": "留め", "is_correct": false, "explanation": "連用形のみで、文末に置くと文が終わらない。"}, {"text": "留めて", "is_correct": false, "explanation": "て形なので、文末に置くと文が終わらない。"}], "correct_form": "留める", "base_form": "留める", "form_label": "終止形", "sentence_index": 1, "explanations": {"留める": "文末の終止形で、動作を述べて文を締める形。「風が強いので、〜留める。」の文に合う。", "留めたり": "「たり」形は文末で文が完結しないため成り立たない。", "留め": "連用形のみで、文末に置くと文が終わらない。", "留めて": "て形なので、文末に置くと文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボタンを留まるのを手伝ってくれて、ありがとう。", "corrected_sentence": "ボタンを留めるのを手伝ってくれて、ありがとう。", "error_description": "『留まる』は自動詞で『ボタンを』と取れない。目的語を取る他動詞の『留める』が正しく、『ボタンを留める』となる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "留める", "is_correct": true, "explanation": "連体形で、直後の『の』に続けて『留めるのを』と名詞句を作る形。文に合う。"}, {"text": "留めれば", "is_correct": false, "explanation": "仮定形なので、「留めればのを」のように名詞句を作れず、文として成り立たない。"}, {"text": "留めます", "is_correct": false, "explanation": "丁寧形なので名詞を修飾できず、「のを」に続けると文として成り立たない。"}, {"text": "留めよう", "is_correct": false, "explanation": "意志形なので話し手の意図を表し、『留めようのを』とは続かず、描写の文に合わない。"}], "correct_form": "留める", "base_form": "留める", "form_label": "連体形", "sentence_index": 7, "explanations": {"留める": "連体形で、直後の『の』に続けて『留めるのを』と名詞句を作る形。文に合う。", "留めれば": "仮定形なので、「留めればのを」のように名詞句を作れず、文として成り立たない。", "留めます": "丁寧形なので名詞を修飾できず、「のを」に続けると文として成り立たない。", "留めよう": "意志形なので話し手の意図を表し、『留めようのを』とは続かず、描写の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "根ざすが取る助詞で、「思い」を土台として示す。"}, {"text": "を", "is_correct": false, "explanation": "根ざすは目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表すので、土台を示す用法には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、土台を示す用法にはならない。"}], "correct_answer": "に", "explanations": {"に": "根ざすが取る助詞で、「思い」を土台として示す。", "を": "根ざすは目的語を取らない自動詞なので、「を」は合わない。", "と": "共同の相手を表すので、土台を示す用法には合わない。", "へ": "方向を表す助詞で、土台を示す用法にはならない。"}, "error_tags": {"を": "目的語の表示は誤り", "と": "共同の表示は誤り", "へ": "方向の表示は誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "根ざすが取る助詞で、「気持ち」を土台として示す。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す助詞で、土台を示す用法にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す助詞で、動詞に直接かかる形にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、土台を示す用法には合わない。"}], "correct_answer": "に", "explanations": {"に": "根ざすが取る助詞で、「気持ち」を土台として示す。", "で": "手段を表す助詞で、土台を示す用法にはならない。", "の": "連体を表す助詞で、動詞に直接かかる形にはならない。", "より": "比較を表す助詞で、土台を示す用法には合わない。"}, "error_tags": {"で": "手段の表示は誤り", "の": "連体修飾の表示は誤り", "より": "比較の表示は誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たしかな気持ちや経験などを土台として、それに基づいて行動したり物事が成り立ったりすること。", "primary_collocate": null, "pronunciation": "ねざす", "ipa": "nezasɯ", "syllable_count": 3, "sentences": [{"text": "自分の経験に根ざした話なので、聞く人の心に響く。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "自分(じぶん)の経験(けいけん)に根(ね)ざした話(はなし)なので、聞(き)く人(ひと)の心(こころ)に響(ひび)く。", "sentence_source": "generated"}, {"text": "彼女は子どもの頃の思いに根ざして、絵本作家になった。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は子(こ)どもの頃(ころ)の思(おも)いに根(ね)ざして、絵本作家(えほんさっか)になった。", "sentence_source": "generated"}, {"text": "強い願いに根ざした計画だから、途中で投げ出さない。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "強(つよ)い願(ねが)いに根(ね)ざした計画(けいかく)だから、途中(とちゅう)で投(な)げ出(だ)さない。", "sentence_source": "generated"}, {"text": "彼女は揺るぎない信念に根ざして、地域の子ども食堂を始めた。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "彼女は揺るぎない信念に根[ね]ざして、地域の子ども食堂を始めた。", "sentence_source": "generated"}, {"text": "祖母の教えに根ざす生き方を、私は大切にしている。", "target_word": "根ざす", "complexity_tier": "T3", "furigana": "祖母(そぼ)の教(おし)えに根(ね)ざす生(い)き方(かた)を、私(わたし)は大切(たいせつ)にしている。", "sentence_source": "generated"}, {"text": "失敗の経験に根ざして始めた事業が、少しずつ育っている。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "失敗(しっぱい)の経験(けいけん)に根(ね)ざして始(はじ)めた事業(じぎょう)が、少(すこ)しずつ育(そだ)っている。", "sentence_source": "generated"}, {"text": "長年の子育ての日々に根ざした助言は、とても心強い。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "長年(ながねん)の子育(こそだ)ての日々(ひび)に根(ね)ざした助言(じょげん)は、とても心強(こころづよ)い。", "sentence_source": "generated"}, {"text": "たしかな気持ちに根ざした行動は、簡単にはぶれない。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "たしかな気持(きも)ちに根(ね)ざした行動(こうどう)は、簡単(かんたん)にはぶれない。", "sentence_source": "generated"}, {"text": "彼は故郷への愛に根ざして、町の人のために店を開いた。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "彼(かれ)は故郷(こきょう)への愛(あい)に根(ね)ざして、町(まち)の人(ひと)のために店(みせ)を開(ひら)いた。", "sentence_source": "generated"}, {"text": "自分の体験に根ざした言葉だけを選んで、手紙を書いた。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "自分(じぶん)の体験(たいけん)に根(ね)ざした言葉(ことば)だけを選(えら)んで、手紙(てがみ)を書(か)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根ざす", "label": "終止形"}, {"form": "根ざし", "label": "連用形"}, {"form": "根ざした", "label": "タ形"}, {"form": "根ざして", "label": "テ形"}, {"form": "根ざさ", "label": "未然形"}], "register": "neutral", "sense_fingerprint": "たしかな気持ちや経験を出発点にして何かを始める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根ざした", "is_correct": true, "explanation": "「経験」を修飾するタ形で、「自分の経験に根ざした話」として正しい。"}, {"text": "根ざして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「根ざして話なので」は続かない。"}, {"text": "根ざし", "is_correct": false, "explanation": "連用形は名詞を修飾できず、「根ざし話」は成り立たない。"}, {"text": "根ざせ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、文が途切れてしまう。"}], "explanations": {"根ざした": "「経験」を修飾するタ形で、「自分の経験に根ざした話」として正しい。", "根ざして": "て形は名詞を修飾できず、「根ざして話なので」は続かない。", "根ざし": "連用形は名詞を修飾できず、「根ざし話」は成り立たない。", "根ざせ": "命令形は名詞を修飾できず、文が途切れてしまう。"}, "sentence_index": 0, "correct_answer": "根ざした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は、斜面の岩場に根ざして、長い年月を生き延びた。", "explanation": "ここは〈根を張る〉の意味。根ざすは植物が根を下ろす意味で、土台に基づく意味ではない。"}, {"text": "その会社の株価は、昨日の天候に根ざしている。", "explanation": "ここは〈左右される〉の意味。根ざすは土台に支えられて存在することを言うので、一日の天候で上下する株価には合わない。"}, {"text": "彼女は留学に根ざした。", "explanation": "ここは〈決意する〉の意味。根ざすは土台に支えられることを言うので、心を固めて決める瞬間を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根ざした", "is_correct": true, "explanation": "「助言」を修飾するタ形で、「長年の子育ての日々に根ざした助言」として正しい。"}, {"text": "根ざさ", "is_correct": false, "explanation": "未然形は名詞を修飾できず、「根ざさ助言」は成り立たない。"}, {"text": "根ざそう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「根ざそう助言は」は続かない。"}, {"text": "根ざしつつ", "is_correct": false, "explanation": "「〜つつ」は同時に続く動作を表す形で、名詞を修飾できず、「根ざしつつ助言は」は続かない。"}], "explanations": {"根ざした": "「助言」を修飾するタ形で、「長年の子育ての日々に根ざした助言」として正しい。", "根ざさ": "未然形は名詞を修飾できず、「根ざさ助言」は成り立たない。", "根ざそう": "意志形は名詞を修飾できず、「根ざそう助言は」は続かない。", "根ざしつつ": "「〜つつ」は同時に続く動作を表す形で、名詞を修飾できず、「根ざしつつ助言は」は続かない。"}, "sentence_index": 6, "correct_answer": "根ざした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この苗木は、痩せた土地にしっかり根ざして、翌年には花をつけた。", "explanation": "ここは〈根を張る〉の意味。植物が根を下ろす意味で、土台に基づく意味ではない。"}, {"text": "この機械の性能は、昨日の偶然に根ざしている。", "explanation": "ここは〈偶然で決まる〉の意味。根ざすは土台に支えられて続くことを言うので、偶然で決まる性能の説明には合わない。"}, {"text": "この店の売上は、昨日の気温に根ざした。", "explanation": "ここは〈影響される〉の意味。根ざすは長く続く土台に支えられることなので、一日の気温で変わる売上には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その言葉は、苦しい経験で根ざして生まれた。", "corrected_sentence": "その言葉は、苦しい経験に根ざして生まれた。", "error_description": "根ざすは「に」で土台を示すので、「で」は誤り。正しくは「に根ざして」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "根ざして", "is_correct": true, "explanation": "て形で「、絵本作家になった」と続ける正しい形。"}, {"text": "根ざした", "is_correct": false, "explanation": "タ形は文を言い切る形なので、「、」の後の「絵本作家になった」とつながらない。"}, {"text": "根ざす", "is_correct": false, "explanation": "終止形は「、」の前に置けず、続きがつながらない。"}, {"text": "根ざせ", "is_correct": false, "explanation": "命令形は文を言い切る形で、続きを作れない。"}], "correct_form": "根ざして", "base_form": "根ざす", "form_label": "テ形", "sentence_index": 1, "explanations": {"根ざして": "て形で「、絵本作家になった」と続ける正しい形。", "根ざした": "タ形は文を言い切る形なので、「、」の後の「絵本作家になった」とつながらない。", "根ざす": "終止形は「、」の前に置けず、続きがつながらない。", "根ざせ": "命令形は文を言い切る形で、続きを作れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53427, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい活動は、地域の人々の願いに根ざされて始まった。", "corrected_sentence": "新しい活動は、地域の人々の願いに根ざして始まった。", "error_description": "根ざすは受身にならないため、「根ざされて」は誤り。正しくは「根ざして」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "根ざした", "is_correct": true, "explanation": "「行動」を修飾するタ形で、「たしかな気持ちに根ざした行動」として正しい。"}, {"text": "根ざして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「根ざして行動は」は続かない。"}, {"text": "根ざし", "is_correct": false, "explanation": "連用形は名詞を修飾できず、文が成り立たない。"}, {"text": "根ざさ", "is_correct": false, "explanation": "未然形は名詞を修飾できず、「行動」に続かない。"}], "correct_form": "根ざした", "base_form": "根ざす", "form_label": "タ形", "sentence_index": 7, "explanations": {"根ざした": "「行動」を修飾するタ形で、「たしかな気持ちに根ざした行動」として正しい。", "根ざして": "て形は名詞を修飾できず、「根ざして行動は」は続かない。", "根ざし": "連用形は名詞を修飾できず、文が成り立たない。", "根ざさ": "未然形は名詞を修飾できず、「行動」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "根ざすが取る助詞で、「信仰」を土台として示す。"}, {"text": "を", "is_correct": false, "explanation": "根ざすは目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、土台を示す用法にはならない。"}, {"text": "と", "is_correct": false, "explanation": "共同や並列を表す助詞で、土台を示す用法には合わない。"}], "correct_answer": "に", "explanations": {"に": "根ざすが取る助詞で、「信仰」を土台として示す。", "を": "根ざすは目的語を取らない自動詞なので、「を」は合わない。", "へ": "方向を表す助詞で、土台を示す用法にはならない。", "と": "共同や並列を表す助詞で、土台を示す用法には合わない。"}, "error_tags": {"を": "目的語の表示は誤り", "へ": "方向の表示は誤り", "と": "共同の表示は誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "根ざすが取る助詞で、「暮らし」を土台として示す。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す助詞で、土台を示す用法にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す助詞で、動詞に直接かかる形にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、土台を示す用法には合わない。"}], "correct_answer": "に", "explanations": {"に": "根ざすが取る助詞で、「暮らし」を土台として示す。", "で": "手段を表す助詞で、土台を示す用法にはならない。", "の": "連体を表す助詞で、動詞に直接かかる形にはならない。", "より": "比較を表す助詞で、土台を示す用法には合わない。"}, "error_tags": {"で": "手段の表示は誤り", "の": "連体修飾の表示は誤り", "より": "比較の表示は誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事のはじまりや基盤となること。ある考え方や伝統、経験などを土台として、それに基づいて存在したり活動したりすること。", "primary_collocate": null, "pronunciation": "ねざす", "ipa": "nezasɯ", "syllable_count": 3, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "根ざした", "complexity_tier": "T5", "furigana": "ロボット工学(こうがく)の深淵(しんえん)を志(こころざ)す者(もの)がまず体現(たいげん)すべきは、DIYの精神(せいしん)に根(ね)ざした泥臭(どろくさ)い試行錯誤(しこうさくご)のプロセスに他(ほか)ならない。", "sentence_source": "mined"}, {"text": "この祭りは、地域の信仰に深く根ざしている。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "この祭(まつ)りは、地域(ちいき)の信仰(しんこう)に深(ふか)く根(ね)ざしている。", "sentence_source": "generated"}, {"text": "日本の食文化は、季節を大切にする考え方に根ざした伝統だ。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "日本(にほん)の食文化(しょくぶんか)は、季節(きせつ)を大切(たいせつ)にする考(かんが)え方(かた)に根(ね)ざした伝統(でんとう)だ。", "sentence_source": "generated"}, {"text": "彼の優しさは、幼いころの苦労に根ざしている。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "彼(かれ)の優(やさ)しさは、幼(おさな)いころの苦労(くろう)に根(ね)ざしている。", "sentence_source": "generated"}, {"text": "地域に根ざした活動を続けて、住民から信頼されるようになった。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "地域(ちいき)に根(ね)ざした活動(かつどう)を続(つづ)けて、住民(じゅうみん)から信頼(しんらい)されるようになった。", "sentence_source": "generated"}, {"text": "この法律は、人権を守るという理念に根ざしている。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "この法律(ほうりつ)は、人権(じんけん)を守(まも)るという理念(りねん)に根(ね)ざしている。", "sentence_source": "generated"}, {"text": "不信感は過去の裏切りに根ざしているため、簡単には消えない。", "target_word": "根ざして", "complexity_tier": "T3", "furigana": "不信感(ふしんかん)は過去(かこ)の裏切(うらぎ)りに根(ね)ざしているため、簡単(かんたん)には消(き)えない。", "sentence_source": "generated"}, {"text": "日常の暮らしに根ざした言葉は、教科書の言葉より力がある。", "target_word": "根ざした", "complexity_tier": "T3", "furigana": "日常(にちじょう)の暮(く)らしに根(ね)ざした言葉(ことば)は、教科書(きょうかしょ)の言葉(ことば)より力(ちから)がある。", "sentence_source": "generated"}, {"text": "伝統に根ざしつつ、新しい表現を探す若い職人が増えている。", "target_word": "根ざし", "complexity_tier": "T3", "furigana": "伝統(でんとう)に根(ね)ざしつつ、新(あたら)しい表現(ひょうげん)を探(さが)す若(わか)い職人(しょくにん)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "二国の対立は、歴史的な誤解に根ざしており、解決に時間がかかる。", "target_word": "根ざし", "complexity_tier": "T3", "furigana": "二国(にこく)の対立(たいりつ)は、歴史的(れきしてき)な誤解(ごかい)に根(ね)ざしており、解決(かいけつ)に時間(じかん)がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根ざす", "label": "終止形"}, {"form": "根ざし", "label": "連用形"}, {"form": "根ざした", "label": "タ形"}, {"form": "根ざして", "label": "テ形"}, {"form": "根ざさ", "label": "未然形"}], "register": "neutral", "sense_fingerprint": "伝統や考え方などを土台としてそれに基づく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根ざした", "is_correct": true, "explanation": "「泥臭い」を修飾する連体形で、「精神に根ざした試行錯誤」として正しく続く。"}, {"text": "根ざして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「根ざして泥臭い」の形で続かない。"}, {"text": "根ざそう", "is_correct": false, "explanation": "意志形は文を言い切る形で、後ろの名詞を修飾できない。"}, {"text": "根ざせ", "is_correct": false, "explanation": "命令形は文末にしか置けず、「精神に根ざせ泥臭い」は成り立たない。"}], "explanations": {"根ざした": "「泥臭い」を修飾する連体形で、「精神に根ざした試行錯誤」として正しく続く。", "根ざして": "て形は名詞を修飾できず、「根ざして泥臭い」の形で続かない。", "根ざそう": "意志形は文を言い切る形で、後ろの名詞を修飾できない。", "根ざせ": "命令形は文末にしか置けず、「精神に根ざせ泥臭い」は成り立たない。"}, "sentence_index": 0, "correct_answer": "根ざした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は山の斜面に深く根ざして、高く伸びている。", "explanation": "ここは〈根を張る〉の意味。植物が根を下ろす意味で、土台に基づく意味ではない。"}, {"text": "祖父は昨夜の夢に根ざして、急に旅に出た。", "explanation": "ここは〈夢に動かされる〉の意味。根ざすは長く続く土台に支えられることなので、一晩の夢で決まる行動には合わない。"}, {"text": "その会議は、昼食の雑談に根ざして決まった。", "explanation": "ここは〈雑談の流れで決まる〉の意味。根ざすは経験や考え方を土台にすることなので、その場の雑談で決まる結論には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根ざして", "is_correct": true, "explanation": "「根ざしている」の形で、「ため」に続く文として正しい。"}, {"text": "根ざし", "is_correct": false, "explanation": "連用形は「いる」に続かず、「根ざしいる」は成り立たない。"}, {"text": "根ざさ", "is_correct": false, "explanation": "未然形は「いる」に続かず、文が成り立たない。"}, {"text": "根ざせ", "is_correct": false, "explanation": "命令形は「いる」に続かず、文が途切れてしまう。"}], "explanations": {"根ざして": "「根ざしている」の形で、「ため」に続く文として正しい。", "根ざし": "連用形は「いる」に続かず、「根ざしいる」は成り立たない。", "根ざさ": "未然形は「いる」に続かず、文が成り立たない。", "根ざせ": "命令形は「いる」に続かず、文が途切れてしまう。"}, "sentence_index": 6, "correct_answer": "根ざして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この苗木は、乾いた土に根ざして、翌年には新芽を出した。", "explanation": "ここは〈根を張る〉の意味。植物が根を下ろす意味で、土台に基づく意味ではない。"}, {"text": "この祭りの名は、昨日の偶然の出来事に根ざしている。", "explanation": "ここは〈偶然から生まれる〉の意味。根ざすは土台に支えられて続くことを言うので、一日の偶然で生じた名前には合わない。"}, {"text": "その契約は、一度の口約束に根ざして交わされた。", "explanation": "ここは〈口約束で成立する〉の意味。根ざすは長く続く土台に支えられることなので、一度の口約束で成立する契約には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この伝統は、昔の人々の知恵を根ざして、今も受け継がれている。", "corrected_sentence": "この伝統は、昔の人々の知恵に根ざして、今も受け継がれている。", "error_description": "根ざすは「〜に根ざす」の形で土台を示す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "根ざして", "is_correct": true, "explanation": "「深く根ざしている」の形で、て形に「いる」が続く正しい形。"}, {"text": "根ざし", "is_correct": false, "explanation": "連用形は「いる」に直接続かず、「根ざしいる」は成り立たない。"}, {"text": "根ざさ", "is_correct": false, "explanation": "未然形は「ない」「う」などにしか続かず、「いる」とはつながらない。"}, {"text": "根ざせ", "is_correct": false, "explanation": "命令形は「いる」に続かず、文が成り立たない。"}], "correct_form": "根ざして", "base_form": "根ざす", "form_label": "テ形", "sentence_index": 1, "explanations": {"根ざして": "「深く根ざしている」の形で、て形に「いる」が続く正しい形。", "根ざし": "連用形は「いる」に直接続かず、「根ざしいる」は成り立たない。", "根ざさ": "未然形は「ない」「う」などにしか続かず、「いる」とはつながらない。", "根ざせ": "命令形は「いる」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53428, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画は、住民の声に根ざされて作られたものだ。", "corrected_sentence": "その計画は、住民の声に根ざして作られたものだ。", "error_description": "根ざすは自動詞で受身にならないため、「根ざされて」は誤り。正しくは「根ざして」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "根ざした", "is_correct": true, "explanation": "「暮らし」を含む言葉を修飾するタ形で、文の流れに合う。"}, {"text": "根ざそう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「根ざそう言葉は」は成り立たない。"}, {"text": "根ざしつつ", "is_correct": false, "explanation": "「〜つつ」は同時に続く動作を表す形で、名詞を修飾できず、「根ざしつつ言葉は」は続かない。"}, {"text": "根ざしながら", "is_correct": false, "explanation": "「〜ながら」は同時の動作を表す形で、名詞を修飾できず、「根ざしながら言葉は」は続かない。"}], "correct_form": "根ざした", "base_form": "根ざす", "form_label": "タ形", "sentence_index": 7, "explanations": {"根ざした": "「暮らし」を含む言葉を修飾するタ形で、文の流れに合う。", "根ざそう": "意志形は名詞を修飾できず、「根ざそう言葉は」は成り立たない。", "根ざしつつ": "「〜つつ」は同時に続く動作を表す形で、名詞を修飾できず、「根ざしつつ言葉は」は続かない。", "根ざしながら": "「〜ながら」は同時の動作を表す形で、名詞を修飾できず、「根ざしながら言葉は」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入っている」の主語にあたるので、「小さなアクチュエータが」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「入っている」は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示す。「小さなアクチュエータで入っている」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示す。「小さなアクチュエータと入っている」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「入っている」の主語にあたるので、「小さなアクチュエータが」が正しい。", "を": "「入っている」は目的語を取らない自動詞なので、「を」は合わない。", "で": "「で」は手段・場所を示す。「小さなアクチュエータで入っている」は不自然。", "と": "「と」は並列・共同を示す。「小さなアクチュエータと入っている」は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「動く」の主語にあたるので、「アクチュエータが動く仕組み」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「アクチュエータへ動く仕組み」は「動く」と結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や存在を示す。「アクチュエータに動く仕組み」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「アクチュエータより動く仕組み」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「動く」の主語にあたるので、「アクチュエータが動く仕組み」が正しい。", "へ": "「へ」は方向を示す。「アクチュエータへ動く仕組み」は「動く」と結びつかない。", "に": "「に」は着点や存在を示す。「アクチュエータに動く仕組み」は意味が通らない。", "より": "「より」は比較を示す。「アクチュエータより動く仕組み」では文が成り立たない。"}, "error_tags": {"へ": "方向", "に": "着点・存在", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電気や信号を受け取って、機械の部分を動かす装置です。おもちゃのロボットが手を動かすときにも使われています。", "primary_collocate": null, "pronunciation": "あくちゅえーた", "ipa": "akɯtɕɯeːta", "syllable_count": 6, "sentences": [{"text": "おもちゃのロボットが手を上げるのは、中のアクチュエータが動くからだ。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "おもちゃのロボットが手[て]を上[あ]げるのは、中[なか]のアクチュエータが動[うご]くからだ。", "sentence_source": "generated"}, {"text": "小さなアクチュエータが入っているので、このロボットは首を回せる。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "小[ちい]さなアクチュエータが入[はい]っているので、このロボットは首[くび]を回[まわ]せる。", "sentence_source": "generated"}, {"text": "電池を入れると、アクチュエータが動いてロボットの足が前に出る。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "電池[でんち]を入[い]れると、アクチュエータが動[うご]いてロボットの足[あし]が前[まえ]に出[で]る。", "sentence_source": "generated"}, {"text": "弟は壊れたおもちゃを開けて、アクチュエータを見つけた。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "弟[おとうと]は壊[こわ]れたおもちゃを開[あ]けて、アクチュエータを見[み]つけた。", "sentence_source": "generated"}, {"text": "夏休みの工作で、アクチュエータを使って動くロボットを作った。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの工作[こうさく]で、アクチュエータを使[つか]って動[うご]くロボットを作[つく]った。", "sentence_source": "generated"}, {"text": "このキットにはアクチュエータが二つ入っていて、両手を動かせる。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "このキットにはアクチュエータが二[ふた]つ入[はい]っていて、両手[りょうて]を動[うご]かせる。", "sentence_source": "generated"}, {"text": "アクチュエータが弱いと、ロボットは重い物を持ち上げられない。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "アクチュエータが弱[よわ]いと、ロボットは重[おも]い物[もの]を持[も]ち上[あ]げられない。", "sentence_source": "generated"}, {"text": "先生は、スイッチを入れるとアクチュエータが動く仕組みを説明した。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、スイッチを入[い]れるとアクチュエータが動[うご]く仕組[しく]みを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "兄のロボットは、アクチュエータを増やしたので、動きが細かくなった。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "兄[あに]のロボットは、アクチュエータを増[ふ]やしたので、動[うご]きが細[こま]かくなった。", "sentence_source": "generated"}, {"text": "ロボット教室では、アクチュエータの働きを実験で学ぶ。", "target_word": "アクチュエータ", "complexity_tier": "T3", "furigana": "ロボット教室[きょうしつ]では、アクチュエータの働[はたら]きを実験[じっけん]で学[まな]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクチュエータ", "label": "基本形"}, {"form": "アクチュエーター", "label": "長音つきの表記"}], "register": "ふつう", "sense_fingerprint": "電気を受けて機械の一部を動かす装置。おもちゃのロボットの手や首を動かす身近な部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクチュエータ", "is_correct": true, "explanation": "ロボットの中で実際に動く部品にあたるので、「中のアクチュエータが動く」に合う。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える部品で、中で動く部品ではないので「動く」と合わない。"}, {"text": "豆電球", "is_correct": false, "explanation": "豆電球は光る部品で、動く部品ではないので「動く」と合わない。"}, {"text": "基板", "is_correct": false, "explanation": "基板は回路を載せる板で、動かない部品なので「動く」と合わない。"}], "explanations": {"アクチュエータ": "ロボットの中で実際に動く部品にあたるので、「中のアクチュエータが動く」に合う。", "電池": "電池は電気を蓄える部品で、中で動く部品ではないので「動く」と合わない。", "豆電球": "豆電球は光る部品で、動く部品ではないので「動く」と合わない。", "基板": "基板は回路を載せる板で、動かない部品なので「動く」と合わない。"}, "sentence_index": 0, "correct_answer": "アクチュエータ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "おもちゃのロボットは、中のアクチュエータで障害物にぶつかったことを感じ取る。", "explanation": "ここは〈センサー〉の役割（ぶつかったことを感じ取る）。アクチュエータは信号を受けて動かす部品で、感じ取る働きはない。"}, {"text": "おもちゃのロボットは、胴体のアクチュエータから大きな音が流れる。", "explanation": "ここは〈スピーカー〉の意味（音を出す装置）。アクチュエータは部品を動かす機器で、音を出すことはない。"}, {"text": "ロボットの電源は、胴体のアクチュエータを押して入れる。", "explanation": "ここは〈スイッチ〉の役割（押して入り切りする）。アクチュエータは信号で部品を動かす機器なので、押して電源を入れる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクチュエータ", "is_correct": true, "explanation": "力を出して部品を動かす機器で、弱いと重い物を持ち上げられないという文に合う。"}, {"text": "ディスプレイ", "is_correct": false, "explanation": "映像を映す装置で、持ち上げる力の強さには関係しない。"}, {"text": "カメラ", "is_correct": false, "explanation": "映像を撮る装置で、持ち上げる力とは関係ない。"}, {"text": "照明", "is_correct": false, "explanation": "光を出す装置で、持ち上げる力の強さとは関係ない。"}], "explanations": {"アクチュエータ": "力を出して部品を動かす機器で、弱いと重い物を持ち上げられないという文に合う。", "ディスプレイ": "映像を映す装置で、持ち上げる力の強さには関係しない。", "カメラ": "映像を撮る装置で、持ち上げる力とは関係ない。", "照明": "光を出す装置で、持ち上げる力の強さとは関係ない。"}, "sentence_index": 6, "correct_answer": "アクチュエータ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロボット教室では、アクチュエータで食べ物を温める方法を学ぶ。", "explanation": "ここは〈電子レンジ〉の役割（食べ物を温める）。アクチュエータは部品を動かす機器で、温める働きはない。"}, {"text": "電流が大きすぎると、アクチュエータが切れて回路を守る。", "explanation": "ここは〈ヒューズ〉の役割（過電流で切れて回路を守る）。アクチュエータは信号を受けて部品を動かす機器で、回路を守るために切れる働きはない。"}, {"text": "ロボット教室では、アクチュエータをかわいい飾りにして身につける。", "explanation": "ここは〈アクセサリー〉（身につける飾り）の意味。アクチュエータは機械の部品で、身につける飾りの意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電池の電気をアクチュエータを流すと、部品が動く。", "corrected_sentence": "電池の電気をアクチュエータに流すと、部品が動く。", "error_description": "「流す」の行き先（着点）には「に」が要る。「アクチュエータを流す」は「を」になっていて誤り。正しくは「アクチュエータに流す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53429, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スイッチを入れると、アクチュエータが動きる。", "corrected_sentence": "スイッチを入れると、アクチュエータが動く。", "error_description": "「動く」は五段活用の動詞。「動きる」は活用の誤り。正しくは「動く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「くじに拠って」の「に」で、根拠や基準を示すので、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "対象（拠るは「〜に拠る」の形で根拠を示す）"}, {"text": "へ", "is_correct": false, "explanation": "方向（根拠を示す形にならない）"}, {"text": "から", "is_correct": false, "explanation": "起点（根拠を示す形にならない）"}], "correct_answer": "に", "explanations": {"に": "「くじに拠って」の「に」で、根拠や基準を示すので、ここに入る。", "を": "対象（拠るは「〜に拠る」の形で根拠を示す）", "へ": "方向（根拠を示す形にならない）", "から": "起点（根拠を示す形にならない）"}, "error_tags": {"を": "対象（拠るは「〜に拠る」の形で根拠を示す）", "へ": "方向（根拠を示す形にならない）", "から": "起点（根拠を示す形にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「感情に拠らず」の「に」で、根拠を示す「〜に拠る」の形になるので、ここに入る。"}, {"text": "で", "is_correct": false, "explanation": "手段（感情を根拠にする形にならない）"}, {"text": "と", "is_correct": false, "explanation": "並列（拠らずを修飾する形にならない）"}, {"text": "の", "is_correct": false, "explanation": "所属（拠らずを修飾できない）"}], "correct_answer": "に", "explanations": {"に": "「感情に拠らず」の「に」で、根拠を示す「〜に拠る」の形になるので、ここに入る。", "で": "手段（感情を根拠にする形にならない）", "と": "並列（拠らずを修飾する形にならない）", "の": "所属（拠らずを修飾できない）"}, "error_tags": {"で": "手段（感情を根拠にする形にならない）", "と": "並列（拠らずを修飾する形にならない）", "の": "所属（拠らずを修飾できない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ほかのものを使って、じぶんのことをきめること。", "primary_collocate": null, "pronunciation": "よる", "ipa": "joɾɯ", "syllable_count": 2, "sentences": [{"text": "私は自分の経験に拠って、進む道を決めました。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の経験[けいけん]に拠[よ]って、進[すす]む道[みち]を決[き]めました。", "sentence_source": "generated"}, {"text": "順番は、くじに拠って決めることにします。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "順番[じゅんばん]は、くじに拠[よ]って決[き]めることにします。", "sentence_source": "generated"}, {"text": "服装は、学校の規則に拠って決めてください。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "服装[ふくそう]は、学校[がっこう]の規則[きそく]に拠[よ]って決[き]めてください。", "sentence_source": "generated"}, {"text": "この店では、お客さんの声に拠って、メニューを決めています。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "この店[みせ]では、お客[きゃく]さんの声[こえ]に拠[よ]って、メニューを決[き]めています。", "sentence_source": "generated"}, {"text": "多数決に拠って、旅行の行き先を決めました。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "多数決[たすうけつ]に拠[よ]って、旅行[りょこう]の行[い]き先[さき]を決[き]めました。", "sentence_source": "generated"}, {"text": "医者は、検査の結果に拠って、薬を決めます。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、検査[けんさ]の結果[けっか]に拠[よ]って、薬[くすり]を決[き]めます。", "sentence_source": "generated"}, {"text": "新人の給料は、会社の規則に拠って決まります。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "新人[しんじん]の給料[きゅうりょう]は、会社[かいしゃ]の規則[きそく]に拠[よ]って決[き]まります。", "sentence_source": "generated"}, {"text": "彼女は感情に拠らず、事実だけで判断しました。", "target_word": "拠らず", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は感情[かんじょう]に拠[よ]らず、事実[じじつ]だけで判断[はんだん]しました。", "sentence_source": "generated"}, {"text": "試合の勝ち負けは、点数に拠って決めます。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "試合[しあい]の勝[か]ち負[ま]けは、点数[てんすう]に拠[よ]って決[き]めます。", "sentence_source": "generated"}, {"text": "先生は、テストの点に拠って、クラスを分けました。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "先生[せんせい]は、テストの点[てん]に拠[よ]って、クラスを分[わ]けました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拠る", "label": "辞書形"}, {"form": "拠らない", "label": "否定形"}, {"form": "拠ります", "label": "丁寧形"}, {"form": "拠って", "label": "て形"}, {"form": "拠った", "label": "た形"}, {"form": "拠れば", "label": "仮定形"}], "register": "formal (丁寧・書き言葉寄り)", "sense_fingerprint": "基準や方法に頼って物事を決める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拠って", "is_correct": true, "explanation": "経験をよりどころにして決める意味で、ここに入る語。"}, {"text": "離れて", "is_correct": false, "explanation": "経験から離れる意味になり、よりどころにして決める意味にはならない。"}, {"text": "届いて", "is_correct": false, "explanation": "経験に届くでは、決めるよりどころの意味にならないので合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "経験に眠るは意味が成り立たず、決めるよりどころにもならない。"}], "explanations": {"拠って": "経験をよりどころにして決める意味で、ここに入る語。", "離れて": "経験から離れる意味になり、よりどころにして決める意味にはならない。", "届いて": "経験に届くでは、決めるよりどころの意味にならないので合わない。", "眠って": "経験に眠るは意味が成り立たず、決めるよりどころにもならない。"}, "sentence_index": 0, "correct_answer": "拠って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "困ったときは、先生に拠って相談しました。", "explanation": "ここは〈頼る〉の意味。人に助けを求める場合は頼るを使い、拠るは合わない。"}, {"text": "駅の近くに拠って、コーヒーを買いました。", "explanation": "ここは〈寄る〉の意味。同じ読みの寄るは立ち寄る意味で、拠るは場所には使わない。"}, {"text": "壁に拠って、少し休みました。", "explanation": "ここは〈寄りかかる〉の意味。体を預ける動作は寄りかかるで、拠るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拠って", "is_correct": true, "explanation": "よりどころにして決める意味で、ここに入る語。"}, {"text": "参加して", "is_correct": false, "explanation": "規則に参加するでは、決められる根拠の意味にならず成り立たない。"}, {"text": "逃げて", "is_correct": false, "explanation": "規則に逃げるは意味が成り立たず、決めるよりどころにもならない。"}, {"text": "座って", "is_correct": false, "explanation": "規則に座るは意味が成り立たず、決めるよりどころにもならない。"}], "explanations": {"拠って": "よりどころにして決める意味で、ここに入る語。", "参加して": "規則に参加するでは、決められる根拠の意味にならず成り立たない。", "逃げて": "規則に逃げるは意味が成り立たず、決めるよりどころにもならない。", "座って": "規則に座るは意味が成り立たず、決めるよりどころにもならない。"}, "sentence_index": 6, "correct_answer": "拠って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バスに拠って、駅に行きました。", "explanation": "ここは〈乗る〉の意味。乗り物に乗る動作は乗るで、拠るは使わない。"}, {"text": "椅子に拠って、話を聞きました。", "explanation": "ここは〈座る〉の意味。腰を下ろす動作は座るで、拠るは合わない。"}, {"text": "ベッドに拠って、朝まで眠りました。", "explanation": "ここは〈寝る〉の意味。ベッドで体を横たえる動作は寝るで、根拠の拠るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の意見を拠って、答えを決めました。", "corrected_sentence": "先生の意見に拠って、答えを決めました。", "error_description": "正しくは「意見に拠って」。「拠る」は「〜に拠る」と「に」で根拠を示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拠って", "is_correct": true, "explanation": "て形。「拠る」は五段動詞なので、て形は「拠って」になる。"}, {"text": "拠った", "is_correct": false, "explanation": "た形で、「くじに」の後に「決めることにします」と続く文脈では合わない。"}, {"text": "拠ります", "is_correct": false, "explanation": "丁寧形で、文の途中に置くと文が切れてしまう。"}, {"text": "拠る", "is_correct": false, "explanation": "辞書形で、「くじに拠る決める」と続かない。"}], "correct_form": "拠って", "base_form": "拠る", "form_label": "て形", "sentence_index": 1, "explanations": {"拠って": "て形。「拠る」は五段動詞なので、て形は「拠って」になる。", "拠った": "た形で、「くじに」の後に「決めることにします」と続く文脈では合わない。", "拠ります": "丁寧形で、文の途中に置くと文が切れてしまう。", "拠る": "辞書形で、「くじに拠る決める」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53435, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "答えは、教科書の説明に拠れて決めました。", "corrected_sentence": "答えは、教科書の説明に拠って決めました。", "error_description": "正しくは「拠って」。「拠る」は五段動詞なので、て形は「拠って」になる。「拠れて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拠らず", "is_correct": true, "explanation": "「拠る」の未然形＋「ず」で「よりどころにせず」の意味になり、「、事実だけで」と続く。"}, {"text": "拠れ", "is_correct": false, "explanation": "命令形で「感情に拠れ」と言い切るので、「、事実だけで判断」と続かない。"}, {"text": "拠るな", "is_correct": false, "explanation": "禁止形で文を言い切るので、「、事実だけで判断」と続かない。"}, {"text": "拠ろう", "is_correct": false, "explanation": "意志形で「拠ることにしよう」の意味になり、過去の判断の文に続かない。"}], "correct_form": "拠らず", "base_form": "拠る", "form_label": "ず形", "sentence_index": 7, "explanations": {"拠らず": "「拠る」の未然形＋「ず」で「よりどころにせず」の意味になり、「、事実だけで」と続く。", "拠れ": "命令形で「感情に拠れ」と言い切るので、「、事実だけで判断」と続かない。", "拠るな": "禁止形で文を言い切るので、「、事実だけで判断」と続かない。", "拠ろう": "意志形で「拠ることにしよう」の意味になり、過去の判断の文に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「新聞に拠れば」などの「に」で、根拠を示すので、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "対象（拠るは「〜に拠る」の形で根拠を示す）"}, {"text": "で", "is_correct": false, "explanation": "手段・場所（根拠を示す形にならない）"}, {"text": "へ", "is_correct": false, "explanation": "方向（根拠を示すのではない）"}], "correct_answer": "に", "explanations": {"に": "「新聞に拠れば」などの「に」で、根拠を示すので、ここに入る。", "を": "対象（拠るは「〜に拠る」の形で根拠を示す）", "で": "手段・場所（根拠を示す形にならない）", "へ": "方向（根拠を示すのではない）"}, "error_tags": {"を": "対象（拠るは「〜に拠る」の形で根拠を示す）", "で": "手段・場所（根拠を示す形にならない）", "へ": "方向（根拠を示すのではない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「発表に拠れば」の「に」で、根拠を示すので、ここに入る。"}, {"text": "の", "is_correct": false, "explanation": "所属（拠る相手を示す形にならない）"}, {"text": "から", "is_correct": false, "explanation": "起点（根拠を示す形にならない）"}, {"text": "より", "is_correct": false, "explanation": "比較（比べる文ではない）"}], "correct_answer": "に", "explanations": {"に": "「発表に拠れば」の「に」で、根拠を示すので、ここに入る。", "の": "所属（拠る相手を示す形にならない）", "から": "起点（根拠を示す形にならない）", "より": "比較（比べる文ではない）"}, "error_tags": {"の": "所属（拠る相手を示す形にならない）", "から": "起点（根拠を示す形にならない）", "より": "比較（比べる文ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の根拠や原因として、ほかのものを使うこと。", "primary_collocate": null, "pronunciation": "よる", "ipa": "joɾɯ", "syllable_count": 2, "sentences": [{"text": "新聞に拠れば、明日は大雪になるそうです。", "target_word": "拠れば", "complexity_tier": "T3", "furigana": "新聞[しんぶん]に拠[よ]れば、明日[あした]は大雪[おおゆき]になるそうです。", "sentence_source": "generated"}, {"text": "調査に拠ると、若者の読書時間は減っています。", "target_word": "拠る", "complexity_tier": "T3", "furigana": "調査[ちょうさ]に拠[よ]ると、若者[わかもの]の読書[どくしょ]時間[じかん]は減[へ]っています。", "sentence_source": "generated"}, {"text": "この話は、本当にあった事件に拠っています。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "この話[はなし]は、本当[ほんとう]にあった事件[じけん]に拠[よ]っています。", "sentence_source": "generated"}, {"text": "彼の意見は古い資料に拠っているので、信頼できません。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は古[ふる]い資料[しりょう]に拠[よ]っているので、信頼[しんらい]できません。", "sentence_source": "generated"}, {"text": "先生の説明に拠れば、この問題には二つの原因があります。", "target_word": "拠れば", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]に拠[よ]れば、この問題[もんだい]には二[ふた]つの原因[げんいん]があります。", "sentence_source": "generated"}, {"text": "天気予報に拠ると、午後から雨が降ります。", "target_word": "拠る", "complexity_tier": "T3", "furigana": "天気[てんき]予報[よほう]に拠[よ]ると、午後[ごご]から雨[あめ]が降[ふ]ります。", "sentence_source": "generated"}, {"text": "この映画は、有名な小説に拠って作られました。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "この映画[えいが]は、有名[ゆうめい]な小説[しょうせつ]に拠[よ]って作[つく]られました。", "sentence_source": "generated"}, {"text": "警察の発表に拠れば、けが人はいなかったそうです。", "target_word": "拠れば", "complexity_tier": "T3", "furigana": "警察[けいさつ]の発表[はっぴょう]に拠[よ]れば、けが人[にん]はいなかったそうです。", "sentence_source": "generated"}, {"text": "研究者は、実験の結果に拠って、新しい説を出しました。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、実験[じっけん]の結果[けっか]に拠[よ]って、新[あたら]しい説[せつ]を出[だ]しました。", "sentence_source": "generated"}, {"text": "その報告は、確かな証拠に拠っていません。", "target_word": "拠って", "complexity_tier": "T3", "furigana": "その報告[ほうこく]は、確[たし]かな証拠[しょうこ]に拠[よ]っていません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拠る", "label": "辞書形"}, {"form": "拠らない", "label": "否定形"}, {"form": "拠ります", "label": "丁寧形"}, {"form": "拠って", "label": "て形"}, {"form": "拠った", "label": "た形"}, {"form": "拠れば", "label": "仮定形"}], "register": "formal (丁寧・書き言葉寄り)", "sense_fingerprint": "情報や資料を根拠にする（〜に拠れば）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拠れば", "is_correct": true, "explanation": "新聞を根拠にする仮定の形で、「〜に拠れば」と続く。"}, {"text": "眺めれば", "is_correct": false, "explanation": "眺めるは「新聞を眺める」の形で、「に」では根拠を示す文にならない。"}, {"text": "座れば", "is_correct": false, "explanation": "座るは場所に腰掛ける動作で、新聞を根拠にする意味にならない。"}, {"text": "眠れば", "is_correct": false, "explanation": "眠るは根拠の意味にならず、文が成り立たない。"}], "explanations": {"拠れば": "新聞を根拠にする仮定の形で、「〜に拠れば」と続く。", "眺めれば": "眺めるは「新聞を眺める」の形で、「に」では根拠を示す文にならない。", "座れば": "座るは場所に腰掛ける動作で、新聞を根拠にする意味にならない。", "眠れば": "眠るは根拠の意味にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "拠れば"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "帰りに、ちょっと駅に拠って買い物をしました。", "explanation": "ここは〈寄る〉の意味。同じ読みの寄るは立ち寄る意味で、拠るは場所には使わない。"}, {"text": "電車に拠って、東京へ行きました。", "explanation": "ここは〈乗る〉の意味。乗り物に乗る動作には乗るを使い、拠るは合わない。"}, {"text": "床に拠って、食事をしました。", "explanation": "ここは〈座る〉の意味。床に腰を下ろす動作は座るで、拠るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拠って", "is_correct": true, "explanation": "小説を元にして作る意味で、ここに入る語。"}, {"text": "届いて", "is_correct": false, "explanation": "小説に届くでは、元にして作るという意味にならない。"}, {"text": "休んで", "is_correct": false, "explanation": "小説に休んでは、元にして作る意味にならず成り立たない。"}, {"text": "抜けて", "is_correct": false, "explanation": "小説から抜けるは、元にする意味ではないので合わない。"}], "explanations": {"拠って": "小説を元にして作る意味で、ここに入る語。", "届いて": "小説に届くでは、元にして作るという意味にならない。", "休んで": "小説に休んでは、元にして作る意味にならず成り立たない。", "抜けて": "小説から抜けるは、元にする意味ではないので合わない。"}, "sentence_index": 6, "correct_answer": "拠って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テーブルに拠って、夕飯を済ませました。", "explanation": "ここは〈食べる〉の意味。食事をする動作は食べるで、根拠を示す拠るは使わない。"}, {"text": "コンクールに拠りました。", "explanation": "ここは〈応募〉の意味。作品を送って申し込む意味で、拠るは使わない。"}, {"text": "彼は野球部に拠っています。", "explanation": "ここは〈所属〉の意味。チームの一員である状態を指し、拠るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ニュースに拠れると、明日は晴れるそうです。", "corrected_sentence": "ニュースに拠ると、明日は晴れるそうです。", "error_description": "正しくは「拠ると」。「〜と」は辞書形に付くので、「拠れると」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拠る", "is_correct": true, "explanation": "辞書形。「〜と」に続けると、根拠を示す文になる。"}, {"text": "拠って", "is_correct": false, "explanation": "て形で、「拠ってと」の形は文として続かない。"}, {"text": "拠った", "is_correct": false, "explanation": "た形で、根拠を示す「〜と」の文として自然でない。"}, {"text": "拠れ", "is_correct": false, "explanation": "命令形で、文の途中では使えない。"}], "correct_form": "拠る", "base_form": "拠る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"拠る": "辞書形。「〜と」に続けると、根拠を示す文になる。", "拠って": "て形で、「拠ってと」の形は文として続かない。", "拠った": "た形で、根拠を示す「〜と」の文として自然でない。", "拠れ": "命令形で、文の途中では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53436, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公式の発表が拠って、日程が決まりました。", "corrected_sentence": "公式の発表に拠って、日程が決まりました。", "error_description": "正しくは「発表に拠って」。根拠を示す「拠る」は「〜に拠る」と「に」で示すので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拠れば", "is_correct": true, "explanation": "仮定形。「警察の発表に拠れば」で「警察の発表を根拠にすると」の意味になり、後ろの伝聞の文につながる。"}, {"text": "拠ります", "is_correct": false, "explanation": "丁寧形で文を言い切るので、「警察の発表に拠ります」で切れてしまい、後の「けが人は」と続かない。"}, {"text": "拠ろう", "is_correct": false, "explanation": "意志形で「拠ることにしよう」の意味になり、「〜そうです」の伝聞の根拠を示す文に合わない。"}, {"text": "拠らない", "is_correct": false, "explanation": "否定形なので「根拠にしない」の意味になり、「〜ば」の条件節にならず、文が成り立たない。"}], "correct_form": "拠れば", "base_form": "拠る", "form_label": "仮定形", "sentence_index": 7, "explanations": {"拠れば": "仮定形。「警察の発表に拠れば」で「警察の発表を根拠にすると」の意味になり、後ろの伝聞の文につながる。", "拠ります": "丁寧形で文を言い切るので、「警察の発表に拠ります」で切れてしまい、後の「けが人は」と続かない。", "拠ろう": "意志形で「拠ることにしよう」の意味になり、「〜そうです」の伝聞の根拠を示す文に合わない。", "拠らない": "否定形なので「根拠にしない」の意味になり、「〜ば」の条件節にならず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を取る動詞「捉える」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置を示すため、「肩に捉えました」では対象を取る意味にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「肩が捉えました」では肩が動作主になり、警官の動作が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すため、「肩で捉えました」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "対象を取る動詞「捉える」の目的語を示す。", "に": "位置を示すため、「肩に捉えました」では対象を取る意味にならない。", "が": "主語を示すため、「肩が捉えました」では肩が動作主になり、警官の動作が成り立たない。", "で": "手段を示すため、「肩で捉えました」は意味が通らない。"}, "error_tags": {"に": "位置", "が": "主語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「変化を捉える」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「変化へ捉えた」では対象を取る意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すため、「変化と捉えた」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示すため、「変化の捉えた」では動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「変化を捉える」の目的語を示す。", "へ": "方向を示すため、「変化へ捉えた」では対象を取る意味にならない。", "と": "相手や引用を示すため、「変化と捉えた」は成り立たない。", "の": "修飾を示すため、「変化の捉えた」では動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・引用", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手でつかむこと。心でわきまえること。", "primary_collocate": null, "pronunciation": "とらえる", "ipa": "toɾaeɾɯ", "syllable_count": 4, "sentences": [{"text": "彼は落ちそうな友だちの腕を、とっさに捉えました。", "target_word": "捉えました", "complexity_tier": "T3", "furigana": "彼[かれ]は落[お]ちそうな友[とも]だちの腕[うで]を、とっさに捉[とら]えました。", "sentence_source": "generated"}, {"text": "警官は逃げる男の肩を捉えました。", "target_word": "捉えました", "complexity_tier": "T3", "furigana": "警官[けいかん]は逃[に]げる男[おとこ]の肩[かた]を捉[とら]えました。", "sentence_source": "generated"}, {"text": "落ちてきた花瓶を、彼は両手でしっかり捉えました。", "target_word": "捉えました", "complexity_tier": "T3", "furigana": "落[お]ちてきた花瓶[かびん]を、彼[かれ]は両手[りょうて]でしっかり捉[とら]えました。", "sentence_source": "generated"}, {"text": "先生は、問題の本当の意味を捉えるように言いました。", "target_word": "捉える", "complexity_tier": "T3", "furigana": "先生[せんせい]は、問題[もんだい]の本当[ほんとう]の意味[いみ]を捉[とら]えるように言[い]いました。", "sentence_source": "generated"}, {"text": "彼は物事を前向きに捉える人です。", "target_word": "捉える", "complexity_tier": "T3", "furigana": "彼[かれ]は物事[ものごと]を前向[まえむ]きに捉[とら]える人[ひと]です。", "sentence_source": "generated"}, {"text": "相手の気持ちを正しく捉えることが大切です。", "target_word": "捉える", "complexity_tier": "T3", "furigana": "相手[あいて]の気持[きも]ちを正[ただ]しく捉[とら]えることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "子どもは、ことばの意味を自分なりに捉えています。", "target_word": "捉えて", "complexity_tier": "T3", "furigana": "子[こ]どもは、ことばの意味[いみ]を自分[じぶん]なりに捉[とら]えています。", "sentence_source": "generated"}, {"text": "景気の変化を早く捉えた会社が、成功しました。", "target_word": "捉えた", "complexity_tier": "T3", "furigana": "景気[けいき]の変化[へんか]を早[はや]く捉[とら]えた会社[かいしゃ]が、成功[せいこう]しました。", "sentence_source": "generated"}, {"text": "この文章は、いろいろな意味に捉えられます。", "target_word": "捉えられます", "complexity_tier": "T3", "furigana": "この文章[ぶんしょう]は、いろいろな意味[いみ]に捉[とら]えられます。", "sentence_source": "generated"}, {"text": "彼女は話の要点を捉えて、短くまとめました。", "target_word": "捉えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は話[はなし]の要点[ようてん]を捉[とら]えて、短[みじか]くまとめました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捉える", "label": "辞書形"}, {"form": "捉えない", "label": "否定形"}, {"form": "捉えます", "label": "丁寧形"}, {"form": "捉えて", "label": "て形"}, {"form": "捉えた", "label": "た形"}, {"form": "捉えれば", "label": "仮定形"}, {"form": "捉えられる", "label": "受身・可能形"}], "register": "neutral (丁寧)", "sense_fingerprint": "手でつかむ／意味や状況を理解してつかむ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '347b81c7-f0bf-4163-bbe0-af75346e6ecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捉えました", "is_correct": true, "explanation": "丁寧な過去形。「とっさに友だちの腕をつかんだ」という出来事を文として完結させる。"}, {"text": "捉えて", "is_correct": false, "explanation": "て形のため文が途中で止まり、「ました」で終わる文に入らない。"}, {"text": "捉えれば", "is_correct": false, "explanation": "仮定形なので「〜れば」に続く文が必要で、この文は完結しない。"}, {"text": "捉えない", "is_correct": false, "explanation": "否定形になり、「腕をつかまない」という意味になって、とっさにつかんだ出来事と合わない。"}], "explanations": {"捉えました": "丁寧な過去形。「とっさに友だちの腕をつかんだ」という出来事を文として完結させる。", "捉えて": "て形のため文が途中で止まり、「ました」で終わる文に入らない。", "捉えれば": "仮定形なので「〜れば」に続く文が必要で、この文は完結しない。", "捉えない": "否定形になり、「腕をつかまない」という意味になって、とっさにつかんだ出来事と合わない。"}, "sentence_index": 0, "correct_answer": "捉えました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験のために英単語を捉えました。", "explanation": "ここは〈覚える〉の意味。捉えるは対象を手でつかむ、または意味や要点をつかむことで、単語を頭に入れる意味では使わない。"}, {"text": "失った信用を捉えました。", "explanation": "ここは〈取り戻す〉の意味。捉えるは対象をつかむ・理解する意味で、失ったものを回復する意味では使わない。"}, {"text": "昔の友だちの名前を捉えました。", "explanation": "ここは〈思い出す〉の意味。捉えるは対象をしっかりつかむことで、記憶から呼び起こす意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捉えて", "is_correct": true, "explanation": "て形に「いる」が続いて「捉えている」となり、現在の状態を表す。"}, {"text": "捉えた", "is_correct": false, "explanation": "た形に「います」は続かず、「捉えたいます」は成り立たない。"}, {"text": "捉えます", "is_correct": false, "explanation": "丁寧形に「います」は続かず、「捉えますいます」となる。"}, {"text": "捉える", "is_correct": false, "explanation": "辞書形に「います」は続かず、「捉えるいます」となる。"}], "explanations": {"捉えて": "て形に「いる」が続いて「捉えている」となり、現在の状態を表す。", "捉えた": "た形に「います」は続かず、「捉えたいます」は成り立たない。", "捉えます": "丁寧形に「います」は続かず、「捉えますいます」となる。", "捉える": "辞書形に「います」は続かず、「捉えるいます」となる。"}, "sentence_index": 6, "correct_answer": "捉えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒に泳ぎ方を捉えました。", "explanation": "ここは〈教える〉の意味。捉えるは対象をつかむ・理解する意味で、人に教えて身につけさせる意味では使わない。"}, {"text": "お客さんは、ラーメンを捉えました。", "explanation": "ここは〈注文する〉の意味。捉えるは対象をつかむ・理解する意味で、料理を頼む意味では使わない。"}, {"text": "彼は遅刻を捉えました。", "explanation": "ここは〈咎める〉の意味。捉えるは対象をつかむ・理解する意味で、遅刻を責めて非難する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警官は、逃げる男の腕に捉えました。", "corrected_sentence": "警官は、逃げる男の腕を捉えました。", "error_description": "「捉える」は対象を直接取る動詞なので、対象には「を」を使う。「腕に捉えました」は誤りで、正しくは「腕を捉えました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "捉えました", "is_correct": true, "explanation": "丁寧な過去形。逃げる男を捉えた出来事を表し、文の時制と丁寧さに合う。"}, {"text": "捉えない", "is_correct": false, "explanation": "否定形なので、警官が捉えた事実と矛盾する。"}, {"text": "捉えて", "is_correct": false, "explanation": "て形のため文が完結せず、過去の出来事を表さない。"}, {"text": "捉えられる", "is_correct": false, "explanation": "受身・可能形で「捉えることができる」の意味になり、過去の出来事を表さない。"}], "correct_form": "捉えました", "base_form": "捉える", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"捉えました": "丁寧な過去形。逃げる男を捉えた出来事を表し、文の時制と丁寧さに合う。", "捉えない": "否定形なので、警官が捉えた事実と矛盾する。", "捉えて": "て形のため文が完結せず、過去の出来事を表さない。", "捉えられる": "受身・可能形で「捉えることができる」の意味になり、過去の出来事を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53439, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は会議の要点を捉えるて、短くまとめました。", "corrected_sentence": "彼は会議の要点を捉えて、短くまとめました。", "error_description": "辞書形の「捉える」の後に「て」は続かない。正しくは て形の「捉えて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "捉えた", "is_correct": true, "explanation": "た形（普通形の過去）。連体修飾で「変化を捉えた会社」と過去の出来事を表す。"}, {"text": "捉えない", "is_correct": false, "explanation": "否定形なので「変化を捉えない会社」という意味になり、早く捉えた会社が成功したという文脈と合わない。"}, {"text": "捉えれば", "is_correct": false, "explanation": "仮定形は条件を表すため、「会社が成功しました」と結ばない。"}, {"text": "捉えます", "is_correct": false, "explanation": "丁寧形は連体修飾（会社を修飾する形）に使えず、不自然になる。"}], "correct_form": "捉えた", "base_form": "捉える", "form_label": "普通形の過去（連体修飾）", "sentence_index": 7, "explanations": {"捉えた": "た形（普通形の過去）。連体修飾で「変化を捉えた会社」と過去の出来事を表す。", "捉えない": "否定形なので「変化を捉えない会社」という意味になり、早く捉えた会社が成功したという文脈と合わない。", "捉えれば": "仮定形は条件を表すため、「会社が成功しました」と結ばない。", "捉えます": "丁寧形は連体修飾（会社を修飾する形）に使えず、不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca162f67-7d0a-45b6-a394-9b75e24b4ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
