INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "できないことです。", "primary_collocate": null, "pronunciation": "ふか", "ipa": "ɸɯka", "syllable_count": 2, "sentences": [{"text": "この部屋は関係者以外、立ち入り不可です。", "target_word": "不可", "complexity_tier": "T3", "furigana": "この部屋[へや]は関係者[かんけいしゃ]以外[いがい]、立[た]ち入[い]り不可[ふか]です。", "sentence_source": "generated"}, {"text": "この商品は、お客様の都合による返品は不可です。", "target_word": "不可", "complexity_tier": "T3", "furigana": "この商品[しょうひん]は、お客様[きゃくさま]の都合[つごう]による返品[へんぴん]は不可[ふか]です。", "sentence_source": "generated"}, {"text": "館内での写真撮影は不可なので、カメラはしまってください。", "target_word": "不可", "complexity_tier": "T3", "furigana": "館内[かんない]での写真[しゃしん]撮影[さつえい]は不可[ふか]なので、カメラはしまってください。", "sentence_source": "generated"}, {"text": "この席は予約席のため、一般の方の利用は不可です。", "target_word": "不可", "complexity_tier": "T3", "furigana": "この席[せき]は予約席[よやくせき]のため、一般[いっぱん]の方[かた]の利用[りよう]は不可[ふか]です。", "sentence_source": "generated"}, {"text": "申込後の日程変更は不可ですから、よく確認してください。", "target_word": "不可", "complexity_tier": "T3", "furigana": "申込後[もうしこみご]の日程[にってい]変更[へんこう]は不可[ふか]ですから、よく確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "雨で道がぬかるみ、車の通行は不可になった。", "target_word": "不可", "complexity_tier": "T3", "furigana": "雨[あめ]で道[みち]がぬかるみ、車[くるま]の通行[つうこう]は不可[ふか]になった。", "sentence_source": "generated"}, {"text": "この駐車場は夜間の駐車が不可で、朝まで車を置けない。", "target_word": "不可", "complexity_tier": "T3", "furigana": "この駐車場[ちゅうしゃじょう]は夜間[やかん]の駐車[ちゅうしゃ]が不可[ふか]で、朝[あさ]まで車[くるま]を置[お]けない。", "sentence_source": "generated"}, {"text": "コピーした資料の持ち出しは不可と決まっている。", "target_word": "不可", "complexity_tier": "T3", "furigana": "コピーした資料[しりょう]の持[も]ち出[だ]しは不可[ふか]と決[き]まっている。", "sentence_source": "generated"}, {"text": "一度出ると再入場は不可なので、忘れ物に気をつけて。", "target_word": "不可", "complexity_tier": "T3", "furigana": "一度[いちど]出[で]ると再入場[さいにゅうじょう]は不可[ふか]なので、忘[わす]れ物[もの]に気[き]をつけて。", "sentence_source": "generated"}, {"text": "この券は他の人への譲渡が不可だと書いてある。", "target_word": "不可", "complexity_tier": "T3", "furigana": "この券[けん]は他[ほか]の人[ひと]への譲渡[じょうと]が不可[ふか]だと書[か]いてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可", "label": "基本形"}, {"form": "不可です", "label": "丁寧形"}, {"form": "不可で", "label": "連用形"}, {"form": "不可な", "label": "連体形"}], "register": "formal written (notices, rules)", "sense_fingerprint": "掲示や規則で、その行為が許されない・できないことを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53445, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "「立ち入り不可」は立ち入りが許されないことを表す名詞で、掲示の定型表現として自然。"}, {"text": "不明", "is_correct": false, "explanation": "不明は「はっきりしないこと」。立ち入りの可否を述べる文には合わない。"}, {"text": "不足", "is_correct": false, "explanation": "不足は「足りないこと」。「立ち入り不足」では文の意味が通らない。"}, {"text": "不安", "is_correct": false, "explanation": "不安は心配の意味。「立ち入り不安」となり、掲示の内容と合わない。"}], "explanations": {"不可": "「立ち入り不可」は立ち入りが許されないことを表す名詞で、掲示の定型表現として自然。", "不明": "不明は「はっきりしないこと」。立ち入りの可否を述べる文には合わない。", "不足": "不足は「足りないこと」。「立ち入り不足」では文の意味が通らない。", "不安": "不安は心配の意味。「立ち入り不安」となり、掲示の内容と合わない。"}, "sentence_index": 0, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣室の騒音で、気分が不可になった。", "explanation": "ここは〈不快〉（いやな感じがすること）の意味。〈不可〉は許されない・できないという意味なので、気分の悪さは表せない。"}, {"text": "水は生きていくうえで不可だ。", "explanation": "ここは〈不可欠〉（なくてはならない）の意味。〈不可〉は許されない・できないという意味なので、必要性を述べる文には使えない。"}, {"text": "新しい制度に不可を持つ人が多い。", "explanation": "ここは〈不満〉の意味。〈不可〉は許可されない・できない状態を指し、感情の不満には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53445, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可", "is_correct": true, "explanation": "「夜間の駐車が不可で」は駐車が認められないことを表し、朝まで車を置けない理由として自然。"}, {"text": "不明", "is_correct": false, "explanation": "不明は「わからないこと」。「夜間の駐車が不明で」では理由として意味が通らない。"}, {"text": "不審", "is_correct": false, "explanation": "不審は怪しいこと。「夜間の駐車が不審で」では理由として意味が通らない。"}, {"text": "不動", "is_correct": false, "explanation": "不動は「動かないこと」。「夜間の駐車が不動で」では駐車の可否の説明にならない。"}], "explanations": {"不可": "「夜間の駐車が不可で」は駐車が認められないことを表し、朝まで車を置けない理由として自然。", "不明": "不明は「わからないこと」。「夜間の駐車が不明で」では理由として意味が通らない。", "不審": "不審は怪しいこと。「夜間の駐車が不審で」では理由として意味が通らない。", "不動": "不動は「動かないこと」。「夜間の駐車が不動で」では駐車の可否の説明にならない。"}, "sentence_index": 6, "correct_answer": "不可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その二つの問題は不可の関係にあり、切り離して考えられない。", "explanation": "ここは〈不可分〉（切り離せない）の意味。〈不可〉は許されない・できないという意味なので、切り離せない関係は表せない。"}, {"text": "製品に不可が見つかったため、出荷を止めた。", "explanation": "ここは〈不良〉（欠陥）の意味。〈不可〉は行為の可否を表すので、製品の欠陥の説明には使えない。"}, {"text": "その事故は不可だった。", "explanation": "ここは〈不可避〉（避けられない）の意味。〈不可〉は許されないという意味なので、避けられない結果を表す文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53445, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この施設では、夜間の利用は不可ので、車は入れません。", "corrected_sentence": "この施設では、夜間の利用は不可なので、車は入れません。", "error_description": "名詞「不可」の後に「の」を続けるのは誤り。「不可な」の形を取り、「なので」とする。正しくは「不可なので」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53445, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この券は他の人への譲渡に不可だと、注意書きに書いてある。", "corrected_sentence": "この券は他の人への譲渡が不可だと、注意書きに書いてある。", "error_description": "「不可」の直前は「が」が正しい。「に」を使うと「譲渡に不可」となり、「不可」が述語として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「ありがとうと言える」の引用の「と」。「言う」に伴う引用の助詞として正しい。"}, {"text": "か", "is_correct": false, "explanation": "「ありがとうか言える」は疑問・不定の「か」で、引用を表せず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ありがとうに言える」では、言葉を言う内容を示す助詞として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ありがとうへ言える」は方向を表す助詞として意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「ありがとうと言える」の引用の「と」。「言う」に伴う引用の助詞として正しい。", "か": "「ありがとうか言える」は疑問・不定の「か」で、引用を表せず成り立たない。", "に": "「ありがとうに言える」では、言葉を言う内容を示す助詞として成り立たない。", "へ": "「ありがとうへ言える」は方向を表す助詞として意味が通らない。"}, "error_tags": {"か": "疑問・不定", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「だれにも言えない」の「も」。「誰に対しても言えない」という意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「だれに」の後に「が」を入れると、主語の位置として意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「だれにを言えない」は目的語の形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「だれにへ言えない」は方向の助詞として不自然で、文が成り立たない。"}], "correct_answer": "も", "explanations": {"も": "「だれにも言えない」の「も」。「誰に対しても言えない」という意味になる。", "が": "「だれに」の後に「が」を入れると、主語の位置として意味が通らない。", "を": "「だれにを言えない」は目的語の形として成り立たない。", "へ": "「だれにへ言えない」は方向の助詞として不自然で、文が成り立たない。"}, "error_tags": {"が": "主格", "を": "目的格", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "声に出して言葉を言うことができる。", "primary_collocate": null, "pronunciation": "いえる", "ipa": "ieɾɯ", "syllable_count": 3, "sentences": [{"text": "緊張していて、自分の名前がうまく言えなかった。", "target_word": "言えなかった", "complexity_tier": "T3", "furigana": "緊張[きんちょう]していて、自分[じぶん]の名前[なまえ]がうまく言[い]えなかった。", "sentence_source": "generated"}, {"text": "子どもは三歳で、ありがとうと言えるようになった。", "target_word": "言える", "complexity_tier": "T3", "furigana": "子[こ]どもは三歳[さんさい]で、ありがとうと言[い]えるようになった。", "sentence_source": "generated"}, {"text": "先生の前では、本当の気持ちが言えない。", "target_word": "言えない", "complexity_tier": "T3", "furigana": "先生[せんせい]の前[まえ]では、本当[ほんとう]の気持[きも]ちが言[い]えない。", "sentence_source": "generated"}, {"text": "勇気を出して、ごめんなさいと言えた。", "target_word": "言えた", "complexity_tier": "T3", "furigana": "勇気[ゆうき]を出[だ]して、ごめんなさいと言[い]えた。", "sentence_source": "generated"}, {"text": "外国語で自分の名前が言えるようになるまで、何度も練習した。", "target_word": "言える", "complexity_tier": "T3", "furigana": "外国語[がいこくご]で自分[じぶん]の名前[なまえ]が言[い]えるようになるまで、何度[なんど]も練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "のどが痛くて、大きな声で言えません。", "target_word": "言えません", "complexity_tier": "T3", "furigana": "のどが痛[いた]くて、大[おお]きな声[こえ]で言[い]えません。", "sentence_source": "generated"}, {"text": "この言葉は、早口で三回言えますか。", "target_word": "言えます", "complexity_tier": "T3", "furigana": "この言葉[ことば]は、早口[はやくち]で三回[さんかい]言[い]えますか。", "sentence_source": "generated"}, {"text": "ひみつなので、だれにも言えない。", "target_word": "言えない", "complexity_tier": "T3", "furigana": "ひみつなので、だれにも言[い]えない。", "sentence_source": "generated"}, {"text": "弟はまだ「らりるれろ」がきれいに言えない。", "target_word": "言えない", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ「らりるれろ」がきれいに言[い]えない。", "sentence_source": "generated"}, {"text": "友だちの前なら、何でも素直に言える。", "target_word": "言える", "complexity_tier": "T3", "furigana": "友[とも]だちの前[まえ]なら、何[なん]でも素直[すなお]に言[い]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言える", "label": "終止形"}, {"form": "言えない", "label": "否定形"}, {"form": "言えた", "label": "過去形"}, {"form": "言えます", "label": "丁寧形"}, {"form": "言えて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "声に出して言葉を言うことができる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: るれ (Zipf 2.37)']::text[], '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言えなかった", "is_correct": true, "explanation": "過去の否定形で、緊張して名前がうまく言えなかったという文脈に合う。"}, {"text": "言えなくて", "is_correct": false, "explanation": "て形のため、文末の「。」の前で文が途中のまま終わってしまう。"}, {"text": "言えなければ", "is_correct": false, "explanation": "仮定形のため、文として完結しない。"}, {"text": "言え", "is_correct": false, "explanation": "語幹だけなので、このままでは文中に単独で置けない。"}], "explanations": {"言えなかった": "過去の否定形で、緊張して名前がうまく言えなかったという文脈に合う。", "言えなくて": "て形のため、文末の「。」の前で文が途中のまま終わってしまう。", "言えなければ": "仮定形のため、文として完結しない。", "言え": "語幹だけなので、このままでは文中に単独で置けない。"}, "sentence_index": 0, "correct_answer": "言えなかった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三段跳びが言えるので、体育の先生に選ばれた。", "explanation": "ここは〈跳べる〉の場面。三段跳びは跳ぶもので、言えるは言葉を言うことなので合わない。"}, {"text": "あの子は、もう自転車が言える。", "explanation": "〈乗れる〉の場面。自転車は乗るもので、言えるは言葉を言うことなので合わない。"}, {"text": "一度投げただけで、同じ球が言える。", "explanation": "ここは〈投げられる〉の場面。球は投げるもので、言えるは言葉を言うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言えます", "is_correct": true, "explanation": "丁寧形の疑問文として「三回言えますか」と続き、能力を尋ねる文脈に合う。"}, {"text": "言えて", "is_correct": false, "explanation": "て形のため、「。」の前で文が途中のまま終わってしまう。"}, {"text": "言えまし", "is_correct": false, "explanation": "丁寧形の語幹だけでは、文末に置いて完結させられない。"}, {"text": "言えば", "is_correct": false, "explanation": "仮定形のため、「三回言えば」で文が完結しない。"}], "explanations": {"言えます": "丁寧形の疑問文として「三回言えますか」と続き、能力を尋ねる文脈に合う。", "言えて": "て形のため、「。」の前で文が途中のまま終わってしまう。", "言えまし": "丁寧形の語幹だけでは、文末に置いて完結させられない。", "言えば": "仮定形のため、「三回言えば」で文が完結しない。"}, "sentence_index": 6, "correct_answer": "言えます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "辛い料理も言える。", "explanation": "〈食べられる〉の場面で使う言葉。料理は食べるもので、言えるは言葉を言うことなので合わない。"}, {"text": "ピアノが言える。", "explanation": "〈弾ける〉の場面。ピアノは弾くもので、言えるは言葉を言うことなので合わない。"}, {"text": "窓から、遠くの山が言える。", "explanation": "〈見える〉の場面。山は見えるもので、言えるは言葉を言うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その理由を、彼は誰にも言えるなかった。", "corrected_sentence": "その理由を、彼は誰にも言えなかった。", "error_description": "「言えなかった」の途中に「る」を入れた誤り。否定過去の正しい形は「言えなかった」で、「言えるなかった」は文法的に成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "言える", "is_correct": true, "explanation": "「ようになった」の前には動詞の基本形（連体形）を置くので正しい。"}, {"text": "言えず", "is_correct": false, "explanation": "連用形は「ようになった」の前に置けず、文が成り立たない。"}, {"text": "言えよう", "is_correct": false, "explanation": "意志の形は「ようになった」の前に置けず、不自然になる。"}, {"text": "言えて", "is_correct": false, "explanation": "て形は後ろに「ようになった」を直接続けられない。"}], "correct_form": "言える", "base_form": "言える", "form_label": "連体形", "sentence_index": 1, "explanations": {"言える": "「ようになった」の前には動詞の基本形（連体形）を置くので正しい。", "言えず": "連用形は「ようになった」の前に置けず、文が成り立たない。", "言えよう": "意志の形は「ようになった」の前に置けず、不自然になる。", "言えて": "て形は後ろに「ようになった」を直接続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は先生にありがとうと言えるた。", "corrected_sentence": "彼は先生にありがとうと言えた。", "error_description": "過去形は「言えた」。「言えるた」は「言える」に「た」が直接続いた活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "言えない", "is_correct": true, "explanation": "否定形で「誰にも言えない」という秘密の文脈に合う。"}, {"text": "言えれば", "is_correct": false, "explanation": "仮定形のため、文末に置くと文が完結しない。"}, {"text": "言えたら", "is_correct": false, "explanation": "仮定形のため、文末に置くと文が完結しない。"}, {"text": "言えず", "is_correct": false, "explanation": "連用形のため、文末に置くと不自然で、文を終えられない。"}], "correct_form": "言えない", "base_form": "言える", "form_label": "否定形", "sentence_index": 7, "explanations": {"言えない": "否定形で「誰にも言えない」という秘密の文脈に合う。", "言えれば": "仮定形のため、文末に置くと文が完結しない。", "言えたら": "仮定形のため、文末に置くと文が完結しない。", "言えず": "連用形のため、文末に置くと不自然で、文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
