INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語。「偽装が続いていた」で、偽装という不正が継続していた意味を表す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので、「偽装を続いていた」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、続いた主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、ここでは主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語。「偽装が続いていた」で、偽装という不正が継続していた意味を表す。", "を": "「続く」は自動詞なので、「偽装を続いていた」は成立しない。", "と": "「と」は並列や相手を示し、続いた主語にはならない。", "より": "「より」は比較を示し、ここでは主語として成り立たない。"}, "error_tags": {"を": "対象", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "本当の姿を隠して、だましごとをすることです。", "primary_collocate": null, "pronunciation": "ぎそう", "ipa": "ɡisoː", "syllable_count": 3, "sentences": [{"text": "彼は身分を偽装して、工場に潜り込んだ。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "彼(かれ)は身分(みぶん)を偽装(ぎそう)して、工場(こうじょう)に潜(もぐ)り込(こ)んだ。", "sentence_source": "generated"}, {"text": "彼は経歴を偽装して、大手企業の採用試験に合格した。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "彼[かれ]は経歴[けいれき]を偽装[ぎそう]して、大手[おおて]企業[きぎょう]の採用[さいよう]試験[しけん]に合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "数字を偽装したことが分かり、社長は責任を取って辞めた。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "数字(すうじ)を偽装(ぎそう)したことが分(わ)かり、社長(しゃちょう)は責任(せきにん)を取(と)って辞(や)めた。", "sentence_source": "generated"}, {"text": "食品の偽装に気づいた客が、保健所に連絡した。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "食品(しょくひん)の偽装(ぎそう)に気(き)づいた客(きゃく)が、保健所(ほけんじょ)に連絡(れんらく)した。", "sentence_source": "generated"}, {"text": "その事件は、自殺に見せかけた偽装だったと判明した。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "その事件(じけん)は、自殺(じさつ)に見(み)せかけた偽装(ぎそう)だったと判明(はんめい)した。", "sentence_source": "generated"}, {"text": "スパイは普通の観光客を偽装して、国境を越えた。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "スパイは普通(ふつう)の観光客(かんこうきゃく)を偽装(ぎそう)して、国境(こっきょう)を越(こ)えた。", "sentence_source": "generated"}, {"text": "偽装を見破るには、細かい違いに注意する必要がある。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "偽装(ぎそう)を見破(みやぶ)るには、細(こま)かい違(ちが)いに注意(ちゅうい)する必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "会社ぐるみの偽装が続いていたので、取引先は契約を打ち切った。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "会社(かいしゃ)ぐるみの偽装(ぎそう)が続(つづ)いていたので、取引先(とりひきさき)は契約(けいやく)を打(う)ち切(き)った。", "sentence_source": "generated"}, {"text": "虫の中には、葉そっくりに偽装して敵の目をごまかすものがいる。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "虫(むし)の中(なか)には、葉(は)そっくりに偽装(ぎそう)して敵(てき)の目(め)をごまかすものがいる。", "sentence_source": "generated"}, {"text": "学歴の偽装が発覚し、彼は内定を取り消された。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "学歴(がくれき)の偽装(ぎそう)が発覚(はっかく)し、彼(かれ)は内定(ないてい)を取(と)り消(け)された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偽装する", "label": "dictionary form (suru verb)"}, {"form": "偽装した", "label": "past"}, {"form": "偽装される", "label": "passive"}], "register": "neutral written", "sense_fingerprint": "本当の姿を隠してだますこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偽装", "is_correct": true, "explanation": "ここは本当の姿を隠す行為を表す語。「身分を〜して、工場に潜り込んだ」として文が成り立つ。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしの行為であり、身分を隠して潜入する文脈には合わない。"}, {"text": "焦燥", "is_correct": false, "explanation": "いらだつ心理を表す語で、身分を隠す行為には合わない。"}, {"text": "帰国", "is_correct": false, "explanation": "国に戻る行為であり、身分を隠して潜入する文脈とは合わない。"}], "explanations": {"偽装": "ここは本当の姿を隠す行為を表す語。「身分を〜して、工場に潜り込んだ」として文が成り立つ。", "散歩": "気晴らしの行為であり、身分を隠して潜入する文脈には合わない。", "焦燥": "いらだつ心理を表す語で、身分を隠す行為には合わない。", "帰国": "国に戻る行為であり、身分を隠して潜入する文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "偽装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞台の照明を偽装して、観客を驚かせた。", "explanation": "ここは〈演出〉（効果を狙って見せる）の意味。偽装は本当の姿を隠す行為で、照明の工夫には合わない。"}, {"text": "業者が屋根を偽装して、雨漏りを防いだ。", "explanation": "ここは〈施工〉（工事をする）の意味。偽装は本当の姿を隠す行為で、雨漏り対策には合わない。"}, {"text": "野菜を冷蔵庫で偽装して、鮮度を保った。", "explanation": "ここは〈保存〉の意味。偽装は別物に見せかける行為で、鮮度を保つ手段とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偽装", "is_correct": true, "explanation": "ここは偽りを見抜く対象となる行為を表す語。「偽装を見破るには」として文が成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態であり、見破る対象にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "身体の数値であり、細かい違いから見破る対象とは言えない。"}, {"text": "足音", "is_correct": false, "explanation": "聞こえる音であり、偽りを見破る対象としては不自然。"}], "explanations": {"偽装": "ここは偽りを見抜く対象となる行為を表す語。「偽装を見破るには」として文が成り立つ。", "天気": "気象の状態であり、見破る対象にはならない。", "体重": "身体の数値であり、細かい違いから見破る対象とは言えない。", "足音": "聞こえる音であり、偽りを見破る対象としては不自然。"}, "sentence_index": 6, "correct_answer": "偽装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農家が畑で花を偽装して、収穫の時期を決めた。", "explanation": "ここは〈収穫〉（作物を取り入れる）の意味。偽装は本当の姿を隠す行為で、収穫の判断には合わない。"}, {"text": "編集者が原稿を偽装して、誤字を直した。", "explanation": "ここは〈校正〉（誤りを正す）の意味。偽装は本当の姿を隠す行為で、誤字を直す作業には合わない。"}, {"text": "古い家を偽装して、家族が暮らしやすくした。", "explanation": "ここは〈増築〉（建物を広げる）の意味。偽装は正体を隠す行為で、建物の拡張には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その男は偽装を身分を隠し、会社に入り込んだ。", "corrected_sentence": "その男は偽装で身分を隠し、会社に入り込んだ。", "error_description": "「偽装で身分を隠す」が正しい。「偽装を」は手段を表す「で」の誤りで、「で」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53449, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は嘘の経歴を偽装ると、採用試験を通った。", "corrected_sentence": "彼は嘘の経歴を偽装して、採用試験を通った。", "error_description": "「偽装する」の活用は「偽装して」（テ形）。「偽装ると」は誤った活用で、「偽装して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「偽装で」は原因を示す。偽装が原因で信用を失ったという意味で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「偽装を」は直後の「信用を失った」と「を」が重なり、文の構造が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、原因を表す文脈には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここは原因の意味なので合わない。"}], "correct_answer": "で", "explanations": {"で": "「偽装で」は原因を示す。偽装が原因で信用を失ったという意味で正しい。", "を": "「偽装を」は直後の「信用を失った」と「を」が重なり、文の構造が崩れる。", "と": "「と」は並列や相手を示し、原因を表す文脈には合わない。", "より": "「より」は比較を示すが、ここは原因の意味なので合わない。"}, "error_tags": {"を": "対象", "と": "並列・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の本質や正体を隠し、別のもののように見せかけること。また、その行為。", "primary_collocate": null, "pronunciation": "ぎそう", "ipa": "ɡisoː", "syllable_count": 3, "sentences": [{"text": "いかなる偽装も、この厳密な科学的検証の前には無力化されるほかない。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "いかなる偽装(ぎそう)も、この厳密(げんみつ)な科学的(かがくてき)検証(けんしょう)の前(まえ)には無力化(むりょくか)されるほかない。", "sentence_source": "mined"}, {"text": "その会社は輸入した肉を国産に見せかける偽装で、信用を失った。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "その会社(かいしゃ)は輸入(ゆにゅう)した肉(にく)を国産(こくさん)に見(み)せかける偽装(ぎそう)で、信用(しんよう)を失(うしな)った。", "sentence_source": "generated"}, {"text": "犯人は強盗に見せかける偽装をしたが、足跡から見破られた。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "犯人(はんにん)は強盗(ごうとう)に見(み)せかける偽装(ぎそう)をしたが、足跡(あしあと)から見破(みやぶ)られた。", "sentence_source": "generated"}, {"text": "産地の偽装が発覚して、店は営業を停止した。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "産地(さんち)の偽装(ぎそう)が発覚(はっかく)して、店(みせ)は営業(えいぎょう)を停止(ていし)した。", "sentence_source": "generated"}, {"text": "兵士たちは戦車を木の葉や枝で覆い、森と見分けがつかないように偽装した。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは戦車[せんしゃ]を木[き]の葉[は]や枝[えだ]で覆[おお]い、森[もり]と見分[みわ]けがつかないように偽装[ぎそう]した。", "sentence_source": "generated"}, {"text": "彼は病気を偽装して会社を休んだが、同僚に写真を見られて嘘がばれた。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "彼(かれ)は病気(びょうき)を偽装(ぎそう)して会社(かいしゃ)を休(やす)んだが、同僚(どうりょう)に写真(しゃしん)を見(み)られて嘘(うそ)がばれた。", "sentence_source": "generated"}, {"text": "この偽装は巧妙で、専門家でさえ本物と見分けられなかった。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "この偽装(ぎそう)は巧妙(こうみょう)で、専門家(せんもんか)でさえ本物(ほんもの)と見分(みわ)けられなかった。", "sentence_source": "generated"}, {"text": "賞味期限の偽装は、消費者をだます悪質な行為だ。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "賞味(しょうみ)期限(きげん)の偽装(ぎそう)は、消費者(しょうひしゃ)をだます悪質(あくしつ)な行為(こうい)だ。", "sentence_source": "generated"}, {"text": "偽装がばれたのは、内部の社員が告発したからだ。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "偽装(ぎそう)がばれたのは、内部(ないぶ)の社員(しゃいん)が告発(こくはつ)したからだ。", "sentence_source": "generated"}, {"text": "古い車を新車に偽装して売った男が、詐欺の疑いで逮捕された。", "target_word": "偽装", "complexity_tier": "T3", "furigana": "古(ふる)い車(くるま)を新車(しんしゃ)に偽装(ぎそう)して売(う)った男(おとこ)が、詐欺(さぎ)の疑(うたが)いで逮捕(たいほ)された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偽装する", "label": "dictionary form (suru verb)"}, {"form": "偽装した", "label": "past"}, {"form": "偽装される", "label": "passive"}], "register": "neutral written", "sense_fingerprint": "正体や本質を隠して別物に見せかける行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偽装", "is_correct": true, "explanation": "ここは本質を隠して見せかける行為を表す語。「いかなる〜も無力化される」の主語として合う。"}, {"text": "演奏", "is_correct": false, "explanation": "音楽の行為であり、見せかけを無力化する文脈には合わない。"}, {"text": "配送", "is_correct": false, "explanation": "物を届ける行為で、見破られる対象にはならない。"}, {"text": "方言", "is_correct": false, "explanation": "地域の言葉であり、科学的検証の前に無力化される文脈には合わない。"}], "explanations": {"偽装": "ここは本質を隠して見せかける行為を表す語。「いかなる〜も無力化される」の主語として合う。", "演奏": "音楽の行為であり、見せかけを無力化する文脈には合わない。", "配送": "物を届ける行為で、見破られる対象にはならない。", "方言": "地域の言葉であり、科学的検証の前に無力化される文脈には合わない。"}, "sentence_index": 0, "correct_answer": "偽装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は壊れた蛇口を偽装して、水漏れを止めた。", "explanation": "ここは〈修理〉（壊れたものを直す）の意味。偽装は本当の姿を隠す行為で、直す作業には合わない。"}, {"text": "工場は最新の偽装を導入して、生産性を上げた。", "explanation": "ここは〈装備〉（機械や道具）の意味。偽装は正体を隠す行為で、導入する設備には合わない。"}, {"text": "受付は来館者を偽装して、出口まで案内した。", "explanation": "ここは〈案内〉（道を教えて導く）の意味。偽装は本当の姿を隠す行為で、来館者を導く作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偽装", "is_correct": true, "explanation": "ここは本当の姿を隠す行為を表す語。「巧妙で、見分けられなかった」の主語として合う。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態であり、巧妙さを語る主語にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "身体の数値であり、見分けられなかったという文脈には合わない。"}, {"text": "地震", "is_correct": false, "explanation": "自然現象であり、人が見分けるという文脈には合わない。"}], "explanations": {"偽装": "ここは本当の姿を隠す行為を表す語。「巧妙で、見分けられなかった」の主語として合う。", "天気": "気象の状態であり、巧妙さを語る主語にはならない。", "体重": "身体の数値であり、見分けられなかったという文脈には合わない。", "地震": "自然現象であり、人が見分けるという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "偽装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は窓を偽装して、部屋をきれいにした。", "explanation": "ここは〈掃除〉（汚れを取る）の意味。偽装は本当の姿を隠す行為で、汚れを落とす作業には合わない。"}, {"text": "古い橋を偽装して、安全に通れるようにした。", "explanation": "ここは〈補修〉（直して強くする）の意味。偽装は隠す行為で、橋を安全にする文脈には合わない。"}, {"text": "有名な絵画を偽装して、教室で練習した。", "explanation": "ここは〈模倣〉（まねて練習する）の意味。偽装は別物に見せかける行為で、練習の手段としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社は、輸入した肉を国産に見せかける偽装に行い、信用を失った。", "corrected_sentence": "その会社は、輸入した肉を国産に見せかける偽装を行い、信用を失った。", "error_description": "「行う」は「を」を取る他動詞。「偽装に行う」は助詞の誤りで、「偽装を行う」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は仕事のミスを偽装ので、上司の評価を得た。", "corrected_sentence": "彼は仕事のミスを偽装して、上司の評価を得た。", "error_description": "「偽装する」のテ形は「偽装して」。「偽装ので」は活用の誤りで、「偽装して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下等", "is_correct": true, "explanation": "「下等」は程度や質が低いことで、「高等」の対義語として辞書に並ぶ。"}, {"text": "平凡", "is_correct": false, "explanation": "「平凡」は特に優れた点がないことで、「高等」の対義語ではない。"}, {"text": "粗雑", "is_correct": false, "explanation": "「粗雑」は仕上がりが荒いことで、能力の段階を表さないので「高等」の対義語ではない。"}, {"text": "普通", "is_correct": false, "explanation": "「普通」は特別でないことで、「高等」と対になる語ではない。"}], "correct_answer": "下等", "explanations": {"下等": "「下等」は程度や質が低いことで、「高等」の対義語として辞書に並ぶ。", "平凡": "「平凡」は特に優れた点がないことで、「高等」の対義語ではない。", "粗雑": "「粗雑」は仕上がりが荒いことで、能力の段階を表さないので「高等」の対義語ではない。", "普通": "「普通」は特別でないことで、「高等」と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下等", "is_correct": true, "explanation": "「下等」は程度や質が低いことで、「高等」の対義語として辞書に並ぶ。"}, {"text": "粗末", "is_correct": false, "explanation": "「粗末」は質素で雑なことで、「高等」の対義語ではない。"}, {"text": "凡庸", "is_correct": false, "explanation": "「凡庸」は特に優れた点がないことで、「高等」の対義語ではない。"}, {"text": "劣悪", "is_correct": false, "explanation": "「劣悪」は非常に質が悪いことで、「高等」と対になる語ではない。"}], "correct_answer": "下等", "explanations": {"下等": "「下等」は程度や質が低いことで、「高等」の対義語として辞書に並ぶ。", "粗末": "「粗末」は質素で雑なことで、「高等」の対義語ではない。", "凡庸": "「凡庸」は特に優れた点がないことで、「高等」の対義語ではない。", "劣悪": "「劣悪」は非常に質が悪いことで、「高等」と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかのものより段階や能力が上であること。", "primary_collocate": null, "pronunciation": "こうとう", "ipa": "koːtoː", "syllable_count": 4, "sentences": [{"text": "人間は他の動物より高等な頭脳を持っている。", "target_word": "高等", "complexity_tier": "T3", "furigana": "人間[にんげん]は他[ほか]の動物[どうぶつ]より高等[こうとう]な頭脳[ずのう]を持[も]っている。", "sentence_source": "generated"}, {"text": "犬は高等な動物なので、人の気持ちを感じ取る。", "target_word": "高等", "complexity_tier": "T3", "furigana": "犬[いぬ]は高等[こうとう]な動物[どうぶつ]なので、人[ひと]の気持[きも]ちを感[かん]じ取[と]る。", "sentence_source": "generated"}, {"text": "イルカは高等な知能を持ち、仲間と協力して狩りをする。", "target_word": "高等", "complexity_tier": "T3", "furigana": "イルカは高等[こうとう]な知能[ちのう]を持[も]ち、仲間[なかま]と協力[きょうりょく]して狩[か]りをする。", "sentence_source": "generated"}, {"text": "この問題は高等な思考力が必要なので、難しい。", "target_word": "高等", "complexity_tier": "T3", "furigana": "この問題[もんだい]は高等[こうとう]な思考力[しこうりょく]が必要[ひつよう]なので、難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼女は高等な判断力で、難しい問題を正しく解決した。", "target_word": "高等", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は高等[こうとう]な判断力[はんだんりょく]で、難[むずか]しい問題[もんだい]を正[ただ]しく解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "高等な能力を持つ生き物ほど、長く子どもを育てる。", "target_word": "高等", "complexity_tier": "T3", "furigana": "高等[こうとう]な能力[のうりょく]を持[も]つ生[い]き物[もの]ほど、長[なが]く子[こ]どもを育[そだ]てる。", "sentence_source": "generated"}, {"text": "サルは魚より高等な動物と言われている。", "target_word": "高等", "complexity_tier": "T3", "furigana": "サルは魚[さかな]より高等[こうとう]な動物[どうぶつ]と言[い]われている。", "sentence_source": "generated"}, {"text": "彼の絵は高等な技術を感じさせ、見る人を驚かせる。", "target_word": "高等", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]は高等[こうとう]な技術[ぎじゅつ]を感[かん]じさせ、見[み]る人[ひと]を驚[おどろ]かせる。", "sentence_source": "generated"}, {"text": "言葉を使うのは、高等な能力のひとつだ。", "target_word": "高等", "complexity_tier": "T3", "furigana": "言葉[ことば]を使[つか]うのは、高等[こうとう]な能力[のうりょく]のひとつだ。", "sentence_source": "generated"}, {"text": "高等な遊びと呼ばれるチェスは、頭をよく使う。", "target_word": "高等", "complexity_tier": "T3", "furigana": "高等[こうとう]な遊[あそ]びと呼[よ]ばれるチェスは、頭[あたま]をよく使[つか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高等だ", "label": "終止形"}, {"form": "高等な", "label": "連体形"}, {"form": "高等に", "label": "連用形"}, {"form": "高等で", "label": "て形"}], "register": "neutral", "sense_fingerprint": "ほかのものより能力や程度がすぐれていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "「高等」は他より能力が優れていることで、頭脳を修飾する文に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈」は物の堅さや丈夫さを言うので、頭脳には合わない。"}, {"text": "手頃", "is_correct": false, "explanation": "「手頃」は値段や大きさが適当なことなので、頭脳を説明する文には合わない。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は物音や様子の穏やかさを表すので、能力の高さを述べる文には合わない。"}], "explanations": {"高等": "「高等」は他より能力が優れていることで、頭脳を修飾する文に合う。", "頑丈": "「頑丈」は物の堅さや丈夫さを言うので、頭脳には合わない。", "手頃": "「手頃」は値段や大きさが適当なことなので、頭脳を説明する文には合わない。", "静か": "「静か」は物音や様子の穏やかさを表すので、能力の高さを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この試験で彼は高等な成績を取った。", "explanation": "ここは〈優秀〉の意味。成績の優れていることは優秀で言い、高等は能力の段階を指すので合わない。"}, {"text": "この店は高等な材料を使い、一つ数百円で売っている。", "explanation": "ここは〈高級〉の意味。品質や値段の高さは高級で言い、高等は能力の段階を指すので「高等な材料」とは言わない。"}, {"text": "この布は高等なにおいで、コートにすると暖かい。", "explanation": "においには「高等」を使わず、能力や段階を表す語でもないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "「高等」は能力や程度が上位にあることで、動物を説明する文に合う。"}, {"text": "堅実", "is_correct": false, "explanation": "「堅実」は確かで手堅いことで、動物の段階を表す文には合わない。"}, {"text": "穏当", "is_correct": false, "explanation": "「穏当」は穏やかで適切なことで、動物の能力を表す文には合わない。"}, {"text": "円滑", "is_correct": false, "explanation": "「円滑」は物事が滞りなく進むことで、動物の段階を表す文には合わない。"}], "explanations": {"高等": "「高等」は能力や程度が上位にあることで、動物を説明する文に合う。", "堅実": "「堅実」は確かで手堅いことで、動物の段階を表す文には合わない。", "穏当": "「穏当」は穏やかで適切なことで、動物の能力を表す文には合わない。", "円滑": "「円滑」は物事が滞りなく進むことで、動物の段階を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は高等な眠気で、小さな箱に絵を彫った。", "explanation": "眠気には「高等」を使わず、能力や段階を表す語でもないので合わない。"}, {"text": "この会社は高等な企業として、国から表彰された。", "explanation": "ここは〈優良〉の意味。企業の評価の良さは優良で言い、高等は能力の段階を指すので合わない。"}, {"text": "彼女は高等な足取りで、夜道を歩いた。", "explanation": "ここは〈軽快〉の意味。動きの軽やかさは軽快で言い、高等は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その鳥は高等だ知能を持ち、道具を使って餌を取る。", "corrected_sentence": "その鳥は高等な知能を持ち、道具を使って餌を取る。", "error_description": "形状詞は名詞の前で「な」の形にする。「高等だ」の終止形を名詞の前に置いたのが誤り。正しくは「高等な知能」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高等な", "is_correct": true, "explanation": "文中の形。連体形で後ろの「動物」を修飾している。"}, {"text": "高等だ", "is_correct": false, "explanation": "終止形。文を言い切るときの形で、名詞の前には置けない。"}, {"text": "高等に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「動物」の前には使わない。"}, {"text": "高等で", "is_correct": false, "explanation": "て形。文をつなぐ形で、名詞を修飾する位置には合わない。"}], "correct_form": "高等な", "base_form": "高等だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"高等な": "文中の形。連体形で後ろの「動物」を修飾している。", "高等だ": "終止形。文を言い切るときの形で、名詞の前には置けない。", "高等に": "連用形。動詞や形容詞を修飾する形で、名詞「動物」の前には使わない。", "高等で": "て形。文をつなぐ形で、名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53469, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その猫は高等の判断力を持つと、研究者は考えている。", "corrected_sentence": "その猫は高等な判断力を持つと、研究者は考えている。", "error_description": "形状詞は名詞を修飾するとき「な」を使う。「高等の」は「の」を付けた誤りで、正しくは「高等な判断力」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高等な", "is_correct": true, "explanation": "文中の形。連体形で後ろの「技術」を修飾している。"}, {"text": "高等だった", "is_correct": false, "explanation": "過去形。文の述語として使う形で、名詞を修飾する位置には合わない。"}, {"text": "高等であった", "is_correct": false, "explanation": "書き言葉の過去形。名詞の前には置けない。"}, {"text": "高等ならば", "is_correct": false, "explanation": "仮定形。条件を述べる形で、名詞を修飾する位置には合わない。"}], "correct_form": "高等な", "base_form": "高等だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"高等な": "文中の形。連体形で後ろの「技術」を修飾している。", "高等だった": "過去形。文の述語として使う形で、名詞を修飾する位置には合わない。", "高等であった": "書き言葉の過去形。名詞の前には置けない。", "高等ならば": "仮定形。条件を述べる形で、名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
