INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53470, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "レベルや程度が非常に高いこと。特に教育や技術などが上級段階にある場合を指す。", "primary_collocate": null, "pronunciation": "こうとう", "ipa": "koːtoː", "syllable_count": 4, "sentences": [{"text": "この研究所では高等な技術を学ぶことができる。", "target_word": "高等", "complexity_tier": "T3", "furigana": "この研究所[けんきゅうじょ]では高等[こうとう]な技術[ぎじゅつ]を学[まな]ぶことができる。", "sentence_source": "generated"}, {"text": "大学では、高等な数学を専門に勉強している。", "target_word": "高等", "complexity_tier": "T3", "furigana": "大学[だいがく]では、高等[こうとう]な数学[すうがく]を専門[せんもん]に勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "高等な技術を身につけるには、基礎の訓練が欠かせない。", "target_word": "高等", "complexity_tier": "T3", "furigana": "高等[こうとう]な技術[ぎじゅつ]を身[み]につけるには、基礎[きそ]の訓練[くんれん]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "彼は高等な教育を受けたので、三か国語を話せる。", "target_word": "高等", "complexity_tier": "T3", "furigana": "彼[かれ]は高等[こうとう]な教育[きょういく]を受[う]けたので、三[さん]か国語[こくご]を話[はな]せる。", "sentence_source": "generated"}, {"text": "高等な能力を持つ人材が、会社で求められている。", "target_word": "高等", "complexity_tier": "T3", "furigana": "高等[こうとう]な能力[のうりょく]を持[も]つ人材[じんざい]が、会社[かいしゃ]で求[もと]められている。", "sentence_source": "generated"}, {"text": "この機械には高等な技術が使われているため、値段も高い。", "target_word": "高等", "complexity_tier": "T3", "furigana": "この機械[きかい]には高等[こうとう]な技術[ぎじゅつ]が使[つか]われているため、値段[ねだん]も高[たか]い。", "sentence_source": "generated"}, {"text": "この論文は、高等な数学を使って理論を証明している。", "target_word": "高等", "complexity_tier": "T3", "furigana": "この論文[ろんぶん]は、高等[こうとう]な数学[すうがく]を使[つか]って理論[りろん]を証明[しょうめい]している。", "sentence_source": "generated"}, {"text": "先生は高等な技術を、やさしい言葉で説明してくれた。", "target_word": "高等", "complexity_tier": "T3", "furigana": "先生[せんせい]は高等[こうとう]な技術[ぎじゅつ]を、やさしい言葉[ことば]で説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "彼は高等な技術を身につけるまで、十年を費やした。", "target_word": "高等", "complexity_tier": "T3", "furigana": "彼[かれ]は高等[こうとう]な技術[ぎじゅつ]を身[み]につけるまで、十年[じゅうねん]を費[つい]やした。", "sentence_source": "generated"}, {"text": "大学院では高等な数学に取り組む学生が多い。", "target_word": "高等", "complexity_tier": "T3", "furigana": "大学院[だいがくいん]では高等[こうとう]な数学[すうがく]に取[と]り組[く]む学生[がくせい]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高等だ", "label": "終止形"}, {"form": "高等な", "label": "連体形"}, {"form": "高等に", "label": "連用形"}, {"form": "高等で", "label": "て形"}], "register": "neutral", "sense_fingerprint": "教育や技術などの水準が上級の段階にあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "「高等」は教育や技術の水準が上級であることで、この文の技術に合う。"}, {"text": "窮屈", "is_correct": false, "explanation": "「窮屈」は狭くて動きにくいことで、技術の水準を表す文には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は明るく快活な性格を表すので、技術を修飾すると意味が通らない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やか」は穏和で落ち着いた様子を表すので、技術の水準の文には合わない。"}], "explanations": {"高等": "「高等」は教育や技術の水準が上級であることで、この文の技術に合う。", "窮屈": "「窮屈」は狭くて動きにくいことで、技術の水準を表す文には合わない。", "陽気": "「陽気」は明るく快活な性格を表すので、技術を修飾すると意味が通らない。", "穏やか": "「穏やか」は穏和で落ち着いた様子を表すので、技術の水準の文には合わない。"}, "sentence_index": 0, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このコーヒーは高等な豆で、香りがよい。", "explanation": "ここは〈上等〉の意味。品質の良さは上等で言い、高等は教育や技術の水準を指すので合わない。"}, {"text": "この店の高等な家具は、とても値段が高い。", "explanation": "ここは〈高級〉の意味。値段が高く上質な品物は高級で言い、高等とは言わない。"}, {"text": "彼は高等な成績で卒業した。", "explanation": "ここは〈優秀〉の意味。成績の優れていることは優秀で言い、高等は水準の段階を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "「高等」は学問や技術の水準が上級であることで、数学を修飾する文に合う。"}, {"text": "手頃", "is_correct": false, "explanation": "「手頃」は値段や大きさが適当なことなので、数学の水準を表す文には合わない。"}, {"text": "愉快", "is_correct": false, "explanation": "「愉快」は楽しく気持ちがよいことで、数学の水準を表す文には合わない。"}, {"text": "賑やか", "is_correct": false, "explanation": "「賑やか」は人や物事が多く活気のある様子で、数学を修飾すると意味が通らない。"}], "explanations": {"高等": "「高等」は学問や技術の水準が上級であることで、数学を修飾する文に合う。", "手頃": "「手頃」は値段や大きさが適当なことなので、数学の水準を表す文には合わない。", "愉快": "「愉快」は楽しく気持ちがよいことで、数学の水準を表す文には合わない。", "賑やか": "「賑やか」は人や物事が多く活気のある様子で、数学を修飾すると意味が通らない。"}, "sentence_index": 6, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの先生は高等な人柄で、誰からも慕われる。", "explanation": "ここは〈高尚〉の意味。人柄の品位は高尚で言い、教育や技術の水準を指す高等は合わない。"}, {"text": "彼女は高等な手つきで、器用に料理を作る。", "explanation": "ここは〈熟練〉の意味。経験を積んだ腕前は熟練で言い、高等は水準の段階を指すので合わない。"}, {"text": "この時計は高等な部品で、狂いが少ない。", "explanation": "ここは〈精密〉の意味。部品の正確さは精密で言い、高等は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この大学院では高等だ化学を学べる。", "corrected_sentence": "この大学院では高等な化学を学べる。", "error_description": "形状詞は名詞の前で「な」の形にする。「高等だ」を名詞の前に置いたのが誤り。正しくは「高等な化学」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高等な", "is_correct": true, "explanation": "文中の形。連体形で後ろの「数学」を修飾している。"}, {"text": "高等だ", "is_correct": false, "explanation": "終止形。文を言い切る形で、名詞の前には置けない。"}, {"text": "高等に", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、名詞「数学」の前には使わない。"}, {"text": "高等で", "is_correct": false, "explanation": "て形。文をつなぐ形で、名詞を修飾する位置には合わない。"}], "correct_form": "高等な", "base_form": "高等だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"高等な": "文中の形。連体形で後ろの「数学」を修飾している。", "高等だ": "終止形。文を言い切る形で、名詞の前には置けない。", "高等に": "連用形。動詞を修飾する形で、名詞「数学」の前には使わない。", "高等で": "て形。文をつなぐ形で、名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は高等の工学を学び、大きな会社に入った。", "corrected_sentence": "彼女は高等な工学を学び、大きな会社に入った。", "error_description": "形状詞は名詞を修飾するとき「な」を使う。「高等の」は「の」を付けた誤りで、正しくは「高等な工学」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高等な", "is_correct": true, "explanation": "文中の形。連体形で後ろの「技術」を修飾している。"}, {"text": "高等だった", "is_correct": false, "explanation": "過去の終止形。文を言い切る形で、名詞の前には置けない。"}, {"text": "高等さ", "is_correct": false, "explanation": "名詞化した形。後ろの名詞「技術」を直接修飾できない。"}, {"text": "高等ならば", "is_correct": false, "explanation": "仮定形。条件を述べる形で、名詞を修飾する位置には合わない。"}], "correct_form": "高等な", "base_form": "高等だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"高等な": "文中の形。連体形で後ろの「技術」を修飾している。", "高等だった": "過去の終止形。文を言い切る形で、名詞の前には置けない。", "高等さ": "名詞化した形。後ろの名詞「技術」を直接修飾できない。", "高等ならば": "仮定形。条件を述べる形で、名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は動作が行われる場所を示し、「投稿できるプラットフォームで友だちを作った」と場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。ここでは「作った」の目的語「友だち」に付くので、場所には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、比べる対象がないので場所を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「作った」が起きる場所としては入らない。"}], "correct_answer": "で", "explanations": {"で": "「で」は動作が行われる場所を示し、「投稿できるプラットフォームで友だちを作った」と場所を表す。", "を": "「を」は動作の対象を示す。ここでは「作った」の目的語「友だち」に付くので、場所には使えない。", "より": "比較の「より」で、比べる対象がないので場所を示せない。", "へ": "「へ」は方向を示し、「作った」が起きる場所としては入らない。"}, "error_tags": {"を": "目的語の誤り", "より": "比較", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
