INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "インターネット上で、人が集まって作品を作ったり遊んだりする場。", "primary_collocate": null, "pronunciation": "ぷらっとふぉーむ", "ipa": "pɯɾattoɸoːmɯ", "syllable_count": 7, "sentences": [{"text": "このプラットフォームでは、世界中の人がゲームを作って遊べる。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "このプラットフォームでは、世界中[せかいじゅう]の人[ひと]がゲームを作[つく]って遊[あそ]べる。", "sentence_source": "generated"}, {"text": "子どもたちは、絵を投稿できるプラットフォームで友だちを作った。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、絵[え]を投稿[とうこう]できるプラットフォームで友[とも]だちを作[つく]った。", "sentence_source": "generated"}, {"text": "新しいプラットフォームに登録して、毎日音楽を発表している。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "新[あたら]しいプラットフォームに登録[とうろく]して、毎日[まいにち]音楽[おんがく]を発表[はっぴょう]している。", "sentence_source": "generated"}, {"text": "プラットフォームには、料理が好きな人がたくさん集まっている。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "プラットフォームには、料理[りょうり]が好[す]きな人[ひと]がたくさん集[あつ]まっている。", "sentence_source": "generated"}, {"text": "兄はプラットフォームで自分のゲームを公開して、感想をもらった。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "兄[あに]はプラットフォームで自分[じぶん]のゲームを公開[こうかい]して、感想[かんそう]をもらった。", "sentence_source": "generated"}, {"text": "このプラットフォームは無料なので、初心者でも気軽に作品を作れる。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "このプラットフォームは無料[むりょう]なので、初心者[しょしんしゃ]でも気軽[きがる]に作品[さくひん]を作[つく]れる。", "sentence_source": "generated"}, {"text": "学生が作品を見せ合うプラットフォームがあって、毎晩にぎやかだ。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "学生[がくせい]が作品[さくひん]を見[み]せ合[あ]うプラットフォームがあって、毎晩[まいばん]にぎやかだ。", "sentence_source": "generated"}, {"text": "年齢が違う人とも遊べるのが、このプラットフォームのいいところだ。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "年齢[ねんれい]が違[ちが]う人[ひと]とも遊[あそ]べるのが、このプラットフォームのいいところだ。", "sentence_source": "generated"}, {"text": "祖母は、手芸の作品を載せるプラットフォームで仲間を見つけた。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、手芸[しゅげい]の作品[さくひん]を載[の]せるプラットフォームで仲間[なかま]を見[み]つけた。", "sentence_source": "generated"}, {"text": "私はプラットフォームで知り合った人と、一緒に動画を作った。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "私[わたし]はプラットフォームで知[し]り合[あ]った人[ひと]と、一緒[いっしょ]に動画[どうが]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プラットフォーム", "label": "基本形"}, {"form": "プラットフォームで", "label": "場所を表す形"}], "register": "標準", "sense_fingerprint": "人が集まって作品を作ったり遊んだりできるインターネット上の場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プラットフォーム", "is_correct": true, "explanation": "「このプラットフォームでは」の名詞。ゲームや作品を作って遊べる場を指す。"}, {"text": "プラットフォームの", "is_correct": false, "explanation": "「この」の後に「の」が重なり、「では」につながらない。"}, {"text": "プラットフォームへ", "is_correct": false, "explanation": "「へ」は方向を示すので、「この」の後の名詞の位置には入らない。"}, {"text": "プラットフォームが", "is_correct": false, "explanation": "「が」は主語を示すが、「この」の後に入ると「では」と続かない。"}], "explanations": {"プラットフォーム": "「このプラットフォームでは」の名詞。ゲームや作品を作って遊べる場を指す。", "プラットフォームの": "「この」の後に「の」が重なり、「では」につながらない。", "プラットフォームへ": "「へ」は方向を示すので、「この」の後の名詞の位置には入らない。", "プラットフォームが": "「が」は主語を示すが、「この」の後に入ると「では」と続かない。"}, "sentence_index": 0, "correct_answer": "プラットフォーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車が来るまで、プラットフォームで十分も待った。", "explanation": "ここは〈駅の乗降場〉の意味。人が集まって作品を作ったり遊んだりする場の意味では合わない。"}, {"text": "倉庫では、荷物をプラットフォームに載せて運ぶ。", "explanation": "ここは〈荷物を載せる台〉の意味。人が集まって作ったり遊んだりする場の意味では合わない。"}, {"text": "厚底のプラットフォームを履いて、街を歩いた。", "explanation": "ここは〈厚底の靴底〉の意味。インターネット上で作品を作る場の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プラットフォーム", "is_correct": true, "explanation": "「作品を見せ合うプラットフォーム」の名詞。作品を見せ合える場を指す。"}, {"text": "プラットフォームを", "is_correct": false, "explanation": "「を」は目的語を示すので、「があって」の前の名詞の位置には入らない。"}, {"text": "プラットフォームで", "is_correct": false, "explanation": "「で」を入れると「見せ合うプラットフォームで」となり、「があって」と続かない。"}, {"text": "プラットフォームに", "is_correct": false, "explanation": "「に」は位置や対象を示すが、「があって」の前には入らない。"}], "explanations": {"プラットフォーム": "「作品を見せ合うプラットフォーム」の名詞。作品を見せ合える場を指す。", "プラットフォームを": "「を」は目的語を示すので、「があって」の前の名詞の位置には入らない。", "プラットフォームで": "「で」を入れると「見せ合うプラットフォームで」となり、「があって」と続かない。", "プラットフォームに": "「に」は位置や対象を示すが、「があって」の前には入らない。"}, "sentence_index": 6, "correct_answer": "プラットフォーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海上のプラットフォームに物資を運び、作業員が乗り降りした。", "explanation": "ここは〈海上の作業施設〉の意味。人が集まって作品を作ったり遊んだりするネット上の場の意味では合わない。"}, {"text": "この工場では、部品をプラットフォームに載せて運ぶ。", "explanation": "ここは〈荷物を載せる台〉の意味。人が集まって作ったり遊んだりする場の意味では合わない。"}, {"text": "彼女は厚底のプラットフォームを履いて、背を高く見せた。", "explanation": "ここは〈厚底の靴底〉の意味。人が集まって作ったり遊んだりする場の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このプラットフォームを参加すれば、絵の好きな人と作品を見せ合える。", "corrected_sentence": "このプラットフォームに参加すれば、絵の好きな人と作品を見せ合える。", "error_description": "誤：「プラットフォームを」（助詞「を」）→正：「プラットフォームに」（「に」）。「参加する」は「に」で集まる先を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は、プラットフォームを絵を描く人を探した。", "corrected_sentence": "妹は、プラットフォームで絵を描く人を探した。", "error_description": "誤：「プラットフォームを」（助詞「を」）→正：「プラットフォームで」（場所を示す「で」）。「を」は「探す」の目的語の人にだけ付く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
