INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53480, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うための基盤となる場所や仕組み。特にデジタル技術を使ってサービスを提供したり、人々をつなげたりするシステムのこと。", "primary_collocate": null, "pronunciation": "ぷらっとふぉーむ", "ipa": "pɯɾattoɸoːmɯ", "syllable_count": 7, "sentences": [{"text": "利用者の情報を一元管理するプラットフォームの導入は、業務の効率を大きく高める。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "利用者[りようしゃ]の情報[じょうほう]を一元[いちげん]管理[かんり]するプラットフォームの導入[どうにゅう]は、業務[ぎょうむ]の効率[こうりつ]を大きく高[たか]める。", "sentence_source": "generated"}, {"text": "この会社は、学習者と先生をつなぐプラットフォームを開発した。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、学習者[がくしゅうしゃ]と先生[せんせい]をつなぐプラットフォームを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "動画を配信するプラットフォームが増えて、誰でも番組を作れるようになった。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "動画[どうが]を配信[はいしん]するプラットフォームが増[ふ]えて、誰[だれ]でも番組[ばんぐみ]を作[つく]れるようになった。", "sentence_source": "generated"}, {"text": "新しいプラットフォームを使えば、遠くの店の商品もスマホで買える。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "新[あたら]しいプラットフォームを使[つか]えば、遠[とお]くの店[みせ]の商品[しょうひん]もスマホで買[か]える。", "sentence_source": "generated"}, {"text": "市は、住民が情報を共有できるプラットフォームを作る予定だ。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "市[し]は、住民[じゅうみん]が情報[じょうほう]を共有[きょうゆう]できるプラットフォームを作[つく]る予定[よてい]だ。", "sentence_source": "generated"}, {"text": "大きなプラットフォームに頼りすぎると、規則が変わったときに困る。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "大[おお]きなプラットフォームに頼[たよ]りすぎると、規則[きそく]が変[か]わったときに困[こま]る。", "sentence_source": "generated"}, {"text": "このプラットフォームでは、世界中の翻訳者が仕事を探せる。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "このプラットフォームでは、世界中[せかいじゅう]の翻訳者[ほんやくしゃ]が仕事[しごと]を探[さが]せる。", "sentence_source": "generated"}, {"text": "利用者が増えたので、プラットフォームの運営会社は安全対策を強めた。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "利用者[りようしゃ]が増[ふ]えたので、プラットフォームの運営[うんえい]会社[がいしゃ]は安全[あんぜん]対策[たいさく]を強[つよ]めた。", "sentence_source": "generated"}, {"text": "農家が直接野菜を売れるプラットフォームのおかげで、収入が安定した。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "農家[のうか]が直接[ちょくせつ]野菜[やさい]を売[う]れるプラットフォームのおかげで、収入[しゅうにゅう]が安定[あんてい]した。", "sentence_source": "generated"}, {"text": "医療のプラットフォームを整えれば、病院どうしで患者の情報を確認しやすくなる。", "target_word": "プラットフォーム", "complexity_tier": "T3", "furigana": "医療[いりょう]のプラットフォームを整[ととの]えれば、病院[びょういん]どうしで患者[かんじゃ]の情報[じょうほう]を確認[かくにん]しやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プラットフォーム", "label": "基本形"}, {"form": "プラットフォームの", "label": "連体形"}], "register": "標準", "sense_fingerprint": "サービス提供や人のつながりの基盤となるデジタルの仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プラットフォーム", "is_correct": true, "explanation": "「アダプティブラーニングプラットフォーム」の末尾。学習の仕組みを提供する基盤を指す名詞の形。"}, {"text": "プラットフォームで", "is_correct": false, "explanation": "「で」を入れると「の導入」に続かず、名詞の形にならない。"}, {"text": "プラットフォームに", "is_correct": false, "explanation": "「に」の後に「の導入」が続かず、導入の対象を示せない。"}, {"text": "プラットフォームを", "is_correct": false, "explanation": "「を」は動詞の目的語を示すので、名詞「導入」を修飾する位置には入らない。"}], "explanations": {"プラットフォーム": "「アダプティブラーニングプラットフォーム」の末尾。学習の仕組みを提供する基盤を指す名詞の形。", "プラットフォームで": "「で」を入れると「の導入」に続かず、名詞の形にならない。", "プラットフォームに": "「に」の後に「の導入」が続かず、導入の対象を示せない。", "プラットフォームを": "「を」は動詞の目的語を示すので、名詞「導入」を修飾する位置には入らない。"}, "sentence_index": 0, "correct_answer": "プラットフォーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車が遅れて、プラットフォームで十分も待った。", "explanation": "ここは〈駅の乗降場〉の意味。デジタルの基盤を指す今回の意味では、電車を待つ場所の話は合わない。"}, {"text": "講師は、教室の前のプラットフォームに立って、説明を始めた。", "explanation": "ここは〈演台〉の意味（人が立つ高い台）。基盤となる仕組みの意味では合わない。"}, {"text": "その候補者は、子育て支援を掲げたプラットフォームで選挙に勝った。", "explanation": "ここは〈政策の綱領〉の意味。デジタルの仕組みを指す今回の意味では、政策の方針の使い方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プラットフォーム", "is_correct": true, "explanation": "「このプラットフォームでは」の名詞。ネット上で仕事を探せる仕組みを指す。"}, {"text": "プラットフォームの", "is_correct": false, "explanation": "「この」の後に「の」が重なり、「では」につながらない。"}, {"text": "プラットフォームが", "is_correct": false, "explanation": "「が」は主語を示すが、「この」の後に入ると「では」と続かず不自然。"}, {"text": "プラットフォームへ", "is_correct": false, "explanation": "「へ」は方向を示すので、「この」の後の名詞の位置には入らない。"}], "explanations": {"プラットフォーム": "「このプラットフォームでは」の名詞。ネット上で仕事を探せる仕組みを指す。", "プラットフォームの": "「この」の後に「の」が重なり、「では」につながらない。", "プラットフォームが": "「が」は主語を示すが、「この」の後に入ると「では」と続かず不自然。", "プラットフォームへ": "「へ」は方向を示すので、「この」の後の名詞の位置には入らない。"}, "sentence_index": 6, "correct_answer": "プラットフォーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、靴のプラットフォームを高くして背を伸ばした。", "explanation": "ここは〈厚底の靴底〉の意味。基盤となる場所や仕組みの意味では合わない。"}, {"text": "彼は毎日、台所のプラットフォームで野菜を切った。", "explanation": "ここは〈調理台〉の意味（物を置く台）。基盤となる仕組みの意味では合わない。"}, {"text": "彼は舞台のプラットフォームに立って、観客に挨拶した。", "explanation": "ここは〈演台〉の意味（人が立つ高い台）。基盤となる仕組みの意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の窓口は、住民をつなぐプラットフォームに整えた。", "corrected_sentence": "市の窓口は、住民をつなぐプラットフォームを整えた。", "error_description": "誤：「プラットフォームに」（助詞「に」）→正：「プラットフォームを」（「を」）。「整える」は目的語に「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
