INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「いる」の場所を表すので「に」。"}, {"text": "を", "is_correct": false, "explanation": "「いる」は目的語を取らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」では「いる」につながらない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は並列の助詞で、ここでは文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「いる」の場所を表すので「に」。", "を": "「いる」は目的語を取らない。", "の": "「の」では「いる」につながらない。", "や": "「や」は並列の助詞で、ここでは文が成り立たない。"}, "error_tags": {"を": "object_marker", "の": "possessive", "や": "listing"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
