INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53481, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "太陽の光があたってあたたかい場所です。", "primary_collocate": null, "pronunciation": "ひだまり", "ipa": "çidamaɾi", "syllable_count": 4, "sentences": [{"text": "陽だまりはあたたかい。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "陽[ひ]だまりはあたたかい。", "sentence_source": "generated"}, {"text": "犬が陽だまりにいる。", "target_word": "陽だまり", "complexity_tier": "T1", "furigana": "犬[いぬ]が陽[ひ]だまりにいる。", "sentence_source": "generated"}, {"text": "陽だまりで休みます。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "陽[ひ]だまりで休[やす]みます。", "sentence_source": "generated"}, {"text": "公園に陽だまりがあります。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "公園[こうえん]に陽[ひ]だまりがあります。", "sentence_source": "generated"}, {"text": "私は陽だまりが好きです。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "私[わたし]は陽[ひ]だまりが好[す]きです。", "sentence_source": "generated"}, {"text": "陽だまりの椅子に座った。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "陽[ひ]だまりの椅子[いす]に座[すわ]った。", "sentence_source": "generated"}, {"text": "子どもが陽だまりで遊んでいる。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "子[こ]どもが陽[ひ]だまりで遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "朝、陽だまりを見つけました。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "朝[あさ]、陽[ひ]だまりを見[み]つけました。", "sentence_source": "generated"}, {"text": "冬の陽だまりは気持ちがいい。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "冬[ふゆ]の陽[ひ]だまりは気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "陽だまりで洗濯物を乾かした。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "陽[ひ]だまりで洗濯物[せんたくもの]を乾[かわ]かした。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 日が当たるあたたかい場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陽だまり", "is_correct": true, "explanation": "日が当たる場所はあたたかいので意味が合う。"}, {"text": "日陰", "is_correct": false, "explanation": "形は合うが、日陰は涼しい場所なので意味が合わない。"}, {"text": "氷", "is_correct": false, "explanation": "形は合うが、氷は冷たいので意味が合わない。"}, {"text": "夜道", "is_correct": false, "explanation": "形は合うが、夜道はあたたかいという意味が合わない。"}], "explanations": {"陽だまり": "日が当たる場所はあたたかいので意味が合う。", "日陰": "形は合うが、日陰は涼しい場所なので意味が合わない。", "氷": "形は合うが、氷は冷たいので意味が合わない。", "夜道": "形は合うが、夜道はあたたかいという意味が合わない。"}, "sentence_index": 0, "correct_answer": "陽だまり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "陽だまりは冷たい水の中にあります。", "explanation": "陽だまりは日光が当たる場所で、冷たい水の中にはない。"}, {"text": "私は毎朝陽だまりを食べます。", "explanation": "陽だまりは場所なので、食べ物としては使えない。"}, {"text": "陽だまりが電話で話しています。", "explanation": "陽だまりは場所なので、話す主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陽だまり", "is_correct": true, "explanation": "子どもが遊ぶ温かい場所として意味が合う。"}, {"text": "冷凍庫", "is_correct": false, "explanation": "形は合うが、子どもが遊ぶ場所としては意味が合わない。"}, {"text": "会議", "is_correct": false, "explanation": "形は合うが、子どもが遊ぶ場面としては意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、遊ぶ場面としては意味が合わない。"}], "explanations": {"陽だまり": "子どもが遊ぶ温かい場所として意味が合う。", "冷凍庫": "形は合うが、子どもが遊ぶ場所としては意味が合わない。", "会議": "形は合うが、子どもが遊ぶ場面としては意味が合わない。", "地震": "形は合うが、遊ぶ場面としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "陽だまり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真っ暗な地下室の陽だまりで本を読んだ。", "explanation": "陽だまりは日が当たる場所なので、真っ暗な地下室とは合わない。"}, {"text": "陽だまりを机の上に置いた。", "explanation": "陽だまりは場所で、机の上に置ける物ではない。"}, {"text": "陽だまりは先生に宿題を出した。", "explanation": "陽だまりは場所なので、宿題を出す主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
