INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53482, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「座る」の場所を表すので「に」。"}, {"text": "を", "is_correct": false, "explanation": "「座る」の場所を「を」では表さない。"}, {"text": "の", "is_correct": false, "explanation": "「の」では「座ると」につながらない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は並列の助詞で、この位置では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「座る」の場所を表すので「に」。", "を": "「座る」の場所を「を」では表さない。", "の": "「の」では「座ると」につながらない。", "や": "「や」は並列の助詞で、この位置では文が成り立たない。"}, "error_tags": {"を": "object_marker", "の": "possessive", "や": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53482, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "太陽の光が直接当たって、温かく感じられる場所。", "primary_collocate": null, "pronunciation": "ひだまり", "ipa": "çidamaɾi", "syllable_count": 4, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "陽だまり", "complexity_tier": "T6", "furigana": "陽[ひ]だまりの縁側[えんがわ]にて、幼[おさな]き童子[どうじ]は陶器[とうき]の鉢[はち]に植[う]えられた一株[ひとかぶ]の植物[しょくぶつ]へと、無心[むしん]なる眼差[まなざ]しを注[そそ]いでいる。", "sentence_source": "mined"}, {"text": "猫が陽だまりで寝ている。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "猫[ねこ]が陽[ひ]だまりで寝[ね]ている。", "sentence_source": "generated"}, {"text": "陽だまりは温かいです。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "陽[ひ]だまりは温[あたた]かいです。", "sentence_source": "generated"}, {"text": "冬は陽だまりが恋しい。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "冬[ふゆ]は陽[ひ]だまりが恋[こい]しい。", "sentence_source": "generated"}, {"text": "窓の下に陽だまりができた。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "窓[まど]の下[した]に陽[ひ]だまりができた。", "sentence_source": "generated"}, {"text": "私は陽だまりを探して歩いた。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "私[わたし]は陽[ひ]だまりを探[さが]して歩[ある]いた。", "sentence_source": "generated"}, {"text": "陽だまりの中で本を読みたい。", "target_word": "陽だまり", "complexity_tier": "T2", "furigana": "陽[ひ]だまりの中[なか]で本[ほん]を読[よ]みたい。", "sentence_source": "generated"}, {"text": "陽だまりに座ると、眠くなってしまった。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "陽[ひ]だまりに座[すわ]ると、眠[ねむ]くなってしまった。", "sentence_source": "generated"}, {"text": "雲が動いて、陽だまりが少しずつ消えていった。", "target_word": "陽だまり", "complexity_tier": "T3", "furigana": "雲[くも]が動[うご]いて、陽[ひ]だまりが少[すこ]しずつ消[き]えていった。", "sentence_source": "generated"}, {"text": "老人たちは公園の陽だまりに集まって話していた。", "target_word": "陽だまり", "complexity_tier": "T4", "furigana": "老人[ろうじん]たちは公園[こうえん]の陽[ひ]だまりに集[あつ]まって話[はな]していた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 日光が当たって温かい場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陽だまり", "is_correct": true, "explanation": "日が当たって温かい縁側の場所という意味で合う。"}, {"text": "夕立", "is_correct": false, "explanation": "形は合うが、縁側の説明としては意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、縁側と結びつかず意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、場所を表す縁側の修飾としては意味が合わない。"}], "explanations": {"陽だまり": "日が当たって温かい縁側の場所という意味で合う。", "夕立": "形は合うが、縁側の説明としては意味が合わない。", "電車": "形は合うが、縁側と結びつかず意味が合わない。", "約束": "形は合うが、場所を表す縁側の修飾としては意味が合わない。"}, "sentence_index": 0, "correct_answer": "陽だまり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の暗い道で、陽だまりに座って星を見た。", "explanation": "陽だまりは日光が当たる場所なので、夜の暗い道に使うのは誤り。"}, {"text": "陽だまりを買いに店へ行った。", "explanation": "陽だまりは場所であり、店で買える品物ではない。"}, {"text": "陽だまりが急に怒って大声を出した。", "explanation": "陽だまりは場所なので、怒る主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陽だまり", "is_correct": true, "explanation": "温かい日だまりの中で本を読みたいという意味で合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「中で本を読む」の場所としては意味が合わない。"}, {"text": "洪水", "is_correct": false, "explanation": "形は合うが、本を読みたい場所として意味が合わない。"}, {"text": "計算", "is_correct": false, "explanation": "形は合うが、「～の中で本を読む」という意味が合わない。"}], "explanations": {"陽だまり": "温かい日だまりの中で本を読みたいという意味で合う。", "約束": "形は合うが、「中で本を読む」の場所としては意味が合わない。", "洪水": "形は合うが、本を読みたい場所として意味が合わない。", "計算": "形は合うが、「～の中で本を読む」という意味が合わない。"}, "sentence_index": 6, "correct_answer": "陽だまり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陽だまりは寒いので、冬は近づかない。", "explanation": "陽だまりは温かい場所なので、「寒い」は意味が合わない。"}, {"text": "陽だまりを財布に入れて持ち歩いている。", "explanation": "陽だまりは場所で、財布に入れて持ち歩けるものではない。"}, {"text": "陽だまりが宿題を忘れて先生に叱られた。", "explanation": "陽だまりは場所なので、人のように行動する主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "縁側の陽だまりを昼寝した。", "corrected_sentence": "縁側の陽だまりで昼寝した。", "error_description": "陽だまりは昼寝をする場所なので、「を」ではなく場所を表す「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
