INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始める」の目的語として「ガーデニングを」が続き、自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「ガーデニングが始めてから」は「始める」の目的語にならず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ガーデニングに始める」は成り立たず、方向や相手を表す格としても合わない。"}, {"text": "と", "is_correct": false, "explanation": "「ガーデニングと始める」は並列の意味にならず、動詞「始める」とつながらない。"}], "correct_answer": "を", "explanations": {"を": "「始める」の目的語として「ガーデニングを」が続き、自然な文になる。", "が": "「ガーデニングが始めてから」は「始める」の目的語にならず、不自然。", "に": "「ガーデニングに始める」は成り立たず、方向や相手を表す格としても合わない。", "と": "「ガーデニングと始める」は並列の意味にならず、動詞「始める」とつながらない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "方向・相手", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ガーデニングの道具」は所属や修飾を表し、道具の種類を示す自然な言い方になる。"}, {"text": "が", "is_correct": false, "explanation": "「ガーデニングが道具を」は主語になり、道具を修飾する関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「ガーデニングを道具を」は目的語が二重になり、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「ガーデニングで道具を」は手段の意味になり、道具を修飾する関係とは合わない。"}], "correct_answer": "の", "explanations": {"の": "「ガーデニングの道具」は所属や修飾を表し、道具の種類を示す自然な言い方になる。", "が": "「ガーデニングが道具を」は主語になり、道具を修飾する関係が成り立たない。", "を": "「ガーデニングを道具を」は目的語が二重になり、不自然。", "で": "「ガーデニングで道具を」は手段の意味になり、道具を修飾する関係とは合わない。"}, "error_tags": {"の": "所属・修飾", "が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "はなや野菜をそだてて、庭をきれいにする活動です。", "primary_collocate": null, "pronunciation": "がーでにんぐ", "ipa": "ɡaːdeniŋɡɯ", "syllable_count": 6, "sentences": [{"text": "祖母はガーデニングで、毎年きれいな花を咲かせます。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "祖母[そぼ]はガーデニングで、毎年[まいとし]きれいな花[はな]を咲[さ]かせます。", "sentence_source": "generated"}, {"text": "ガーデニングを始めてから、庭が明るくなりました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングを始[はじ]めてから、庭[にわ]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "父はガーデニングが好きで、野菜も育てています。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "父[ちち]はガーデニングが好[す]きで、野菜[やさい]も育[そだ]てています。", "sentence_source": "generated"}, {"text": "日曜日の朝は、ガーデニングをして過ごします。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]は、ガーデニングをして過[す]ごします。", "sentence_source": "generated"}, {"text": "ガーデニングは土をさわるので、手袋が必要です。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングは土[つち]をさわるので、手袋[てぶくろ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "雨が続いたので、今週はガーデニングができませんでした。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたので、今週[こんしゅう]はガーデニングができませんでした。", "sentence_source": "generated"}, {"text": "隣の家はガーデニングが上手で、いつも花でいっぱいです。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]はガーデニングが上手[じょうず]で、いつも花[はな]でいっぱいです。", "sentence_source": "generated"}, {"text": "ガーデニングの道具を、ホームセンターで買いました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングの道具[どうぐ]を、ホームセンターで買[か]いました。", "sentence_source": "generated"}, {"text": "私はガーデニングで育てたトマトを食べました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "私[わたし]はガーデニングで育[そだ]てたトマトを食[た]べました。", "sentence_source": "generated"}, {"text": "ガーデニングに興味があるなら、まず小さい花から始めましょう。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングに興味[きょうみ]があるなら、まず小[ちい]さい花[はな]から始[はじ]めましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガーデニング", "label": "基本形"}], "register": "標準", "sense_fingerprint": "花や野菜を育てて庭を美しくする活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガーデニング", "is_correct": true, "explanation": "「ガーデニングで」は手段を表し、庭仕事で花を咲かせるという文脈に合う。"}, {"text": "料理", "is_correct": false, "explanation": "「料理で花を咲かせる」は意味が通らず、この空欄には入らない。"}, {"text": "登山", "is_correct": false, "explanation": "「登山で花を咲かせる」は不自然で、花を育てる文脈とつながらない。"}, {"text": "水泳", "is_correct": false, "explanation": "「水泳で花を咲かせる」は成り立たず、この文の内容と結びつかない。"}], "explanations": {"ガーデニング": "「ガーデニングで」は手段を表し、庭仕事で花を咲かせるという文脈に合う。", "料理": "「料理で花を咲かせる」は意味が通らず、この空欄には入らない。", "登山": "「登山で花を咲かせる」は不自然で、花を育てる文脈とつながらない。", "水泳": "「水泳で花を咲かせる」は成り立たず、この文の内容と結びつかない。"}, "sentence_index": 0, "correct_answer": "ガーデニング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風で、家のガーデニングが割れた。", "explanation": "ここは〈窓ガラス〉（物）の意味。ガーデニングは活動なので、割れる物には使わない。"}, {"text": "この農園では、ガーデニングを毎日散布している。", "explanation": "ここは〈農薬〉の意味。ガーデニングは散布できる物質ではなく、活動を指す語なので合わない。"}, {"text": "庭では、ガーデニングを刈るのが週末の仕事だ。", "explanation": "ここは〈芝生〉の意味。ガーデニングは刈る対象の草ではないので、「刈る」の目的語には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガーデニング", "is_correct": true, "explanation": "「ガーデニングが上手」は自然な言い方で、庭いっぱいの花を育てる文脈に合う。"}, {"text": "電池", "is_correct": false, "explanation": "「電池が上手」は意味をなさず、この空欄には入らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震が上手」は成り立たず、花でいっぱいの庭という文脈とも結びつかない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧が上手」は不自然で、庭の花の話題とは関係がない。"}], "explanations": {"ガーデニング": "「ガーデニングが上手」は自然な言い方で、庭いっぱいの花を育てる文脈に合う。", "電池": "「電池が上手」は意味をなさず、この空欄には入らない。", "地震": "「地震が上手」は成り立たず、花でいっぱいの庭という文脈とも結びつかない。", "霧": "「霧が上手」は不自然で、庭の花の話題とは関係がない。"}, "sentence_index": 6, "correct_answer": "ガーデニング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週は隣のクラスとガーデニングを対戦する。", "explanation": "ここは〈試合・勝負〉の意味。ガーデニングは勝ち負けを争う活動ではないので、対戦の相手にはならない。"}, {"text": "朝はいつも音楽のかわりにガーデニングを聴く。", "explanation": "ここは〈音〉の意味。ガーデニングは音ではないので、聴くものとしては使えない。"}, {"text": "川へ行って、ガーデニングを釣ってきた。", "explanation": "ここは〈魚〉の意味。ガーデニングは生き物ではないので、釣れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄はガーデニングを好きで、週末は花を育てています。", "corrected_sentence": "兄はガーデニングが好きで、週末は花を育てています。", "error_description": "「好き」の前に来る助詞は「が」。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉はガーデニングの上手で、毎朝花に水をやります。", "corrected_sentence": "姉はガーデニングが上手で、毎朝花に水をやります。", "error_description": "「上手」の前に来る助詞は「が」。「の」は誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「仕事にする」の対象として「ガーデニングを」が続き、文が自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「ガーデニングが仕事にして」は対象を正しく示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「ガーデニングで仕事にして」は手段の意味になり、「仕事にする」とはつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「ガーデニングと仕事にして」は並列の意味になり、この文の意味に合わない。"}], "correct_answer": "を", "explanations": {"を": "「仕事にする」の対象として「ガーデニングを」が続き、文が自然になる。", "が": "「ガーデニングが仕事にして」は対象を正しく示せず、不自然。", "で": "「ガーデニングで仕事にして」は手段の意味になり、「仕事にする」とはつながらない。", "と": "「ガーデニングと仕事にして」は並列の意味になり、この文の意味に合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・材料", "と": "共同・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ガーデニングは」で話題を示し、工夫すれば可能だという文の主題として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「ガーデニングをできます」は目的語の格として成り立たず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ガーデニングと」は並列を作るが、「できます」と続けると文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ガーデニングのできます」は名詞に続く形で、述語「できます」と結びつかない。"}], "correct_answer": "は", "explanations": {"は": "「ガーデニングは」で話題を示し、工夫すれば可能だという文の主題として自然に続く。", "を": "「ガーデニングをできます」は目的語の格として成り立たず、不自然。", "と": "「ガーデニングと」は並列を作るが、「できます」と続けると文として成り立たない。", "の": "「ガーデニングのできます」は名詞に続く形で、述語「できます」と結びつかない。"}, "error_tags": {"は": "主題", "を": "目的語", "と": "並列", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "庭やプランターで植物を育て、お手入れをする趣味や仕事のことです。", "primary_collocate": null, "pronunciation": "がーでにんぐ", "ipa": "ɡaːdeniŋɡɯ", "syllable_count": 6, "sentences": [{"text": "ベランダでも、プランターがあればガーデニングを楽しめます。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ベランダでも、プランターがあればガーデニングを楽[たの]しめます。", "sentence_source": "generated"}, {"text": "叔母はガーデニングを仕事にして、花の育て方を教えています。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "叔母[おば]はガーデニングを仕事[しごと]にして、花[はな]の育[そだ]て方[かた]を教[おし]えています。", "sentence_source": "generated"}, {"text": "忙しい人には、ガーデニングは気持ちが休まる趣味です。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "忙[いそが]しい人[ひと]には、ガーデニングは気持[きも]ちが休[やす]まる趣味[しゅみ]です。", "sentence_source": "generated"}, {"text": "ガーデニングのおかげで、毎日植物の世話をする習慣がつきました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングのおかげで、毎日[まいにち]植物[しょくぶつ]の世話[せわ]をする習慣[しゅうかん]がつきました。", "sentence_source": "generated"}, {"text": "夏はこまめに水をやることが、ガーデニングでは大切です。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "夏[なつ]はこまめに水[みず]をやることが、ガーデニングでは大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "最近、若い人の間でもガーデニングが人気になっています。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "最近[さいきん]、若[わか]い人[ひと]の間[あいだ]でもガーデニングが人気[にんき]になっています。", "sentence_source": "generated"}, {"text": "彼はガーデニングの本を読んで、ハーブを育て始めました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "彼[かれ]はガーデニングの本[ほん]を読[よ]んで、ハーブを育[そだ]て始[はじ]めました。", "sentence_source": "generated"}, {"text": "狭い庭でも、工夫すればガーデニングはできます。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "狭[せま]い庭[にわ]でも、工夫[くふう]すればガーデニングはできます。", "sentence_source": "generated"}, {"text": "ガーデニングの会に入って、友だちが増えました。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "ガーデニングの会[かい]に入[はい]って、友[とも]だちが増[ふ]えました。", "sentence_source": "generated"}, {"text": "祖父は退職後、ガーデニングに毎日時間を使っています。", "target_word": "ガーデニング", "complexity_tier": "T3", "furigana": "祖父[そふ]は退職後[たいしょくご]、ガーデニングに毎日[まいにち]時間[じかん]を使[つか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガーデニング", "label": "基本形"}], "register": "標準", "sense_fingerprint": "庭やプランターで植物を育てて世話をする趣味・仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガーデニング", "is_correct": true, "explanation": "「ガーデニングを楽しめます」は自然で、植物を育てる趣味の文脈に合う。"}, {"text": "地震", "is_correct": false, "explanation": "「地震を楽しめます」は成り立たず、ベランダの趣味の話とも関係がない。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音を楽しめます」は不自然で、趣味を述べる文には入らない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電を楽しめます」は意味をなさず、この空欄には入らない。"}], "explanations": {"ガーデニング": "「ガーデニングを楽しめます」は自然で、植物を育てる趣味の文脈に合う。", "地震": "「地震を楽しめます」は成り立たず、ベランダの趣味の話とも関係がない。", "騒音": "「騒音を楽しめます」は不自然で、趣味を述べる文には入らない。", "停電": "「停電を楽しめます」は意味をなさず、この空欄には入らない。"}, "sentence_index": 0, "correct_answer": "ガーデニング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎朝、ガーデニングを掃除機でかけている。", "explanation": "ここは〈掃除〉の意味。ガーデニングは植物を育てる活動で、掃除機をかける対象にはならない。"}, {"text": "家の水道が古いので、ガーデニングを修理した。", "explanation": "ここは〈水道などの設備〉の意味。ガーデニングは活動なので、修理の対象にはならない。"}, {"text": "姉は毎晩、ガーデニングを演奏して気分を変える。", "explanation": "ここは〈楽器・音楽〉の意味。ガーデニングは演奏できるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガーデニング", "is_correct": true, "explanation": "「ガーデニングの本」は園芸の本を指し、ハーブを育て始めるという文脈に合う。"}, {"text": "午後", "is_correct": false, "explanation": "「午後の本」では内容が特定できず、この空欄には入らない。"}, {"text": "夕立", "is_correct": false, "explanation": "「夕立の本」は不自然で、ハーブを育てる話題とつながらない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊の本」は意味をなさず、この文の内容とも関係がない。"}], "explanations": {"ガーデニング": "「ガーデニングの本」は園芸の本を指し、ハーブを育て始めるという文脈に合う。", "午後": "「午後の本」では内容が特定できず、この空欄には入らない。", "夕立": "「夕立の本」は不自然で、ハーブを育てる話題とつながらない。", "寝坊": "「寝坊の本」は意味をなさず、この文の内容とも関係がない。"}, "sentence_index": 6, "correct_answer": "ガーデニング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は退職後、ガーデニングを毎日食べている。", "explanation": "ここは〈食べ物〉の意味。ガーデニングは食べられる物ではないので合わない。"}, {"text": "祖父は退職後、ガーデニングを眼鏡のようにかけて過ごしている。", "explanation": "ここは〈眼鏡〉の意味。ガーデニングは身につけられる物ではないので合わない。"}, {"text": "祖父は退職後、毎朝ガーデニングに乗って買い物へ行く。", "explanation": "ここは〈乗り物〉の意味。ガーデニングは乗れるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は週末、ガーデニングの楽しめて、毎朝庭の手入れをしています。", "corrected_sentence": "祖父は週末、ガーデニングを楽しめて、毎朝庭の手入れをしています。", "error_description": "「楽しめる」の目的語は助詞「を」で示す。「の」は文が成り立たないので誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53484, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉はガーデニングを興味があって、週末に庭の手入れをしています。", "corrected_sentence": "姉はガーデニングに興味があって、週末に庭の手入れをしています。", "error_description": "「興味がある」に続く助詞は「に」。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
