INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとのいちばんたいせつなところを、まるごとあたらしいものにすることです。", "primary_collocate": null, "pronunciation": "ばっぽん", "ipa": "bappoɴ", "syllable_count": 4, "sentences": [{"text": "古い規則では問題が解決しないので、抜本的に作り直すことにした。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "古[ふる]い規則[きそく]では問題[もんだい]が解決[かいけつ]しないので、抜本的[ばっぽんてき]に作[つく]り直[なお]すことにした。", "sentence_source": "generated"}, {"text": "この会社は売り上げが落ち続け、抜本的な改革が必要になった。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は売[う]り上[あ]げが落[お]ち続[つづ]け、抜本的[ばっぽんてき]な改革[かいかく]が必要[ひつよう]になった。", "sentence_source": "generated"}, {"text": "家の古い設計を抜本的に変えて、家族みんなが使いやすくした。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "家[いえ]の古[ふる]い設計[せっけい]を抜本的[ばっぽんてき]に変[か]えて、家族[かぞく]みんなが使[つか]いやすくした。", "sentence_source": "generated"}, {"text": "小手先の直しではなく、抜本的な方法で問題を解決したい。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "小手先[こてさき]の直[なお]しではなく、抜本的[ばっぽんてき]な方法[ほうほう]で問題[もんだい]を解決[かいけつ]したい。", "sentence_source": "generated"}, {"text": "市は交通の仕組みを抜本的に見直す計画を発表した。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "市[し]は交通[こうつう]の仕組[しく]みを抜本的[ばっぽんてき]に見直[みなお]す計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "授業のやり方を抜本的に変えたら、生徒の成績が上がった。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]のやり方[かた]を抜本的[ばっぽんてき]に変[か]えたら、生徒[せいと]の成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}, {"text": "手直しだけでは足りない。抜本的な対策が求められている。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "手直[てなお]しだけでは足[た]りない。抜本的[ばっぽんてき]な対策[たいさく]が求[もと]められている。", "sentence_source": "generated"}, {"text": "店は赤字が続いたため、メニューを抜本的に入れ替えた。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "店[みせ]は赤字[あかじ]が続[つづ]いたため、メニューを抜本的[ばっぽんてき]に入[い]れ替[か]えた。", "sentence_source": "generated"}, {"text": "彼は、自分の生活習慣を抜本的に変える決意をした。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "彼[かれ]は、自分[じぶん]の生活習慣[せいかつしゅうかん]を抜本的[ばっぽんてき]に変[か]える決意[けつい]をした。", "sentence_source": "generated"}, {"text": "会議では、小さな修正より抜本的な改善を優先すべきだという意見が出た。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、小[ちい]さな修正[しゅうせい]より抜本的[ばっぽんてき]な改善[かいぜん]を優先[ゆうせん]すべきだという意見[いけん]が出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抜本", "label": "基本形"}, {"form": "抜本的", "label": "的がついた形"}], "register": "やや硬い", "sense_fingerprint": "大事な部分をまるごと新しくするさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抜本的", "is_correct": true, "explanation": "「根本から作り直す」という意味で、問題の解決に合う。"}, {"text": "一時的", "is_correct": false, "explanation": "〈一時的〉は一時的な対応の意味で、根本から作り直す文脈には合わない。"}, {"text": "空想的", "is_correct": false, "explanation": "〈空想的〉は現実離れしたさまを表し、作り直す方法としては合わない。"}, {"text": "表面的", "is_correct": false, "explanation": "〈表面的〉は見た目だけの対応で、問題が解決しないので根本から作り直す文脈には合わない。"}], "explanations": {"抜本的": "「根本から作り直す」という意味で、問題の解決に合う。", "一時的": "〈一時的〉は一時的な対応の意味で、根本から作り直す文脈には合わない。", "空想的": "〈空想的〉は現実離れしたさまを表し、作り直す方法としては合わない。", "表面的": "〈表面的〉は見た目だけの対応で、問題が解決しないので根本から作り直す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "抜本的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は抜本的な成績で、学年一位になった。", "explanation": "ここは〈抜群〉の意味。「抜群の成績」とは言うが、〈抜本的〉は根本から変えることなので、優れた成績の意味では使えない。"}, {"text": "応急処置として、抜本的な対策で、とりあえず水漏れを止めた。", "explanation": "ここは〈一時的〉の意味。〈抜本的〉は根本から変えることで、応急処置としてのしのぎとは合わない。"}, {"text": "まずは抜本的な決まりを覚えてから、応用に進む。", "explanation": "ここは〈基本的〉の意味。〈抜本的〉は根本からすべてを変える意味で、基礎となる決まりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抜本的", "is_correct": true, "explanation": "「根本から対策を立てる」という意味で、手直しでは足りないという文脈に合う。"}, {"text": "宗教的", "is_correct": false, "explanation": "〈宗教的〉は宗教に関するさまで、「宗教的な対策」は文脈に合わない。"}, {"text": "芸術的", "is_correct": false, "explanation": "〈芸術的〉は芸術に関するさまで、対策を表す語としては合わない。"}, {"text": "文学的", "is_correct": false, "explanation": "〈文学的〉は文学に関するさまで、対策の文脈には合わない。"}], "explanations": {"抜本的": "「根本から対策を立てる」という意味で、手直しでは足りないという文脈に合う。", "宗教的": "〈宗教的〉は宗教に関するさまで、「宗教的な対策」は文脈に合わない。", "芸術的": "〈芸術的〉は芸術に関するさまで、対策を表す語としては合わない。", "文学的": "〈文学的〉は文学に関するさまで、対策の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "抜本的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見た目を整えるだけの表面的な作業で、店を抜本的に変えた。", "explanation": "ここは〈表面的〉の意味。〈抜本的〉は根本から変えることなので、見た目だけの作業とは合わない。"}, {"text": "音量を、ほんの少しだけ抜本的に調整した。", "explanation": "ここは〈微調整〉の意味。「微調整する」とは言うが、〈抜本的〉は根本から大きく変えることなので、ほんの少しの調整には合わない。"}, {"text": "小規模な改善を抜本的に行い、社員に説明した。", "explanation": "ここは〈小規模〉の意味。〈抜本的〉は根本からの大きな変更なので、小さな改善には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53489, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "根本から見直すには、抜本的の計画が必要だ。", "corrected_sentence": "根本から見直すには、抜本的な計画が必要だ。", "error_description": "正しくは「抜本的な計画」。〈抜本的〉は形容動詞なので、名詞を修飾するには「な」が必要で、「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
