INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の根本や基礎のこと。また、その根本からすべてを見直して変えるさま。", "primary_collocate": null, "pronunciation": "ばっぽん", "ipa": "bappoɴ", "syllable_count": 4, "sentences": [{"text": "病気を防ぐには、食生活を抜本的に見直す必要がある。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "病気[びょうき]を防[ふせ]ぐには、食生活[しょくせいかつ]を抜本的[ばっぽんてき]に見直[みなお]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "抜本的な解決のためには、問題の原因から調べなければならない。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "抜本的[ばっぽんてき]な解決[かいけつ]のためには、問題[もんだい]の原因[げんいん]から調[しら]べなければならない。", "sentence_source": "generated"}, {"text": "政府は税の仕組みを抜本的に変える方針を決めた。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "政府[せいふ]は税[ぜい]の仕組[しく]みを抜本的[ばっぽんてき]に変[か]える方針[ほうしん]を決[き]めた。", "sentence_source": "generated"}, {"text": "古い橋は修理を重ねても危ないので、抜本的な建て替えが決まった。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]は修理[しゅうり]を重[かさ]ねても危[あぶ]ないので、抜本的[ばっぽんてき]な建[た]て替[か]えが決[き]まった。", "sentence_source": "generated"}, {"text": "学校は、いじめをなくすための抜本的な対策を考えている。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "学校[がっこう]は、いじめをなくすための抜本的[ばっぽんてき]な対策[たいさく]を考[かんが]えている。", "sentence_source": "generated"}, {"text": "工場の安全管理を、抜本的に改めると社長は約束した。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "工場[こうじょう]の安全管理[あんぜんかんり]を、抜本的[ばっぽんてき]に改[あらた]めると社長[しゃちょう]は約束[やくそく]した。", "sentence_source": "generated"}, {"text": "彼の提案は、これまでのやり方を見直す抜本的な案だった。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "彼[かれ]の提案[ていあん]は、これまでのやり方[かた]を見直[みなお]す抜本的[ばっぽんてき]な案[あん]だった。", "sentence_source": "generated"}, {"text": "表面だけ直しても、抜本的な改善にはならない。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "表面[ひょうめん]だけ直[なお]しても、抜本的[ばっぽんてき]な改善[かいぜん]にはならない。", "sentence_source": "generated"}, {"text": "町の水不足を抜本的に解決するため、新しいダムが造られた。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "町[まち]の水不足[みずぶそく]を抜本的[ばっぽんてき]に解決[かいけつ]するため、新[あたら]しいダムが造[つく]られた。", "sentence_source": "generated"}, {"text": "研究チームは、実験の進め方を抜本的に変えて、やり直した。", "target_word": "抜本的", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、実験[じっけん]の進[すす]め方[かた]を抜本的[ばっぽんてき]に変[か]えて、やり直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抜本", "label": "基本形"}, {"form": "抜本的", "label": "的がついた形"}], "register": "やや硬い", "sense_fingerprint": "根本から見直して変えるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抜本的", "is_correct": true, "explanation": "「根本から見直す」という意味で、病気を防ぐための食生活の見直しに合う。"}, {"text": "空想的", "is_correct": false, "explanation": "〈空想的〉は現実離れしたさまで、食生活の見直しには合わない。"}, {"text": "宇宙的", "is_correct": false, "explanation": "〈宇宙的〉は宇宙に関するさまで、食生活の見直しには合わない。"}, {"text": "宗教的", "is_correct": false, "explanation": "〈宗教的〉は宗教に関するさまで、食生活の見直しには合わない。"}], "explanations": {"抜本的": "「根本から見直す」という意味で、病気を防ぐための食生活の見直しに合う。", "空想的": "〈空想的〉は現実離れしたさまで、食生活の見直しには合わない。", "宇宙的": "〈宇宙的〉は宇宙に関するさまで、食生活の見直しには合わない。", "宗教的": "〈宗教的〉は宗教に関するさまで、食生活の見直しには合わない。"}, "sentence_index": 0, "correct_answer": "抜本的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の走りは、抜本的な速さで他の選手を大きく引き離した。", "explanation": "ここは〈抜群〉の意味。「抜群の速さ」とは言うが、〈抜本的〉は根本からの変更を指すので、速さの程度には使えない。"}, {"text": "小手先の工夫で、この問題を抜本的に解決した。", "explanation": "ここは〈小手先〉の意味。〈抜本的〉は根本から変えることなので、その場しのぎの工夫とは合わない。"}, {"text": "彼は抜本的な笑顔で挨拶した。", "explanation": "〈抜本的〉は根本から変えることを表し、笑顔の様子を表す語ではないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抜本的", "is_correct": true, "explanation": "「これまでのやり方を根本から見直す案」という意味で、文に合う。"}, {"text": "芸術的", "is_correct": false, "explanation": "〈芸術的〉は芸術に関するさまで、やり方を見直す案の説明には合わない。"}, {"text": "文学的", "is_correct": false, "explanation": "〈文学的〉は文学に関するさまで、提案の説明には合わない。"}, {"text": "宇宙的", "is_correct": false, "explanation": "〈宇宙的〉は宇宙に関するさまで、やり方の見直しには合わない。"}], "explanations": {"抜本的": "「これまでのやり方を根本から見直す案」という意味で、文に合う。", "芸術的": "〈芸術的〉は芸術に関するさまで、やり方を見直す案の説明には合わない。", "文学的": "〈文学的〉は文学に関するさまで、提案の説明には合わない。", "宇宙的": "〈宇宙的〉は宇宙に関するさまで、やり方の見直しには合わない。"}, "sentence_index": 6, "correct_answer": "抜本的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "表面的な飾りつけだけで、建物を抜本的に変えた。", "explanation": "ここは〈表面的〉の意味。〈抜本的〉は根本から変えることなので、飾りだけの変更とは合わない。"}, {"text": "小規模な改善を抜本的に行い、社員に説明した。", "explanation": "ここは〈小規模〉の意味。〈抜本的〉は根本からの大きな変更なので、小さな改善には合わない。"}, {"text": "一時的な応急処置を抜本的に行い、水漏れを止めた。", "explanation": "ここは〈一時的〉の意味。〈抜本的〉は根本から変えることなので、応急処置とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
