INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "これからこうしたいと心の中でじっと考えること。", "primary_collocate": null, "pronunciation": "きと", "ipa": "kito", "syllable_count": 2, "sentences": [{"text": "彼は海外で働くことを企図していたが、家族には話さなかった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼[かれ]は海外[かいがい]で働[はたら]くことを企図[きと]していたが、家族[かぞく]には話[はな]さなかった。", "sentence_source": "generated"}, {"text": "彼女が何を企図しているのか、周りの人は誰も知らなかった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が何[なに]を企図[きと]しているのか、周[まわ]りの人[ひと]は誰[だれ]も知[し]らなかった。", "sentence_source": "generated"}, {"text": "社長は会社を海外に広げることを、何年も前から企図していた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は会社[かいしゃ]を海外[かいがい]に広[ひろ]げることを、何年[なんねん]も前[まえ]から企図[きと]していた。", "sentence_source": "generated"}, {"text": "本人の企図とは関係なく、その発言は大きな問題になった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "本人[ほんにん]の企図[きと]とは関係[かんけい]なく、その発言[はつげん]は大[おお]きな問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "彼は独立を企図しながら、静かに貯金を続けた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼[かれ]は独立[どくりつ]を企図[きと]しながら、静[しず]かに貯金[ちょきん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "父は退職後に農業を始めることを企図していたようだ。", "target_word": "企図", "complexity_tier": "T3", "furigana": "父[ちち]は退職後[たいしょくご]に農業[のうぎょう]を始[はじ]めることを企図[きと]していたようだ。", "sentence_source": "generated"}, {"text": "友人の企図に気づいたとき、私はもう止められなかった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の企図[きと]に気[き]づいたとき、私[わたし]はもう止[と]められなかった。", "sentence_source": "generated"}, {"text": "彼らの企図は最後まで外には知られなかった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼[かれ]らの企図[きと]は最後[さいご]まで外[そと]には知[し]られなかった。", "sentence_source": "generated"}, {"text": "先生は、生徒を驚かせようと企図して、わざと黙っていた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]を驚[おどろ]かせようと企図[きと]して、わざと黙[だま]っていた。", "sentence_source": "generated"}, {"text": "彼が小説家になろうと企図したのは、十代のころだった。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼[かれ]が小説家[しょうせつか]になろうと企図[きと]したのは、十代[じゅうだい]のころだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "企図", "label": "基本形"}, {"form": "企図する", "label": "する動詞の辞書形"}, {"form": "企図した", "label": "過去形"}], "register": "硬い", "sense_fingerprint": "これからしたいことを心の中で考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企図", "is_correct": true, "explanation": "「働くことを企図する」は、心の中で考えて計画するという意味で、文に合う。"}, {"text": "発明", "is_correct": false, "explanation": "〈発明〉は新しいものを作り出すことで、「働くことを発明」は文として成り立たない。"}, {"text": "寄付", "is_correct": false, "explanation": "〈寄付〉は金品を贈ることで、「働くことを寄付」は意味をなさない。"}, {"text": "解散", "is_correct": false, "explanation": "〈解散〉は集団をばらすことで、「働くことを解散」は文脈に合わない。"}], "explanations": {"企図": "「働くことを企図する」は、心の中で考えて計画するという意味で、文に合う。", "発明": "〈発明〉は新しいものを作り出すことで、「働くことを発明」は文として成り立たない。", "寄付": "〈寄付〉は金品を贈ることで、「働くことを寄付」は意味をなさない。", "解散": "〈解散〉は集団をばらすことで、「働くことを解散」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "企図"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は企図に震えながら、舞台を見つめていた。", "explanation": "ここは〈感動〉の意味。「感動に震える」とは言うが、〈企図〉は心の中で考える計画で、震える感情の意味にはならない。"}, {"text": "大手の企図が、海外に工場を建てた。", "explanation": "ここは〈企業〉の意味。〈企図〉は考えることで、会社の意味には使えない。"}, {"text": "彼は昔の企図に浸って、窓の外を見ていた。", "explanation": "ここは〈思い出〉の意味。「思い出に浸る」とは言うが、〈企図〉は将来に向けて考える計画で、過去の出来事を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企図", "is_correct": true, "explanation": "「友人の企図に気づく」は、友人が心の中で考えていた計画に気づくという意味で、文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "「友人の雨に気づく」は意味をなさない。"}, {"text": "光", "is_correct": false, "explanation": "「友人の光に気づく」は文脈に合わない。"}, {"text": "駅", "is_correct": false, "explanation": "「友人の駅に気づく」は文脈に合わない。"}], "explanations": {"企図": "「友人の企図に気づく」は、友人が心の中で考えていた計画に気づくという意味で、文に合う。", "雨": "「友人の雨に気づく」は意味をなさない。", "光": "「友人の光に気づく」は文脈に合わない。", "駅": "「友人の駅に気づく」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "企図"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は企図に暮れて、夜も眠れなかった。", "explanation": "ここは〈思案〉の意味。「思案に暮れる」とは言うが、〈企図〉は「暮れる」の対象にならない。"}, {"text": "その言葉を聞いて、彼は深い企図をついた。", "explanation": "ここは〈ため息〉の意味。「ため息をつく」とは言うが、〈企図〉は「つく」の対象にならない。"}, {"text": "山道に企図を立てて、道に迷わないようにした。", "explanation": "ここは〈目印〉の意味。〈企図〉は目印として立てるものではないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人は、留学を企図で貯金を始めた。", "corrected_sentence": "友人は、留学を企図して貯金を始めた。", "error_description": "正しくは「企図して」。〈企図〉は「する」を付けて動詞になるので、「して」が必要で、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、新しい店を開くことを企図ている。", "corrected_sentence": "彼女は、新しい店を開くことを企図している。", "error_description": "正しくは「企図している」。進行の「している」の「し」が抜けており、「企図ている」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大事業を企図する」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「企図する」は目的語に「を」を取るので、「に」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、計画の対象を示す文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、「大事業と企図した」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「大事業を企図する」の目的語を示す「を」。", "に": "「企図する」は目的語に「を」を取るので、「に」は合わない。", "へ": "方向を表す「へ」は、計画の対象を示す文脈に合わない。", "と": "「と」は並列や引用を表し、「大事業と企図した」は意味が通らない。"}, "error_tags": {"に": "相手・対象", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
