INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある目標を達成しようと、心の中で計画したり考えたりすること。", "primary_collocate": null, "pronunciation": "きと", "ipa": "kito", "syllable_count": 2, "sentences": [{"text": "会社は新しい市場に進出することを企図して、調査を始めた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい市場[しじょう]に進出[しんしゅつ]することを企図[きと]して、調査[ちょうさ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "この大事業を企図した人は、成功のために細かい準備を重ねた。", "target_word": "企図した", "complexity_tier": "T3", "furigana": "この大事業[だいじぎょう]を企図[きと]した人[ひと]は、成功[せいこう]のために細[こま]かい準備[じゅんび]を重[かさ]ねた。", "sentence_source": "generated"}, {"text": "大会で優勝することを企図し、チームは毎日練習を続けた。", "target_word": "企図し", "complexity_tier": "T3", "furigana": "大会[たいかい]で優勝[ゆうしょう]することを企図[きと]し、チームは毎日[まいにち]練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "この新製品は、若い人への売り上げ拡大を企図して作られた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "この新製品[しんせいひん]は、若[わか]い人[ひと]への売[う]り上[あ]げ拡大[かくだい]を企図[きと]して作[つく]られた。", "sentence_source": "generated"}, {"text": "市は観光客を増やすことを企図し、新しい祭りを始めた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "市[し]は観光客[かんこうきゃく]を増[ふ]やすことを企図[きと]し、新[あたら]しい祭[まつ]りを始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼は事業の拡大を企図して、銀行に相談した。", "target_word": "企図", "complexity_tier": "T3", "furigana": "彼[かれ]は事業[じぎょう]の拡大[かくだい]を企図[きと]して、銀行[ぎんこう]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "研究所は、環境を守る技術の開発を企図している。", "target_word": "企図", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]は、環境[かんきょう]を守[まも]る技術[ぎじゅつ]の開発[かいはつ]を企図[きと]している。", "sentence_source": "generated"}, {"text": "彼らは試合の流れを変えることを企図したが、うまくいかなかった。", "target_word": "企図した", "complexity_tier": "T3", "furigana": "彼[かれ]らは試合[しあい]の流[なが]れを変[か]えることを企図[きと]したが、うまくいかなかった。", "sentence_source": "generated"}, {"text": "今回の改革は、働く人の負担を減らすことを企図している。", "target_word": "企図", "complexity_tier": "T3", "furigana": "今回[こんかい]の改革[かいかく]は、働[はたら]く人[ひと]の負担[ふたん]を減[へ]らすことを企図[きと]している。", "sentence_source": "generated"}, {"text": "その本は、子どもたちに読書の楽しさを伝えることを企図して書かれた。", "target_word": "企図", "complexity_tier": "T3", "furigana": "その本[ほん]は、子[こ]どもたちに読書[どくしょ]の楽[たの]しさを伝[つた]えることを企図[きと]して書[か]かれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "企図", "label": "基本形"}, {"form": "企図する", "label": "する動詞の辞書形"}, {"form": "企図して", "label": "て形"}], "register": "硬い", "sense_fingerprint": "目標のために計画を立てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企図", "is_correct": true, "explanation": "「目標のために計画を立てる」意味で、進出を目指す文に合う。"}, {"text": "没収", "is_correct": false, "explanation": "「没収」は物を取り上げる意味で、「進出することを没収して」は成り立たない。"}, {"text": "解雇", "is_correct": false, "explanation": "「解雇」は雇用を終わらせる意味で、進出の計画とは結びつかない。"}, {"text": "納入", "is_correct": false, "explanation": "「納入」は品物を届ける意味で、「進出することを納入して」は不自然。"}], "explanations": {"企図": "「目標のために計画を立てる」意味で、進出を目指す文に合う。", "没収": "「没収」は物を取り上げる意味で、「進出することを没収して」は成り立たない。", "解雇": "「解雇」は雇用を終わらせる意味で、進出の計画とは結びつかない。", "納入": "「納入」は品物を届ける意味で、「進出することを納入して」は不自然。"}, "sentence_index": 0, "correct_answer": "企図"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この企図は、年間三百人を雇う大きな会社だ。", "explanation": "〈企業〉の意味。企図は計画や目論見を指し、会社そのものは指さないので合わない。"}, {"text": "彼は悲しみを企図して、涙を流した。", "explanation": "ここは〈感じる・抱く〉の意味。企図は目標を立てて計画することで、感情を抱く意味では使わない。"}, {"text": "彼は窓を企図して、笑顔で話した。", "explanation": "〈企図〉は計画を立てる語で、窓という物を対象にはできないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企図", "is_correct": true, "explanation": "「開発を計画する」の意味で、環境技術の開発という目標に合う。"}, {"text": "謝罪", "is_correct": false, "explanation": "「謝罪」は詫びる行為で、開発の対象にはならない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は取り除く行為で、「開発を撤去している」は合わない。"}, {"text": "解散", "is_correct": false, "explanation": "「解散」は集まりを終わらせる意味で、開発とは結びつかない。"}], "explanations": {"企図": "「開発を計画する」の意味で、環境技術の開発という目標に合う。", "謝罪": "「謝罪」は詫びる行為で、開発の対象にはならない。", "撤去": "「撤去」は取り除く行為で、「開発を撤去している」は合わない。", "解散": "「解散」は集まりを終わらせる意味で、開発とは結びつかない。"}, "sentence_index": 6, "correct_answer": "企図"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の天気を企図して、傘を持った。", "explanation": "ここは〈予想する〉の意味。企図は目標を立てて計画することで、天気を予想する意味では使わない。"}, {"text": "彼女は先生の机を企図して、ずっと謝っていた。", "explanation": "〈企図〉は計画や目標を立てる語で、机という物を対象にはできないので、この文では使えない。"}, {"text": "子犬が吠えることを企図して、庭を走り回った。", "explanation": "ここは〈無意識に〉の意味。企図は人が目標を立てて計画する行為で、動物が無意識に吠える様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新しい店を開くことを企図に、資金を集めた。", "corrected_sentence": "彼は新しい店を開くことを企図して、資金を集めた。", "error_description": "「企図して」が正しい。「企図に」は後ろに続く文の形が成り立たず、て形の連結が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は新しい橋を作ることを企図られて、資金を集めた。", "corrected_sentence": "町は新しい橋を作ることを企図して、資金を集めた。", "error_description": "「企図られて」は誤り。サ変動詞「する」の受身は「企図される」となるが、ここは能動の「企図して」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「必要だ」の主語を示す「が」で、「リテラシーが必要だ」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「必要だ」の主語には「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すので、必要だと言われる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、「必要だ」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「必要だ」の主語を示す「が」で、「リテラシーが必要だ」が自然。", "を": "「必要だ」の主語には「を」は使えない。", "で": "手段や場所を表すので、必要だと言われる対象を示せない。", "と": "相手や並列を表すので、「必要だ」の主語にはならない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "教える対象を示す目的語の「を」で、「リテラシーを教える」が自然。"}, {"text": "に", "is_correct": false, "explanation": "受け手を示すので、「リテラシーに教える」では対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、教える内容を示す位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、教える対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "教える対象を示す目的語の「を」で、「リテラシーを教える」が自然。", "に": "受け手を示すので、「リテラシーに教える」では対象を示せない。", "へ": "方向を表すので、教える内容を示す位置には入らない。", "より": "比較を表すので、教える対象にはならない。"}, "error_tags": {"に": "受け手・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "よんだりかいたりできる力、そしてじょうほうを正しく理解して上手に使う能力のことです。", "primary_collocate": null, "pronunciation": "りてらしー", "ipa": "ɾiteɾaɕiː", "syllable_count": 5, "sentences": [{"text": "ネットの情報を信じる前に、リテラシーを身につけることが大切だ。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "ネットの情報[じょうほう]を信[しん]じる前[まえ]に、リテラシーを身[み]につけることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "子どもにはまず、情報を正しく見分けるリテラシーが必要だ。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "子[こ]どもにはまず、情報[じょうほう]を正[ただ]しく見分[みわ]けるリテラシーが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この国では、字を読み書きするリテラシーが広がり、生活が変わった。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "この国[くに]では、字[じ]を読[よ]み書[か]きするリテラシーが広[ひろ]がり、生活[せいかつ]が変[か]わった。", "sentence_source": "generated"}, {"text": "リテラシーが低いと、うその情報にだまされやすい。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "リテラシーが低[ひく]いと、うその情報[じょうほう]にだまされやすい。", "sentence_source": "generated"}, {"text": "学校は、生徒のリテラシーを高める授業を始めた。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "学校[がっこう]は、生徒[せいと]のリテラシーを高[たか]める授業[じゅぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼は新聞を読み比べて、自分のリテラシーを鍛えている。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "彼[かれ]は新聞[しんぶん]を読[よ]み比[くら]べて、自分[じぶん]のリテラシーを鍛[きた]えている。", "sentence_source": "generated"}, {"text": "SNSを使う前に、リテラシーについて親子で話し合った。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "SNSを使[つか]う前[まえ]に、リテラシーについて親子[おやこ]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "お年寄りにも分かるように、リテラシーを教える会が開かれた。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "お年寄[としよ]りにも分[わ]かるように、リテラシーを教[おし]える会[かい]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "リテラシーのある人は、ニュースを見ても落ち着いて考える。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "リテラシーのある人[ひと]は、ニュースを見[み]ても落[お]ち着[つ]いて考[かんが]える。", "sentence_source": "generated"}, {"text": "高いリテラシーを持つ彼女は、情報の正しさをいつも確かめる。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "高[たか]いリテラシーを持[も]つ彼女[かのじょ]は、情報[じょうほう]の正[ただ]しさをいつも確[たし]かめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リテラシー", "label": "基本形"}, {"form": "リテラシーの", "label": "連体形"}, {"form": "リテラシーが", "label": "が格形"}], "register": "neutral", "sense_fingerprint": "情報を正しく理解し、上手に使いこなす力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リテラシー", "is_correct": true, "explanation": "情報を読み解く力を表し、身につけることが大切だという文脈と合う。"}, {"text": "同情", "is_correct": false, "explanation": "他人への思いやりを表す語で、能力として身につける対象ではない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめにする態度を表す語で、身につけて大切だという文脈と合わない。"}, {"text": "反発", "is_correct": false, "explanation": "反抗する気持ちを表す語で、情報を正しく扱う力とは別。"}], "explanations": {"リテラシー": "情報を読み解く力を表し、身につけることが大切だという文脈と合う。", "同情": "他人への思いやりを表す語で、能力として身につける対象ではない。", "遠慮": "控えめにする態度を表す語で、身につけて大切だという文脈と合わない。", "反発": "反抗する気持ちを表す語で、情報を正しく扱う力とは別。"}, "sentence_index": 0, "correct_answer": "リテラシー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパソコンは、リテラシーが壊れて動かない。", "explanation": "〈機器の機能〉の意味でリテラシーを使っているが、能力は物のように壊れないので、パソコンの状態には合わない。"}, {"text": "彼女はリテラシーが高く、重い荷物も楽に持ち上げる。", "explanation": "力仕事の力は「体力」で表す。リテラシーは情報の理解の能力を指すので合わない。"}, {"text": "今日はリテラシーが晴れて、洗濯物がよく乾く。", "explanation": "〈天気〉の意味でリテラシーを主語にしているが、能力は天候のように晴れたりしないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リテラシー", "is_correct": true, "explanation": "情報を読み解く力を表し、SNSを使う前に話し合う話題として自然に入る。"}, {"text": "段ボール", "is_correct": false, "explanation": "包装用の紙素材で、SNSを使う前の話題としては不自然になる。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝具の名前で、SNSの利用について話し合う文脈と合わない。"}, {"text": "味噌", "is_correct": false, "explanation": "食品の名前で、SNSを使う前の話題としては不自然になる。"}], "explanations": {"リテラシー": "情報を読み解く力を表し、SNSを使う前に話し合う話題として自然に入る。", "段ボール": "包装用の紙素材で、SNSを使う前の話題としては不自然になる。", "寝袋": "寝具の名前で、SNSの利用について話し合う文脈と合わない。", "味噌": "食品の名前で、SNSを使う前の話題としては不自然になる。"}, "sentence_index": 6, "correct_answer": "リテラシー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は朝から走り続けて、リテラシーが尽きてしまった。", "explanation": "ここは〈体力〉の意味。疲れて力が尽きるのは体力で言い、リテラシーは情報を理解する能力なので合わない。"}, {"text": "祖母は毎朝、リテラシーで庭の花に水をやる。", "explanation": "〈じょうろ〉のような道具の意味でリテラシーを使っているが、能力は水をやるための道具にはならないので、この文では使えない。"}, {"text": "彼はお店でリテラシーを買って、家に持ち帰った。", "explanation": "〈商品〉の意味でリテラシーを使っているが、能力は店で売り買いできる物ではないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校では、情報を正しく見分けるリテラシーを必要だ。", "corrected_sentence": "学校では、情報を正しく見分けるリテラシーが必要だ。", "error_description": "「リテラシーを必要だ」は誤り。「必要だ」の主語には「が」を使うので、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53497, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "リテラシーをある大人は、ニュースを見ても落ち着いて考える。", "corrected_sentence": "リテラシーのある大人は、ニュースを見ても落ち着いて考える。", "error_description": "「リテラシーを」は誤り。「ある」を修飾するには「の」が必要で、「リテラシーのある」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「リテラシー」が主語になり、「あれば」の条件節の主語として自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないため、「を」を付けると不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「リテラシーへあれば」と結びつかず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では「あれば」の条件が成り立たず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「リテラシー」が主語になり、「あれば」の条件節の主語として自然に成り立つ。", "を": "「ある」は目的語を取らないため、「を」を付けると不自然。", "へ": "方向を表す「へ」は「リテラシーへあれば」と結びつかず、不自然。", "から": "起点を表す「から」では「あれば」の条件が成り立たず、不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「リテラシー」を主題として示し、「社会で生きるための基本だ」と述べる文の形に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着や対象を示すため、「基本だ」の主題を作れず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、社会で生きる基本を主題として述べる文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、「基本だ」と述べる主題にはならず不自然。"}], "correct_answer": "は", "explanations": {"は": "「リテラシー」を主題として示し、「社会で生きるための基本だ」と述べる文の形に合う。", "に": "「に」は帰着や対象を示すため、「基本だ」の主題を作れず文が成り立たない。", "で": "「で」は手段や場所を示すため、社会で生きる基本を主題として述べる文には合わない。", "と": "「と」は並列や引用を示すため、「基本だ」と述べる主題にはならず不自然。"}, "error_tags": {"に": "帰着・対象", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "文字を読み書きする基本的な能力。また、専門的な知識や情報を正確に理解し、適切に処理・活用する能力を指します。", "primary_collocate": null, "pronunciation": "りてらしー", "ipa": "ɾiteɾaɕiː", "syllable_count": 5, "sentences": [{"text": "識字率が上がると、国民のリテラシーも向上する。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "識字率[しきじりつ]が上[あ]がると、国民[こくみん]のリテラシーも向上[こうじょう]する。", "sentence_source": "generated"}, {"text": "医療のリテラシーがあれば、医者の説明を正確に理解できる。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "医療[いりょう]のリテラシーがあれば、医者[いしゃ]の説明[せつめい]を正確[せいかく]に理解[りかい]できる。", "sentence_source": "generated"}, {"text": "昔は、読み書きのリテラシーを持たない人が多かった。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "昔[むかし]は、読[よ]み書[か]きのリテラシーを持[も]たない人[ひと]が多[おお]かった。", "sentence_source": "generated"}, {"text": "専門家は、データを正確に処理するリテラシーを身につけている。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、データを正確[せいかく]に処理[しょり]するリテラシーを身[み]につけている。", "sentence_source": "generated"}, {"text": "数字を読み解くリテラシーがないと、グラフにだまされる。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "数字[すうじ]を読[よ]み解[と]くリテラシーがないと、グラフにだまされる。", "sentence_source": "generated"}, {"text": "彼女は法律のリテラシーが高く、契約書の内容をすぐ理解した。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は法律[ほうりつ]のリテラシーが高[たか]く、契約書[けいやくしょ]の内容[ないよう]をすぐ理解[りかい]した。", "sentence_source": "generated"}, {"text": "会社では、新入社員にデータを扱うリテラシーを求めている。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では、新入[しんにゅう]社員[しゃいん]にデータを扱[あつか]うリテラシーを求[もと]めている。", "sentence_source": "generated"}, {"text": "読み書きのリテラシーは、社会で生きるための基本だ。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "読[よ]み書[か]きのリテラシーは、社会[しゃかい]で生[い]きるための基本[きほん]だ。", "sentence_source": "generated"}, {"text": "統計のリテラシーを高めるため、毎晩グラフの読み方を勉強している。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "統計[とうけい]のリテラシーを高[たか]めるため、毎晩[まいばん]グラフの読[よ]み方[かた]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "地域の学校で、大人にも読み書きのリテラシーを教えている。", "target_word": "リテラシー", "complexity_tier": "T3", "furigana": "地域[ちいき]の学校[がっこう]で、大人[おとな]にも読[よ]み書[か]きのリテラシーを教[おし]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リテラシー", "label": "基本形"}, {"form": "リテラシーの", "label": "連体形"}, {"form": "リテラシーが", "label": "が格形"}], "register": "neutral", "sense_fingerprint": "読み書きの基本能力、または専門的な知識を正確に理解し活用する力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リテラシー", "is_correct": true, "explanation": "「国民の」に続けて能力を表し、「向上する」の主語として自然に成り立つ。"}, {"text": "ジャンル", "is_correct": false, "explanation": "作品や分野の分類を指す語で、「国民のジャンル」は能力の向上と結びつかない。"}, {"text": "ドラマ", "is_correct": false, "explanation": "作品や出来事を指す語で、「国民のドラマも向上する」は意味をなさない。"}, {"text": "ハンガー", "is_correct": false, "explanation": "衣類を掛ける道具で、能力の向上を表す文には入らない。"}], "explanations": {"リテラシー": "「国民の」に続けて能力を表し、「向上する」の主語として自然に成り立つ。", "ジャンル": "作品や分野の分類を指す語で、「国民のジャンル」は能力の向上と結びつかない。", "ドラマ": "作品や出来事を指す語で、「国民のドラマも向上する」は意味をなさない。", "ハンガー": "衣類を掛ける道具で、能力の向上を表す文には入らない。"}, "sentence_index": 0, "correct_answer": "リテラシー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人望のリテラシーが厚く、みんなに慕われている。", "explanation": "ここは〈人望〉の意味。人望は周囲から慕われ信頼される力を指すので、情報を読み解く能力のリテラシーとは結びつかない。"}, {"text": "この職人は木材を削るリテラシーが高く、どんな細工もこなす。", "explanation": "ここは〈技術〉の意味。リテラシーは手作業の腕前ではなく、情報を理解する力を指すので合わない。"}, {"text": "旅行の写真を見ると、楽しかった日のリテラシーがよみがえる。", "explanation": "ここは〈思い出〉の意味。リテラシーは記憶ではなく能力なので、よみがえるものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リテラシー", "is_correct": true, "explanation": "新入社員に求める能力を表し、「扱う〜を求めている」の目的語として成り立つ。"}, {"text": "カレンダー", "is_correct": false, "explanation": "日付を示す表で、「データを扱う」「求める」の対象として文が成り立たない。"}, {"text": "ボトル", "is_correct": false, "explanation": "容器を指す語で、「データを扱うボトル」は意味をなさない。"}, {"text": "ランプ", "is_correct": false, "explanation": "照明器具で、能力を求める文の目的語にはならない。"}], "explanations": {"リテラシー": "新入社員に求める能力を表し、「扱う〜を求めている」の目的語として成り立つ。", "カレンダー": "日付を示す表で、「データを扱う」「求める」の対象として文が成り立たない。", "ボトル": "容器を指す語で、「データを扱うボトル」は意味をなさない。", "ランプ": "照明器具で、能力を求める文の目的語にはならない。"}, "sentence_index": 6, "correct_answer": "リテラシー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先輩は海外勤務のリテラシーが長く、現地の商習慣をよく知っている。", "explanation": "ここは〈経験〉の意味。経験は期間の長さで語れるが、リテラシーは能力であり、長さを表す語とは結びつかないので合わない。"}, {"text": "この店は内装のリテラシーがよく、落ち着いた雰囲気だ。", "explanation": "ここは〈センス〉の意味。美的な感覚を指す語で、情報を読み解く能力のリテラシーは内装の良し悪しには使わない。"}, {"text": "彼は勇気のリテラシーが強く、どんな困難にも立ち向かう。", "explanation": "ここは〈勇気〉の意味。勇気は困難に立ち向かう心を指す語で、情報を読み解く能力のリテラシーとは結びつかないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は医療のリテラシーを高く、薬の説明書をすぐ理解した。", "corrected_sentence": "彼は医療のリテラシーが高く、薬の説明書をすぐ理解した。", "error_description": "誤りは助詞「を」。「高い」の主語には「が」が必要で、「リテラシーを高く」は目的語を取らない形容詞に目的語を付けた誤り。正しくは「リテラシーが高く」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は統計のリテラシーを高くため、毎晩グラフを読んでいる。", "corrected_sentence": "彼は統計のリテラシーを高めるため、毎晩グラフを読んでいる。", "error_description": "誤りは「高める」の形。「ため」の前は動詞の辞書形が必要で、「高く」は形容詞の連用形なので誤り。正しくは「高めるため」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「想いを書く」で、書く対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「想いが手紙に書いた」は書く人が欠けて成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「想いと手紙に書いた」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「想いへ手紙に書いた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「想いを書く」で、書く対象を示す。", "が": "「想いが手紙に書いた」は書く人が欠けて成り立たない。", "と": "「想いと手紙に書いた」は文として成り立たない。", "へ": "「想いへ手紙に書いた」は文として成り立たない。"}, "error_tags": {"が": "wrong_subject", "と": "wrong_case", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「強い想いで追いかける」で、原動力を示す。"}, {"text": "を", "is_correct": false, "explanation": "後ろに「夢を」があり、「を」が重なって成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「想いへ夢を追いかける」は文として成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「想いまで夢を追いかける」は文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「強い想いで追いかける」で、原動力を示す。", "を": "後ろに「夢を」があり、「を」が重なって成り立たない。", "へ": "「想いへ夢を追いかける」は文として成り立たない。", "まで": "「想いまで夢を追いかける」は文として成り立たない。"}, "error_tags": {"を": "double_object", "へ": "direction", "まで": "wrong_case"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中に抱いている感情や願い。また、それらを何かに向けて表現すること。", "primary_collocate": "込める", "pronunciation": "おもい", "ipa": "omoi", "syllable_count": 3, "sentences": [{"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "想い", "complexity_tier": "T6", "furigana": "生徒[せいと]たちが繊維[せんい]の纹理[もんり]に想[おも]いを込[こ]め、独自[どくじ]のプロットを紡[つむ]ぎ出[だ]すとき、それは単[たん]なる被服[ひふく]製作[せいさく]ではなく、記号的[きごうてき]な自己[じこ]主張[しゅちょう]の確立[かくりつ]へと昇華[しょうか]されるのである。", "sentence_source": "mined"}, {"text": "母への想いを手紙に書いた。", "target_word": "想い", "complexity_tier": "T2", "furigana": "母[はは]への想[おも]いを手紙[てがみ]に書[か]いた。", "sentence_source": "generated"}, {"text": "彼に想いを伝えたい。", "target_word": "想い", "complexity_tier": "T2", "furigana": "彼[かれ]に想[おも]いを伝[つた]えたい。", "sentence_source": "generated"}, {"text": "想いは言葉にしないと届かない。", "target_word": "想い", "complexity_tier": "T3", "furigana": "想[おも]いは言葉[ことば]にしないと届[とど]かない。", "sentence_source": "generated"}, {"text": "二人の想いが一つになった。", "target_word": "想い", "complexity_tier": "T2", "furigana": "二人[ふたり]の想[おも]いが一[ひと]つになった。", "sentence_source": "generated"}, {"text": "私は故郷への想いを忘れない。", "target_word": "想い", "complexity_tier": "T2", "furigana": "私[わたし]は故郷[こきょう]への想[おも]いを忘[わす]れない。", "sentence_source": "generated"}, {"text": "長い間、胸に想いを秘めていた。", "target_word": "想い", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、胸[むね]に想[おも]いを秘[ひ]めていた。", "sentence_source": "generated"}, {"text": "彼女は強い想いで夢を追いかけている。", "target_word": "想い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は強[つよ]い想[おも]いで夢[ゆめ]を追[お]いかけている。", "sentence_source": "generated"}, {"text": "卒業式で、先生への想いを話した。", "target_word": "想い", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]で、先生[せんせい]への想[おも]いを話[はな]した。", "sentence_source": "generated"}, {"text": "その歌には、作った人の想いが込められている。", "target_word": "想い", "complexity_tier": "T4", "furigana": "その歌[うた]には、作[つく]った人[ひと]の想[おも]いが込[こ]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "想う", "label": "派生"}, {"form": "想い出", "label": "派生"}, {"form": "想い人", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 心に抱く感情や願い", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 被服 (Zipf 2.42)']::text[], '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想い", "is_correct": true, "explanation": "見出し語「おもい」。"}, {"text": "餅", "is_correct": false, "explanation": "「おもち」は最後の1拍だけが違う。"}, {"text": "錘", "is_correct": false, "explanation": "「おもり」は最後の1拍だけが違う。"}, {"text": "表", "is_correct": false, "explanation": "「おもて」は最後の1拍だけが違う。"}, {"text": "鴨居", "is_correct": false, "explanation": "「かもい」は最初の1拍だけが違う。"}], "explanations": {"想い": "見出し語「おもい」。", "餅": "「おもち」は最後の1拍だけが違う。", "錘": "「おもり」は最後の1拍だけが違う。", "表": "「おもて」は最後の1拍だけが違う。", "鴨居": "「かもい」は最初の1拍だけが違う。"}, "sentence_index": null, "correct_answer": "想い"}, "level_3": {"options": [{"text": "想い", "is_correct": true, "explanation": "「想いを込める」で、気持ちを込める意味になる。"}, {"text": "砂", "is_correct": false, "explanation": "形は合うが、砂を込めるでは意味が合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "形は合うが、湯気を込めるでは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気を込めるでは意味が合わない。"}], "explanations": {"想い": "「想いを込める」で、気持ちを込める意味になる。", "砂": "形は合うが、砂を込めるでは意味が合わない。", "湯気": "形は合うが、湯気を込めるでは意味が合わない。", "天気": "形は合うが、天気を込めるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "想い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、想いを飲んでから出かける。", "explanation": "想いは心の感情で、飲む物ではない。"}, {"text": "想いは重さが三キロもある。", "explanation": "想いは感情なので、重さを量る対象ではない。"}, {"text": "雨で想いが濡れたので、乾かした。", "explanation": "想いは形のない気持ちで、濡れたり乾かしたりする物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "想い", "is_correct": true, "explanation": "見出し語「おもい」。"}, {"text": "重み", "is_correct": false, "explanation": "「おもみ」は最後の1拍だけが違う。"}, {"text": "母屋", "is_correct": false, "explanation": "「おもや」は最後の1拍だけが違う。"}, {"text": "重湯", "is_correct": false, "explanation": "「おもゆ」は最後の1拍だけが違う。"}], "explanations": {"想い": "見出し語「おもい」。", "重み": "「おもみ」は最後の1拍だけが違う。", "母屋": "「おもや」は最後の1拍だけが違う。", "重湯": "「おもゆ」は最後の1拍だけが違う。"}, "sentence_index": null, "correct_answer": "想い"}, "level_3": {"options": [{"text": "想い", "is_correct": true, "explanation": "「胸に想いを秘める」で、心に感情を隠す意味になる。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜を胸に秘めるでは意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、電車を胸に秘めるでは意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、「胸に地図を秘める」では意味が合わない。"}], "explanations": {"想い": "「胸に想いを秘める」で、心に感情を隠す意味になる。", "野菜": "形は合うが、野菜を胸に秘めるでは意味が合わない。", "電車": "形は合うが、電車を胸に秘めるでは意味が合わない。", "地図": "形は合うが、「胸に地図を秘める」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "想い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は想いを机の上に置いて、部屋を出た。", "explanation": "想いは感情で、机の上に置ける物ではない。"}, {"text": "このカバンは想いが三つ付いている。", "explanation": "想いは数えられるポケットのような物ではなく、感情を表す。"}, {"text": "彼は想いを洗濯機で洗った。", "explanation": "想いは感情なので、洗濯する物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生に感謝の想いが伝えた。", "corrected_sentence": "先生に感謝の想いを伝えた。", "error_description": "伝える対象の「想い」は「を」で示す。「が」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女への想いを胸に飲んで、旅に出た。", "corrected_sentence": "彼女への想いを胸に秘めて、旅に出た。", "error_description": "想いを胸に「秘める」が正しい。「飲む」は想いと結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短し", "is_correct": true, "explanation": "「長し」の対義語。距離や時間が短いことを表す文語の対になる語。"}, {"text": "重し", "is_correct": false, "explanation": "形容詞だが「長し」の対義語ではない。重さが大きいことを表す語。"}, {"text": "深し", "is_correct": false, "explanation": "形容詞だが「長し」の対義語ではない。深さが大きいことを表す語。"}, {"text": "広し", "is_correct": false, "explanation": "形容詞だが「長し」の対義語ではない。広さが大きいことを表す語。"}], "correct_answer": "短し", "explanations": {"短し": "「長し」の対義語。距離や時間が短いことを表す文語の対になる語。", "重し": "形容詞だが「長し」の対義語ではない。重さが大きいことを表す語。", "深し": "形容詞だが「長し」の対義語ではない。深さが大きいことを表す語。", "広し": "形容詞だが「長し」の対義語ではない。広さが大きいことを表す語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
